INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87600, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，书面语，表示程度很深，很有。", "primary_collocate": null, "pronunciation": "dà yǒu", "ipa": "ta˥˩ joʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "多读书对学习大有好处。", "target_word": "大有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法大有用处。", "target_word": "大有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的汉语比去年大有进步。", "target_word": "大有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次谈话对我大有帮助。", "target_word": "大有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个年轻人大有希望。", "target_word": "大有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新工作让他大有收获。", "target_word": "大有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跟老师的谈话对我大有启发。", "target_word": "大有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的变化大有看头。", "target_word": "大有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每天锻炼，对身体大有益处。", "target_word": "大有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划大有前途。", "target_word": "大有", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "程度很深地有（大有好处、大有进步）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '117b498c-ddd5-4e59-81b8-2a4e87b7131e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87600, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大有", "is_correct": true, "explanation": "大有（dà yǒu）是副词，表示程度很深地有，书面语，如“大有好处”。"}, {"text": "大雨", "is_correct": false, "explanation": "yǔ（第三声）与 yǒu 韵母不同（ü 与 ou），声调相同，意思是“大雨”。"}, {"text": "带有", "is_correct": false, "explanation": "dài 与 dà 只差韵母（ai 与 a），意思是“带有”。"}, {"text": "但有", "is_correct": false, "explanation": "dàn 与 dà 只差鼻音韵尾（n），意思是“只要有”，与“大有”不同。"}], "explanations": {"大有": "大有（dà yǒu）是副词，表示程度很深地有，书面语，如“大有好处”。", "大雨": "yǔ（第三声）与 yǒu 韵母不同（ü 与 ou），声调相同，意思是“大雨”。", "带有": "dài 与 dà 只差韵母（ai 与 a），意思是“带有”。", "但有": "dàn 与 dà 只差鼻音韵尾（n），意思是“只要有”，与“大有”不同。"}, "sentence_index": null, "correct_answer": "大有"}, "level_3": {"options": [{"text": "大有", "is_correct": true, "explanation": "“大有”是副词，表示程度很深地有，“大有好处”符合本句。"}, {"text": "很", "is_correct": false, "explanation": "搭配：“很”不能直接修饰“好处”，应说“很有好处”。"}, {"text": "挺", "is_correct": false, "explanation": "搭配：“挺”不能直接修饰名词“好处”，“挺好处”不成立。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”后面要接形容词或“有”，不能直接接“好处”。"}], "explanations": {"大有": "“大有”是副词，表示程度很深地有，“大有好处”符合本句。", "很": "搭配：“很”不能直接修饰“好处”，应说“很有好处”。", "挺": "搭配：“挺”不能直接修饰名词“好处”，“挺好处”不成立。", "非常": "搭配：“非常”后面要接形容词或“有”，不能直接接“好处”。"}, "sentence_index": 0, "correct_answer": "大有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "想学汉语的人大有人在。", "explanation": "这里“大有”表示数量很多（大有人在），不是“程度很深地有”的意思。"}, {"text": "愿意帮忙的人大有人在。", "explanation": "这里“大有”表示数量很多（大有人在），不是“程度很深地有”的意思。"}, {"text": "喜欢看书的孩子大有人在。", "explanation": "这里“大有”表示数量很多（大有人在），不是“程度很深地有”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87600, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大有", "is_correct": true, "explanation": "“大有”表示程度很深地有，“对我大有启发”符合本句。"}, {"text": "颇", "is_correct": false, "explanation": "搭配：“颇”要带“有”才能修饰“启发”，“颇启发”不成立。"}, {"text": "老", "is_correct": false, "explanation": "搭配：“老”不能直接修饰名词“启发”，“老启发”不成立。"}, {"text": "怪", "is_correct": false, "explanation": "搭配：“怪”不能直接修饰名词“启发”，“怪启发”不成立。"}], "explanations": {"大有": "“大有”表示程度很深地有，“对我大有启发”符合本句。", "颇": "搭配：“颇”要带“有”才能修饰“启发”，“颇启发”不成立。", "老": "搭配：“老”不能直接修饰名词“启发”，“老启发”不成立。", "怪": "搭配：“怪”不能直接修饰名词“启发”，“怪启发”不成立。"}, "sentence_index": 6, "correct_answer": "大有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爱看这个节目的观众大有人在。", "explanation": "这里“大有”表示数量很多，与本词“程度很深地有”的意思不同。"}, {"text": "愿意买这本书的读者大有人在。", "explanation": "这里“大有”表示数量很多（大有人在），不是“程度很深地有”的意思。"}, {"text": "这样做的公司大有人在。", "explanation": "这里“大有”表示数量很多，与本词“程度很深地有”的意思不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87600, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次培训对我们的工作大有了帮助。", "corrected_sentence": "这次培训对我们的工作大有帮助。", "error_description": "错误在“大有”后面加了“了”。“大有”是副词，后面不能加“了”，应直接说“大有帮助”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87600, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份工作对他的成长很大有好处。", "corrected_sentence": "这份工作对他的成长大有好处。", "error_description": "错误在“大有”前面加了“很”。“大有”本身已表示程度很深，前面不能再加“很”，应说“大有好处”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
