INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87601, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "提到是在说话时说起某个人或某件事。", "primary_collocate": null, "pronunciation": "tí dào", "ipa": "tʰi˧˥ taʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他在会上提到了你的名字。", "target_word": "提到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师今天提到了明天的考试。", "target_word": "提到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈常常提到小时候的事。", "target_word": "提到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你刚才提到的那本书，我也想看。", "target_word": "提到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来没有提到过自己的家人。", "target_word": "提到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友聊天时提到了新工作。", "target_word": "提到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报告里提到了几个重要问题。", "target_word": "提到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想提到他的名字。", "target_word": "提到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在信里提到下个月要回国。", "target_word": "提到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶聊天时总提到爷爷。", "target_word": "提到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "提到了", "label": "体标"}, {"form": "提到过", "label": "体标"}], "register": "中性", "sense_fingerprint": "说话时说起某个人或某件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4e62db1-d0f4-433b-9204-45f7851b2ab7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87601, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "提到", "is_correct": true, "explanation": "提到（tí dào，第二声＋第四声）是正确答案，意思是说起某人或某事。"}, {"text": "踢到", "is_correct": false, "explanation": "tī（第一声）与 tí（第二声）声调不同，意思是用脚碰到。"}, {"text": "踢倒", "is_correct": false, "explanation": "tī dǎo（第一声＋第三声）与 tí dào 声调不同，意思是用脚把东西踢得倒下。"}, {"text": "提刀", "is_correct": false, "explanation": "dāo（第一声）与 dào（第四声）声调不同，意思是拿着刀。"}], "explanations": {"提到": "提到（tí dào，第二声＋第四声）是正确答案，意思是说起某人或某事。", "踢到": "tī（第一声）与 tí（第二声）声调不同，意思是用脚碰到。", "踢倒": "tī dǎo（第一声＋第三声）与 tí dào 声调不同，意思是用脚把东西踢得倒下。", "提刀": "dāo（第一声）与 dào（第四声）声调不同，意思是拿着刀。"}, "sentence_index": null, "correct_answer": "提到"}, "level_3": {"options": [{"text": "提到", "is_correct": true, "explanation": "“提到”表示在会上说起你的名字，符合语境。"}, {"text": "发表", "is_correct": false, "explanation": "搭配：“发表”用于意见、讲话、文章，不能和“名字”搭配。"}, {"text": "收回", "is_correct": false, "explanation": "语义：“收回”指撤回已说的话或已给出的东西，名字不能被收回。"}, {"text": "评价", "is_correct": false, "explanation": "搭配：“评价”的对象是作品、表现等，不能评价一个名字。"}], "explanations": {"提到": "“提到”表示在会上说起你的名字，符合语境。", "发表": "搭配：“发表”用于意见、讲话、文章，不能和“名字”搭配。", "收回": "语义：“收回”指撤回已说的话或已给出的东西，名字不能被收回。", "评价": "搭配：“评价”的对象是作品、表现等，不能评价一个名字。"}, "sentence_index": 0, "correct_answer": "提到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他看着照片，眼泪一下子提到了眼眶。", "explanation": "这里应该用〈涌上〉。“提到”没有涌上的意思，眼泪涌上眼眶要说“涌上”。"}, {"text": "这学期我的英语提到了很高的水平。", "explanation": "这里应该用〈提高〉。“提到”没有提升水平的意思，英语水平的提高要说“提高”。"}, {"text": "他一个人把三个孩子提到了大学毕业。", "explanation": "这里应该用〈拉扯〉。“提到”没有养育孩子的意思，把孩子养大要说“拉扯”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2e7a7e9-67bd-4f23-9898-ac5580120dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87601, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "提到", "is_correct": true, "explanation": "提到（tí dào，第二声＋第四声）是正确答案，意思是说起某人或某事。"}, {"text": "剃刀", "is_correct": false, "explanation": "tì dāo（第四声＋第一声）与 tí dào 声调不同，意思是刮胡子用的刀。"}, {"text": "地道", "is_correct": false, "explanation": "dì（声母 d、第四声）与 tí（声母 t、第二声）读音不同，意思是地下通道。"}, {"text": "剃到", "is_correct": false, "explanation": "tì（第四声）与 tí（第二声）声调不同，意思是剃时碰到。"}], "explanations": {"提到": "提到（tí dào，第二声＋第四声）是正确答案，意思是说起某人或某事。", "剃刀": "tì dāo（第四声＋第一声）与 tí dào 声调不同，意思是刮胡子用的刀。", "地道": "dì（声母 d、第四声）与 tí（声母 t、第二声）读音不同，意思是地下通道。", "剃到": "tì（第四声）与 tí（第二声）声调不同，意思是剃时碰到。"}, "sentence_index": null, "correct_answer": "提到"}, "level_3": {"options": [{"text": "提到", "is_correct": true, "explanation": "“提到”表示在报告里说起几个问题，符合语境。"}, {"text": "体验", "is_correct": false, "explanation": "搭配：“体验”的对象是生活、感受，不能说体验问题。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”是迎接、接纳的意思，问题不能被欢迎。"}, {"text": "颁发", "is_correct": false, "explanation": "搭配：“颁发”用于奖状、证书等，不能颁发问题。"}], "explanations": {"提到": "“提到”表示在报告里说起几个问题，符合语境。", "体验": "搭配：“体验”的对象是生活、感受，不能说体验问题。", "欢迎": "语义：“欢迎”是迎接、接纳的意思，问题不能被欢迎。", "颁发": "搭配：“颁发”用于奖状、证书等，不能颁发问题。"}, "sentence_index": 6, "correct_answer": "提到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这棵树一年里提到了两米。", "explanation": "这里应该用〈长到〉。“提到”没有长高的意思，树木长到某个高度要说“长到”。"}, {"text": "雨一直提到了晚上。", "explanation": "这里应该用〈下到〉。“提到”指说起，不表示持续到某时，下雨持续到晚上要说“下到”。"}, {"text": "这张照片让她的心情提到了谷底。", "explanation": "这里应该用〈落到〉。“提到”没有下降的意思，心情跌到低点要说“落到谷底”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2e7a7e9-67bd-4f23-9898-ac5580120dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_erro