INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87602, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "说到；谈到。", "primary_collocate": null, "pronunciation": "tí dào", "ipa": "tʰi˧˥ taʊ˥˩", "syllable_count": 2, "sentences": [{"text": "提到北京，我就想起烤鸭。", "target_word": "提到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一提到考试，他就很紧张。", "target_word": "提到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "提到这个问题，大家都不说话了。", "target_word": "提到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "提到家乡，她的眼睛一下子亮了。", "target_word": "提到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们刚才谈话时没提到钱。", "target_word": "提到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板在电话里提到了明天开会的时间。", "target_word": "提到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天谁也没提到那件事。", "target_word": "提到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "提到足球，他可以说一整天。", "target_word": "提到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "提到她的老师，她总是很感动。", "target_word": "提到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他提到过想去海边住。", "target_word": "提到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "提到了", "label": "体标"}, {"form": "提到过", "label": "体标"}], "register": "中性", "sense_fingerprint": "说到；谈到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4e62db1-d0f4-433b-9204-45f7851b2ab7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87602, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "提到", "is_correct": true, "explanation": "提到（tí dào，第二声＋第四声）是正确答案，意思是说到、谈到。"}, {"text": "踢到", "is_correct": false, "explanation": "tī（第一声）与 tí（第二声）声调不同，意思是用脚碰到。"}, {"text": "提刀", "is_correct": false, "explanation": "dāo（第一声）与 dào（第四声）声调不同，意思是拿着刀。"}, {"text": "剃到", "is_correct": false, "explanation": "tì（第四声）与 tí（第二声）声调不同，意思是剃时碰到。"}], "explanations": {"提到": "提到（tí dào，第二声＋第四声）是正确答案，意思是说到、谈到。", "踢到": "tī（第一声）与 tí（第二声）声调不同，意思是用脚碰到。", "提刀": "dāo（第一声）与 dào（第四声）声调不同，意思是拿着刀。", "剃到": "tì（第四声）与 tí（第二声）声调不同，意思是剃时碰到。"}, "sentence_index": null, "correct_answer": "提到"}, "level_3": {"options": [{"text": "提到", "is_correct": true, "explanation": "“提到”表示说到北京，符合语境。"}, {"text": "发表", "is_correct": false, "explanation": "搭配：“发表”用于意见、文章，不能说发表一个地名。"}, {"text": "打印", "is_correct": false, "explanation": "搭配：“打印”的对象是文件、照片，不能打印北京。"}, {"text": "批准", "is_correct": false, "explanation": "语义：“批准”是同意、核准的意思，北京不能被批准。"}], "explanations": {"提到": "“提到”表示说到北京，符合语境。", "发表": "搭配：“发表”用于意见、文章，不能说发表一个地名。", "打印": "搭配：“打印”的对象是文件、照片，不能打印北京。", "批准": "语义：“批准”是同意、核准的意思，北京不能被批准。"}, "sentence_index": 0, "correct_answer": "提到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月他的体重提到了三公斤。", "explanation": "这里应该用〈增加〉。“提到”指说起，不表示数量上升，体重增加要说“增加”。"}, {"text": "奶奶一个人把我提到了能上学的年纪。", "explanation": "这里应该用〈拉扯〉。“提到”没有养育孩子的意思，把孩子养到能上学要说“拉扯”。"}, {"text": "她翻着相册，眼泪一下子提到了眼眶。", "explanation": "这里应该用〈涌上〉。“提到”没有涌上的意思，眼泪涌上眼眶要说“涌上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2e7a7e9-67bd-4f23-9898-ac5580120dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87602, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "提到", "is_correct": true, "explanation": "提到（tí dào，第二声＋第四声）是正确答案，意思是说到、谈到。"}, {"text": "踢倒", "is_correct": false, "explanation": "tī dǎo（第一声＋第三声）与 tí dào 声调不同，意思是用脚把东西踢得倒下。"}, {"text": "剃刀", "is_correct": false, "explanation": "tì dāo（第四声＋第一声）与 tí dào 声调不同，意思是刮胡子用的刀。"}, {"text": "地道", "is_correct": false, "explanation": "dì（声母 d、第四声）与 tí（声母 t、第二声）读音不同，意思是地下通道。"}], "explanations": {"提到": "提到（tí dào，第二声＋第四声）是正确答案，意思是说到、谈到。", "踢倒": "tī dǎo（第一声＋第三声）与 tí dào 声调不同，意思是用脚把东西踢得倒下。", "剃刀": "tì dāo（第四声＋第一声）与 tí dào 声调不同，意思是刮胡子用的刀。", "地道": "dì（声母 d、第四声）与 tí（声母 t、第二声）读音不同，意思是地下通道。"}, "sentence_index": null, "correct_answer": "提到"}, "level_3": {"options": [{"text": "提到", "is_correct": true, "explanation": "“提到”表示说起那件事，符合语境。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说吃一件事。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受”指得到快乐或好处，与“没……那件事”的语境不符。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是液体，不能说喝那件事。"}], "explanations": {"提到": "“提到”表示说起那件事，符合语境。", "吃": "搭配：“吃”的对象是食物，不能说吃一件事。", "享受": "语义：“享受”指得到快乐或好处，与“没……那件事”的语境不符。", "喝": "搭配：“喝”的对象是液体，不能说喝那件事。"}, "sentence_index": 6, "correct_answer": "提到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这孩子一夜之间提到了一米六。", "explanation": "这里应该用〈长到〉。“提到”没有长高的意思，身高增长要说“长到”。"}, {"text": "气温一夜之间提到了零下二十度。", "explanation": "这里应该用〈降到〉。“提到”没有下降的意思，气温降低要说“降到”。"}, {"text": "他的脸一下子提到了通红。", "explanation": "这里应该用〈涨红〉。“提到”没有变红的意思，脸色变红要说“涨红”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2e7a7e9-67bd-4f23-9898-ac5580120dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87602, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我听他提到了过北京的事。", "corrected_sentence": "我听他提到过北京的事。", "error_description": "体标错误：应改为“提到过”。“了”和“过”不能同时用在“提到”后，表示曾经说起过只用“过”，不说“提到了过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2e7a7e9-67bd-4f23-9898-ac5580120dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87602, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他这辈子不提到过北京。", "corrected_sentence": "他这辈子没提到过北京。", "error_description": "“过”表示曾经有过，否定要用“没”。“不”表示习惯或意愿，不能与“过”搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2e7a7e9-67bd-4f23-9898-ac5580120dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
