INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87603, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "猪肉是从猪身上来的肉，可以做菜吃。", "primary_collocate": null, "pronunciation": "zhū ròu", "ipa": "ʈʂu˥ ʐoʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "奶奶每个周末都去市场买猪肉。", "target_word": "猪肉", "complexity_tier": "T3", "furigana": "nǎinai měi ge zhōumò dōu qù shìchǎng mǎi zhūròu", "sentence_source": "generated"}, {"text": "他把猪肉放进了热锅里。", "target_word": "猪肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆的猪肉很好吃。", "target_word": "猪肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方人常用猪肉做馅儿。", "target_word": "猪肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们买了一些猪肉和青菜。", "target_word": "猪肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都爱吃妈妈做的猪肉。", "target_word": "猪肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些人因为宗教不吃猪肉。", "target_word": "猪肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请给我半斤猪肉。", "target_word": "猪肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些猪肉是从农村送来的。", "target_word": "猪肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做菜以前，先把猪肉洗干净。", "target_word": "猪肉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一块猪肉", "label": "量词"}, {"form": "一斤猪肉", "label": "量词"}, {"form": "豬肉", "label": "繁体"}], "register": "中性", "sense_fingerprint": "取自猪身上、用来做菜的肉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c3fb48-7015-4f79-9d9c-8a4eda67e6b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87603, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "猪肉", "is_correct": true, "explanation": "猪肉可以在市场买，是做菜用的食材，与“去市场买”搭配。"}, {"text": "故事", "is_correct": false, "explanation": "语义：故事不能在市场买，句子无法成立。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是市场上出售的东西，与“买”不合。"}, {"text": "手术", "is_correct": false, "explanation": "搭配：“做”才能搭配“手术”，不能说“买手术”。"}], "explanations": {"猪肉": "猪肉可以在市场买，是做菜用的食材，与“去市场买”搭配。", "故事": "语义：故事不能在市场买，句子无法成立。", "空气": "语义：空气不是市场上出售的东西，与“买”不合。", "手术": "搭配：“做”才能搭配“手术”，不能说“买手术”。"}, "sentence_index": 0, "correct_answer": "猪肉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他吃了一朵猪肉。", "explanation": "这里应该用〈块〉。“朵”用于花、云等，猪肉不能用“朵”。"}, {"text": "村里的猪肉在院子里跑。", "explanation": "这里应该用〈猪〉。“猪肉”只指宰后取来做菜的肉，不能指活着在院子里跑的猪。"}, {"text": "他的书包里放着一张猪肉。", "explanation": "这里应该用〈块〉。“张”用于纸、桌子等平面的东西，猪肉不能用“张”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5e4362-c5fb-45e9-aafc-472479894262') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87603, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "猪肉", "is_correct": true, "explanation": "猪肉是食物，因宗教原因不吃的正是猪肉，与句意相符。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说“吃钢琴”。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字不是可以吃的东西，与“不吃”搭配不合。"}, {"text": "故事", "is_correct": false, "explanation": "语义：故事不能被吃，与“不吃”搭配不合。"}], "explanations": {"猪肉": "猪肉是食物，因宗教原因不吃的正是猪肉，与句意相符。", "钢琴": "搭配：“吃”的对象是食物，不能说“吃钢琴”。", "名字": "语义：名字不是可以吃的东西，与“不吃”搭配不合。", "故事": "语义：故事不能被吃，与“不吃”搭配不合。"}, "sentence_index": 6, "correct_answer": "猪肉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们正在唱猪肉。", "explanation": "“唱”的对象应是歌曲，猪肉是食物，不能用“唱”。"}, {"text": "他把猪肉穿在身上了。", "explanation": "“穿”的对象应是衣服，猪肉不能穿，应用“做”“煮”等动词。"}, {"text": "他每天给猪肉讲故事。", "explanation": "这里的“讲”的对象应是故事、道理，猪肉是食物，不能给它讲故事；猪肉应与“吃”“煮”“切”等动词搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5e4362-c5fb-45e9-aafc-472479894262') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87603, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妈妈今天煮了一头猪肉。", "corrected_sentence": "我妈妈今天煮了一斤猪肉。", "error_description": "量词错误：猪肉应该用“斤”或“块”等称量，“头”用于整只的牲畜，如“一头猪”，不能说“一头猪肉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5e4362-c5fb-45e9-aafc-472479894262') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87603, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶给了我一只猪肉。", "corrected_sentence": "奶奶给了我一块猪肉。", "error_description": "量词错误：猪肉应该用“块”或“斤”称量，“只”用于动物，不能说“一只猪肉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5e4362-c5fb-45e9-aafc-472479894262') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
