INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87605, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "惯例是大家一直都这样做的老办法。", "primary_collocate": null, "pronunciation": "guàn lì", "ipa": "kuan⁵¹ li⁵¹", "syllable_count": 2, "sentences": [{"text": "按惯例，新年全家要一起吃饺子。", "target_word": "惯例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的惯例是周一开会。", "target_word": "惯例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个惯例已经有五十年了。", "target_word": "惯例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打破了老惯例，没有请客。", "target_word": "惯例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按照学校的惯例，毕业时要拍照。", "target_word": "惯例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里有个惯例，过节要唱歌。", "target_word": "惯例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家有个惯例，饭后一起散步。", "target_word": "惯例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的人不懂这里的惯例。", "target_word": "惯例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照惯例，老师先坐下，大家再坐。", "target_word": "惯例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不喜欢老惯例，想换个办法。", "target_word": "惯例", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "老惯例", "label": "复合"}, {"form": "慣例", "label": "繁体"}], "register": "中性", "sense_fingerprint": "大家一直这样做的老办法、老规矩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c82921da-4675-443e-aa98-940b45501dcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87605, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "惯例", "is_correct": true, "explanation": "惯例（guàn lì）：大家一直沿用的老办法。"}, {"text": "管理", "is_correct": false, "explanation": "guǎn lǐ 与 guàn lì 两个音节的声调都不同（第三声、第三声 对 第四声、第四声），意思是管理。"}, {"text": "观礼", "is_correct": false, "explanation": "guān lǐ 与 guàn lì 两个音节的声调都不同（第一声、第三声 对 第四声、第四声），意思是到场观看典礼。"}, {"text": "绚丽", "is_correct": false, "explanation": "xuàn 与 guàn 声母不同（x 与 g），lì 相同，意思是灿烂美丽。"}, {"text": "算力", "is_correct": false, "explanation": "suàn 与 guàn 声母不同（s 与 g），lì 相同，意思是计算能力。"}], "explanations": {"惯例": "惯例（guàn lì）：大家一直沿用的老办法。", "管理": "guǎn lǐ 与 guàn lì 两个音节的声调都不同（第三声、第三声 对 第四声、第四声），意思是管理。", "观礼": "guān lǐ 与 guàn lì 两个音节的声调都不同（第一声、第三声 对 第四声、第四声），意思是到场观看典礼。", "绚丽": "xuàn 与 guàn 声母不同（x 与 g），lì 相同，意思是灿烂美丽。", "算力": "suàn 与 guàn 声母不同（s 与 g），lì 相同，意思是计算能力。"}, "sentence_index": null, "correct_answer": "惯例"}, "level_3": {"options": [{"text": "惯例", "is_correct": true, "explanation": "正确：惯例指大家沿用的老规矩，“按惯例”表示依照习惯做法，与新年全家吃饺子相合。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不是可以依照的标准，“按窗户”说不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能作为依照的依据，这里的“按”需要规矩或习俗作宾语。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟是报时用品，不能作为依照的标准，“按闹钟”说不通。"}], "explanations": {"惯例": "正确：惯例指大家沿用的老规矩，“按惯例”表示依照习惯做法，与新年全家吃饺子相合。", "窗户": "语义：窗户不是可以依照的标准，“按窗户”说不通。", "石头": "语义：石头不能作为依照的依据，这里的“按”需要规矩或习俗作宾语。", "闹钟": "语义：闹钟是报时用品，不能作为依照的标准，“按闹钟”说不通。"}, "sentence_index": 0, "correct_answer": "惯例"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校刚发了一个惯例，明天不上课。", "explanation": "这里应该用〈通知〉。惯例是长期沿用的做法，不是临时发出的消息，发出的消息要说通知。"}, {"text": "这条惯例是上个月刚发布的。", "explanation": "这里应该用〈规则〉。惯例是长期沿用形成的，不是新发布的条文，刚发布的要说规则。"}, {"text": "警察找到了这个惯例，案件有了进展。", "explanation": "这里应该用〈线索〉。惯例是长期沿用的做法，不是调查中获得的信息，找到的信息要说线索。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '932a57fe-9398-41db-9fdd-1b79fde921e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87605, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "惯例", "is_correct": true, "explanation": "惯例（guàn lì）：大家一直沿用的老办法。"}, {"text": "炫丽", "is_correct": false, "explanation": "xuàn 与 guàn 声母不同（x 与 g），lì 相同，意思是光彩耀眼。"}, {"text": "冠礼", "is_correct": false, "explanation": "guàn lǐ 与 guàn lì 第二个音节声调不同（第三声 对 第四声），意思是古代男子的成年礼。"}, {"text": "官吏", "is_correct": false, "explanation": "guān lì 与 guàn lì 第一个音节声调不同（第一声 对 第四声），意思是旧时的官员。"}], "explanations": {"惯例": "惯例（guàn lì）：大家一直沿用的老办法。", "炫丽": "xuàn 与 guàn 声母不同（x 与 g），lì 相同，意思是光彩耀眼。", "冠礼": "guàn lǐ 与 guàn lì 第二个音节声调不同（第三声 对 第四声），意思是古代男子的成年礼。", "官吏": "guān lì 与 guàn lì 第一个音节声调不同（第一声 对 第四声），意思是旧时的官员。"}, "sentence_index": null, "correct_answer": "惯例"}, "level_3": {"options": [{"text": "惯例", "is_correct": true, "explanation": "正确：惯例指我们家长期形成的做法，与“饭后一起散步”相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是做法或习惯，“有个天气”与饭后散步无关。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，句子说的是饭后一起散步的做法，两者不搭。"}, {"text": "皮鞋", "is_correct": false, "explanation": "语义：皮鞋是穿着用的物品，不是家里的做法或习惯，“有个皮鞋”与饭后散步无关。"}], "explanations": {"惯例": "正确：惯例指我们家长期形成的做法，与“饭后一起散步”相符。", "天气": "语义：天气不是做法或习惯，“有个天气”与饭后散步无关。", "冰箱": "语义：冰箱是家电，句子说的是饭后一起散步的做法，两者不搭。", "皮鞋": "语义：皮鞋是穿着用的物品，不是家里的做法或习惯，“有个皮鞋”与饭后散步无关。"}, "sentence_index": 6, "correct_answer": "惯例"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个惯例里写着所有员工的名字。", "explanation": "这里应该用〈名单〉。惯例是长期沿用的做法，不是记录人名的材料，记录人名要说名单。"}, {"text": "他从这次失败中得到了宝贵的惯例。", "explanation": "这里应该用〈经验〉。惯例是大家沿用的做法，从失败中总结的心得要说经验。"}, {"text": "这个惯例解释了地球为什么绕着太阳转。", "explanation": "这里应该用〈理论〉。惯例是做法，不能解释自然现象，解释规律要用理论。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '932a57fe-9398-41db-9fdd-1b79fde921e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87605, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们单位有只惯例，每周五下午打扫办公室。", "corrected_sentence": "我们单位有个惯例，每周五下午打扫办公室。", "error_description": "量词错误：惯例应该用“个”，不能用“只”。“只”多用于动物或成对的东西。正确说法是“有个惯例”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '932a57fe-9398-41db-9fdd-1b79fde921e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87605, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "班上有张惯例，每月第一天换座位。", "corrected_sentence": "班上有个惯例，每月第一天换座位。", "error_description": "量词错误：惯例应该用“个”，不能用“张”。“张”用于纸张、桌子这类平面的东西。正确说法是“班上有个惯例”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '932a57fe-9398-41db-9fdd-1b79fde921e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
