INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87608, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国家的根本大法，规定国家制度和公民的基本权利。", "primary_collocate": null, "pronunciation": "xiàn fǎ", "ipa": "ɕjɛn˥˩ fa˨˩˦", "syllable_count": 2, "sentences": [{"text": "宪法是国家最重要的法律。", "target_word": "宪法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中国的宪法保护公民的权利。", "target_word": "宪法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个人都要遵守宪法。", "target_word": "宪法", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师给我们讲了宪法的内容。", "target_word": "宪法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家的宪法规定了总统的权力。", "target_word": "宪法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "宪法规定公民有受教育的权利。", "target_word": "宪法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家修改了宪法，大家都在讨论。", "target_word": "宪法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校请律师来给学生讲宪法。", "target_word": "宪法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法院不能做违反宪法的事。", "target_word": "宪法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部宪法是三十年前通过的。", "target_word": "宪法", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "部", "label": "量词"}, {"form": "憲法", "label": "繁体"}, {"form": "宪法修正案", "label": "复合"}], "register": "书面", "sense_fingerprint": "名词，国家的根本大法，规定国家制度和公民权利", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bb8d477-42ee-4005-b0c4-97766b2fc790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87608, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "宪法", "is_correct": true, "explanation": "宪法是国家的根本大法，规定国家制度和公民的基本权利。"}, {"text": "想法", "is_correct": false, "explanation": "xiǎng（第三声）与 xiàn（第四声）韵母不同（ang / an），意思是想法、念头。"}, {"text": "献花", "is_correct": false, "explanation": "xiàn huā 第一个音节与 xiàn 相同，huā 与 fǎ 声母、声调不同，意思是献上鲜花。"}, {"text": "县府", "is_correct": false, "explanation": "fǔ 与 fǎ 韵母不同（u / a），意思是县政府。"}], "explanations": {"宪法": "宪法是国家的根本大法，规定国家制度和公民的基本权利。", "想法": "xiǎng（第三声）与 xiàn（第四声）韵母不同（ang / an），意思是想法、念头。", "献花": "xiàn huā 第一个音节与 xiàn 相同，huā 与 fǎ 声母、声调不同，意思是献上鲜花。", "县府": "fǔ 与 fǎ 韵母不同（u / a），意思是县政府。"}, "sentence_index": null, "correct_answer": "宪法"}, "level_3": {"options": [{"text": "宪法", "is_correct": true, "explanation": "宪法是国家根本大法，正符合“国家最重要的法律”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不是法律，句子说的是国家的法律。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校是机构，不能是“国家最重要的法律”。"}, {"text": "老规矩", "is_correct": false, "explanation": "语域：“老规矩”是口语说法，指习惯做法，不是法律文件，语域和意义都不合。"}], "explanations": {"宪法": "宪法是国家根本大法，正符合“国家最重要的法律”。", "天气": "语义：天气是自然现象，不是法律，句子说的是国家的法律。", "学校": "语义：学校是机构，不能是“国家最重要的法律”。", "老规矩": "语域：“老规矩”是口语说法，指习惯做法，不是法律文件，语域和意义都不合。"}, "sentence_index": 0, "correct_answer": "宪法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "依照宪法，他被判了三年。", "explanation": "这里应该用〈刑法〉。宪法是国家根本大法，不直接用来判刑，判刑依据刑法。"}, {"text": "他违反了交通宪法，被罚了款。", "explanation": "这里应该用〈法规〉。宪法是国家根本大法，只有一部；交通方面的规定叫法规，不能说交通宪法。"}, {"text": "我和房东签了宪法。", "explanation": "这里应该用〈合同〉。合同可以签，宪法应说制定或通过，不能签。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adb0bbfe-38d6-494b-aa72-a06b51652833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87608, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "宪法", "is_correct": true, "explanation": "宪法是国家的根本大法，规定国家制度和公民的基本权利。"}, {"text": "减法", "is_correct": false, "explanation": "jiǎn（第三声）与 xiàn（第四声）声母不同（j / x），意思是减法运算。"}, {"text": "效法", "is_correct": false, "explanation": "xiào 与 xiàn 韵母不同（ao / ian），声调相同，意思是模仿、学习。"}, {"text": "先发", "is_correct": false, "explanation": "xiān（第一声）与 xiàn（第四声）声调不同，fā（第一声）与 fǎ（第三声）声调也不同，意思是抢先发出。"}], "explanations": {"宪法": "宪法是国家的根本大法，规定国家制度和公民的基本权利。", "减法": "jiǎn（第三声）与 xiàn（第四声）声母不同（j / x），意思是减法运算。", "效法": "xiào 与 xiàn 韵母不同（ao / ian），声调相同，意思是模仿、学习。", "先发": "xiān（第一声）与 xiàn（第四声）声调不同，fā（第一声）与 fǎ（第三声）声调也不同，意思是抢先发出。"}, "sentence_index": null, "correct_answer": "宪法"}, "level_3": {"options": [{"text": "宪法", "is_correct": true, "explanation": "宪法可以被修改，符合“国家修改了”与“大家都在讨论”的语境。"}, {"text": "葡萄", "is_correct": false, "explanation": "搭配：“修改”的对象是文件、方案等，不能说修改葡萄。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，国家不会修改它，也不会引起大家讨论。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：午饭是一顿饭，不是可以修改的规定。"}], "explanations": {"宪法": "宪法可以被修改，符合“国家修改了”与“大家都在讨论”的语境。", "葡萄": "搭配：“修改”的对象是文件、方案等，不能说修改葡萄。", "冰箱": "语义：冰箱是家用电器，国家不会修改它，也不会引起大家讨论。", "午饭": "语义：午饭是一顿饭，不是可以修改的规定。"}, "sentence_index": 6, "correct_answer": "宪法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的宪法很好，很少生病。", "explanation": "这里应该用〈体质〉。宪法指国家的根本大法，身体素质要说“体质”。"}, {"text": "学校的宪法是三十年前通过的。", "explanation": "这里应该用〈章程〉。宪法只指国家的根本大法，学校内部的规定叫章程。"}, {"text": "这次比赛的宪法很公平。", "explanation": "这里应该用〈规则〉。宪法指国家的根本大法，比赛的规则要说“规则”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adb0bbfe-38d6-494b-aa72-a06b51652833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87608, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公民应该遵守于宪法。", "corrected_sentence": "公民应该遵守宪法。", "error_description": "“遵守”是及物动词，直接带宾语“宪法”，中间不能加“于”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adb0bbfe-38d6-494b-aa72-a06b51652833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87608, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "国家制作了宪法，大家都很关心。", "corrected_sentence": "国家制定了宪法，大家都很关心。", "error_description": "动词搭配错误：“宪法”应说“制定”，不说“制作”；“制作”用于具体物品，不能用于法律文件。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adb0bbfe-38d6-494b-aa72-a06b51652833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
