INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87609, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "赐是地位高的人把东西送给别人。", "primary_collocate": null, "pronunciation": "cì", "ipa": "tsʰɨ˥˩", "syllable_count": 1, "sentences": [{"text": "皇帝赐金子给立功的将军。", "target_word": "赐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老爷赐了仆人一些米和钱。", "target_word": "赐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国王赐他一座花园。", "target_word": "赐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大臣收到了皇上赐的茶叶。", "target_word": "赐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太后赐给小公主一条金项链。", "target_word": "赐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇上把一块好地赐给了老将军。", "target_word": "赐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他高兴地接过了皇上赐的礼物。", "target_word": "赐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候，皇帝会赐东西给有功的人。", "target_word": "赐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王爷赐我一杯酒，我不敢不喝。", "target_word": "赐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇上赐过他一把宝剑。", "target_word": "赐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "赐了", "label": "体标"}, {"form": "赐过", "label": "体标"}, {"form": "赐给", "label": "复合"}, {"form": "赐予", "label": "复合"}], "register": "书面", "sense_fingerprint": "地位高的人把东西送给别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9918d052-1adb-48b9-9d27-8bde39cc1f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87609, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "赐", "is_correct": true, "explanation": "正确。赐是“地位高的人把东西送给别人”的意思，读 cì（第四声）。"}, {"text": "此", "is_correct": false, "explanation": "cǐ（第三声）与 cì（第四声）声调不同，此是“这、这里”的意思。"}, {"text": "四", "is_correct": false, "explanation": "sì 与 cì 声母不同（s 与 c），四是数字“四”的意思。"}, {"text": "厕", "is_correct": false, "explanation": "cè（第四声）与 cì 韵母不同（e 与 i），厕是“厕所”的意思。"}, {"text": "字", "is_correct": false, "explanation": "zì 与 cì 声母不同（z 与 c），字是“文字”的意思。"}], "explanations": {"赐": "正确。赐是“地位高的人把东西送给别人”的意思，读 cì（第四声）。", "此": "cǐ（第三声）与 cì（第四声）声调不同，此是“这、这里”的意思。", "四": "sì 与 cì 声母不同（s 与 c），四是数字“四”的意思。", "厕": "cè（第四声）与 cì 韵母不同（e 与 i），厕是“厕所”的意思。", "字": "zì 与 cì 声母不同（z 与 c），字是“文字”的意思。"}, "sentence_index": null, "correct_answer": "赐"}, "level_3": {"options": [{"text": "赐", "is_correct": true, "explanation": "正确。“赐”指地位高的人把东西送给别人，与“皇帝”和“金子”的情境相符。"}, {"text": "吞", "is_correct": false, "explanation": "语义：皇帝吞下金子，与“送给将军”的情境毫不相关。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的宾语是文字，不能说“写金子”。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的宾语是液体，金子不能被喝。"}], "explanations": {"赐": "正确。“赐”指地位高的人把东西送给别人，与“皇帝”和“金子”的情境相符。", "吞": "语义：皇帝吞下金子，与“送给将军”的情境毫不相关。", "写": "搭配：“写”的宾语是文字，不能说“写金子”。", "喝": "搭配：“喝”的宾语是液体，金子不能被喝。"}, "sentence_index": 0, "correct_answer": "赐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把多余的书赐给了同学，同学很开心。", "explanation": "这里应该用〈送〉。“赐”只用于尊长或上级给下级，同学之间赠送要用“送”。"}, {"text": "他把书赐给了图书馆，管理员很惊讶。", "explanation": "这里应该用〈捐〉。“赐”只用于尊长或上级给下级，把书送给图书馆要用“捐”。"}, {"text": "弟弟赐给哥哥一支笔，哥哥很感动。", "explanation": "这里应该用〈送〉。“赐”只用于尊长或上级给下级，弟弟给哥哥东西要用“送”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d9a46-2ba1-452a-b3c2-3285ff2ef274') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87609, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "赐", "is_correct": true, "explanation": "正确。赐是“地位高的人把东西送给别人”的意思，读 cì（第四声）。"}, {"text": "词", "is_correct": false, "explanation": "cí（第二声）与 cì（第四声）声调不同，词是“词语”的意思。"}, {"text": "雌", "is_correct": false, "explanation": "cī（第一声）与 cì（第四声）声调不同，雌是“雌性”的意思。"}, {"text": "自", "is_correct": false, "explanation": "zì 与 cì 声母不同（z 与 c），自是“自己”的意思。"}, {"text": "测", "is_correct": false, "explanation": "cè（第四声）与 cì 韵母不同（e 与 i），测是“测量”的意思。"}], "explanations": {"赐": "正确。赐是“地位高的人把东西送给别人”的意思，读 cì（第四声）。", "词": "cí（第二声）与 cì（第四声）声调不同，词是“词语”的意思。", "雌": "cī（第一声）与 cì（第四声）声调不同，雌是“雌性”的意思。", "自": "zì 与 cì 声母不同（z 与 c），自是“自己”的意思。", "测": "cè（第四声）与 cì 韵母不同（e 与 i），测是“测量”的意思。"}, "sentence_index": null, "correct_answer": "赐"}, "level_3": {"options": [{"text": "赐", "is_correct": true, "explanation": "正确。“赐的礼物”指皇上赏给的礼物，与“接过”的情境相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃的礼物”与“接过礼物”的情境矛盾，吃不表示给予。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能修饰“礼物”。"}, {"text": "骂", "is_correct": false, "explanation": "搭配：“骂”的对象不能是礼物，搭配不当。"}], "explanations": {"赐": "正确。“赐的礼物”指皇上赏给的礼物，与“接过”的情境相符。", "吃": "语义：“吃的礼物”与“接过礼物”的情境矛盾，吃不表示给予。", "唱": "搭配：“唱”不能修饰“礼物”。", "骂": "搭配：“骂”的对象不能是礼物，搭配不当。"}, "sentence_index": 6, "correct_answer": "赐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "同学赐了我一支笔，我很感动。", "explanation": "这里应该用〈送〉。“赐”只用于尊长或上级给下级，同学之间赠送要用“送”。"}, {"text": "我在花园里赐了一朵花，送给妈妈。", "explanation": "这里应该用〈摘〉。“赐”不能用于采摘花朵。"}, {"text": "学徒把一碗汤赐给了师傅，师傅很满意。", "explanation": "这里应该用〈送〉。“赐”只用于上级给下级，学徒送给师傅要用“送”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d9a46-2ba1-452a-b3c2-3285ff2ef274') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87609, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "皇帝赐给给功臣一座宅院。", "corrected_sentence": "皇帝赐给功臣一座宅院。", "error_description": "“赐给”是一个词，“给”不能重复。应说“赐给功臣一座宅院”，不能说“赐给给功臣一座宅院”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d9a46-2ba1-452a-b3c2-3285ff2ef274') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87609, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "将军赐了了他一把宝剑，让他去守城。", "corrected_sentence": "将军赐了他一把宝剑，让他去守城。", "error_description": "“赐了”后面的“了”只需一个，这里多写了一个“了”，写成“赐了了他”，是错误的。应说“赐了他一把宝剑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d9a46-2ba1-452a-b3c2-3285ff2ef274') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
