INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87610, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "赏给；尊长或上级给予。", "primary_collocate": null, "pronunciation": "cì", "ipa": "tsʰɨ˥˩", "syllable_count": 1, "sentences": [{"text": "皇帝赐了他一块玉。", "target_word": "赐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老太爷赐给小孙子一个红包。", "target_word": "赐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国王赐他一匹好马，他高兴极了。", "target_word": "赐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇上赐酒给大臣们喝。", "target_word": "赐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太后赐了公主一件新衣服。", "target_word": "赐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "将军把一把宝剑赐给了他。", "target_word": "赐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王赐过他一座大房子。", "target_word": "赐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大王赐给每个士兵一碗酒。", "target_word": "赐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "皇帝赐他一个官职，让他去边疆守城。", "target_word": "赐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他得到了皇帝赐的黄金。", "target_word": "赐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "赐了", "label": "体标"}, {"form": "赐过", "label": "体标"}, {"form": "赐给", "label": "复合"}, {"form": "赐予", "label": "复合"}], "register": "书面", "sense_fingerprint": "尊长或上级赏给", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9918d052-1adb-48b9-9d27-8bde39cc1f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87610, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "赐", "is_correct": true, "explanation": "正确。赐是“赏给；尊长或上级给予”的意思，读 cì（第四声）。"}, {"text": "词", "is_correct": false, "explanation": "cí（第二声）与 cì（第四声）声调不同，词是“词语”的意思。"}, {"text": "此", "is_correct": false, "explanation": "cǐ（第三声）与 cì（第四声）声调不同，此是“这、这里”的意思。"}, {"text": "四", "is_correct": false, "explanation": "sì 与 cì 声母不同（s 与 c），四是数字“四”的意思。"}, {"text": "厕", "is_correct": false, "explanation": "cè（第四声）与 cì 韵母不同（e 与 i），厕是“厕所”的意思。"}], "explanations": {"赐": "正确。赐是“赏给；尊长或上级给予”的意思，读 cì（第四声）。", "词": "cí（第二声）与 cì（第四声）声调不同，词是“词语”的意思。", "此": "cǐ（第三声）与 cì（第四声）声调不同，此是“这、这里”的意思。", "四": "sì 与 cì 声母不同（s 与 c），四是数字“四”的意思。", "厕": "cè（第四声）与 cì 韵母不同（e 与 i），厕是“厕所”的意思。"}, "sentence_index": null, "correct_answer": "赐"}, "level_3": {"options": [{"text": "赐", "is_correct": true, "explanation": "正确。“赐”指尊长或上级把东西赏给下级，与“皇帝”和“一块玉”相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：皇帝把玉吃下去，与“赏给”的意思毫不相关。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的宾语是歌曲，不能用“唱”带“玉”作宾语。"}, {"text": "骂", "is_correct": false, "explanation": "搭配：“骂”的对象是人，不能说“骂了他一块玉”，搭配不成立。"}], "explanations": {"赐": "正确。“赐”指尊长或上级把东西赏给下级，与“皇帝”和“一块玉”相符。", "吃": "语义：皇帝把玉吃下去，与“赏给”的意思毫不相关。", "唱": "搭配：“唱”的宾语是歌曲，不能用“唱”带“玉”作宾语。", "骂": "搭配：“骂”的对象是人，不能说“骂了他一块玉”，搭配不成立。"}, "sentence_index": 0, "correct_answer": "赐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把自己做的点心赐给了朋友，大家都很喜欢。", "explanation": "这里应该用〈送〉。“赐”只用于尊长或上级给下级，朋友之间赠送要用“送”。"}, {"text": "我用工资赐了一台电脑。", "explanation": "这里应该用〈买〉。“赐”的施事必须是尊长或上级，自己用工资买东西不能用“赐”。"}, {"text": "学生把作业赐给了老师，老师看了很满意。", "explanation": "这里应该用〈交〉。“赐”只能是上级给下级，学生把作业交给老师不能用“赐”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d9a46-2ba1-452a-b3c2-3285ff2ef274') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87610, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "赐", "is_correct": true, "explanation": "正确。赐是“赏给；尊长或上级给予”的意思，读 cì（第四声）。"}, {"text": "瓷", "is_correct": false, "explanation": "cí（第二声）与 cì（第四声）声调不同，瓷是瓷器的意思。"}, {"text": "雌", "is_correct": false, "explanation": "cī（第一声）与 cì（第四声）声调不同，雌是“雌性”的意思。"}, {"text": "自", "is_correct": false, "explanation": "zì 与 cì 声母不同（z 与 c），自是“自己”的意思。"}, {"text": "测", "is_correct": false, "explanation": "cè（第四声）与 cì 韵母不同（e 与 i），测是“测量”的意思。"}], "explanations": {"赐": "正确。赐是“赏给；尊长或上级给予”的意思，读 cì（第四声）。", "瓷": "cí（第二声）与 cì（第四声）声调不同，瓷是瓷器的意思。", "雌": "cī（第一声）与 cì（第四声）声调不同，雌是“雌性”的意思。", "自": "zì 与 cì 声母不同（z 与 c），自是“自己”的意思。", "测": "cè（第四声）与 cì 韵母不同（e 与 i），测是“测量”的意思。"}, "sentence_index": null, "correct_answer": "赐"}, "level_3": {"options": [{"text": "赐", "is_correct": true, "explanation": "正确。“赐过”表示尊长或上级曾把房子赏给他，与“国王”相符。"}, {"text": "吞", "is_correct": false, "explanation": "语义：吞下一座房子，与“赏给”的意思毫不相关。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的宾语是文字，不能说“写过一座房子”。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的宾语是液体，房子不能被喝。"}], "explanations": {"赐": "正确。“赐过”表示尊长或上级曾把房子赏给他，与“国王”相符。", "吞": "语义：吞下一座房子，与“赏给”的意思毫不相关。", "写": "搭配：“写”的宾语是文字，不能说“写过一座房子”。", "喝": "搭配：“喝”的宾语是液体，房子不能被喝。"}, "sentence_index": 6, "correct_answer": "赐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把一本书赐给了同桌，同桌很开心。", "explanation": "这里应该用〈送〉。“赐”只用于尊长或上级给下级，同桌之间赠送要用“送”。"}, {"text": "我在树上赐了一个苹果，很甜。", "explanation": "这里应该用〈摘〉。“赐”指赏给，不能用于从树上采摘果实。"}, {"text": "员工把一束花赐给了经理，经理很高兴。", "explanation": "这里应该用〈送〉。“赐”只用于上级给下级，员工送给经理要用“送”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d9a46-2ba1-452a-b3c2-3285ff2ef274') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87610, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "皇帝把赐功臣一座府第。", "corrected_sentence": "皇帝赐功臣一座府第。", "error_description": "“把”字后面须接名词性宾语，不能直接接动词“赐”，这里多写了“把”。应说“赐功臣一座府第”，去掉“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d9a46-2ba1-452a-b3c2-3285ff2ef274') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87610, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古代皇帝常赐给给大臣金银。", "corrected_sentence": "古代皇帝常赐给大臣金银。", "error_description": "“赐给”是一个词，“给”不能重复。应说“赐给大臣金银”，不能说“赐给给大臣金银”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d9a46-2ba1-452a-b3c2-3285ff2ef274') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
