INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87611, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "摄影是用照相机拍下好看的东西。", "primary_collocate": null, "pronunciation": "shè yǐng", "ipa": "ʂɤ˥˩ iŋ˨˩", "syllable_count": 2, "sentences": [{"text": "姐姐喜欢摄影，常拍花和鸟。", "target_word": "摄影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "摄影需要一台好相机。", "target_word": "摄影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们明天早上去湖边摄影。", "target_word": "摄影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手机摄影，拍得也很好看。", "target_word": "摄影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "摄影时，你要站得稳一点。", "target_word": "摄影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的爱好是摄影和画画。", "target_word": "摄影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天的山很美，很适合摄影。", "target_word": "摄影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想跟你学摄影。", "target_word": "摄影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷退休以后开始摄影了。", "target_word": "摄影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公园的花开了，大家都来摄影。", "target_word": "摄影", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "摄影师", "label": "复合"}, {"form": "摄影机", "label": "复合"}, {"form": "攝影", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用照相机拍下好看的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '957488b2-d73b-4bc6-b47f-79a362d47852') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87611, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打字", "is_correct": false, "explanation": "语义：“打字”与“常拍花和鸟”无关，不是姐姐的爱好。"}, {"text": "摄影", "is_correct": true, "explanation": "“摄影”是姐姐的爱好，与“常拍花和鸟”一致。"}, {"text": "修车", "is_correct": false, "explanation": "语义：“修车”与“拍花和鸟”没有关系。"}, {"text": "烧饭", "is_correct": false, "explanation": "搭配：“烧饭”与后文“常拍花和鸟”无关联，不能说明这种爱好。"}], "explanations": {"打字": "语义：“打字”与“常拍花和鸟”无关，不是姐姐的爱好。", "摄影": "“摄影”是姐姐的爱好，与“常拍花和鸟”一致。", "修车": "语义：“修车”与“拍花和鸟”没有关系。", "烧饭": "搭配：“烧饭”与后文“常拍花和鸟”无关联，不能说明这种爱好。"}, "sentence_index": 0, "correct_answer": "摄影"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈摄影的菜很好吃。", "explanation": "这里应该用〈做〉。摄影指拍摄影像，做菜不能用“摄影”。"}, {"text": "他在台上摄影了一首歌，大家都鼓掌。", "explanation": "这里应该用〈唱〉。摄影指拍摄影像，唱歌不能用“摄影”。"}, {"text": "他每天早上去公园摄影，一跑就是三公里。", "explanation": "这里应该用〈跑步〉。摄影指拍摄影像，跑三公里要说“跑步”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87611, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吵架", "is_correct": false, "explanation": "语义：“秋天的山很美”与“吵架”不协调，山景不适合吵架。"}, {"text": "摄影", "is_correct": true, "explanation": "“摄影”与“秋天的山很美”搭配，句意通顺。"}, {"text": "打针", "is_correct": false, "explanation": "语义：“打针”与美丽的山景无关，不适合这里。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“很适合”后接“考试”与描写山景的句意不搭配。"}], "explanations": {"吵架": "语义：“秋天的山很美”与“吵架”不协调，山景不适合吵架。", "摄影": "“摄影”与“秋天的山很美”搭配，句意通顺。", "打针": "语义：“打针”与美丽的山景无关，不适合这里。", "考试": "搭配：“很适合”后接“考试”与描写山景的句意不搭配。"}, "sentence_index": 6, "correct_answer": "摄影"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "乐队在广场上摄影，很多人都来听。", "explanation": "这里应该用〈演奏〉。摄影指拍摄影像，演奏乐器要用“演奏”。"}, {"text": "秘书在电脑前摄影，打得又快又准。", "explanation": "这里应该用〈打字〉。摄影指拍摄影像，用键盘输入文字要用“打字”。"}, {"text": "他在院子里摄影了三棵树，现在都长高了。", "explanation": "这里应该用〈种〉。摄影指拍摄影像，让树长起来要说“种”树。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87611, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们明天去湖边摄影了。", "corrected_sentence": "我们明天去湖边摄影。", "error_description": "体标错误：“明天”是将来的事，不能用表示完成的“了”。正确是“明天去湖边摄影”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87611, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他上个星期去山上摄影着。", "corrected_sentence": "他上个星期去山上摄影了。", "error_description": "体标错误：“上个星期”是已完成的动作，应用“了”，不能用表示持续的“着”。正确是“去山上摄影了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
