INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87612, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用照相机等设备拍摄影像。", "primary_collocate": null, "pronunciation": "shè yǐng", "ipa": "ʂɤ˥˩ iŋ˨˩", "syllable_count": 2, "sentences": [{"text": "他每个周末都去公园摄影。", "target_word": "摄影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很喜欢摄影，也爱旅行。", "target_word": "摄影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸去山上摄影了。", "target_word": "摄影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里不能摄影，请大家把相机收起来。", "target_word": "摄影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她学摄影已经三年了。", "target_word": "摄影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "摄影时要先看看光线好不好。", "target_word": "摄影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想用新相机去海边摄影。", "target_word": "摄影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对摄影很有兴趣。", "target_word": "摄影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王最近常跟朋友一起摄影。", "target_word": "摄影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "摄影的时候，大家都不要说话。", "target_word": "摄影", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "摄影师", "label": "复合"}, {"form": "摄影机", "label": "复合"}, {"form": "攝影", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用照相机等设备拍摄影像", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '957488b2-d73b-4bc6-b47f-79a362d47852') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87612, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打字", "is_correct": false, "explanation": "语义：“打字”需要键盘，不是在公园里做的事。"}, {"text": "摄影", "is_correct": true, "explanation": "“摄影”指用设备拍摄影像，符合“去公园”的活动。"}, {"text": "修车", "is_correct": false, "explanation": "搭配：“去公园”与“修车”不搭配，修车一般不在公园进行。"}, {"text": "点菜", "is_correct": false, "explanation": "语义：“点菜”要在餐厅进行，不是去公园的活动。"}], "explanations": {"打字": "语义：“打字”需要键盘，不是在公园里做的事。", "摄影": "“摄影”指用设备拍摄影像，符合“去公园”的活动。", "修车": "搭配：“去公园”与“修车”不搭配，修车一般不在公园进行。", "点菜": "语义：“点菜”要在餐厅进行，不是去公园的活动。"}, "sentence_index": 0, "correct_answer": "摄影"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈摄影的菜很好吃。", "explanation": "这里应该用〈做〉。摄影指用设备拍摄影像，做菜不能用“摄影”。"}, {"text": "他在台上摄影了一首歌，大家都鼓掌。", "explanation": "这里应该用〈唱〉。摄影指拍摄影像，唱歌不能用“摄影”。"}, {"text": "录音室里请大家不要说话，我们要开始摄影了。", "explanation": "这里应该用〈录音〉。摄影指拍摄影像，录制声音要用“录音”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87612, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "做饭", "is_correct": false, "explanation": "语义：相机不能用来做饭，“用新相机”去海边做饭不合理。"}, {"text": "看书", "is_correct": false, "explanation": "语义：“看书”不需要相机，“用新相机去海边看书”不合理。"}, {"text": "摄影", "is_correct": true, "explanation": "“摄影”指用相机拍摄影像，符合“用新相机”。"}, {"text": "睡觉", "is_correct": false, "explanation": "搭配：“用……睡觉”不搭配，相机与睡觉没有关系。"}], "explanations": {"做饭": "语义：相机不能用来做饭，“用新相机”去海边做饭不合理。", "看书": "语义：“看书”不需要相机，“用新相机去海边看书”不合理。", "摄影": "“摄影”指用相机拍摄影像，符合“用新相机”。", "睡觉": "搭配：“用……睡觉”不搭配，相机与睡觉没有关系。"}, "sentence_index": 6, "correct_answer": "摄影"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "乐队在广场上摄影，很多人都来听。", "explanation": "这里应该用〈演奏〉。摄影指拍摄影像，演奏乐器要用“演奏”。"}, {"text": "秘书在电脑前摄影，打得很快。", "explanation": "这里应该用〈打字〉。摄影指拍摄影像，用键盘输入文字要用“打字”。"}, {"text": "他在院子里摄影了三棵树，现在都长高了。", "explanation": "这里应该用〈种〉。摄影指拍摄影像，让树长起来要说“种”树。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87612, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她上个月去海边摄影着。", "corrected_sentence": "她上个月去海边摄影了。", "error_description": "体标错误：“上个月”已结束的动作应用“了”，“着”表示动作持续，不能用于已完成的动作。正确是“去海边摄影了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87612, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们下个星期去海边摄影了。", "corrected_sentence": "我们下个星期去海边摄影。", "error_description": "体标错误：“下个星期”是将来的事，不能用表示完成的“了”。正确是“下个星期去海边摄影”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
