INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87615, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "扇是说门或窗的时候用的，一扇就是一块。", "primary_collocate": null, "pronunciation": "shàn", "ipa": "ʂan⁵¹", "syllable_count": 1, "sentences": [{"text": "这间屋子只有一扇门。", "target_word": "扇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她站在第三扇窗前看雪。", "target_word": "扇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们教室有四扇窗户。", "target_word": "扇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他推开了左边那扇门。", "target_word": "扇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那扇门锁着，我们进不去。", "target_word": "扇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这扇窗户太脏了，需要擦一擦。", "target_word": "扇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫钻过了那扇小门。", "target_word": "扇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每扇窗都挂着白色的窗帘。", "target_word": "扇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把这扇窗关上。", "target_word": "扇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了两扇新门。", "target_word": "扇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "量词，数门或窗，一扇就是一块", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed802cd7-e1c1-4adc-8439-d8c9d3271fb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87615, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "扇", "is_correct": true, "explanation": "扇（shàn，第四声）是正确答案：量词，数门或窗，一扇就是一块。"}, {"text": "闪", "is_correct": false, "explanation": "闪（shǎn，第三声）与扇（shàn，第四声）声调不同，意思是闪光。"}, {"text": "散", "is_correct": false, "explanation": "散（sàn）与扇（shàn）声母不同（s/sh），声调相同，意思是分散。"}, {"text": "上", "is_correct": false, "explanation": "上（shàng）与扇（shàn）韵母不同（an/ang），声调相同，意思是上面。"}, {"text": "衫", "is_correct": false, "explanation": "衫（shān，第一声）与扇（shàn，第四声）声调不同，意思是衣服。"}], "explanations": {"扇": "扇（shàn，第四声）是正确答案：量词，数门或窗，一扇就是一块。", "闪": "闪（shǎn，第三声）与扇（shàn，第四声）声调不同，意思是闪光。", "散": "散（sàn）与扇（shàn）声母不同（s/sh），声调相同，意思是分散。", "上": "上（shàng）与扇（shàn）韵母不同（an/ang），声调相同，意思是上面。", "衫": "衫（shān，第一声）与扇（shàn，第四声）声调不同，意思是衣服。"}, "sentence_index": null, "correct_answer": "扇"}, "level_3": {"options": [{"text": "扇", "is_correct": true, "explanation": "扇：量词，数门或窗，与“这间屋子”的门相符。"}, {"text": "把", "is_correct": false, "explanation": "搭配：“把”用于有柄或可握持的器具，“只有一把门”不成立。"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”用于动物，不能用来量“门”。"}, {"text": "本", "is_correct": false, "explanation": "搭配：“本”用于书、本子等，“只有一本门”不成立。"}], "explanations": {"扇": "扇：量词，数门或窗，与“这间屋子”的门相符。", "把": "搭配：“把”用于有柄或可握持的器具，“只有一把门”不成立。", "只": "搭配：“只”用于动物，不能用来量“门”。", "本": "搭配：“本”用于书、本子等，“只有一本门”不成立。"}, "sentence_index": 0, "correct_answer": "扇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把作业放在那扇桌子上。", "explanation": "这里应该用〈张〉。桌子用“张”计量，“扇”只用于门、窗、屏风等成扇的物体。"}, {"text": "院子里停着一扇汽车。", "explanation": "这里应该用〈辆〉。汽车用“辆”计量，“扇”只用于门、窗、屏风等成扇的物体。"}, {"text": "这扇屋子很大。", "explanation": "这里应该用〈间〉。屋子用“间”计量，“扇”不能用于屋子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd886a38-5bf1-4944-a671-17fe4416db10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87615, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "扇", "is_correct": true, "explanation": "扇（shàn，第四声）是正确答案：量词，数门或窗，一扇就是一块。"}, {"text": "散", "is_correct": false, "explanation": "散（sàn）与扇（shàn）声母不同（s/sh），声调相同，意思是分散。"}, {"text": "删", "is_correct": false, "explanation": "删（shān，第一声）与扇（shàn，第四声）声调不同，意思是删除。"}, {"text": "山", "is_correct": false, "explanation": "山（shān，第一声）与扇（shàn，第四声）声调不同，意思是山。"}, {"text": "闪", "is_correct": false, "explanation": "闪（shǎn，第三声）与扇（shàn，第四声）声调不同，意思是闪光。"}], "explanations": {"扇": "扇（shàn，第四声）是正确答案：量词，数门或窗，一扇就是一块。", "散": "散（sàn）与扇（shàn）声母不同（s/sh），声调相同，意思是分散。", "删": "删（shān，第一声）与扇（shàn，第四声）声调不同，意思是删除。", "山": "山（shān，第一声）与扇（shàn，第四声）声调不同，意思是山。", "闪": "闪（shǎn，第三声）与扇（shàn，第四声）声调不同，意思是闪光。"}, "sentence_index": null, "correct_answer": "扇"}, "level_3": {"options": [{"text": "扇", "is_correct": true, "explanation": "扇：量词，用于门、窗等成扇的物体，与“小门”搭配。"}, {"text": "幅", "is_correct": false, "explanation": "搭配：“幅”用于字画、布帛，“那幅小门”不成立。"}, {"text": "首", "is_correct": false, "explanation": "语义：“首”用于诗、歌等，与“钻过”的小门无关。"}, {"text": "篇", "is_correct": false, "explanation": "搭配：“篇”用于文章，不能用来量门。"}], "explanations": {"扇": "扇：量词，用于门、窗等成扇的物体，与“小门”搭配。", "幅": "搭配：“幅”用于字画、布帛，“那幅小门”不成立。", "首": "语义：“首”用于诗、歌等，与“钻过”的小门无关。", "篇": "搭配：“篇”用于文章，不能用来量门。"}, "sentence_index": 6, "correct_answer": "扇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的书架上放着一扇新书。", "explanation": "这里应该用〈本〉。书用“本”计量，“扇”只用于门、窗、屏风等成扇的物体。"}, {"text": "他买了两扇新椅子。", "explanation": "这里应该用〈把〉。椅子用“把”计量，“扇”只用于门、窗、屏风等成扇的物体。"}, {"text": "他拿着一扇纸写字。", "explanation": "这里应该用〈张〉。纸这类平面的东西用“张”，“扇”不能用于纸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd886a38-5bf1-4944-a671-17fe4416db10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87615, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "教室的这扇桌子关着。", "corrected_sentence": "教室的这扇门关着。", "error_description": "错误形式：这扇桌子；正确形式：这扇门。“扇”只量门、窗、屏风等成扇的物体，不能量桌子，桌子应用“张”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd886a38-5bf1-4944-a671-17fe4416db10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87615, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这扇大床很新。", "corrected_sentence": "这扇大门很新。", "error_description": "错误形式：这扇大床；正确形式：这扇大门。“扇”只量门、窗、屏风等成扇的物体，床应用“张”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd886a38-5bf1-4944-a671-17fe4416db10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
