INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87616, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "量词，用于门、窗、屏风等成扇的物体。", "primary_collocate": null, "pronunciation": "shàn", "ipa": "ʂan⁵¹", "syllable_count": 1, "sentences": [{"text": "房间里有一扇很大的窗。", "target_word": "扇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他轻轻关上了这扇门。", "target_word": "扇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙边放着一扇漂亮的屏风。", "target_word": "扇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的客厅有两扇窗户。", "target_word": "扇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把那扇门打开。", "target_word": "扇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这扇窗外面有一棵树。", "target_word": "扇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师走进来，关好了后面的那扇门。", "target_word": "扇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家有一扇红色的大门。", "target_word": "扇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那扇屏风是爷爷留下来的。", "target_word": "扇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风一吹，那扇窗就开了。", "target_word": "扇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "量词，用于门、窗、屏风等成扇的物体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed802cd7-e1c1-4adc-8439-d8c9d3271fb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87616, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "扇", "is_correct": true, "explanation": "扇（shàn，第四声）是正确答案：量词，用于门、窗、屏风等成扇的物体。"}, {"text": "山", "is_correct": false, "explanation": "山（shān，第一声）与扇（shàn，第四声）声调不同，意思是山。"}, {"text": "闪", "is_correct": false, "explanation": "闪（shǎn，第三声）与扇（shàn，第四声）声调不同，意思是闪光。"}, {"text": "伤", "is_correct": false, "explanation": "伤（shāng）与扇（shàn）韵母不同（an/ang），意思是伤害。"}, {"text": "散", "is_correct": false, "explanation": "散（sàn）与扇（shàn）声母不同（s/sh），声调相同，意思是分散。"}, {"text": "上", "is_correct": false, "explanation": "上（shàng）与扇（shàn）韵母不同（an/ang），声调相同，意思是上面。"}], "explanations": {"扇": "扇（shàn，第四声）是正确答案：量词，用于门、窗、屏风等成扇的物体。", "山": "山（shān，第一声）与扇（shàn，第四声）声调不同，意思是山。", "闪": "闪（shǎn，第三声）与扇（shàn，第四声）声调不同，意思是闪光。", "伤": "伤（shāng）与扇（shàn）韵母不同（an/ang），意思是伤害。", "散": "散（sàn）与扇（shàn）声母不同（s/sh），声调相同，意思是分散。", "上": "上（shàng）与扇（shàn）韵母不同（an/ang），声调相同，意思是上面。"}, "sentence_index": null, "correct_answer": "扇"}, "level_3": {"options": [{"text": "扇", "is_correct": true, "explanation": "扇：量词，用于门、窗、屏风等成扇的物体，可以量“很大的窗”。"}, {"text": "把", "is_correct": false, "explanation": "搭配：“把”用于有柄或可握持的器具，不能用来量“窗”。"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”用于动物，“一只很大的窗”不成立。"}, {"text": "座", "is_correct": false, "explanation": "语义：“座”多用于山、桥、楼等大型固定物，与“房间里”的一扇窗不符。"}], "explanations": {"扇": "扇：量词，用于门、窗、屏风等成扇的物体，可以量“很大的窗”。", "把": "搭配：“把”用于有柄或可握持的器具，不能用来量“窗”。", "只": "搭配：“只”用于动物，“一只很大的窗”不成立。", "座": "语义：“座”多用于山、桥、楼等大型固定物，与“房间里”的一扇窗不符。"}, "sentence_index": 0, "correct_answer": "扇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他坐在一扇椅子上看书。", "explanation": "这里应该用〈把〉。椅子这类有靠背、可以搬动的器具用“把”，“扇”只用于门、窗、屏风等成扇的物体。"}, {"text": "他家门口停着一扇汽车。", "explanation": "这里应该用〈辆〉。汽车用“辆”计量，“扇”只用于门、窗、屏风等成扇的物体。"}, {"text": "他吃了一扇苹果。", "explanation": "这里应该用〈个〉。苹果用“个”计量，“扇”只用于门、窗、屏风等成扇的物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd886a38-5bf1-4944-a671-17fe4416db10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87616, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "扇", "is_correct": true, "explanation": "扇（shàn，第四声）是正确答案：量词，用于门、窗、屏风等成扇的物体。"}, {"text": "删", "is_correct": false, "explanation": "删（shān，第一声）与扇（shàn，第四声）声调不同，意思是删除。"}, {"text": "衫", "is_correct": false, "explanation": "衫（shān，第一声）与扇（shàn，第四声）声调不同，意思是衣衫。"}, {"text": "陕", "is_correct": false, "explanation": "陕（shǎn，第三声）与扇（shàn，第四声）声调不同，意思是陕西（简称）。"}, {"text": "尚", "is_correct": false, "explanation": "尚（shàng）与扇（shàn）韵母不同（ang/an），声调相同，意思是还、尚且。"}], "explanations": {"扇": "扇（shàn，第四声）是正确答案：量词，用于门、窗、屏风等成扇的物体。", "删": "删（shān，第一声）与扇（shàn，第四声）声调不同，意思是删除。", "衫": "衫（shān，第一声）与扇（shàn，第四声）声调不同，意思是衣衫。", "陕": "陕（shǎn，第三声）与扇（shàn，第四声）声调不同，意思是陕西（简称）。", "尚": "尚（shàng）与扇（shàn）韵母不同（ang/an），声调相同，意思是还、尚且。"}, "sentence_index": null, "correct_answer": "扇"}, "level_3": {"options": [{"text": "扇", "is_correct": true, "explanation": "扇：量词，用于门、窗、屏风等成扇的物体，可以量“那扇门”。"}, {"text": "幅", "is_correct": false, "explanation": "搭配：“幅”用于字画、布帛，不能用来量门。"}, {"text": "首", "is_correct": false, "explanation": "语义：“首”用于诗、歌等，与“关好了”的门不合。"}, {"text": "盏", "is_correct": false, "explanation": "搭配：“盏”用于灯，“那盏门”不成立。"}], "explanations": {"扇": "扇：量词，用于门、窗、屏风等成扇的物体，可以量“那扇门”。", "幅": "搭配：“幅”用于字画、布帛，不能用来量门。", "首": "语义：“首”用于诗、歌等，与“关好了”的门不合。", "盏": "搭配：“盏”用于灯，“那盏门”不成立。"}, "sentence_index": 6, "correct_answer": "扇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "桌上放着一扇灯，很亮。", "explanation": "这里应该用〈盏〉。灯用“盏”计量，“扇”只用于门、窗、屏风等成扇的物体。"}, {"text": "他的床上放着一扇被子。", "explanation": "这里应该用〈床〉。被子用“床”计量，“扇”只用于门、窗、屏风等成扇的物体。"}, {"text": "墙上挂着一扇画。", "explanation": "这里应该用〈幅〉。画用“幅”计量，“扇”不能用于画。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd886a38-5bf1-4944-a671-17fe4416db10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87616, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "书房里有一扇木椅。", "corrected_sentence": "书房里有一扇木门。", "error_description": "错误形式：一扇木椅；正确形式：一扇木门。“扇”只量门、窗、屏风等成扇的物体，不能量椅子，椅子应用“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd886a38-5bf1-4944-a671-17fe4416db10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87616, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这扇铁锅很结实。", "corrected_sentence": "这扇铁门很结实。", "error_description": "错误形式：这扇铁锅；正确形式：这扇铁门。“扇”只量门、窗等成扇的物体，锅应用“口”（一口锅）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd886a38-5bf1-4944-a671-17fe4416db10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
