INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87617, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "走水是房子着火了的另一种说法。", "primary_collocate": null, "pronunciation": "zǒu shuǐ", "ipa": "tsoʊ˨˩˦ ʂweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "半夜隔壁仓库走水了，大家都跑出来。", "target_word": "走水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说王大爷家的厨房走水了。", "target_word": "走水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农家的草房突然走水了，村民们提着水桶赶来救火。", "target_word": "走水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书房走水后，那些旧书都烧没了。", "target_word": "走水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "庙里半夜走水，和尚们赶紧去救火。", "target_word": "走水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼上走水了，快打电话叫消防队！", "target_word": "走水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到有人喊走水了，大家马上拿水桶去救火。", "target_word": "走水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老房子里电线旧了，容易走水。", "target_word": "走水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天夜里村里走水，幸好没有人受伤。", "target_word": "走水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家的院子走水了，消防车很快就来了。", "target_word": "走水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "走水了", "label": "体标"}], "register": "书面", "sense_fingerprint": "房子着火的委婉说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9918d052-1adb-48b9-9d27-8bde39cc1f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87617, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "走水", "is_correct": true, "explanation": "正确。“走水”是房屋着火的婉称，用在仓库着火的句子里最自然。"}, {"text": "发烧", "is_correct": false, "explanation": "搭配：“发烧”说的是人的体温升高，仓库不能发烧。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：仓库半夜唱歌，与“大家都跑出来”的情境矛盾。"}, {"text": "结婚", "is_correct": false, "explanation": "搭配：“结婚”的主语必须是人，仓库不能结婚。"}], "explanations": {"走水": "正确。“走水”是房屋着火的婉称，用在仓库着火的句子里最自然。", "发烧": "搭配：“发烧”说的是人的体温升高，仓库不能发烧。", "唱歌": "语义：仓库半夜唱歌，与“大家都跑出来”的情境矛盾。", "结婚": "搭配：“结婚”的主语必须是人，仓库不能结婚。"}, "sentence_index": 0, "correct_answer": "走水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他擦枪时枪走水了，打伤了自己。", "explanation": "这里应该用〈走火〉。“走水”指房屋、仓库等着火，枪支意外发射要用“走火”。"}, {"text": "他昨天夜里走水了，被救护车送到了医院。", "explanation": "“走水”只用于房屋、仓库等着火，不能用于人。这里把它用在人身上，是误用。"}, {"text": "听了这个好消息，他的心里走水了，高兴得睡不着觉。", "explanation": "“走水”只指着火，不能用来形容心情。这里把它用于高兴，是误用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d9a46-2ba1-452a-b3c2-3285ff2ef274') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87617, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "走水", "is_correct": true, "explanation": "正确。这里的“走水”指着火，与“喊”的内容和“拿水桶去救火”的情境相符。"}, {"text": "下雪", "is_correct": false, "explanation": "语义：下雪不会让人急着拿水桶去救火，与救火的情境矛盾。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“有人喊生病了”与“拿水桶去救火”的情境不相符。"}, {"text": "跳舞", "is_correct": false, "explanation": "搭配：“跳舞”不能作为紧急事件的报警内容，“喊跳舞了”搭配不当。"}], "explanations": {"走水": "正确。这里的“走水”指着火，与“喊”的内容和“拿水桶去救火”的情境相符。", "下雪": "语义：下雪不会让人急着拿水桶去救火，与救火的情境矛盾。", "生病": "语义：“有人喊生病了”与“拿水桶去救火”的情境不相符。", "跳舞": "搭配：“跳舞”不能作为紧急事件的报警内容，“喊跳舞了”搭配不当。"}, "sentence_index": 6, "correct_answer": "走水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那只小狗走水了，跑得直喘气。", "explanation": "“走水”只用于房屋、仓库等着火，不能用于动物，这里的主语用错了。"}, {"text": "这次考试我的成绩一下子走水了，只考了三十分。", "explanation": "“走水”只指着火，不能用来说成绩下降，这里误用了词义。"}, {"text": "这个月的工资一下子走水了，全都花光了。", "explanation": "“走水”不能用于工资这样的钱款，这里误用了词义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d9a46-2ba1-452a-b3c2-3285ff2ef274') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87617, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜里老房子突然走水了了，邻居们都赶来帮忙。", "corrected_sentence": "夜里老房子突然走水了，邻居们都赶来帮忙。", "error_description": "“走水了”是一个整体，“了”只需一个。这里在“走水了”后面又多加了一个“了”，写成“走水了了”，是错误的。应说“走水了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d9a46-2ba1-452a-b3c2-3285ff2ef274') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87617, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "厨房突然把走水了，妈妈赶紧去救火。", "corrected_sentence": "厨房突然走水了，妈妈赶紧去救火。", "error_description": "“走水”是不及物动词，前面不能加“把”。应直接说“厨房走水了”，不能说“把走水了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d9a46-2ba1-452a-b3c2-3285ff2ef274') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
