INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87619, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "日报是每天都出一份的报纸。", "primary_collocate": null, "pronunciation": "rì bào", "ipa": "ɻ̩˥˩ pau̯˥˩", "syllable_count": 2, "sentences": [{"text": "爸爸每天早上看一份日报。", "target_word": "日报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份日报很便宜，只要两块钱。", "target_word": "日报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在日报上看到了这个新闻。", "target_word": "日报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校门口有卖日报的小店。", "target_word": "日报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在地铁站买了一份日报。", "target_word": "日报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份日报每天早上六点送到家。", "target_word": "日报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日报上的天气预报不太准。", "target_word": "日报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们订了一年的日报。", "target_word": "日报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷喜欢一边喝茶，一边看日报。", "target_word": "日报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日报今天登了一张很大的照片。", "target_word": "日报", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "日報", "label": "繁体"}], "register": "中性", "sense_fingerprint": "每天出一份的报纸", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4e62db1-d0f4-433b-9204-45f7851b2ab7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87619, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "周报", "is_correct": false, "explanation": "语义：“周报”是每周出版一次的报纸，与“每天早上”矛盾。"}, {"text": "早餐", "is_correct": false, "explanation": "搭配：“看”搭配的是读物，不能说“看一份早餐”，这里应是“吃”。"}, {"text": "处方", "is_correct": false, "explanation": "语义：“处方”是医生开给病人的用药单，不是每天出版的报纸。"}, {"text": "日报", "is_correct": true, "explanation": "“日报”是每天出一份的报纸，与“每天早上看一份”相符。"}], "explanations": {"周报": "语义：“周报”是每周出版一次的报纸，与“每天早上”矛盾。", "早餐": "搭配：“看”搭配的是读物，不能说“看一份早餐”，这里应是“吃”。", "处方": "语义：“处方”是医生开给病人的用药单，不是每天出版的报纸。", "日报": "“日报”是每天出一份的报纸，与“每天早上看一份”相符。"}, "sentence_index": 0, "correct_answer": "日报"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份日报每周五出一期，我每周五都去买。", "explanation": "这里应该用〈周报〉。日报是每天出版的，每周出一期要用周报。"}, {"text": "我昨天晚上一口气读完了日报的全部章节。", "explanation": "这里应该用〈小说〉。日报是报纸，按版面出版，没有章节；分章节的长篇故事是小说。"}, {"text": "我每天晚上在日报里写下当天的心情。", "explanation": "这里应该用〈日记〉。日报是每天出版的报纸，记录自己的心情要用日记，不能写在日报里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2e7a7e9-67bd-4f23-9898-ac5580120dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87619, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "字典", "is_correct": false, "explanation": "语义：字典不刊登天气预报，“字典上的天气预报”说不通。"}, {"text": "论文", "is_correct": false, "explanation": "语义：论文是学术文章，不会登天气预报，“论文上的天气预报”说不通。"}, {"text": "食谱", "is_correct": false, "explanation": "语义：食谱只登菜谱，不会有天气预报。"}, {"text": "日报", "is_correct": true, "explanation": "“日报”是报纸，报纸上可以刊登天气预报，与句意相符。"}], "explanations": {"字典": "语义：字典不刊登天气预报，“字典上的天气预报”说不通。", "论文": "语义：论文是学术文章，不会登天气预报，“论文上的天气预报”说不通。", "食谱": "语义：食谱只登菜谱，不会有天气预报。", "日报": "“日报”是报纸，报纸上可以刊登天气预报，与句意相符。"}, "sentence_index": 6, "correct_answer": "日报"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈收到一张日报，上面写着要付电费。", "explanation": "这里应该用〈账单〉。付款通知要用账单，日报是报纸，不会写付费信息。"}, {"text": "这台洗衣机的日报写得很详细。", "explanation": "这里应该用〈说明书〉。介绍机器用法的是说明书，日报是新闻报纸。"}, {"text": "服务员递给我一张日报，上面写着今天有哪些菜。", "explanation": "这里应该用〈菜单〉。餐厅让顾客点菜用的是菜单，日报是报纸，不列菜品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2e7a7e9-67bd-4f23-9898-ac5580120dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87619, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每天早上都买一个日报。", "corrected_sentence": "我每天早上都买一份日报。", "error_description": "量词错误：报纸应用“份”或“张”，不能用“个”。“一个日报”应改为“一份日报”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2e7a7e9-67bd-4f23-9898-ac5580120dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87619, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他常常在地铁上读一份日报们。", "corrected_sentence": "他常常在地铁上读一份日报。", "error_description": "词形错误：报纸是物品名词，不能加“们”表复数，“一份日报们”错误，应说“一份日报”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2e7a7e9-67bd-4f23-9898-ac5580120dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
