INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87621, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "讨论", "is_correct": false, "explanation": "与“破坏”无反义关系：“讨论”是交流意见的动作，与弄坏东西没有对立。"}, {"text": "修理", "is_correct": true, "explanation": "“修理”与“破坏”意义相反，指使东西恢复完好，正与“弄坏”相对。"}, {"text": "观察", "is_correct": false, "explanation": "与“破坏”无反义关系：“观察”是看的动作，与弄坏东西没有对立。"}, {"text": "参加", "is_correct": false, "explanation": "与“破坏”无反义关系：“参加”与损坏东西没有对立。"}], "correct_answer": "修理", "explanations": {"讨论": "与“破坏”无反义关系：“讨论”是交流意见的动作，与弄坏东西没有对立。", "修理": "“修理”与“破坏”意义相反，指使东西恢复完好，正与“弄坏”相对。", "观察": "与“破坏”无反义关系：“观察”是看的动作，与弄坏东西没有对立。", "参加": "与“破坏”无反义关系：“参加”与损坏东西没有对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87621, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "旅行", "is_correct": false, "explanation": "与“破坏”无反义关系：“旅行”与损坏东西没有对立。"}, {"text": "修补", "is_correct": true, "explanation": "“修补”与“破坏”意义相反，指把破损的东西补好，正与“米袋被破坏”相对。"}, {"text": "唱歌", "is_correct": false, "explanation": "与“破坏”无反义关系：“唱歌”与损坏东西没有对立。"}, {"text": "游泳", "is_correct": false, "explanation": "与“破坏”无反义关系：“游泳”与损坏东西没有对立。"}], "correct_answer": "修补", "explanations": {"旅行": "与“破坏”无反义关系：“旅行”与损坏东西没有对立。", "修补": "“修补”与“破坏”意义相反，指把破损的东西补好，正与“米袋被破坏”相对。", "唱歌": "与“破坏”无反义关系：“唱歌”与损坏东西没有对立。", "游泳": "与“破坏”无反义关系：“游泳”与损坏东西没有对立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87621, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "破坏是把东西弄坏，让它不好了。", "primary_collocate": null, "pronunciation": "pò huài", "ipa": "pʰwo˥˩ xwai˥˩", "syllable_count": 2, "sentences": [{"text": "弟弟又破坏了我的玩具。", "target_word": "破坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗破坏了新买的沙发。", "target_word": "破坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们破坏了花园里的花。", "target_word": "破坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁破坏了教室里的桌子？", "target_word": "破坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生气的时候，会破坏身边的东西。", "target_word": "破坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要破坏图书馆的书。", "target_word": "破坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只小猫破坏了妈妈的窗帘。", "target_word": "破坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥破坏了我刚做好的模型。", "target_word": "破坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子常常破坏家里的东西。", "target_word": "破坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老鼠破坏了我们家的米袋。", "target_word": "破坏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "破坏了", "label": "体标"}, {"form": "破坏过", "label": "体标"}, {"form": "破坏者", "label": "复合"}, {"form": "破壞", "label": "繁体"}], "register": "通用", "sense_fingerprint": "破坏|把东西弄坏|玩具桌子花瓶", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '117b498c-ddd5-4e59-81b8-2a4e87b7131e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87621, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：“吃”的宾语应是食物，玩具不能被吃。"}, {"text": "破坏", "is_correct": true, "explanation": "“破坏”表示把玩具弄坏，与“弟弟又……了我的玩具”的语境相符。"}, {"text": "喂", "is_correct": false, "explanation": "语义：“喂”的对象应是人或动物，玩具不能被喂。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，不能带“玩具”作宾语。"}], "explanations": {"吃": "语义：“吃”的宾语应是食物，玩具不能被吃。", "破坏": "“破坏”表示把玩具弄坏，与“弟弟又……了我的玩具”的语境相符。", "喂": "语义：“喂”的对象应是人或动物，玩具不能被喂。", "散步": "配价：“散步”是不及物动词，不能带“玩具”作宾语。"}, "sentence_index": 0, "correct_answer": "破坏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那只猫破坏了路过的老人。", "explanation": "这里应该用〈伤害〉。破坏的对象是东西，不能用于人身，伤害人要用伤害。"}, {"text": "他破坏了这次会议的主持人。", "explanation": "这里应该用〈担任〉。主持人是人，“破坏”只用于把东西弄坏；担任主持要用担任。"}, {"text": "他破坏了这次比赛的纪录。", "explanation": "这里应该用〈打破〉。纪录这类成绩要用打破，破坏只用于使具体东西受损。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87621, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放弃", "is_correct": false, "explanation": "搭配：“放弃”多接机会、梦想，不能接“窗帘”作宾语。"}, {"text": "破坏", "is_correct": true, "explanation": "“破坏”表示小猫把窗帘弄坏，符合句意。"}, {"text": "唱", "is_correct": false, "explanation": "配价：“唱”不能带“窗帘”作宾语。"}, {"text": "想象", "is_correct": false, "explanation": "语义：小猫不会“想象”，且“想象”不接“窗帘”这类宾语。"}], "explanations": {"放弃": "搭配：“放弃”多接机会、梦想，不能接“窗帘”作宾语。", "破坏": "“破坏”表示小猫把窗帘弄坏，符合句意。", "唱": "配价：“唱”不能带“窗帘”作宾语。", "想象": "语义：小猫不会“想象”，且“想象”不接“窗帘”这类宾语。"}, "sentence_index": 6, "correct_answer": "破坏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他破坏了这次比赛的冠军。", "explanation": "这里应该用〈获得〉。冠军是荣誉，不能被破坏；夺得冠军要用获得。"}, {"text": "我们破坏了这个问题的答案。", "explanation": "这里应该用〈得出〉。答案是通过思考得出的，不能说被破坏。"}, {"text": "她破坏了昨天的天气。", "explanation": "这里应该用〈改变〉。天气是自然现象，不是可以被弄坏的东西；说天气发生变化要用改变，不能用破坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87621, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子不小心被破坏了家里的台灯。", "corrected_sentence": "孩子不小心破坏了家里的台灯。", "error_description": "错误：“被”不能加在施事“孩子”前面。“破坏”的施事应直接作主语，应说“孩子不小心破坏了家里的台灯”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87621, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我没有破坏了你的玩具。", "corrected_sentence": "我没有破坏你的玩具。", "error_description": "错误：“没有”否定动作后不能再加“了”。正确形式是“没有破坏你的玩具”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87622, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "旅行", "is_correct": false, "explanation": "与“破坏”无反义关系：“旅行”与损坏事物没有对立。"}, {"text": "维护", "is_correct": true, "explanation": "“维护”与“破坏”意义相反，指保护使其完好，正与“破坏友谊”相对。"}, {"text": "观察", "is_correct": false, "explanation": "与“破坏”无反义关系：“观察”是看的动作，与毁坏没有对立。"}, {"text": "吃饭", "is_correct": false, "explanation": "与“破坏”无反义关系：“吃饭”与损坏事物没有对立。"}], "correct_answer": "维护", "explanations": {"旅行": "与“破坏”无反义关系：“旅行”与损坏事物没有对立。", "维护": "“维护”与“破坏”意义相反，指保护使其完好，正与“破坏友谊”相对。", "观察": "与“破坏”无反义关系：“观察”是看的动作，与毁坏没有对立。", "吃饭": "与“破坏”无反义关系：“吃饭”与损坏事物没有对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87622, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87622, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使事物受到损坏；毁坏。", "primary_collocate": null, "pronunciation": "pò huài", "ipa": "pʰwo˥˩ xwai˥˩", "syllable_count": 2, "sentences": [{"text": "大雨破坏了河边的小路。", "target_word": "破坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂排出的脏水破坏了环境。", "target_word": "破坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争破坏了这个国家的和平。", "target_word": "破坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的坏话破坏了我们的友谊。", "target_word": "破坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要破坏公园里的花草。", "target_word": "破坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震破坏了很多老房子。", "target_word": "破坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场大火破坏了整座山的树林。", "target_word": "破坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想破坏大家的好心情。", "target_word": "破坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乱扔垃圾会破坏城市的样子。", "target_word": "破坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的同事破坏了我们的计划。", "target_word": "破坏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "破坏了", "label": "体标"}, {"form": "破坏过", "label": "体标"}, {"form": "破坏者", "label": "复合"}, {"form": "破壞", "label": "繁体"}], "register": "通用", "sense_fingerprint": "破坏|使事物受损|环境和平关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '117b498c-ddd5-4e59-81b8-2a4e87b7131e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87622, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "修建", "is_correct": false, "explanation": "语义：“修建”指有意识地建造，大雨不能修建小路。"}, {"text": "破坏", "is_correct": true, "explanation": "“破坏”表示使河边的小路受损，与大雨造成的后果相符。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，不能带“小路”作宾语。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”的主语须是能感知美的人，大雨不能欣赏小路。"}], "explanations": {"修建": "语义：“修建”指有意识地建造，大雨不能修建小路。", "破坏": "“破坏”表示使河边的小路受损，与大雨造成的后果相符。", "散步": "配价：“散步”是不及物动词，不能带“小路”作宾语。", "欣赏": "语义：“欣赏”的主语须是能感知美的人，大雨不能欣赏小路。"}, "sentence_index": 0, "correct_answer": "破坏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他破坏了世界纪录。", "explanation": "这里应该用〈打破〉。破坏指使具体事物或关系受损，纪录这类成绩要用打破。"}, {"text": "那只狗破坏了路过的孩子。", "explanation": "这里应该用〈伤害〉。破坏的对象是事物或关系，不能用于人身，伤害人要用伤害。"}, {"text": "他破坏了这位老人的年龄。", "explanation": "这里应该用〈增长〉。年龄不是可以被弄坏的事物，表示年龄增加要用增长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87622, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "种植", "is_correct": false, "explanation": "语义：“种植”需要有人有意栽培，大火不能种植树林。"}, {"text": "破坏", "is_correct": true, "explanation": "“破坏”表示使整座山的树林受损，与大火造成的后果相符。"}, {"text": "散发", "is_correct": false, "explanation": "搭配：“散发”多接气味、热量，不能接“树林”作宾语。"}, {"text": "开放", "is_correct": false, "explanation": "语义：“开放”指向人敞开场所，大火不能开放树林。"}], "explanations": {"种植": "语义：“种植”需要有人有意栽培，大火不能种植树林。", "破坏": "“破坏”表示使整座山的树林受损，与大火造成的后果相符。", "散发": "搭配：“散发”多接气味、热量，不能接“树林”作宾语。", "开放": "语义：“开放”指向人敞开场所，大火不能开放树林。"}, "sentence_index": 6, "correct_answer": "破坏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "为了让这座桥更稳固，工程队每天都在破坏它的桥墩。", "explanation": "这里应该用〈加固〉。破坏是使事物受损，与“让桥更稳固”的目的正相反；使结构更牢固要用加固。"}, {"text": "他破坏了这次比赛的冠军。", "explanation": "这里应该用〈获得〉。冠军是荣誉，不能被破坏；夺得冠军要用获得。"}, {"text": "我们破坏了这个问题的答案。", "explanation": "这里应该用〈得出〉。答案是通过思考得出的，不能说被破坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87622, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场台风把很多老房子破坏。", "corrected_sentence": "这场台风把很多老房子破坏了。", "error_description": "错误：“把”字句中的动词不能单独出现在句末，后面要带其他成分，如动态助词“了”或结果补语。应说“把很多老房子破坏了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87622, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我没有破坏了你的东西。", "corrected_sentence": "我没有破坏你的东西。", "error_description": "错误：“没有”否定动作后不能再加“了”。正确形式是“没有破坏你的东西”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
