INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87623, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "技术知识是做一件事要会的办法和道理。", "primary_collocate": null, "pronunciation": "jì shù zhī shi", "ipa": "tɕi˥˩ ʂu˥˩ ʈʂɨ˥ ʂɨ", "syllable_count": 4, "sentences": [{"text": "做这个工作要先学会基本的技术知识。", "target_word": "技术知识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种菜也有技术知识，不是随便种的。", "target_word": "技术知识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不懂技术知识，所以做不好这件事。", "target_word": "技术知识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅一边做，一边教我们技术知识。", "target_word": "技术知识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想做好蛋糕，要懂得一些技术知识。", "target_word": "技术知识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项工作的技术知识很多，要慢慢学。", "target_word": "技术知识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学游泳，先要掌握换气的技术知识。", "target_word": "技术知识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她会做家具，因为她懂木工的技术知识。", "target_word": "技术知识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有力气，没有技术知识，也做不好。", "target_word": "技术知识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷把修车的技术知识都教给了我。", "target_word": "技术知识", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "些", "label": "量词"}], "register": "中性", "sense_fingerprint": "做一件事要会的办法和道理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4002be13-b123-4b4b-8667-dd242372d8ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87623, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "技术知识", "is_correct": true, "explanation": "技术知识：做一件事要会的办法和道理，与“学会基本的”的语境相合。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：“学会”后接的是可掌握的技能或知识，不能说“学会感情”。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：“玩具”是游戏用品，不是做工作需要学会的内容。"}, {"text": "收入", "is_correct": false, "explanation": "语义：“收入”是钱款，不能作为要“学会”的内容，与“基本的”语境不合。"}], "explanations": {"技术知识": "技术知识：做一件事要会的办法和道理，与“学会基本的”的语境相合。", "感情": "搭配：“学会”后接的是可掌握的技能或知识，不能说“学会感情”。", "玩具": "语义：“玩具”是游戏用品，不是做工作需要学会的内容。", "收入": "语义：“收入”是钱款，不能作为要“学会”的内容，与“基本的”语境不合。"}, "sentence_index": 0, "correct_answer": "技术知识"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他懂一把修车的技术知识。", "explanation": "这里应该用〈些〉。“把”用于有柄或可握的器具，不能用来数抽象的“知识”。"}, {"text": "他做饭的技术知识很熟练。", "explanation": "这里应该用〈技能〉。“熟练”形容动作和能力，知识不能说熟练。"}, {"text": "这位师傅学了一部木工的技术知识。", "explanation": "这里应该用〈些〉。“部”用于书籍、影片、机器等，不能用来数“知识”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87623, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "技术知识", "is_correct": true, "explanation": "技术知识：做一件事要会的办法和道理，与“学游泳”“换气”的语境相合。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：“音乐”与“换气”没有关系，不符合学游泳的语境。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”与“换气”没有关系，不能作为游泳要掌握的内容。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：“掌握”后不能接“礼物”这类实物，“掌握换气的礼物”说不通。"}], "explanations": {"技术知识": "技术知识：做一件事要会的办法和道理，与“学游泳”“换气”的语境相合。", "音乐": "语义：“音乐”与“换气”没有关系，不符合学游泳的语境。", "颜色": "语义：“颜色”与“换气”没有关系，不能作为游泳要掌握的内容。", "礼物": "搭配：“掌握”后不能接“礼物”这类实物，“掌握换气的礼物”说不通。"}, "sentence_index": 6, "correct_answer": "技术知识"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爷爷教了我一束修车的技术知识。", "explanation": "这里应该用〈些〉。“束”用于花、光线等成束的东西，不能用来数“知识”。"}, {"text": "爷爷教了我一座修车的技术知识。", "explanation": "这里应该用〈些〉。“座”用于山、桥、房屋等大型固定物，不能用来数“知识”。"}, {"text": "爷爷教了我一杯修车的技术知识。", "explanation": "这里应该用〈些〉。“杯”用于盛装液体的容器，不能用来数抽象的“知识”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87623, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他学了一块技术知识。", "corrected_sentence": "他学了一点技术知识。", "error_description": "错误：量词“块”用于块状的实物，不能用来数抽象的“知识”。应说“一点技术知识”，“点”表示少量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87623, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他学了过修车的技术知识。", "corrected_sentence": "他学过修车的技术知识。", "error_description": "错误：“了”和“过”不能同时用在动词“学”后。表示有过这种经历时只用“过”，应说“学过修车的技术知识”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
