INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87624, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "与某种技术相关的专门知识。", "primary_collocate": null, "pronunciation": "jì shù zhī shi", "ipa": "tɕi˥˩ ʂu˥˩ ʈʂɨ˥ ʂɨ", "syllable_count": 4, "sentences": [{"text": "他有很多电脑方面的技术知识。", "target_word": "技术知识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修飞机需要很多技术知识。", "target_word": "技术知识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们每周都要学习新的技术知识。", "target_word": "技术知识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有技术知识，就不能修这台机器。", "target_word": "技术知识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了一些手机的技术知识。", "target_word": "技术知识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对汽车的技术知识了解得很多。", "target_word": "技术知识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司请专家来讲网络技术知识。", "target_word": "技术知识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书介绍了很多农业技术知识。", "target_word": "技术知识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的技术知识很丰富，大家都来问她。", "target_word": "技术知识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有学过技术知识，所以不会修电视。", "target_word": "技术知识", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "些", "label": "量词"}], "register": "中性", "sense_fingerprint": "与某种技术相关的专门知识", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4002be13-b123-4b4b-8667-dd242372d8ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87624, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "技术知识", "is_correct": true, "explanation": "技术知识：与某种技术相关的专门知识，与“电脑方面的”语境相合。"}, {"text": "美食", "is_correct": false, "explanation": "语义：“美食”属饮食，与“电脑方面的”语境不合。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”是物理量，与“电脑方面的”不能构成可以拥有的知识。"}, {"text": "诗词", "is_correct": false, "explanation": "语义：“诗词”属文学作品，与“电脑方面的”内容不合。"}], "explanations": {"技术知识": "技术知识：与某种技术相关的专门知识，与“电脑方面的”语境相合。", "美食": "语义：“美食”属饮食，与“电脑方面的”语境不合。", "温度": "语义：“温度”是物理量，与“电脑方面的”不能构成可以拥有的知识。", "诗词": "语义：“诗词”属文学作品，与“电脑方面的”内容不合。"}, "sentence_index": 0, "correct_answer": "技术知识"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他学会了一块技术知识。", "explanation": "这里应该用〈些〉。“块”用于块状的实物，不能用来数抽象的“知识”。"}, {"text": "他每天都在打扫修车的技术知识。", "explanation": "这里应该用〈整理〉。“打扫”用于地面、房间等有形场所，不能用来处理抽象的知识；“整理”才适合知识。"}, {"text": "他学了一台技术知识。", "explanation": "这里应该用〈些〉。“台”用于机器、设备，不能用来数“知识”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87624, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "技术知识", "is_correct": true, "explanation": "技术知识：与某种技术相关的专门知识，可以由专家讲授，与“网络”的语境相合。"}, {"text": "家具", "is_correct": false, "explanation": "语义：“家具”是生活用品，不能作为“讲”的内容，与“网络”的语境不合。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：“早餐”属饮食，与“网络”的技术语境不合。"}, {"text": "盆栽", "is_correct": false, "explanation": "搭配：“讲”后面不能接“盆栽”这类实物，说不通。"}], "explanations": {"技术知识": "技术知识：与某种技术相关的专门知识，可以由专家讲授，与“网络”的语境相合。", "家具": "语义：“家具”是生活用品，不能作为“讲”的内容，与“网络”的语境不合。", "早餐": "语义：“早餐”属饮食，与“网络”的技术语境不合。", "盆栽": "搭配：“讲”后面不能接“盆栽”这类实物，说不通。"}, "sentence_index": 6, "correct_answer": "技术知识"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他学了一部技术知识，所以会修电视。", "explanation": "这里应该用〈些〉。“部”用于书籍、影片、机器等，不能用来数“知识”。"}, {"text": "他学了一张技术知识，所以会修电视。", "explanation": "这里应该用〈些〉。“张”用于纸张、床等平面的物件，不能用来数“知识”。"}, {"text": "他学了一位技术知识，所以会修电视。", "explanation": "这里应该用〈些〉。“位”用于人，不能用来数抽象的“知识”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87624, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他学了一只技术知识。", "corrected_sentence": "他学了一些技术知识。", "error_description": "错误：量词“只”用于动物或单件器物，不能用来数抽象的“知识”。应说“一些技术知识”，“些”表示不确定的少量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87624, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他学了一条技术知识。", "corrected_sentence": "他学了不少技术知识。", "error_description": "错误：量词“条”用于细长的物件，不能用来数抽象的“技术知识”。应说“学了不少技术知识”，用“不少”表示数量多。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
