INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87625, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "车钱是坐车要付的钱。", "primary_collocate": null, "pronunciation": "chē qián", "ipa": "ʈʂʰɤ˥ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "我身上没带车钱，只好走路回家。", "target_word": "车钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸给了我十块钱当车钱。", "target_word": "车钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐出租车的车钱太贵了。", "target_word": "车钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把车钱放在口袋里了。", "target_word": "车钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子问妈妈要车钱去学校。", "target_word": "车钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的车钱我来付吧。", "target_word": "车钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每天上班的车钱要二十块。", "target_word": "车钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她忘了带车钱，请朋友帮忙。", "target_word": "车钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去机场的车钱比我想的便宜。", "target_word": "车钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先把车钱给司机吧。", "target_word": "车钱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "車錢", "label": "繁体"}], "register": "口语", "sense_fingerprint": "坐车时要付给司机或车站的钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f4e257c-d76d-447e-870c-0909fbaadfdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87625, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "车钱", "is_correct": true, "explanation": "正确。“车钱”是坐车要付的钱，随身带着的就是它。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“带”用于随身物品，身体器官不能说“身上带”。"}, {"text": "故事", "is_correct": false, "explanation": "语义：“故事”不是可以随身携带的东西，这里说不通。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”不能带在身上，句子说不通。"}], "explanations": {"车钱": "正确。“车钱”是坐车要付的钱，随身带着的就是它。", "眼睛": "搭配：“带”用于随身物品，身体器官不能说“身上带”。", "故事": "语义：“故事”不是可以随身携带的东西，这里说不通。", "名字": "语义：“名字”不能带在身上，句子说不通。"}, "sentence_index": 0, "correct_answer": "车钱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在售票处买了一张车钱。", "explanation": "这里应该用〈车票〉。买票买到的是“车票”，“车钱”是付出去的钱，不能这样说。"}, {"text": "他把车钱停在路边了。", "explanation": "这里应该用〈车子〉。“车子”可以停放，“车钱”是钱，不能停在路边。"}, {"text": "汽车的车钱坏了，开不动了。", "explanation": "这里应该用〈车轮〉。车轮坏了车才开不动，“车钱”是坐车要付的钱，不会坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67457b36-9b08-436a-8906-a17e34b2c92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87625, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "车钱", "is_correct": true, "explanation": "正确。“每天上班的车钱”指坐车上班要付的钱。"}, {"text": "房租", "is_correct": false, "explanation": "语义：房租按月计算，不随每天上班而定。"}, {"text": "水费", "is_correct": false, "explanation": "语义：水费与上班无关，这里说不通。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“上班的手机”不是要付的费用，不能说“要二十块”。"}], "explanations": {"车钱": "正确。“每天上班的车钱”指坐车上班要付的钱。", "房租": "语义：房租按月计算，不随每天上班而定。", "水费": "语义：水费与上班无关，这里说不通。", "手机": "搭配：“上班的手机”不是要付的费用，不能说“要二十块”。"}, "sentence_index": 6, "correct_answer": "车钱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天都要用车钱开门。", "explanation": "这里应该用〈车钥匙〉。开门要用钥匙，“车钱”是付车费的钱，不能用来开门。"}, {"text": "这辆车的车钱号很好记。", "explanation": "这里应该用〈车牌〉。车牌上有号码，“车钱”是钱，不能用来编号。"}, {"text": "我在车钱里睡着了。", "explanation": "这里应该用〈车厢〉。人可以坐在车厢里，“车钱”是钱，人不能在里面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67457b36-9b08-436a-8906-a17e34b2c92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87625, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我付着车钱，就下车了。", "corrected_sentence": "我付了车钱，就下车了。", "error_description": "动作已经完成要用“了”，“着”表示动作持续，这里应说“付了车钱”，不能说“付着车钱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67457b36-9b08-436a-8906-a17e34b2c92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87625, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天没付了车钱。", "corrected_sentence": "我昨天没付车钱。", "error_description": "否定过去的动作用“没”，后面不能再加“了”，应说“没付车钱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67457b36-9b08-436a-8906-a17e34b2c92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87627, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "逐渐", "is_correct": true, "explanation": "反义：「突然」表示很快发生，「逐渐」表示慢慢发展，二者意思相对。"}, {"text": "偶尔", "is_correct": false, "explanation": "与「突然」不构成反义关系，「偶尔」表示次数少，与发生的快慢无关。"}, {"text": "一直", "is_correct": false, "explanation": "与「突然」不构成反义关系，「一直」表示持续，与发生的快慢无关。"}, {"text": "已经", "is_correct": false, "explanation": "与「突然」不构成反义关系，「已经」表示已经完成，与「突然」没有对立关系。"}], "correct_answer": "逐渐", "explanations": {"逐渐": "反义：「突然」表示很快发生，「逐渐」表示慢慢发展，二者意思相对。", "偶尔": "与「突然」不构成反义关系，「偶尔」表示次数少，与发生的快慢无关。", "一直": "与「突然」不构成反义关系，「一直」表示持续，与发生的快慢无关。", "已经": "与「突然」不构成反义关系，「已经」表示已经完成，与「突然」没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87627, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "逐渐", "is_correct": true, "explanation": "反义：「突然」表示很快发生，「逐渐」表示慢慢发展，二者意思相对。"}, {"text": "常常", "is_correct": false, "explanation": "与「突然」不构成反义关系，「常常」表示经常发生，与发生的快慢无关。"}, {"text": "曾经", "is_correct": false, "explanation": "与「突然」不构成反义关系，「曾经」指过去的经历，与之没有对立关系。"}, {"text": "总是", "is_correct": false, "explanation": "与「突然」不构成反义关系，「总是」表示一直如此，与发生的快慢无关。"}], "correct_answer": "逐渐", "explanations": {"逐渐": "反义：「突然」表示很快发生，「逐渐」表示慢慢发展，二者意思相对。", "常常": "与「突然」不构成反义关系，「常常」表示经常发生，与发生的快慢无关。", "曾经": "与「突然」不构成反义关系，「曾经」指过去的经历，与之没有对立关系。", "总是": "与「突然」不构成反义关系，「总是」表示一直如此，与发生的快慢无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87627, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "property", "definition": "突然是事情很快发生，没有想到。", "primary_collocate": null, "pronunciation": "tū rán", "ipa": "tʰu˥ ɻan˧˥", "syllable_count": 2, "sentences": [{"text": "天突然黑了。", "target_word": "突然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他突然哭了。", "target_word": "突然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们正在吃饭，电灯突然灭了。", "target_word": "突然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车突然停在路中间。", "target_word": "突然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨突然下得很大。", "target_word": "突然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子突然跑了出来。", "target_word": "突然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我走着走着，突然听到有人叫我。", "target_word": "突然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋里突然安静了。", "target_word": "突然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他突然站起来，走了出去。", "target_word": "突然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师突然问我一个问题。", "target_word": "突然", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "突然间", "label": "复合"}], "register": "通用", "sense_fingerprint": "放在动词前，说动作或事情很快发生，事先没有想到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcccfa74-1e16-4e92-abd1-a3b542c01668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87627, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "突然", "is_correct": true, "explanation": "正确：「突然」表示事情在短时间内发生而没有预料，与「天突然黑了」的变化相符。"}, {"text": "故意", "is_correct": false, "explanation": "语义：「故意」指有意去做某事，天不会有意变黑，这里讲不通。"}, {"text": "一直", "is_correct": false, "explanation": "体貌：「一直」表示持续不断，与「黑了」这种一次完成的变化不搭配。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：「从来」多与否定或经历搭配，不说「天从来黑了」。"}], "explanations": {"突然": "正确：「突然」表示事情在短时间内发生而没有预料，与「天突然黑了」的变化相符。", "故意": "语义：「故意」指有意去做某事，天不会有意变黑，这里讲不通。", "一直": "体貌：「一直」表示持续不断，与「黑了」这种一次完成的变化不搭配。", "从来": "搭配：「从来」多与否定或经历搭配，不说「天从来黑了」。"}, "sentence_index": 0, "correct_answer": "突然"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他突然学习了三年德语。", "explanation": "这里把〈突然〉当成了〈长期〉的意思。〈突然〉指事情在短时间内出人意料地发生，不能用来描述持续三年的学习。"}, {"text": "他突然一点一点地长高了。", "explanation": "这里把〈突然〉当成了〈逐渐〉的意思。〈突然〉指事情很快发生，〈逐渐〉指缓慢的变化过程，二者矛盾，这个词不这么用。"}, {"text": "这辆车突然慢慢地开过去。", "explanation": "这里把〈突然〉当成了〈缓缓〉的意思，表示慢慢行进。〈突然〉指动作很快出现，二者不能同时描述同一个动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87627, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "突然", "is_correct": true, "explanation": "正确：「突然」表示没有预料地发生，与「听到有人叫我」的情境一致。"}, {"text": "只好", "is_correct": false, "explanation": "语义：「只好」表示没有别的选择才这样做，听到叫声不是被迫的，不合语境。"}, {"text": "白白", "is_correct": false, "explanation": "语义：「白白」表示徒然、没有收获，与「听到有人叫我」的意思不符。"}, {"text": "大声", "is_correct": false, "explanation": "语义：「大声」修饰说话、叫喊等发声动作，不能修饰「听到」，这里讲不通。"}], "explanations": {"突然": "正确：「突然」表示没有预料地发生，与「听到有人叫我」的情境一致。", "只好": "语义：「只好」表示没有别的选择才这样做，听到叫声不是被迫的，不合语境。", "白白": "语义：「白白」表示徒然、没有收获，与「听到有人叫我」的意思不符。", "大声": "语义：「大声」修饰说话、叫喊等发声动作，不能修饰「听到」，这里讲不通。"}, "sentence_index": 6, "correct_answer": "突然"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们按计划突然出发了。", "explanation": "这里把〈突然〉当成了〈立即〉的意思。〈突然〉指事先没有想到的事情发生，而这里说的是事先安排好的出发，二者矛盾。"}, {"text": "他每天晚上都突然打电话回家。", "explanation": "这里把〈突然〉当成了〈经常〉的意思。〈突然〉指事情出人意料地一次发生，〈经常〉指反复发生，每天都做的事不能说突然。"}, {"text": "我提前一周通知了大家，突然开了会。", "explanation": "这里把〈突然〉当成了〈临时〉的意思。〈临时〉指事先没有安排、临时决定，而这里会议已提前一周通知，二者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87627, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她突然的笑了。", "corrected_sentence": "她突然笑了。", "error_description": "错误：「突然」修饰动词时不加「的」。「突然的」是定语形式，只能修饰名词（如「突然的大雨」）；这里应说「突然笑了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87627, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨很突然停了。", "corrected_sentence": "雨突然停了。", "error_description": "错误：「突然」直接修饰动词时不带程度副词；「很突然」后面直接跟动词「停了」不成立（若用「很突然」须加「地」）。这里应说「雨突然停了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
