INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87628, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "在短时间内发生而出乎意料。", "primary_collocate": null, "pronunciation": "tū rán", "ipa": "tʰu˥ ɻan˧˥", "syllable_count": 2, "sentences": [{"text": "这件事太突然了。", "target_word": "突然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的离开很突然。", "target_word": "突然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气变化得很突然。", "target_word": "突然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个消息来得很突然。", "target_word": "突然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "突然的大雨让我们措手不及。", "target_word": "突然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这样问，我觉得有点突然。", "target_word": "突然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情发生得太突然，我没准备好。", "target_word": "突然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走得很突然，大家都很难过。", "target_word": "突然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个决定不算突然。", "target_word": "突然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛的结果很突然，谁也没想到。", "target_word": "突然", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "突然间", "label": "复合"}], "register": "通用", "sense_fingerprint": "作谓语或定语，说事情来得太快、出乎意料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcccfa74-1e16-4e92-abd1-a3b542c01668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87628, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "突然", "is_correct": true, "explanation": "正确：「突然」形容事情来得快、出乎意料，与「这件事太突然了」一致。"}, {"text": "安静", "is_correct": false, "explanation": "语义：「安静」形容环境或人的状态，不能用来形容事情，这里讲不通。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：「潮湿」形容物体或空气所含水分多，不能用来形容事情，这里讲不通。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：「明亮」指光线充足或颜色鲜亮，与事情的性质无关。"}], "explanations": {"突然": "正确：「突然」形容事情来得快、出乎意料，与「这件事太突然了」一致。", "安静": "语义：「安静」形容环境或人的状态，不能用来形容事情，这里讲不通。", "潮湿": "语义：「潮湿」形容物体或空气所含水分多，不能用来形容事情，这里讲不通。", "明亮": "语义：「明亮」指光线充足或颜色鲜亮，与事情的性质无关。"}, "sentence_index": 0, "correct_answer": "突然"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个消息来得很突然，因为我已经期待了三年。", "explanation": "这里把〈突然〉当成了〈迅速〉的意思。〈突然〉指事情出人意料地发生，与已经期待三年的情况相矛盾；〈迅速〉只说速度快。"}, {"text": "这个建议来得很突然，我早就准备了很久。", "explanation": "这里把〈突然〉当成了〈预料之中〉的意思。〈突然〉指事先没有想到，而这里说早已准备好，二者矛盾。"}, {"text": "这个答案很突然，我早就想到了。", "explanation": "这里把〈突然〉当成了〈预见〉的意思。〈突然〉指事先没有想到，〈预见〉指事先料到，二者正好相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87628, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "突然", "is_correct": true, "explanation": "正确：「突然」形容事情发生得快、没有预料，与「我没准备好」相呼应。"}, {"text": "清楚", "is_correct": false, "explanation": "语义：「清楚」指明白、分明，事情发生得清楚并不会让人没有准备，讲不通。"}, {"text": "整齐", "is_correct": false, "explanation": "搭配：「整齐」形容排列规整，「发生」不能与「整齐」搭配，不说「发生得整齐」。"}, {"text": "干净", "is_correct": false, "explanation": "语义：「干净」形容清洁，与事情的发生方式无关，这里不合语境。"}], "explanations": {"突然": "正确：「突然」形容事情发生得快、没有预料，与「我没准备好」相呼应。", "清楚": "语义：「清楚」指明白、分明，事情发生得清楚并不会让人没有准备，讲不通。", "整齐": "搭配：「整齐」形容排列规整，「发生」不能与「整齐」搭配，不说「发生得整齐」。", "干净": "语义：「干净」形容清洁，与事情的发生方式无关，这里不合语境。"}, "sentence_index": 6, "correct_answer": "突然"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的离开很突然，所以他提前两周订好了机票。", "explanation": "这里把〈突然〉当成了〈计划〉的意思。〈突然〉指事情出人意料地发生，而提前两周订票说明早有安排，二者矛盾。"}, {"text": "这个决定很突然，大家讨论了一个月才做出。", "explanation": "这里误把〈突然〉当成了〈重大〉的意思。〈突然〉指事情出人意料地发生，与讨论一个月才做出的决定相矛盾。"}, {"text": "天气变化得很突然，它却是一点点慢慢形成的。", "explanation": "这里把〈突然〉当成了〈逐渐〉的意思。〈突然〉指事情很快发生，〈逐渐〉指缓慢形成的过程，二者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87628, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场雨下得很突然极了。", "corrected_sentence": "这场雨下得很突然。", "error_description": "错误：「很」和「极了」都表示程度，不能同时修饰「突然」。应说「这场雨下得很突然」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87628, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她来得很突然地。", "corrected_sentence": "她来得很突然。", "error_description": "错误：「很突然」作补语时后面不加「地」。应说「她来得很突然」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
