INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87629, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "按天是一天一天地算，每一天都算一次。", "primary_collocate": null, "pronunciation": "àn tiān", "ipa": "an˥˩ tʰjɛn˥", "syllable_count": 2, "sentences": [{"text": "银行的利息是按天算的，每天都不一样。", "target_word": "按天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告的数字是按天更新的。", "target_word": "按天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔钱按天增加利息。", "target_word": "按天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师按天记录学生的进步。", "target_word": "按天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂按天统计每个工人的产量。", "target_word": "按天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的营业额是按天算的，每天都有报表。", "target_word": "按天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司按天计算迟到的次数。", "target_word": "按天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔贷款的利息按天累计，不是按月。", "target_word": "按天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他按天写日记，一天都没有停过。", "target_word": "按天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他按天检查数据，每天都不漏掉。", "target_word": "按天", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一天一天地逐日计算", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1eb026d-f55f-4628-a2a2-eaf33fe1d183') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87629, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "按天", "is_correct": true, "explanation": "按天：一天一天地计算利息，与“每天都不一样”相符。"}, {"text": "一律", "is_correct": false, "explanation": "语义：“一律”表示全都一样，与“每天都不一样”相矛盾。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“每天都不一样”相矛盾。"}, {"text": "按月", "is_correct": false, "explanation": "搭配：按月结算的周期与“每天都不一样”的说法不搭。"}], "explanations": {"按天": "按天：一天一天地计算利息，与“每天都不一样”相符。", "一律": "语义：“一律”表示全都一样，与“每天都不一样”相矛盾。", "偶尔": "语义：“偶尔”表示不常发生，与“每天都不一样”相矛盾。", "按月": "搭配：按月结算的周期与“每天都不一样”的说法不搭。"}, "sentence_index": 0, "correct_answer": "按天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他按天爱上了那个城市。", "explanation": "这里应该用〈忽然〉。按天是逐日计算或记录，不能用来说明一次性的突然变化。"}, {"text": "他按天考上了大学。", "explanation": "这里应该用〈终于〉。考上大学是一次性的结果，按天只表示逐日的过程，不能用来说明结果。"}, {"text": "我们按天结了婚。", "explanation": "这里应该用〈已经〉。结婚是一次性的事件，按天表示逐日的计算，不能用来说明这件事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87629, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "按天", "is_correct": true, "explanation": "按天：逐日计算迟到的次数，与句中“计算迟到的次数”相符。"}, {"text": "大声", "is_correct": false, "explanation": "语义：“大声”描述声音的大小，不能修饰“计算”，句子读不通。"}, {"text": "苹果", "is_correct": false, "explanation": "语法：“苹果”是名词，不能作状语修饰“计算”，句子读不通。"}, {"text": "撒谎", "is_correct": false, "explanation": "搭配：“撒谎”是动词，不能作状语修饰“计算”，句子读不通。"}], "explanations": {"按天": "按天：逐日计算迟到的次数，与句中“计算迟到的次数”相符。", "大声": "语义：“大声”描述声音的大小，不能修饰“计算”，句子读不通。", "苹果": "语法：“苹果”是名词，不能作状语修饰“计算”，句子读不通。", "撒谎": "搭配：“撒谎”是动词，不能作状语修饰“计算”，句子读不通。"}, "sentence_index": 6, "correct_answer": "按天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他按天中了彩票。", "explanation": "这里应该用〈意外〉。中彩票是偶然发生的一次性事件，按天表示逐日的计算或重复，不能用来说明这种偶然结果。"}, {"text": "两个人按天到达了车站。", "explanation": "这里应该用〈同时〉。按天指逐日计算，不能用来说明两人在同一时间到达。"}, {"text": "他按天当选了班长。", "explanation": "这里应该用〈最终〉。当选班长是一次性的结果，按天只表示逐日的计算，不能用来说明这种结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87629, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司按天了统计访客人数。", "corrected_sentence": "这家公司按天统计访客人数。", "error_description": "“按天”是状语，后面直接接动词，不能加“了”。应为“这家公司按天统计访客人数”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87629, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店把按天统计客流量。", "corrected_sentence": "这家店按天统计客流量。", "error_description": "“把”字句的“把”后应是宾语，“按天”是状语，不能放在“把”后。应为“这家店按天统计客流量”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
