INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87630, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "以天为单位（计算或结算）。", "primary_collocate": null, "pronunciation": "àn tiān", "ipa": "an˥˩ tʰjɛn˥", "syllable_count": 2, "sentences": [{"text": "这个房间按天收费，一天两百元。", "target_word": "按天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们按天付钱，不用一次付一个月。", "target_word": "按天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的自行车可以按天租。", "target_word": "按天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机按天算工资，每天三百块。", "target_word": "按天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店按天计费，晚走一天就要多付钱。", "target_word": "按天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行社按天收钱，住得越久越贵。", "target_word": "按天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他按天租了一辆车，用了五天。", "target_word": "按天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的停车费按天结算。", "target_word": "按天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人按天拿工钱，做一天给一天的钱。", "target_word": "按天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "租这台机器可以按天，也可以按月。", "target_word": "按天", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "以天为单位计费或结算", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1eb026d-f55f-4628-a2a2-eaf33fe1d183') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87630, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "按天", "is_correct": true, "explanation": "按天：以天为单位计价，与“一天两百元”的说法相符。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不经常，与“一天两百元”的每日计价相矛盾。"}, {"text": "立即", "is_correct": false, "explanation": "语义：“立即”表示马上，不是计价单位，与“一天两百元”搭配不上，句子读不通。"}, {"text": "按年", "is_correct": false, "explanation": "搭配：按年计价的单位与“一天两百元”的日价冲突。"}], "explanations": {"按天": "按天：以天为单位计价，与“一天两百元”的说法相符。", "偶尔": "语义：“偶尔”表示不经常，与“一天两百元”的每日计价相矛盾。", "立即": "语义：“立即”表示马上，不是计价单位，与“一天两百元”搭配不上，句子读不通。", "按年": "搭配：按年计价的单位与“一天两百元”的日价冲突。"}, "sentence_index": 0, "correct_answer": "按天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我按天买了一辆车。", "explanation": "这里应该用〈刚〉。买车是一次性的事件，按天表示以天为单位的计算或结算，不能用来说明这次购买。"}, {"text": "他按天毕业了。", "explanation": "这里应该用〈已经〉。毕业是一次性的结果，按天只表示以天为单位的计算或结算，不能用来说明这件事。"}, {"text": "我们要按天规定办事。", "explanation": "这里应该用〈按照〉。按天表示以天计算，不能用来表示依照规定办事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87630, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "按天", "is_correct": true, "explanation": "按天：以天为单位计算租金，与句中“用了五天”的说法相符。"}, {"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示从来没有，与“租了一辆车”的已完成事实矛盾。"}, {"text": "永远", "is_correct": false, "explanation": "语义：“永远”表示始终如此，与“租了一辆车”的一次性动作不合。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”与“租了一辆车，用了五天”的已完成事实相矛盾。"}], "explanations": {"按天": "按天：以天为单位计算租金，与句中“用了五天”的说法相符。", "从不": "语义：“从不”表示从来没有，与“租了一辆车”的已完成事实矛盾。", "永远": "语义：“永远”表示始终如此，与“租了一辆车”的一次性动作不合。", "拒绝": "语义：“拒绝”与“租了一辆车，用了五天”的已完成事实相矛盾。"}, "sentence_index": 6, "correct_answer": "按天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他按天赢得了冠军。", "explanation": "这里应该用〈终于〉。赢得冠军是一次性的结果，按天不能用来说明这种结果。"}, {"text": "他按天拿到了驾照。", "explanation": "这里应该用〈已经〉。拿到驾照是一次性的结果，按天只表示以天为单位的计算或结算，不能用来说明这件事。"}, {"text": "他按天当选了市长。", "explanation": "这里应该用〈最终〉。当选市长是一次性的结果，按天不能用来说明这种结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
