INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87630, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个停车场把按天收费，我停了三天。", "corrected_sentence": "这个停车场按天收费，我停了三天。", "error_description": "“把”字句的“把”后应是宾语，“按天”是状语，不能放在“把”后。应为“这个停车场按天收费，我停了三天”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
