INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87631, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "转去是转过身往回走，或换到别处去。", "primary_collocate": null, "pronunciation": "zhuǎn qù", "ipa": "ʈʂwan˨˩ tɕʰy˥˩", "syllable_count": 2, "sentences": [{"text": "他忘了关门，走到楼下又转去楼上了。", "target_word": "转去", "complexity_tier": "T3", "furigana": "zhuǎn qù", "sentence_source": "generated"}, {"text": "前面堵车，司机转去左边那条路了。", "target_word": "转去", "complexity_tier": "T3", "furigana": "zhuǎn qù", "sentence_source": "generated"}, {"text": "她在公园里走着走着，忽然转去了湖边。", "target_word": "转去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟不喜欢这个班，想转去另一个班。", "target_word": "转去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们走过头了，得转去找那家饭店。", "target_word": "转去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想见到老王，就转去别的方向。", "target_word": "转去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上完中文课，我转去图书馆看书。", "target_word": "转去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈放下碗，转去追他。", "target_word": "转去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电视台的节目不好看，大家都转去看别的台。", "target_word": "转去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她走到车站，才发现没带票，就转去家里拿。", "target_word": "转去", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "转去了", "label": "体标"}, {"form": "转去过", "label": "体标"}, {"form": "轉去", "label": "繁体"}], "register": "中性", "sense_fingerprint": "转过身往回走，或换到别处去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8e11571-276b-4f80-a3d3-598e69fefa2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87631, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "转去", "is_correct": true, "explanation": "转去（zhuǎn qù）是这个词的读音，指转过身往回走或换到别处去。"}, {"text": "赚取", "is_correct": false, "explanation": "zhuàn qǔ（第四声、第三声）与 zhuǎn qù（第三声、第四声）两个音节声调都不同，意思是赚取。"}, {"text": "展区", "is_correct": false, "explanation": "zhǎn qū（第三声、第一声）与 zhuǎn qù 首音节缺少 u 介音，第二音节声调也不同，意思是展示的区域。"}, {"text": "占去", "is_correct": false, "explanation": "zhàn qù 与 zhuǎn qù 的首音节缺少 u 介音且声调不同，第二音节相同，意思是占去（空间或时间）。"}], "explanations": {"转去": "转去（zhuǎn qù）是这个词的读音，指转过身往回走或换到别处去。", "赚取": "zhuàn qǔ（第四声、第三声）与 zhuǎn qù（第三声、第四声）两个音节声调都不同，意思是赚取。", "展区": "zhǎn qū（第三声、第一声）与 zhuǎn qù 首音节缺少 u 介音，第二音节声调也不同，意思是展示的区域。", "占去": "zhàn qù 与 zhuǎn qù 的首音节缺少 u 介音且声调不同，第二音节相同，意思是占去（空间或时间）。"}, "sentence_index": null, "correct_answer": "转去"}, "level_3": {"options": [{"text": "翻到", "is_correct": false, "explanation": "搭配：“翻到”用于翻书页、翻东西，人不能“翻到楼上”。"}, {"text": "转去", "is_correct": true, "explanation": "正确：表示转身或改道，走到楼下后又去了楼上，符合语境。"}, {"text": "飞上", "is_correct": false, "explanation": "语义：人不会飞，与“走到楼下”的步行语境矛盾。"}, {"text": "游上", "is_correct": false, "explanation": "语义：楼梯不是水，人不能游上楼去。"}], "explanations": {"翻到": "搭配：“翻到”用于翻书页、翻东西，人不能“翻到楼上”。", "转去": "正确：表示转身或改道，走到楼下后又去了楼上，符合语境。", "飞上": "语义：人不会飞，与“走到楼下”的步行语境矛盾。", "游上": "语义：楼梯不是水，人不能游上楼去。"}, "sentence_index": 0, "correct_answer": "转去"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在书上转去了那一页。", "explanation": "这里应该用〈翻到〉。翻书页要说“翻到”，“转去”指人或车辆转身或改往别处。"}, {"text": "他一脚踩空，转去了水里。", "explanation": "这里应该用〈掉进〉。不小心坠落要说“掉进”，“转去”不表示坠落。"}, {"text": "他把垃圾转去了门外。", "explanation": "这里应该用〈扔到〉。把东西抛出去要说“扔到”，“转去”指转身或换去别处，不能用来描述抛出东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5d38431-8fe9-4adc-a7ae-41894017f9b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87631, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "转去", "is_correct": true, "explanation": "转去（zhuǎn qù）是这个词的读音，指转过身往回走或换到别处去。"}, {"text": "专区", "is_correct": false, "explanation": "zhuān qū（第一声、第一声）与 zhuǎn qù 两个音节声调都不同，意思是专门的区域。"}, {"text": "战区", "is_correct": false, "explanation": "zhàn qū（第四声、第一声）与 zhuǎn qù 首音节缺少 u 介音且声调不同，第二音节声调也不同，意思是战争区域。"}, {"text": "赚取", "is_correct": false, "explanation": "zhuàn qǔ（第四声、第三声）与 zhuǎn qù（第三声、第四声）两个音节声调都不同，意思是挣得（钱、利润）。"}], "explanations": {"转去": "转去（zhuǎn qù）是这个词的读音，指转过身往回走或换到别处去。", "专区": "zhuān qū（第一声、第一声）与 zhuǎn qù 两个音节声调都不同，意思是专门的区域。", "战区": "zhàn qū（第四声、第一声）与 zhuǎn qù 首音节缺少 u 介音且声调不同，第二音节声调也不同，意思是战争区域。", "赚取": "zhuàn qǔ（第四声、第三声）与 zhuǎn qù（第三声、第四声）两个音节声调都不同，意思是挣得（钱、利润）。"}, "sentence_index": null, "correct_answer": "转去"}, "level_3": {"options": [{"text": "跳到", "is_correct": false, "explanation": "语义：跳不能表示前往图书馆看书，与“上完中文课”后去图书馆的常理不符。"}, {"text": "飘到", "is_correct": false, "explanation": "语义：人不会飘，去图书馆看书不能用“飘”。"}, {"text": "转去", "is_correct": true, "explanation": "正确：表示改换方向前往图书馆，与“上完中文课”的语境相符。"}, {"text": "放到", "is_correct": false, "explanation": "搭配：“放”需要带被放的物品，不能说“我放到图书馆看书”。"}], "explanations": {"跳到": "语义：跳不能表示前往图书馆看书，与“上完中文课”后去图书馆的常理不符。", "飘到": "语义：人不会飘，去图书馆看书不能用“飘”。", "转去": "正确：表示改换方向前往图书馆，与“上完中文课”的语境相符。", "放到": "搭配：“放”需要带被放的物品，不能说“我放到图书馆看书”。"}, "sentence_index": 6, "correct_answer": "转去"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下午天气转去晴天了。", "explanation": "这里应该用〈转成〉。天气变化要说“转成”或“转晴”，“转去”指人换到别处去，不表示状态变化。"}, {"text": "这场比赛在电视上转去了。", "explanation": "这里应该用〈转播〉。通过电视播出比赛要说“转播”，“转去”不用于节目或比赛的播放。"}, {"text": "我们把这间屋子转去成了书房。", "explanation": "这里应该用〈改成〉。把房间换作别的用途要说“改成”，“转去”指人往别处去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5d38431-8fe9-4adc-a7ae-41894017f9b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87631, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我走到楼下，发现钥匙不见了，又转去来楼上找。", "corrected_sentence": "我走到楼下，发现钥匙不见了，又转去楼上找。", "error_description": "趋向补语重复：“转去”已含“去”的方向，后面不能再加“来”。正确说法是“又转去楼上找”，不能说“又转去来楼上找”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5d38431-8fe9-4adc-a7ae-41894017f9b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87631, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在半路发现走错了，决定转去了另一条路。", "corrected_sentence": "我们在半路发现走错了，决定转去另一条路。", "error_description": "体标错误：“了”接在“转去”后表示动作已经完成，与前面“决定”（尚未实施的打算）相矛盾。正确说法是“决定转去另一条路”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5d38431-8fe9-4adc-a7ae-41894017f9b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
