INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87633, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "管是照看一件事或一个人，让他不出问题。", "primary_collocate": null, "pronunciation": "guǎn", "ipa": "kwan˨˩˦", "syllable_count": 1, "sentences": [{"text": "奶奶在家管着小孙子。", "target_word": "管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去买水，你帮我管着东西。", "target_word": "管", "complexity_tier": "T3", "furigana": "wǒ qù mǎi shuǐ nǐ bāng wǒ guǎn zhe dōng xi", "sentence_source": "generated"}, {"text": "我出门时，邻居帮我管着家。", "target_word": "管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一个人管三只小猫。", "target_word": "管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子太调皮，我管不过来。", "target_word": "管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸管弟弟的功课。", "target_word": "管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗没人管，到处乱跑。", "target_word": "管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几个孩子你一个人管得过来吗？", "target_word": "管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你去上班，孩子我来管。", "target_word": "管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥管着家里的小妹妹。", "target_word": "管", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "管了", "label": "完成体"}, {"form": "管过", "label": "经历体"}, {"form": "管着", "label": "持续体"}, {"form": "管管", "label": "重叠"}], "register": "口语", "sense_fingerprint": "照看某事或某人，使其不出问题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4e08ad9-0b97-4081-94ef-5f5d51ef7e8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87633, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "管", "is_correct": true, "explanation": "管（guǎn）是照看、使其不出问题的意思。"}, {"text": "观", "is_correct": false, "explanation": "观（guān）与管（guǎn）声调不同，观是观看的意思。"}, {"text": "款", "is_correct": false, "explanation": "款（kuǎn）与管（guǎn）声母不同（k 与 g），款是款项的意思。"}, {"text": "罐", "is_correct": false, "explanation": "罐（guàn）与管（guǎn）声调不同，罐是容器的意思。"}], "explanations": {"管": "管（guǎn）是照看、使其不出问题的意思。", "观": "观（guān）与管（guǎn）声调不同，观是观看的意思。", "款": "款（kuǎn）与管（guǎn）声母不同（k 与 g），款是款项的意思。", "罐": "罐（guàn）与管（guǎn）声调不同，罐是容器的意思。"}, "sentence_index": null, "correct_answer": "管"}, "level_3": {"options": [{"text": "管", "is_correct": true, "explanation": "管在这里表示照看小孙子，使其不出问题，与“奶奶在家”相合。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃的对象应是食物，不能指小孩子。"}, {"text": "写", "is_correct": false, "explanation": "搭配：写用于文字，不说“写小孙子”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱的对象是歌曲，不能说“唱小孙子”。"}], "explanations": {"管": "管在这里表示照看小孙子，使其不出问题，与“奶奶在家”相合。", "吃": "语义：吃的对象应是食物，不能指小孩子。", "写": "搭配：写用于文字，不说“写小孙子”。", "唱": "语义：唱的对象是歌曲，不能说“唱小孙子”。"}, "sentence_index": 0, "correct_answer": "管"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师让我们管一首诗。", "explanation": "这里应该用〈背〉。管表示照看或约束，不表示背诵，背一首诗要用“背”。"}, {"text": "我每天晚上管日记。", "explanation": "这里应该用〈写〉。管表示照看或约束，不表示书写，写日记要用“写”。"}, {"text": "我每天早上管牙。", "explanation": "这里应该用〈刷〉。管不表示清洁，刷牙要用“刷”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87633, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "管", "is_correct": true, "explanation": "管（guǎn）是照看、使其不出问题的意思。"}, {"text": "关", "is_correct": false, "explanation": "关（guān）与管（guǎn）声调不同，关是关闭的意思。"}, {"text": "广", "is_correct": false, "explanation": "广（guǎng）与管（guǎn）韵尾不同（ng 与 n），广是宽广的意思。"}, {"text": "灌", "is_correct": false, "explanation": "灌（guàn）与管（guǎn）声调不同，灌是灌溉的意思。"}], "explanations": {"管": "管（guǎn）是照看、使其不出问题的意思。", "关": "关（guān）与管（guǎn）声调不同，关是关闭的意思。", "广": "广（guǎng）与管（guǎn）韵尾不同（ng 与 n），广是宽广的意思。", "灌": "灌（guàn）与管（guǎn）声调不同，灌是灌溉的意思。"}, "sentence_index": null, "correct_answer": "管"}, "level_3": {"options": [{"text": "管", "is_correct": true, "explanation": "管在这里表示照看，使小狗不出乱子，与“没人”相合。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：穿用于衣物，不能用于小狗。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：戴用于帽子、饰物等，不能用于小狗。"}, {"text": "喝", "is_correct": false, "explanation": "语义：喝的对象是饮料，不能指小狗。"}], "explanations": {"管": "管在这里表示照看，使小狗不出乱子，与“没人”相合。", "穿": "搭配：穿用于衣物，不能用于小狗。", "戴": "搭配：戴用于帽子、饰物等，不能用于小狗。", "喝": "语义：喝的对象是饮料，不能指小狗。"}, "sentence_index": 6, "correct_answer": "管"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌是他管出来的。", "explanation": "这里应该用〈写〉。管表示照看或约束，不表示创作，歌要用“写”。"}, {"text": "他把镜子管干净了。", "explanation": "这里应该用〈擦〉。管表示照看或约束，不表示擦拭，把镜子擦干净要用“擦”。"}, {"text": "他会管钢琴。", "explanation": "这里应该用〈弹〉。管表示照看或约束，不表示演奏，会弹钢琴要用“弹”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_