INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87633, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把孩子管了很好。", "corrected_sentence": "她把孩子管得很好。", "error_description": "表示程度的补语应由结构助词“得”连接，说“管得很好”；用“了”连接“很好”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87633, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子交给我管了着。", "corrected_sentence": "孩子交给我管着。", "error_description": "持续体只用“着”，不能同时用“了”；“管了着”是错误的，应说“管着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87634, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放", "is_correct": true, "explanation": "放与管在“管束”义上构成反义关系，管束与放任相对。"}, {"text": "写", "is_correct": false, "explanation": "写与“管”在此义上没有反义关系。"}, {"text": "跑", "is_correct": false, "explanation": "跑与“管”在此义上没有反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "唱与“管”在此义上没有反义关系。"}], "correct_answer": "放", "explanations": {"放": "放与管在“管束”义上构成反义关系，管束与放任相对。", "写": "写与“管”在此义上没有反义关系。", "跑": "跑与“管”在此义上没有反义关系。", "唱": "唱与“管”在此义上没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
