INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87634, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "负责；照料；约束。", "primary_collocate": null, "pronunciation": "guǎn", "ipa": "kwan˨˩˦", "syllable_count": 1, "sentences": [{"text": "这个班由王老师管。", "target_word": "管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁来管这件事？", "target_word": "管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈每天管三个孩子。", "target_word": "管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他太小了，需要大人管着。", "target_word": "管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸管得很严，我不能晚回家。", "target_word": "管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个部门管公司的钱。", "target_word": "管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别管我，我自己能做好。", "target_word": "管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师管不住那几个爱玩的学生。", "target_word": "管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行，公司管吃管住。", "target_word": "管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是别人的家事，你别多管。", "target_word": "管", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "管了", "label": "完成体"}, {"form": "管过", "label": "经历体"}, {"form": "管着", "label": "持续体"}, {"form": "管管", "label": "重叠"}], "register": "口语", "sense_fingerprint": "负责、照料或约束某事某人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4e08ad9-0b97-4081-94ef-5f5d51ef7e8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87634, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "管", "is_correct": true, "explanation": "管（guǎn）是负责、照料、约束的意思。"}, {"text": "关", "is_correct": false, "explanation": "关（guān）与管（guǎn）声调不同，关是关闭的意思。"}, {"text": "官", "is_correct": false, "explanation": "官（guān）与管（guǎn）声调不同，官是官员的意思。"}, {"text": "惯", "is_correct": false, "explanation": "惯（guàn）与管（guǎn）声调不同，惯是习惯的意思。"}, {"text": "款", "is_correct": false, "explanation": "款（kuǎn）与管（guǎn）声母不同（k 与 g），款是款项的意思。"}], "explanations": {"管": "管（guǎn）是负责、照料、约束的意思。", "关": "关（guān）与管（guǎn）声调不同，关是关闭的意思。", "官": "官（guān）与管（guǎn）声调不同，官是官员的意思。", "惯": "惯（guàn）与管（guǎn）声调不同，惯是习惯的意思。", "款": "款（kuǎn）与管（guǎn）声母不同（k 与 g），款是款项的意思。"}, "sentence_index": null, "correct_answer": "管"}, "level_3": {"options": [{"text": "管", "is_correct": true, "explanation": "管在这里表示负责、管理班级，与“由王老师”相合。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃的对象应是食物，不能以班级为对象。"}, {"text": "笑", "is_correct": false, "explanation": "配价：笑是不及物动词，不能带“班”作宾语。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：喝搭配饮料，不说“喝班”。"}], "explanations": {"管": "管在这里表示负责、管理班级，与“由王老师”相合。", "吃": "语义：吃的对象应是食物，不能以班级为对象。", "笑": "配价：笑是不及物动词，不能带“班”作宾语。", "喝": "搭配：喝搭配饮料，不说“喝班”。"}, "sentence_index": 0, "correct_answer": "管"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上管一杯咖啡。", "explanation": "这里应该用〈喝〉。管表示负责或约束，不表示饮用，喝咖啡要用“喝”。"}, {"text": "他把书管到书架上。", "explanation": "这里应该用〈放〉。管表示照看或约束，不表示安放物品，把书放到书架上要用“放”。"}, {"text": "我每天管一小时书。", "explanation": "这里应该用〈读〉。管表示负责或照料，不表示阅读，每天读一小时书要用“读”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87634, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "管", "is_correct": true, "explanation": "管（guǎn）是负责、照料、约束的意思。"}, {"text": "观", "is_correct": false, "explanation": "观（guān）与管（guǎn）声调不同，观是观看的意思。"}, {"text": "广", "is_correct": false, "explanation": "广（guǎng）与管（guǎn）韵尾不同（ng 与 n），广是宽广的意思。"}, {"text": "罐", "is_correct": false, "explanation": "罐（guàn）与管（guǎn）声调不同，罐是容器的意思。"}, {"text": "灌", "is_correct": false, "explanation": "灌（guàn）与管（guǎn）声调不同，灌是灌溉的意思。"}], "explanations": {"管": "管（guǎn）是负责、照料、约束的意思。", "观": "观（guān）与管（guǎn）声调不同，观是观看的意思。", "广": "广（guǎng）与管（guǎn）韵尾不同（ng 与 n），广是宽广的意思。", "罐": "罐（guàn）与管（guǎn）声调不同，罐是容器的意思。", "灌": "灌（guàn）与管（guǎn）声调不同，灌是灌溉的意思。"}, "sentence_index": null, "correct_answer": "管"}, "level_3": {"options": [{"text": "管", "is_correct": true, "explanation": "管在这里表示干预、约束，“你别管我”就是不要干预我，与后句“我自己能做好”相合。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：穿用于衣物，不能用来指人。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱的对象是歌曲，不能以人为对象，“别唱我”说不通。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：戴用于帽子、饰物等，不能用于人。"}], "explanations": {"管": "管在这里表示干预、约束，“你别管我”就是不要干预我，与后句“我自己能做好”相合。", "穿": "搭配：穿用于衣物，不能用来指人。", "唱": "语义：唱的对象是歌曲，不能以人为对象，“别唱我”说不通。", "戴": "搭配：戴用于帽子、饰物等，不能用于人。"}, "sentence_index": 6, "correct_answer": "管"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上管一杯牛奶。", "explanation": "这里应该用〈喝〉。管表示负责或约束，不表示饮用，喝牛奶要用“喝”。"}, {"text": "他把房间管干净了。", "explanation": "这里应该用〈打扫〉。管表示照看或约束，不表示清扫，把房间弄干净要用“打扫”。"}, {"text": "他每天都管一次澡。", "explanation": "这里应该用〈洗〉。管表示负责或约束，不表示沐浴，洗澡要用“洗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87634, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把家里的事管了很好。", "corrected_sentence": "他把家里的事管得很好。", "error_description": "表示程度的补语应由结构助词“得”连接，说“管得很好”；用“了”连接“很好”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87634, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板管得这家公司。", "corrected_sentence": "老板管着这家公司。", "error_description": "持续体误用：表示动作持续应说“管着”，“着”不能换成“得”；“管得”需要跟程度补语，如“管得很好”。应说“管着这家公司”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
