INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87635, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "探测是用东西去找一找、看一看，弄清楚里面有什么。", "primary_collocate": null, "pronunciation": "tàn cè", "ipa": "tʰan˥˩ tsʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "他用棍子探测水有多深。", "target_word": "探测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用铁棍轻轻探测冰面，看看它厚不厚。", "target_word": "探测", "complexity_tier": "T3", "furigana": "tàncè", "sentence_source": "generated"}, {"text": "他用手探测袋子里有没有钥匙。", "target_word": "探测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用长棍探测地下有没有东西。", "target_word": "探测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渔民用长杆探测河底有没有石头。", "target_word": "探测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用铁棒探测墙里面有没有水管。", "target_word": "探测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们用树枝探测洞里有什么。", "target_word": "探测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用脚探测了一下，水不太深。", "target_word": "探测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边走，一边用棍子探测前面的路。", "target_word": "探测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盲人用手杖探测路上有没有东西。", "target_word": "探测", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "探测了", "label": "体标"}, {"form": "探测过", "label": "体标"}, {"form": "探测器", "label": "复合"}], "register": "中性", "sense_fingerprint": "用东西去试探，弄清楚里面有什么", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4002be13-b123-4b4b-8667-dd242372d8ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87635, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "搅动", "is_correct": false, "explanation": "语义：搅动是搅拌水，不能用来弄清水有多深。"}, {"text": "探测", "is_correct": true, "explanation": "探测：用棍子去试探水的深浅，弄清水有多深，符合句意。"}, {"text": "品尝", "is_correct": false, "explanation": "语义：品尝是辨别味道，不能用来测量水的深度。"}, {"text": "冲洗", "is_correct": false, "explanation": "搭配：冲洗指用水洗刷，不说用棍子冲洗水有多深。"}], "explanations": {"搅动": "语义：搅动是搅拌水，不能用来弄清水有多深。", "探测": "探测：用棍子去试探水的深浅，弄清水有多深，符合句意。", "品尝": "语义：品尝是辨别味道，不能用来测量水的深度。", "冲洗": "搭配：冲洗指用水洗刷，不说用棍子冲洗水有多深。"}, "sentence_index": 0, "correct_answer": "探测"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈探测了我的作业，看看有没有错字。", "explanation": "这里应该用〈检查〉。探测是用东西试探、弄清藏在里面的情况，检查作业应该用〈检查〉。"}, {"text": "妈妈探测了一下咖啡的味道。", "explanation": "这里应该用〈尝〉。品尝味道要用〈尝〉，探测不用于品味。"}, {"text": "我探测了一下那首歌好不好听。", "explanation": "这里应该用〈听〉。判断好不好听要用〈听〉，探测不用于欣赏音乐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87635, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "捆扎", "is_correct": false, "explanation": "搭配：捆扎用于捆绑物品，不说用树枝捆扎洞里有什么。"}, {"text": "探测", "is_correct": true, "explanation": "探测：用树枝去试探洞里的情况，弄清里面有什么，正确。"}, {"text": "擦洗", "is_correct": false, "explanation": "语义：擦洗是清洁表面，不能用来弄清洞里有什么。"}, {"text": "燃烧", "is_correct": false, "explanation": "语义：燃烧是使东西着火，不能用树枝去弄清洞里的情况。"}], "explanations": {"捆扎": "搭配：捆扎用于捆绑物品，不说用树枝捆扎洞里有什么。", "探测": "探测：用树枝去试探洞里的情况，弄清里面有什么，正确。", "擦洗": "语义：擦洗是清洁表面，不能用来弄清洞里有什么。", "燃烧": "语义：燃烧是使东西着火，不能用树枝去弄清洞里的情况。"}, "sentence_index": 6, "correct_answer": "探测"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他渴了，探测了一杯水。", "explanation": "这里应该用〈喝〉。探测是用东西试探、弄清情况，喝水不能用探测。"}, {"text": "老师在教室里探测学生的表现。", "explanation": "这里应该用〈观察〉。探测是用东西去试探、弄清楚藏在里面的情况，观察学生要用〈观察〉。"}, {"text": "妈妈探测了一件脏衣服。", "explanation": "这里应该用〈洗〉。探测不表示清洁，洗衣服要用〈洗〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87635, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用棍子轻轻地探测在冰面的厚度。", "corrected_sentence": "他用棍子轻轻地探测冰面的厚度。", "error_description": "宾语前多了“在”：“探测”后直接带宾语，应说“探测冰面的厚度”，不能在宾语“冰面”前加“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87635, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们用树枝探测了过那个山洞。", "corrected_sentence": "孩子们用树枝探测过那个山洞。", "error_description": "体标误用：表示曾经的经历只用“过”，“探测”后不能同时带“了”和“过”，应说“探测过”，不说“探测了过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
