INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87636, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用仪器等对人不易到达的地方进行测量和探查。", "primary_collocate": null, "pronunciation": "tàn cè", "ipa": "tʰan˥˩ tsʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "科学家用仪器探测海底的情况。", "target_word": "探测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞船正在探测火星的表面。", "target_word": "探测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用机器探测地下有没有石油。", "target_word": "探测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机器人可以探测很深的山洞。", "target_word": "探测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家用声音探测海有多深。", "target_word": "探测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用仪器探测过这座火山。", "target_word": "探测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月亮上的情况，要靠飞船来探测。", "target_word": "探测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师用仪器探测大楼下面有没有水管。", "target_word": "探测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这颗卫星专门探测太空里的光。", "target_word": "探测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "救援队用仪器探测倒了的房子里有没有人。", "target_word": "探测", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "探测了", "label": "体标"}, {"form": "探测过", "label": "体标"}, {"form": "探测器", "label": "复合"}], "register": "中性", "sense_fingerprint": "用仪器测量探查人不易到达的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4002be13-b123-4b4b-8667-dd242372d8ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87636, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "修理", "is_correct": false, "explanation": "搭配：修理用于机器和物品，不说修理海底的情况。"}, {"text": "擦", "is_correct": false, "explanation": "语义：擦是擦拭物体表面，不能用来查探海底的情况。"}, {"text": "探测", "is_correct": true, "explanation": "探测：用仪器去查看人不易到达的海底，弄清情况，正确。"}, {"text": "搬运", "is_correct": false, "explanation": "语义：搬运是移动物品，海底的情况不能搬运。"}], "explanations": {"修理": "搭配：修理用于机器和物品，不说修理海底的情况。", "擦": "语义：擦是擦拭物体表面，不能用来查探海底的情况。", "探测": "探测：用仪器去查看人不易到达的海底，弄清情况，正确。", "搬运": "语义：搬运是移动物品，海底的情况不能搬运。"}, "sentence_index": 0, "correct_answer": "探测"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们站在山顶探测远处的风景。", "explanation": "这里应该用〈看〉。探测指用仪器探查人不易到达的地方，站在山顶看风景不用探测。"}, {"text": "我在教室里探测了黑板上的字。", "explanation": "这里应该用〈看〉。黑板上的字直接看就能读，探测用于人不易到达的地方。"}, {"text": "我们周末去博物馆探测恐龙化石。", "explanation": "这里应该用〈参观〉。探测指探查人不易到达之处，去博物馆看化石要用〈参观〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87636, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "熬", "is_correct": false, "explanation": "语义：熬是用小火煎煮，月亮上的情况不能熬。"}, {"text": "修补", "is_correct": false, "explanation": "搭配：修补用于破损的物品，不说修补情况。"}, {"text": "探测", "is_correct": true, "explanation": "探测：靠飞船去查看人不易到达的月面，弄清情况，正确。"}, {"text": "缝", "is_correct": false, "explanation": "语义：缝是用针线连缀织物，情况不能缝。"}], "explanations": {"熬": "语义：熬是用小火煎煮，月亮上的情况不能熬。", "修补": "搭配：修补用于破损的物品，不说修补情况。", "探测": "探测：靠飞船去查看人不易到达的月面，弄清情况，正确。", "缝": "语义：缝是用针线连缀织物，情况不能缝。"}, "sentence_index": 6, "correct_answer": "探测"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他渴了，探测了一杯水。", "explanation": "这里应该用〈喝〉。探测用于探查人不易到达的地方，喝水不能用探测。"}, {"text": "同学们探测了操场。", "explanation": "这里应该用〈检查〉。探测指用仪器探查人不易到达的地方，同学们只是到操场上查看，应该用〈检查〉。"}, {"text": "妈妈探测了房间。", "explanation": "这里应该用〈找〉。探测指用仪器探查人不易到达的地方；妈妈在房间里找东西要用〈找〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87636, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "科学家们用仪器仔细地探测在那片海底。", "corrected_sentence": "科学家们用仪器仔细地探测那片海底。", "error_description": "宾语前多了“在”：“探测”后直接带宾语，应说“探测那片海底”，不能在宾语前加“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87636, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "救援队用仪器探测了过倒了的房子。", "corrected_sentence": "救援队用仪器探测过倒了的房子。", "error_description": "“探测”后只能用“过”表示曾经有过的经历，不能同时带“了”，应说“探测过”，不说“探测了过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
