INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87637, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "转好是从不好变得好起来。", "primary_collocate": null, "pronunciation": "zhuǎn hǎo", "ipa": "ʈʂwan˨˩˦ xaʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "天气明天会转好。", "target_word": "转好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的病终于转好了。", "target_word": "转好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两天生意慢慢转好。", "target_word": "转好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济转好以后，工作多了。", "target_word": "转好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃了药，她的心情渐渐转好。", "target_word": "转好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下午雨停了，天气开始转好。", "target_word": "转好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他的身体正在转好。", "target_word": "转好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的关系最近转好了。", "target_word": "转好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气转好时，我们去爬山。", "target_word": "转好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的成绩从下学期开始转好。", "target_word": "转好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "转好了", "label": "体标"}, {"form": "转好过", "label": "体标"}], "register": "中性", "sense_fingerprint": "从不好的状态变得好起来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af6f987a-8e01-425b-8e85-d1719427681f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87637, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "转好", "is_correct": true, "explanation": "转好：天气由坏变好，与“明天会”搭配，符合句意。"}, {"text": "提高", "is_correct": false, "explanation": "搭配：“提高”用于水平、质量，不用来说天气的变化。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：天气不会结婚，句子无法成立。"}, {"text": "生病", "is_correct": false, "explanation": "语义：天气不会生病，与句子主语不搭。"}], "explanations": {"转好": "转好：天气由坏变好，与“明天会”搭配，符合句意。", "提高": "搭配：“提高”用于水平、质量，不用来说天气的变化。", "结婚": "语义：天气不会结婚，句子无法成立。", "生病": "语义：天气不会生病，与句子主语不搭。"}, "sentence_index": 0, "correct_answer": "转好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子终于转好了。", "explanation": "这里应该用〈修好〉。转好指情况由坏变好，多用于病情、天气、局势，不用于物品的修理。"}, {"text": "这个西瓜转好了，可以吃了。", "explanation": "这里应该用〈切好〉。转好表示情况由坏变好，不用于食材切完。"}, {"text": "饭转好了，快来吃吧。", "explanation": "这里应该用〈煮好〉。转好用于情况的变化，不用于饭菜烹煮完成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c6956b-51c6-417b-baad-332d53f3cdb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87637, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "转好", "is_correct": true, "explanation": "转好：身体由坏变好，与“正在”搭配，符合句意。"}, {"text": "增加", "is_correct": false, "explanation": "搭配：“增加”用于数量，不能用来说身体的状况。"}, {"text": "出差", "is_correct": false, "explanation": "语义：身体不会出差，与“医生说”的语境不符。"}, {"text": "散步", "is_correct": false, "explanation": "语义：身体不能散步，句子不成立。"}], "explanations": {"转好": "转好：身体由坏变好，与“正在”搭配，符合句意。", "增加": "搭配：“增加”用于数量，不能用来说身体的状况。", "出差": "语义：身体不会出差，与“医生说”的语境不符。", "散步": "语义：身体不能散步，句子不成立。"}, "sentence_index": 6, "correct_answer": "转好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "闹钟转好了，我可以睡觉了。", "explanation": "这里应该用〈调好〉。转好指情况由坏变好，不用于仪器的调整完成。"}, {"text": "东西都转好了，请大家过来。", "explanation": "这里应该用〈摆好〉。转好描述状况的好转，不用于物品摆放完成。"}, {"text": "鞋带转好了，我们走吧。", "explanation": "这里应该用〈系好〉。转好不用于物体被系紧的结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c6956b-51c6-417b-baad-332d53f3cdb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87637, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天气慢慢转好了了。", "corrected_sentence": "天气慢慢转好了。", "error_description": "体标错误：“转好了”后不能再加“了”，错误形式“转好了了”多出一个“了”，应删去，正确的说法是“转好了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c6956b-51c6-417b-baad-332d53f3cdb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87637, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几天爷爷的身体慢慢转好着。", "corrected_sentence": "这几天爷爷的身体慢慢转好了。", "error_description": "体标错误：“转好”表示状态的变化，不能加“着”表示持续。错误形式是“转好着”，应改为“转好了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c6956b-51c6-417b-baad-332d53f3cdb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
