INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87639, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abe1b8c7-5769-429e-b5fd-ee02daa76644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87639, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "部长是学生会、社团或单位里负责某个部门的人。", "primary_collocate": null, "pronunciation": "bù zhǎng", "ipa": "pu˥˩ ʈʂɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "学生会的部长通知我们开会。", "target_word": "部长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是我们社团宣传部的部长。", "target_word": "部长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "部长让我明天把表格交给他。", "target_word": "部长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们社团的部长做事很认真。", "target_word": "部长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新部长上个月才来我们部门。", "target_word": "部长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "部长对大家说，今天可以早点下班。", "target_word": "部长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "销售部的部长正在和客户见面。", "target_word": "部长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她当了三年部长，大家都很喜欢她。", "target_word": "部长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "部长带着我们去外面吃了一顿饭。", "target_word": "部长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想问我们部门的部长，这件事应该怎么做。", "target_word": "部长", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "部長", "label": "繁体"}], "register": "口语", "sense_fingerprint": "部长：学生会、社团或单位里某个部门的负责人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee16606a-f927-4c1a-ac0f-73f57f89b922') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87639, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "部长", "is_correct": true, "explanation": "正确选项。“部长”指学生会的部门负责人，能够通知大家开会。"}, {"text": "花园", "is_correct": false, "explanation": "语义：“花园”是地方，不能通知大家开会。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”是建筑部件，不会通知别人。"}, {"text": "汽水", "is_correct": false, "explanation": "搭配：“通知”的主语须是人，“汽水”不能通知我们开会。"}], "explanations": {"部长": "正确选项。“部长”指学生会的部门负责人，能够通知大家开会。", "花园": "语义：“花园”是地方，不能通知大家开会。", "窗户": "语义：“窗户”是建筑部件，不会通知别人。", "汽水": "搭配：“通知”的主语须是人，“汽水”不能通知我们开会。"}, "sentence_index": 0, "correct_answer": "部长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器的部长坏了，需要换一个。", "explanation": "这里误把“部长”当成“部件”来用。部长指管一个大部门的人，不能指机器的零件，应说“部件”。"}, {"text": "我们学生会选出了一根部长。", "explanation": "这里应该用〈位〉。部长指人，量词“根”用于细长的东西，不能用来数人。"}, {"text": "这份报告的部长写得很清楚。", "explanation": "这里误把“部长”当成“部分”来用，指报告的一部分。部长指学生会、社团或单位里某部门的负责人，应说“部分”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abe1b8c7-5769-429e-b5fd-ee02daa76644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87639, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "部长", "is_correct": true, "explanation": "正确选项。“销售部的部长”指部门负责人，能够和客户见面。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“见面”的主语须是人，“冰箱”不能和客户见面。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”不能和客户见面，句子说不通。"}, {"text": "树木", "is_correct": false, "explanation": "语义：“树木”不会与人见面，不能作主语。"}], "explanations": {"部长": "正确选项。“销售部的部长”指部门负责人，能够和客户见面。", "冰箱": "搭配：“见面”的主语须是人，“冰箱”不能和客户见面。", "石头": "语义：“石头”不能和客户见面，句子说不通。", "树木": "语义：“树木”不会与人见面，不能作主语。"}, "sentence_index": 6, "correct_answer": "部长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份合同的部长我已经看完了。", "explanation": "这里误把“部长”当成“部分”来用，指合同的一部分。部长指学生会、社团或单位里某部门的负责人，应说“部分”。"}, {"text": "这辆自行车的部长松了，要拧紧。", "explanation": "这里误把“部长”当成“部件”来用，指自行车的零件。部长指人，不能指零件，应说“部件”。"}, {"text": "我们班来了两条部长。", "explanation": "这里应该用〈位〉。量词“条”用于细长的东西，不能用来数人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abe1b8c7-5769-429e-b5fd-ee02daa76644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87639, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每个部长们都要参加这次会议。", "corrected_sentence": "每个部长都要参加这次会议。", "error_description": "错误：“每个部长们”；正确：“每个部长”。“每”已表示全体，后面不能再加“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abe1b8c7-5769-429e-b5fd-ee02daa76644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87639, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们部门新来了一只部长。", "corrected_sentence": "我们部门新来了一位部长。", "error_description": "错误：“一只部长”；正确：“一位部长”。“只”用于动物或小件物品，指人的部长要用量词“位”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abe1b8c7-5769-429e-b5fd-ee02daa76644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
