INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87642, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "主动将信息、内容发送给用户。", "primary_collocate": null, "pronunciation": "tuī sòng", "ipa": "tʰweɪ˥ sʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这个软件会给用户推送新的音乐。", "target_word": "推送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店向用户推送了很多打折消息。", "target_word": "推送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司每周都向用户推送一次新内容。", "target_word": "推送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网站根据你的喜好推送文章。", "target_word": "推送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "平台把最新的节目推送给了用户。", "target_word": "推送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行主动给客户推送新的服务消息。", "target_word": "推送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "软件更新后，会主动给用户推送一条通知。", "target_word": "推送", "complexity_tier": "T3", "furigana": "tuīsòng", "sentence_source": "generated"}, {"text": "这个平台只向用户推送他们喜欢的视频。", "target_word": "推送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习软件每天给学生推送十个新词。", "target_word": "推送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的软件推送过很多有用的课程。", "target_word": "推送", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "推送了", "label": "体标"}, {"form": "推送过", "label": "体标"}, {"form": "推送着", "label": "体标"}], "register": "中性", "sense_fingerprint": "平台主动把信息内容发给用户", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4002be13-b123-4b4b-8667-dd242372d8ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87642, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "熬", "is_correct": false, "explanation": "语义：熬是用小火煎煮，音乐不能熬。"}, {"text": "推送", "is_correct": true, "explanation": "推送：平台主动把音乐发给用户，正确。"}, {"text": "砍", "is_correct": false, "explanation": "语义：砍是用刀斧劈断，音乐不能砍。"}, {"text": "修补", "is_correct": false, "explanation": "搭配：修补用于破损的东西，不说给用户修补新的音乐。"}], "explanations": {"熬": "语义：熬是用小火煎煮，音乐不能熬。", "推送": "推送：平台主动把音乐发给用户，正确。", "砍": "语义：砍是用刀斧劈断，音乐不能砍。", "修补": "搭配：修补用于破损的东西，不说给用户修补新的音乐。"}, "sentence_index": 0, "correct_answer": "推送"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他给朋友推送了一条短信。", "explanation": "这里应该用〈发〉。推送是平台主动发给用户的，个人之间发短信要用〈发〉。"}, {"text": "我推送了一封信给妈妈。", "explanation": "这里应该用〈寄〉。推送用于平台给用户发送内容，寄信要用〈寄〉。"}, {"text": "我推送了几箱书进屋。", "explanation": "这里应该用〈搬〉。推送是发送信息，不能用于搬运东西，搬书要用〈搬〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87642, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "擦拭", "is_correct": false, "explanation": "搭配：擦拭指擦干净物体表面，不说擦拭一条通知。"}, {"text": "演唱", "is_correct": false, "explanation": "语义：演唱是唱歌，通知不能演唱。"}, {"text": "推送", "is_correct": true, "explanation": "推送：软件更新后把通知发给用户，正确。"}, {"text": "清洗", "is_correct": false, "explanation": "语义：清洗是洗去污物，通知不能清洗。"}], "explanations": {"擦拭": "搭配：擦拭指擦干净物体表面，不说擦拭一条通知。", "演唱": "语义：演唱是唱歌，通知不能演唱。", "推送": "推送：软件更新后把通知发给用户，正确。", "清洗": "语义：清洗是洗去污物，通知不能清洗。"}, "sentence_index": 6, "correct_answer": "推送"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈推送了一锅汤。", "explanation": "这里应该用〈煮〉。推送是把内容发给用户，不能用于做饭，煮汤要用〈煮〉。"}, {"text": "工人推送了一座房子。", "explanation": "这里应该用〈盖〉。推送用于发送内容，不用于建造房屋。"}, {"text": "我推送了很多花。", "explanation": "这里应该用〈养〉。推送不用于照料植物，养花要用〈养〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87642, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个软件会给用户了推送一首新歌。", "corrected_sentence": "这个软件会给用户推送一首新歌。", "error_description": "“推送”前不能加“了”。“了”只能放在动词后表示完成，而且句中有“会”表示将来，不能用“了”。应说“会给用户推送一首新歌”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87642, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "软件每周都会主动给用户推送得一条提醒。", "corrected_sentence": "软件每周都会主动给用户推送一条提醒。", "error_description": "“推送”后直接加“得”是错的：“得”用在动词后引出补语，这里没有补语，应去掉“得”，写作“推送一条提醒”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
