INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87644, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "机关、团体在外地或基层设立的办理事务的机构。", "primary_collocate": null, "pronunciation": "bàn shì chù", "ipa": "pan˥˩ ʂɻ̩˥˩ ʈʂʰu˥˩", "syllable_count": 3, "sentences": [{"text": "红十字会在这个城市设有办事处。", "target_word": "办事处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "联合国在很多国家都有办事处。", "target_word": "办事处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府在外地设了办事处。", "target_word": "办事处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办事处负责办理签证。", "target_word": "办事处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办事处的工作人员很热情。", "target_word": "办事处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "协会的办事处搬到了新大楼。", "target_word": "办事处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在学会的办事处工作了三年。", "target_word": "办事处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办理手续要去办事处。", "target_word": "办事处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个团体的办事处只有两间屋子。", "target_word": "办事处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们办事处明年要招新人。", "target_word": "办事处", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "街道办事处", "label": "复合词"}], "register": "正式", "sense_fingerprint": "机关团体在外地或基层设的办事机构", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c82921da-4675-443e-aa98-940b45501dcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87644, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雨伞", "is_correct": false, "explanation": "语义：红十字会不会设立“雨伞”，“设有”后面需要一个机构或办事点。"}, {"text": "办事处", "is_correct": true, "explanation": "正确：办事处是机关团体在外地或基层设的办事机构，“设有办事处”是固定说法。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“设有”的对象应是机构或场所，“脾气”不能被设立。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：红十字会没有眼睛这类器官，句意不通。"}], "explanations": {"雨伞": "语义：红十字会不会设立“雨伞”，“设有”后面需要一个机构或办事点。", "办事处": "正确：办事处是机关团体在外地或基层设的办事机构，“设有办事处”是固定说法。", "脾气": "搭配：“设有”的对象应是机构或场所，“脾气”不能被设立。", "眼睛": "语义：红十字会没有眼睛这类器官，句意不通。"}, "sentence_index": 0, "correct_answer": "办事处"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是这里的办事处。", "explanation": "这里应该用〈办事员〉。办事处指办事的机构，不指人；说人要用“办事员”。"}, {"text": "这家办事处去年在股市上市了。", "explanation": "这里应该用〈分公司〉。分公司是独立经营的企业，可以上市；办事处只是机关、团体在外地设立的办事机构，不是企业，不能上市。"}, {"text": "这家办事处每天生产一千台机器。", "explanation": "这里应该用〈工厂〉。工厂负责生产；办事处只是办理事务的机构，不生产产品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '932a57fe-9398-41db-9fdd-1b79fde921e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87644, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "卧室", "is_correct": false, "explanation": "语义：卧室是居住的地方，不是机构，不能说在里面“工作”三年。"}, {"text": "办事处", "is_correct": true, "explanation": "正确：办事处是学会设立的办事机构，“在学会的办事处工作”合理。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：眼镜是物品，不是工作的场所，不能说在眼镜里工作。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“工作”要求地点是机构或单位，“窗户”不能作工作场所。"}], "explanations": {"卧室": "语义：卧室是居住的地方，不是机构，不能说在里面“工作”三年。", "办事处": "正确：办事处是学会设立的办事机构，“在学会的办事处工作”合理。", "眼镜": "语义：眼镜是物品，不是工作的场所，不能说在眼镜里工作。", "窗户": "搭配：“工作”要求地点是机构或单位，“窗户”不能作工作场所。"}, "sentence_index": 6, "correct_answer": "办事处"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天都去办事处跑步。", "explanation": "这里应该用〈健身房〉。跑步的场所是健身房、操场一类；办事处是办理事务的机构，不能用来跑步。"}, {"text": "他把办事处挂在了墙上。", "explanation": "这里应该用〈画〉。挂在墙上的是画、钟表等物件；办事处是机构，不能挂。"}, {"text": "这个办事处的头发很长。", "explanation": "这里应该用〈人〉。头发长的是人；办事处是机构，没有头发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '932a57fe-9398-41db-9fdd-1b79fde921e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87644, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们在基层设了一辆办事处。", "corrected_sentence": "他们在基层设了一个办事处。", "error_description": "量词错误：办事处是机构，量词用“个”，不用“辆”。应说“设了一个办事处”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '932a57fe-9398-41db-9fdd-1b79fde921e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87644, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "协会在外地开了一条办事处。", "corrected_sentence": "协会在外地开了一个办事处。", "error_description": "量词错误：办事处是机构，量词用“个”，不用“条”。“条”用于长条形的东西。应说“开了一个办事处”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '932a57fe-9398-41db-9fdd-1b79fde921e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
