INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87645, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "金融是和钱怎么存、怎么借有关的事。", "primary_collocate": null, "pronunciation": "jīn róng", "ipa": "tɕin˥ ʐʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我哥哥在银行工作，他学的是金融。", "target_word": "金融", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我姐姐对金融很感兴趣。", "target_word": "金融", "complexity_tier": "T3", "furigana": "wǒ jiě jie duì jīn róng hěn gǎn xìng qù", "sentence_source": "generated"}, {"text": "他想了解金融，所以每天看财经新闻。", "target_word": "金融", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金融和我们的生活有很大关系。", "target_word": "金融", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸做了二十年金融工作。", "target_word": "金融", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对金融一点儿也不懂，不会存钱也不会借钱。", "target_word": "金融", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王想去北京学金融。", "target_word": "金融", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在的金融服务很方便，用手机就能存钱。", "target_word": "金融", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说金融就是和钱有关的事。", "target_word": "金融", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈不太懂金融，只会把钱存在银行里。", "target_word": "金融", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "金融业", "label": "复合"}, {"form": "金融危机", "label": "复合"}], "register": "中性", "sense_fingerprint": "和存钱、借钱有关的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T1: 3 words above tier T1 (max 2): 一点儿 (Zipf 3.95), 存钱 (Zipf 3.17), 借钱 (Zipf 3.85)']::text[], '4eb1202a-debe-449b-9a5c-f738d8413e68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87645, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "金融", "is_correct": true, "explanation": "正确。“学的是”后接学科名，“金融”是这句里所学的学科，与前文“在银行工作”的背景一致。"}, {"text": "银行", "is_correct": false, "explanation": "搭配：“学的是”后接学科或技能，“银行”是场所，不能作学习的内容。"}, {"text": "北京", "is_correct": false, "explanation": "搭配：“学的是”后接学科或技能，地名不能作学习的内容。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”是建筑部件，不能作学习的内容。"}], "explanations": {"金融": "正确。“学的是”后接学科名，“金融”是这句里所学的学科，与前文“在银行工作”的背景一致。", "银行": "搭配：“学的是”后接学科或技能，“银行”是场所，不能作学习的内容。", "北京": "搭配：“学的是”后接学科或技能，地名不能作学习的内容。", "窗户": "语义：“窗户”是建筑部件，不能作学习的内容。"}, "sentence_index": 0, "correct_answer": "金融"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天去金融存钱。", "explanation": "这里应该用〈银行〉。“金融”指和钱有关的行业和活动，不是可以去的地方；存钱要去银行。"}, {"text": "他是一位金融。", "explanation": "这里应该用〈金融家〉。“金融”指领域，不指人；指从事金融工作的人要说金融家。"}, {"text": "我每天喝一杯金融。", "explanation": "这里应该用〈咖啡〉。“金融”是抽象的行业和活动，不是可以喝的饮品；“喝一杯”要接饮料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87645, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "金融", "is_correct": true, "explanation": "正确。“学”后接学科，“金融”是小王想学的学科。"}, {"text": "北京", "is_correct": false, "explanation": "搭配：“学”的宾语应是学科或技能，地名不能作“学”的宾语。"}, {"text": "嘴巴", "is_correct": false, "explanation": "语义：“学嘴巴”没有实际意义，与“学”后接学科的用法不符。"}, {"text": "空气", "is_correct": false, "explanation": "语义：“空气”不是可以学习的内容，与“学”后接学科的用法不符。"}], "explanations": {"金融": "正确。“学”后接学科，“金融”是小王想学的学科。", "北京": "搭配：“学”的宾语应是学科或技能，地名不能作“学”的宾语。", "嘴巴": "语义：“学嘴巴”没有实际意义，与“学”后接学科的用法不符。", "空气": "语义：“空气”不是可以学习的内容，与“学”后接学科的用法不符。"}, "sentence_index": 6, "correct_answer": "金融"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的金融坏了，要去修一下。", "explanation": "这里应该用〈手机〉。“金融”指抽象的行业和活动，不是能坏、能修的东西。"}, {"text": "他的金融很多，全都是房子和车。", "explanation": "这里应该用〈财产〉。“金融”指行业和活动，不是可以拥有的财物；说拥有的房子、车要用“财产”。"}, {"text": "妈妈把金融存进了账户。", "explanation": "这里应该用〈钱〉。“把”后面存放的是钱，“金融”是领域，不能被存进账户。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87645, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他以前学了过金融。", "corrected_sentence": "他以前学过金融。", "error_description": "错误在于“了”和“过”同时用在“学”后面。“过”表示经历，应紧跟动词，应为“学过金融”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87645, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他毕业后从事金融了工作。", "corrected_sentence": "他毕业后从事金融工作。", "error_description": "错误在于“了”被插在“金融”和“工作”之间。“从事金融工作”中不需要“了”，应去掉这个“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
