INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87646, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "货币的流通和信用活动，包括存款、贷款、投资等。", "primary_collocate": null, "pronunciation": "jīn róng", "ipa": "tɕin˥ ʐʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "金融包括存款、贷款和投资。", "target_word": "金融", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的金融很稳定。", "target_word": "金融", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最近两年金融变化很大。", "target_word": "金融", "complexity_tier": "T3", "furigana": "zuì jìn liǎng nián jīn róng biàn huà hěn dà", "sentence_source": "generated"}, {"text": "银行是金融的重要部分。", "target_word": "金融", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府想让金融更好地帮助小公司。", "target_word": "金融", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金融出了问题，很多公司借不到钱。", "target_word": "金融", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司做金融，可以帮你投资。", "target_word": "金融", "complexity_tier": "T3", "furigana": "zhè jiā gōng sī zuò jīn róng, kě yǐ bāng nǐ tóu zī", "sentence_source": "generated"}, {"text": "国家要严格管理金融。", "target_word": "金融", "complexity_tier": "T3", "furigana": "guó jiā yào yán gé guǎn lǐ jīn róng", "sentence_source": "generated"}, {"text": "现在的金融越来越方便，存款和贷款都很快。", "target_word": "金融", "complexity_tier": "T3", "furigana": "xiàn zài de jīn róng yuè lái yuè fāng biàn, cún kuǎn hé dài kuǎn dōu hěn kuài", "sentence_source": "generated"}, {"text": "她做了五年金融，现在负责投资。", "target_word": "金融", "complexity_tier": "T3", "furigana": "tā zuò le wǔ nián jīn róng, xiàn zài fù zé tóu zī", "sentence_source": "generated"}], "morphological_forms": [{"form": "金融业", "label": "复合"}, {"form": "金融危机", "label": "复合"}], "register": "中性", "sense_fingerprint": "货币流通和信用活动，如存款、贷款、投资", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eb1202a-debe-449b-9a5c-f738d8413e68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87646, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "金融", "is_correct": true, "explanation": "正确。“包括存款、贷款和投资”说明的正是金融业务的范围。"}, {"text": "动物", "is_correct": false, "explanation": "语义：“动物”不包括存款、贷款和投资，与句意相矛盾。"}, {"text": "方言", "is_correct": false, "explanation": "语义：“方言”是语言的地域变体，不包括存款、贷款和投资。"}, {"text": "农业", "is_correct": false, "explanation": "搭配：“包括存款、贷款和投资”是金融业务的内容，“农业”不包括这类内容。"}], "explanations": {"金融": "正确。“包括存款、贷款和投资”说明的正是金融业务的范围。", "动物": "语义：“动物”不包括存款、贷款和投资，与句意相矛盾。", "方言": "语义：“方言”是语言的地域变体，不包括存款、贷款和投资。", "农业": "搭配：“包括存款、贷款和投资”是金融业务的内容，“农业”不包括这类内容。"}, "sentence_index": 0, "correct_answer": "金融"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把金融很锋利。", "explanation": "这里应该用〈刀〉。“金融”是抽象的行业和活动，不是有形器具，不能说锋利，也不能用“把”计量。"}, {"text": "我每次都去金融取钱。", "explanation": "这里应该用〈自动取款机〉。“金融”不是可以去的地方，也不是取钱的设备。"}, {"text": "政府每年要花很多金融修路。", "explanation": "这里应该用〈钱〉。“花”的对象要是钱，“金融”指货币流通和信用活动，不是可以花掉的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87646, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "金融", "is_correct": true, "explanation": "正确。“做金融”指从事金融业务，与“帮你投资”相符。"}, {"text": "诗歌", "is_correct": false, "explanation": "语义：“诗歌”不能帮人投资，与“帮你投资”的语境相矛盾。"}, {"text": "书法", "is_correct": false, "explanation": "语义：“书法”是艺术，与“帮你投资”的业务不符。"}, {"text": "甜点", "is_correct": false, "explanation": "搭配：“做甜点”是制作食品，与“帮你投资”不构成同一类业务。"}], "explanations": {"金融": "正确。“做金融”指从事金融业务，与“帮你投资”相符。", "诗歌": "语义：“诗歌”不能帮人投资，与“帮你投资”的语境相矛盾。", "书法": "语义：“书法”是艺术，与“帮你投资”的业务不符。", "甜点": "搭配：“做甜点”是制作食品，与“帮你投资”不构成同一类业务。"}, "sentence_index": 6, "correct_answer": "金融"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他去公司买金融。", "explanation": "这里应该用〈保险〉。“金融”是领域，不是可以购买的产品。"}, {"text": "她是一名金融。", "explanation": "这里应该用〈老师〉。“金融”指行业，不指人；指从事金融的人要说金融从业者或金融家。"}, {"text": "这家餐厅的金融很好吃。", "explanation": "这里应该用〈食物〉。“金融”是抽象领域，不能作“很好吃”的主语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87646, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "现在地金融行业很有前景。", "corrected_sentence": "现在的金融行业很有前景。", "error_description": "结构助词错误：“地”用于修饰动词的状语，名词前的修饰语要用“的”。应说“现在的金融行业”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87646, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她曾经做着金融工作。", "corrected_sentence": "她曾经做过金融工作。", "error_description": "体标错误：“着”表示动作持续，与表示经历的“曾经”矛盾。应用“过”表示经历，说“她曾经做过金融工作”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
