INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87647, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "搜寻是到处找，想找到一个东西或一个人。", "primary_collocate": null, "pronunciation": "sōu xún", "ipa": "sou̯˥ ɕyn˧˥", "syllable_count": 2, "sentences": [{"text": "警察正在搜寻失踪的孩子。", "target_word": "搜寻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这栋老房子很大，我搜寻了半天，还是没找到钥匙。", "target_word": "搜寻", "complexity_tier": "T3", "furigana": "sōu xún", "sentence_source": "generated"}, {"text": "他在大仓库里搜寻那批丢失的货物。", "target_word": "搜寻", "complexity_tier": "T3", "furigana": "sōu xún", "sentence_source": "generated"}, {"text": "救援队在山里搜寻着遇难的人。", "target_word": "搜寻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗在草地上搜寻自己的球。", "target_word": "搜寻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她到处搜寻那本旧书。", "target_word": "搜寻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一起搜寻走丢的小猫。", "target_word": "搜寻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在网上搜寻过很多资料。", "target_word": "搜寻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人在公园里搜寻丢失的拐杖。", "target_word": "搜寻", "complexity_tier": "T3", "furigana": "sōu xún", "sentence_source": "generated"}, {"text": "我们搜寻了整个公园，也没看到她。", "target_word": "搜寻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "搜寻了", "label": "完成体"}, {"form": "搜寻着", "label": "持续体"}, {"form": "搜寻过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "到处找，想找到某样东西或某个人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f650a73-b56c-4b35-a5aa-fa33d63c4ebd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87647, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "搜寻", "is_correct": true, "explanation": "“搜寻”指到处找失踪的孩子，与句意相符。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”表示讥讽，与警察寻找失踪孩子的职责相矛盾。"}, {"text": "逃避", "is_correct": false, "explanation": "搭配：“逃避”后接责任、困难等，不能接失踪的孩子。"}, {"text": "讲述", "is_correct": false, "explanation": "配价：“讲述”的宾语应是事情或故事，不能是人。"}], "explanations": {"搜寻": "“搜寻”指到处找失踪的孩子，与句意相符。", "嘲笑": "语义：“嘲笑”表示讥讽，与警察寻找失踪孩子的职责相矛盾。", "逃避": "搭配：“逃避”后接责任、困难等，不能接失踪的孩子。", "讲述": "配价：“讲述”的宾语应是事情或故事，不能是人。"}, "sentence_index": 0, "correct_answer": "搜寻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们正在搜寻帮助。", "explanation": "这里应该用〈寻求〉。搜寻指到处找具体的人或物，要求帮助、支持等抽象事物时用寻求。"}, {"text": "我只是随便搜寻了一眼窗外。", "explanation": "这里应该用〈望〉。搜寻指有目的地到处、仔细地找，随便看一眼要用望。"}, {"text": "老师搜寻了学生的作业，给了一个高分。", "explanation": "这里应该用〈批改〉。搜寻指到处找人或物，老师看作业、打分要用批改。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c912a95-669d-44e6-a421-6c480014ffc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87647, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "搜寻", "is_correct": true, "explanation": "“搜寻”指到处找走丢的小猫，与句意相符。"}, {"text": "逮捕", "is_correct": false, "explanation": "语义：“逮捕”针对犯罪嫌疑人，不能用于走丢的小猫。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”多用于器物，不能用于走丢的小猫。"}, {"text": "拥有", "is_correct": false, "explanation": "语义：“拥有”表示占有，与“走丢”的小猫相矛盾。"}], "explanations": {"搜寻": "“搜寻”指到处找走丢的小猫，与句意相符。", "逮捕": "语义：“逮捕”针对犯罪嫌疑人，不能用于走丢的小猫。", "修理": "语义：“修理”多用于器物，不能用于走丢的小猫。", "拥有": "语义：“拥有”表示占有，与“走丢”的小猫相矛盾。"}, "sentence_index": 6, "correct_answer": "搜寻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我不小心搜寻到了一只猫。", "explanation": "这里应该用〈碰到〉。搜寻是有目的地到处找，“不小心”表示偶然，应说碰到，不能用搜寻。"}, {"text": "医生搜寻了病人的心跳。", "explanation": "这里应该用〈检查〉。搜寻指到处找人或物，医生查看病人身体状况时用检查。"}, {"text": "我搜寻到了阳光的温暖。", "explanation": "这里应该用〈感受〉。搜寻指有目的地找具体的人或物，阳光的温暖这类感觉要用感受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c912a95-669d-44e6-a421-6c480014ffc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87647, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈在整栋房子里搜寻了着一把旧钥匙。", "corrected_sentence": "妈妈在整栋房子里搜寻着一把旧钥匙。", "error_description": "体标错误：“了”（完成）和“着”（持续）不能同时用在“搜寻”后面。这里表示正在找，应去掉“了”，说“搜寻着一把旧钥匙”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c912a95-669d-44e6-a421-6c480014ffc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87647, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们搜寻了到一只丢失的狗。", "corrected_sentence": "我们搜寻到了一只丢失的狗。", "error_description": "补语位置错误：结果补语“到”应紧跟动词，“了”放在补语之后，应说“搜寻到了”，不能说“搜寻了到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c912a95-669d-44e6-a421-6c480014ffc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87650, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "轮作", "is_correct": true, "explanation": "反义：轮作指轮换种植不同作物，与连作正好相反。"}, {"text": "施肥", "is_correct": false, "explanation": "无反义关系：施肥是给土地加肥料，与连作的种植方式不构成对立。"}, {"text": "播种", "is_correct": false, "explanation": "无反义关系：播种是下种，与连作不构成对立。"}, {"text": "收割", "is_correct": false, "explanation": "无反义关系：收割是收获作物，与连作不构成对立。"}], "correct_answer": "轮作", "explanations": {"轮作": "反义：轮作指轮换种植不同作物，与连作正好相反。", "施肥": "无反义关系：施肥是给土地加肥料，与连作的种植方式不构成对立。", "播种": "无反义关系：播种是下种，与连作不构成对立。", "收割": "无反义关系：收割是收获作物，与连作不构成对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f594faad-37eb-47e7-8bae-409dfee625fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87650, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "轮作", "is_correct": true, "explanation": "反义：轮作指轮换种植不同作物，与连作正好相反。"}, {"text": "浇灌", "is_correct": false, "explanation": "无反义关系：浇灌是给作物供水，与连作不构成对立。"}, {"text": "翻耕", "is_correct": false, "explanation": "无反义关系：翻耕是翻松土地，与连作不构成对立。"}, {"text": "除草", "is_correct": false, "explanation": "无反义关系：除草是清除杂草，与连作不构成对立。"}], "correct_answer": "轮作", "explanations": {"轮作": "反义：轮作指轮换种植不同作物，与连作正好相反。", "浇灌": "无反义关系：浇灌是给作物供水，与连作不构成对立。", "翻耕": "无反义关系：翻耕是翻松土地，与连作不构成对立。", "除草": "无反义关系：除草是清除杂草，与连作不构成对立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f594faad-37eb-47e7-8bae-409dfee625fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87650, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在同一块田地上连续多年种植同一种作物。", "primary_collocate": null, "pronunciation": "lián zuò", "ipa": "lʲɛn˧˥ tsuɔ˥˩", "syllable_count": 2, "sentences": [{"text": "这块地连作玉米，土地越来越差。", "target_word": "连作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民说，这块地不能连作棉花。", "target_word": "连作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "连作会让土地里的病虫越来越多。", "target_word": "连作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷家的田连作多年，产量下降了。", "target_word": "连作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了保护土地，农民不再连作。", "target_word": "连作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同一块田连作三年后，麦子长得不好。", "target_word": "连作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家建议这里不要连作，应该换着种。", "target_word": "连作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "连作的田容易生虫，要多注意。", "target_word": "连作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的地连作过水稻，所以今年改种豆子。", "target_word": "连作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "连作时间太长，土地就没有力气了。", "target_word": "连作", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "连作了", "label": "体标"}, {"form": "连作过", "label": "体标"}, {"form": "連作", "label": "繁体"}], "register": "书面", "sense_fingerprint": "同一块田连续多年种同一种作物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77dd5244-fd53-4152-b5ae-74a62c865356') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87650, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "邻座", "is_correct": false, "explanation": "lín 与 lián 只差韵母，邻座指旁边的座位。"}, {"text": "闲坐", "is_correct": false, "explanation": "xián 与 lián 只差声母，闲坐指无事而坐。"}, {"text": "前作", "is_correct": false, "explanation": "qián（第二声）与 lián（第二声）仅声母不同，只差一个音位；前作指前一部作品。"}, {"text": "连作", "is_correct": true, "explanation": "正确：连作，在同一块田上连续多年种同一种作物。"}], "explanations": {"邻座": "lín 与 lián 只差韵母，邻座指旁边的座位。", "闲坐": "xián 与 lián 只差声母，闲坐指无事而坐。", "前作": "qián（第二声）与 lián（第二声）仅声母不同，只差一个音位；前作指前一部作品。", "连作": "正确：连作，在同一块田上连续多年种同一种作物。"}, "sentence_index": null, "correct_answer": "连作"}, "level_3": {"options": [{"text": "连作", "is_correct": true, "explanation": "正确：“这块地连作玉米”指同一块地多年连续种玉米。"}, {"text": "轮作", "is_correct": false, "explanation": "搭配：“轮作”要求轮换多种作物，只说“玉米”不成立，且与“土地越来越差”的后果相矛盾。"}, {"text": "卖", "is_correct": false, "explanation": "语义：“卖”需要有人作卖的主体，“这块地”是无生命的土地，句意不通。"}, {"text": "煮", "is_correct": false, "explanation": "语义：土地不会“煮玉米”，句子意思荒谬。"}], "explanations": {"连作": "正确：“这块地连作玉米”指同一块地多年连续种玉米。", "轮作": "搭配：“轮作”要求轮换多种作物，只说“玉米”不成立，且与“土地越来越差”的后果相矛盾。", "卖": "语义：“卖”需要有人作卖的主体，“这块地”是无生命的土地，句意不通。", "煮": "语义：土地不会“煮玉米”，句子意思荒谬。"}, "sentence_index": 0, "correct_answer": "连作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爷爷家的田今年种玉米，明年改种大豆，这样连作很好。", "explanation": "这里应该用〈轮作〉。连作指在同一块田里多年种同一种作物；今年玉米、明年大豆是轮作。"}, {"text": "他连作参加了三年比赛。", "explanation": "这里应该用〈连续〉。连作只指在同一块田里多年种同一种作物，不能用来说人参加比赛。"}, {"text": "玉米和大豆连作，两种作物都长得很好。", "explanation": "这里应该用〈间作〉。连作指同一块田只种同一种作物，玉米和大豆同时种属于间作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f594faad-37eb-47e7-8bae-409dfee625fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87650, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "两座", "is_correct": false, "explanation": "liǎng（第三声）与 lián（第二声）声调、韵尾都不同，两座指两个（座位或建筑）。"}, {"text": "联络", "is_correct": false, "explanation": "luò 与 zuò 只差声母（l 与 z），联络指互相联系。"}, {"text": "连锁", "is_correct": false, "explanation": "suǒ（第三声）与 zuò（第四声）声母、声调都不同，连锁指一环扣一环或连锁店。"}, {"text": "连作", "is_correct": true, "explanation": "正确：连作，在同一块田上连续多年种同一种作物。"}], "explanations": {"两座": "liǎng（第三声）与 lián（第二声）声调、韵尾都不同，两座指两个（座位或建筑）。", "联络": "luò 与 zuò 只差声母（l 与 z），联络指互相联系。", "连锁": "suǒ（第三声）与 zuò（第四声）声母、声调都不同，连锁指一环扣一环或连锁店。", "连作": "正确：连作，在同一块田上连续多年种同一种作物。"}, "sentence_index": null, "correct_answer": "连作"}, "level_3": {"options": [{"text": "连作", "is_correct": true, "explanation": "正确：“不要连作”指不要在同一块地多年种同一作物，与“换着种”相对应。"}, {"text": "吵", "is_correct": false, "explanation": "语义：“吵”是争吵，与种植建议无关，句意荒唐。"}, {"text": "浇灌", "is_correct": false, "explanation": "语义：“不要浇灌”与“应该换着种”的换茬建议不相呼应，句意不通。"}, {"text": "偷", "is_correct": false, "explanation": "语义：“偷”是窃取，与“换着种”的种植建议毫无关系。"}], "explanations": {"连作": "正确：“不要连作”指不要在同一块地多年种同一作物，与“换着种”相对应。", "吵": "语义：“吵”是争吵，与种植建议无关，句意荒唐。", "浇灌": "语义：“不要浇灌”与“应该换着种”的换茬建议不相呼应，句意不通。", "偷": "语义：“偷”是窃取，与“换着种”的种植建议毫无关系。"}, "sentence_index": 6, "correct_answer": "连作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师连作了三节课，学生都很认真。", "explanation": "这里应该用〈上〉。连作只用于在田里多年种同一种作物，不能用来说上课。"}, {"text": "这块田只种了一次玉米，我们就说它连作了。", "explanation": "只种一次不算连作；连作要在同一块田里连续多年种同一种作物。"}, {"text": "他连作了一封长信。", "explanation": "这里应该用〈写〉。连作只指种田，不能用来说写信。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f594faad-37eb-47e7-8bae-409dfee625fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87650, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他家的田连作得五年，今年得休息。", "corrected_sentence": "他家的田连作了五年，今年得休息。", "error_description": "“得”用法错误：“连作得五年”不成立，已经持续五年的连作应说“连作了五年”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f594faad-37eb-47e7-8bae-409dfee625fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87650, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农民不让这块地很连作。", "corrected_sentence": "农民不让这块地连作。", "error_description": "错误：“很连作”；正确：“连作”。连作是动词，不能受程度副词“很”修饰。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f594faad-37eb-47e7-8bae-409dfee625fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
