INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87651, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "错是不对，不是应该有的样子。", "primary_collocate": null, "pronunciation": "cuò", "ipa": "tsʰwo˥˩", "syllable_count": 1, "sentences": [{"text": "你的想法错了，要改一改。", "target_word": "错", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这样做是错的。", "target_word": "错", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他知道自己错了，所以道歉。", "target_word": "错", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事不是我错，是他错。", "target_word": "错", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁对谁错，大家心里都清楚。", "target_word": "错", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的做法没有错，只是太慢。", "target_word": "错", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我没有错，你为什么骂我？", "target_word": "错", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "错的事情，我们不要再做。", "target_word": "错", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸说，打人是错的。", "target_word": "错", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "方向错了，再努力也没用。", "target_word": "错", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "错误", "label": "复合"}, {"form": "对错", "label": "复合"}, {"form": "错了", "label": "体标"}, {"form": "錯", "label": "繁体"}], "register": "中性", "sense_fingerprint": "形容词，指想法、做法、行为不对，不是应该的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bb8d477-42ee-4005-b0c4-97766b2fc790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87651, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "错", "is_correct": true, "explanation": "错是不对，不是应该有的样子。"}, {"text": "做", "is_correct": false, "explanation": "zuò 与 cuò 声母不同（z / c），声调相同，意思是做事。"}, {"text": "搓", "is_correct": false, "explanation": "cuō（第一声）与 cuò（第四声）声调不同，意思是用手来回揉。"}, {"text": "脆", "is_correct": false, "explanation": "cuì 与 cuò 韵母不同（ui / uo），声调相同，意思是容易折断、松脆。"}, {"text": "座", "is_correct": false, "explanation": "zuò 与 cuò 声母不同（z / c），声调相同，意思是座位。"}], "explanations": {"错": "错是不对，不是应该有的样子。", "做": "zuò 与 cuò 声母不同（z / c），声调相同，意思是做事。", "搓": "cuō（第一声）与 cuò（第四声）声调不同，意思是用手来回揉。", "脆": "cuì 与 cuò 韵母不同（ui / uo），声调相同，意思是容易折断、松脆。", "座": "zuò 与 cuò 声母不同（z / c），声调相同，意思是座位。"}, "sentence_index": null, "correct_answer": "错"}, "level_3": {"options": [{"text": "错", "is_correct": true, "explanation": "“错了”指想法不对，正好与后文“要改一改”相合。"}, {"text": "对", "is_correct": false, "explanation": "语义：“对了”与后文“要改一改”矛盾，想法对了就不需要改。"}, {"text": "亮", "is_correct": false, "explanation": "搭配：“亮”形容光线，不能用来形容想法。"}, {"text": "咸", "is_correct": false, "explanation": "搭配：“咸”形容味道，想法没有咸淡。"}], "explanations": {"错": "“错了”指想法不对，正好与后文“要改一改”相合。", "对": "语义：“对了”与后文“要改一改”矛盾，想法对了就不需要改。", "亮": "搭配：“亮”形容光线，不能用来形容想法。", "咸": "搭配：“咸”形容味道，想法没有咸淡。"}, "sentence_index": 0, "correct_answer": "错"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个人心很错，大家都不喜欢。", "explanation": "这里应该用〈坏〉。错指想法、做法不对，说人品不好要用“坏”。"}, {"text": "我的成绩很错，老师很生气。", "explanation": "这里应该用〈差〉。成绩好坏说“差”，“错”不用来形容成绩。"}, {"text": "这里离车站很错。", "explanation": "这里应该用〈远〉。错是不对，不能用来描述距离。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adb0bbfe-38d6-494b-aa72-a06b51652833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87651, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "错", "is_correct": true, "explanation": "错是不对，不是应该有的样子。"}, {"text": "坐", "is_correct": false, "explanation": "zuò 与 cuò 声母不同（z / c），声调相同，意思是坐下。"}, {"text": "粗", "is_correct": false, "explanation": "cū（第一声）与 cuò（第四声）声调不同，意思是粗细、不精细。"}, {"text": "醋", "is_correct": false, "explanation": "cù 与 cuò 韵母不同（u / uo），声调相同，意思是醋。"}, {"text": "作", "is_correct": false, "explanation": "zuò 与 cuò 声母不同（z / c），声调相同，意思是做、写作。"}], "explanations": {"错": "错是不对，不是应该有的样子。", "坐": "zuò 与 cuò 声母不同（z / c），声调相同，意思是坐下。", "粗": "cū（第一声）与 cuò（第四声）声调不同，意思是粗细、不精细。", "醋": "cù 与 cuò 韵母不同（u / uo），声调相同，意思是醋。", "作": "zuò 与 cuò 声母不同（z / c），声调相同，意思是做、写作。"}, "sentence_index": null, "correct_answer": "错"}, "level_3": {"options": [{"text": "错", "is_correct": true, "explanation": "“没有错”表示自己没有做不对的事，句意成立。"}, {"text": "厚", "is_correct": false, "explanation": "搭配：“厚”形容物体，不能用来形容人的对错。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”指味道，与被骂的原因无关。"}, {"text": "高", "is_correct": false, "explanation": "搭配：“没有高”不成说法，“高”不能表示对错。"}], "explanations": {"错": "“没有错”表示自己没有做不对的事，句意成立。", "厚": "搭配：“厚”形容物体，不能用来形容人的对错。", "甜": "语义：“甜”指味道，与被骂的原因无关。", "高": "搭配：“没有高”不成说法，“高”不能表示对错。"}, "sentence_index": 6, "correct_answer": "错"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "房间很错，大家都不想进去。", "explanation": "这里应该用〈乱〉。房间的整洁程度说“乱”，“错”不能形容房间。"}, {"text": "他走路很错，总是迟到。", "explanation": "这里应该用〈慢〉。走路快慢说“慢”，“错”不表示速度。"}, {"text": "今天天气很错，我们在家待着。", "explanation": "这里应该用〈冷〉。天气冷热说“冷”，“错”不表示温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adb0bbfe-38d6-494b-aa72-a06b51652833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
