INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87653, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "放过是不再怪他，也不处罚他。", "primary_collocate": null, "pronunciation": "fàng guò", "ipa": "fɑŋ˥˩ kuo˥˩", "syllable_count": 2, "sentences": [{"text": "老师说这次就放过你了。", "target_word": "放过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你放过我吧，我真的知道错了。", "target_word": "放过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈看他哭了，就放过了他。", "target_word": "放过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次我放过你，下次不行。", "target_word": "放过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他认错很诚恳，经理决定放过他。", "target_word": "放过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你就放过那个孩子吧。", "target_word": "放过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察看他年纪小，放过了他。", "target_word": "放过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟打破了杯子，姐姐没有放过他。", "target_word": "放过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板这次放过了迟到的小王。", "target_word": "放过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不会放过说谎的人。", "target_word": "放过", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "放过了", "label": "体标"}, {"form": "没放过", "label": "否定"}, {"form": "放過", "label": "繁体"}], "register": "口语", "sense_fingerprint": "放过：不再责怪、不处罚某人，原谅对方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c338676-2383-4c9c-9a7a-bdb10f081010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87653, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "放过", "is_correct": true, "explanation": "正确：“放过”表示不再责怪、不处罚，与“这次就”的宽大语气相合。"}, {"text": "罚站", "is_correct": false, "explanation": "配价：“罚”要带兼语，应说“罚你站”，“罚站你”不成立。"}, {"text": "剥夺", "is_correct": false, "explanation": "语义：“剥夺”是夺去权利，语气严厉，与“这次就”的轻松语气不合。"}, {"text": "鞭打", "is_correct": false, "explanation": "语域：“鞭打”是体罚，语气过重，与老师对学生“这次就”的宽大处理相冲突。"}], "explanations": {"放过": "正确：“放过”表示不再责怪、不处罚，与“这次就”的宽大语气相合。", "罚站": "配价：“罚”要带兼语，应说“罚你站”，“罚站你”不成立。", "剥夺": "语义：“剥夺”是夺去权利，语气严厉，与“这次就”的轻松语气不合。", "鞭打": "语域：“鞭打”是体罚，语气过重，与老师对学生“这次就”的宽大处理相冲突。"}, "sentence_index": 0, "correct_answer": "放过"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他放过了这个念头，不再想去国外。", "explanation": "这里应该用〈放弃〉。放弃指主动舍弃念头、计划；放过用于不追究人或不阻拦事情，不能用于念头。"}, {"text": "孩子松开手，把气球放过了。", "explanation": "这里应该用〈放掉〉。放掉指松开、让东西离开手；放过没有松手的意思。"}, {"text": "他放过了心里的担心，安心地睡了。", "explanation": "这里应该用〈消除〉。消除指把心里的担忧去掉；放过用于不追究人或不阻拦事情，不能用于担心这类心理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87653, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放过", "is_correct": true, "explanation": "正确：“放过”表示不追究、不处罚，与“年纪小”的宽大理由相合。"}, {"text": "重判", "is_correct": false, "explanation": "语义：“重判”是从重处罚，与“年纪小”的宽大理由相反。"}, {"text": "逮捕", "is_correct": false, "explanation": "语义：因为“年纪小”而逮捕，理由与行为互相矛盾，不合情理。"}, {"text": "制裁", "is_correct": false, "explanation": "语域：“制裁”是严厉的书面用语，与“年纪小”的日常语境不合。"}], "explanations": {"放过": "正确：“放过”表示不追究、不处罚，与“年纪小”的宽大理由相合。", "重判": "语义：“重判”是从重处罚，与“年纪小”的宽大理由相反。", "逮捕": "语义：因为“年纪小”而逮捕，理由与行为互相矛盾，不合情理。", "制裁": "语域：“制裁”是严厉的书面用语，与“年纪小”的日常语境不合。"}, "sentence_index": 6, "correct_answer": "放过"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他放过了手里的书，去开门了。", "explanation": "这里应该用〈放下〉。放下指把拿着的东西搁下；放过不表示搁下东西。"}, {"text": "他把钥匙放过桌子上，就出门了。", "explanation": "这里应该用〈放在〉。放在指把东西搁到某处；放过不表示搁置东西。"}, {"text": "她放过了妹妹的手，让她先走。", "explanation": "这里应该用〈放开〉。放开指松开、解除束缚；放过不表示松手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87653, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这一次我没有放过了他。", "corrected_sentence": "这一次我没有放过他。", "error_description": "错误：“没有放过了”；正确：“没有放过”。“没有”否定已发生的动作时，动词后不再加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87653, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师没有被放过那个抄作业的学生。", "corrected_sentence": "老师没有放过那个抄作业的学生。", "error_description": "错误：“没有被放过”；正确：“没有放过”。“被”字句的主语应是受事，这里“老师”是放过学生的施事，不能加“被”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
