INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87654, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不追究，不处罚；也指让其通过而不加阻拦。", "primary_collocate": null, "pronunciation": "fàng guò", "ipa": "fɑŋ˥˩ kuo˥˩", "syllable_count": 2, "sentences": [{"text": "警察没有放过任何一个坏人。", "target_word": "放过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法律不会放过犯罪的人。", "target_word": "放过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "检查的人放过了那辆车。", "target_word": "放过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "守门的人放过了那个小孩。", "target_word": "放过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他认真检查，没放过一个错误。", "target_word": "放过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "保安放过了那位忘带证件的老人。", "target_word": "放过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保安看了他的证件，就放过了他。", "target_word": "放过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生不放过任何小问题。", "target_word": "放过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师批改作业时没放过一个错字。", "target_word": "放过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次警察抓到了他，不会再放过他。", "target_word": "放过", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "放过了", "label": "体标"}, {"form": "没放过", "label": "否定"}, {"form": "放過", "label": "繁体"}], "register": "通用", "sense_fingerprint": "放过：不追究不处罚，或不加阻拦、让其通过", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c338676-2383-4c9c-9a7a-bdb10f081010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87654, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "放过", "is_correct": true, "explanation": "正确：“放过”表示不加追究、宽容，与“没有……任何一个坏人”搭配通顺。"}, {"text": "美丽", "is_correct": false, "explanation": "词性：“美丽”是形容词，不能带宾语“坏人”。"}, {"text": "突然", "is_correct": false, "explanation": "词性：“突然”是形容词/副词，不能带宾语，句子不通。"}, {"text": "窗户", "is_correct": false, "explanation": "词性：“窗户”是名词，不能作谓语带宾语。"}], "explanations": {"放过": "正确：“放过”表示不加追究、宽容，与“没有……任何一个坏人”搭配通顺。", "美丽": "词性：“美丽”是形容词，不能带宾语“坏人”。", "突然": "词性：“突然”是形容词/副词，不能带宾语，句子不通。", "窗户": "词性：“窗户”是名词，不能作谓语带宾语。"}, "sentence_index": 0, "correct_answer": "放过"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把照片放过了，看得更清楚。", "explanation": "这里应该用〈放大〉。放大指把图像变大；放过没有扩大的意思。"}, {"text": "他放过了桌上的信，去接电话了。", "explanation": "这里应该用〈放下〉。放下指把拿着的东西搁到一边；放过不表示搁置东西。"}, {"text": "他放过了孩子的手，让他跑走了。", "explanation": "这里应该用〈放开〉。放开指松开手，放过不表示松手或放开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87654, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放过", "is_correct": true, "explanation": "正确：“放过”表示让其通过、不加阻拦，与“看了证件”相合。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是地方，不能说“打扫了他”。"}, {"text": "洗澡", "is_correct": false, "explanation": "语法：“洗澡”是离合词，不能直接带宾语“他”。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”是天气现象，不能以人为宾语。"}], "explanations": {"放过": "正确：“放过”表示让其通过、不加阻拦，与“看了证件”相合。", "打扫": "搭配：“打扫”的对象是地方，不能说“打扫了他”。", "洗澡": "语法：“洗澡”是离合词，不能直接带宾语“他”。", "下雨": "语义：“下雨”是天气现象，不能以人为宾语。"}, "sentence_index": 6, "correct_answer": "放过"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他放过了手里的包，去接电话。", "explanation": "这里应该用〈放下〉。放下指把拿着的东西搁下；放过不表示搁下东西。"}, {"text": "他一撒手，就放过了那只风筝。", "explanation": "这里应该用〈放掉〉。放掉指松开、让东西脱手；放过没有这个意思。"}, {"text": "她把苹果放过盘子里，然后拿起了书。", "explanation": "这里应该用〈放在〉。放在指把东西搁到某处；放过不表示搁置东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87654, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "门口的保安被放过了我们，没有检查。", "corrected_sentence": "门口的保安放过了我们，没有检查。", "error_description": "错误：“被放过了”；正确：“放过了”。“被”字句的主语应是受事，这里“保安”是放过“我们”的施事，不能加“被”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87654, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "交警没有放过了那辆违章的车。", "corrected_sentence": "交警没有放过那辆违章的车。", "error_description": "错误：“没有放过了”；正确：“没有放过”。“没有”否定已发生的动作时，动词后不再加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87657, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下等", "is_correct": true, "explanation": "正确：下等与上等构成反义，指等级最低，与“上等”的质量等级相对。"}, {"text": "安静", "is_correct": false, "explanation": "与上等无反义关系：安静形容没有声音或不吵闹。"}, {"text": "巨大", "is_correct": false, "explanation": "与上等无反义关系：巨大形容体积或数量很大。"}, {"text": "轻松", "is_correct": false, "explanation": "与上等无反义关系：轻松形容心情或状态不紧张。"}], "correct_answer": "下等", "explanations": {"下等": "正确：下等与上等构成反义，指等级最低，与“上等”的质量等级相对。", "安静": "与上等无反义关系：安静形容没有声音或不吵闹。", "巨大": "与上等无反义关系：巨大形容体积或数量很大。", "轻松": "与上等无反义关系：轻松形容心情或状态不紧张。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be528465-bd94-493b-b734-18aa1c035366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87657, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "次等", "is_correct": true, "explanation": "正确：次等与上等构成反义，指质量或等级低于一般。"}, {"text": "简单", "is_correct": false, "explanation": "与上等无反义关系：简单形容事情不复杂。"}, {"text": "漫长", "is_correct": false, "explanation": "与上等无反义关系：漫长形容时间或距离很长。"}, {"text": "明亮", "is_correct": false, "explanation": "与上等无反义关系：明亮形容光线充足或颜色鲜亮。"}], "correct_answer": "次等", "explanations": {"次等": "正确：次等与上等构成反义，指质量或等级低于一般。", "简单": "与上等无反义关系：简单形容事情不复杂。", "漫长": "与上等无反义关系：漫长形容时间或距离很长。", "明亮": "与上等无反义关系：明亮形容光线充足或颜色鲜亮。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be528465-bd94-493b-b734-18aa1c035366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87657, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "上等是很好很好，比别的都好。", "primary_collocate": null, "pronunciation": "shàng děng", "ipa": "ʂɑŋ˥˩ təŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这家店的茶叶是上等的。", "target_word": "上等", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他送给我一块上等的玉。", "target_word": "上等", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这里的牛肉都是上等货。", "target_word": "上等", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这条鱼很新鲜，肉质是上等的。", "target_word": "上等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起别的米，这种米是上等的。", "target_word": "上等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板用上等的木头做了一张桌子。", "target_word": "上等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "客人来了，妈妈拿出上等的茶招待他们。", "target_word": "上等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块布是上等的，别的都比不上它。", "target_word": "上等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他喜欢收藏上等的字画。", "target_word": "上等", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "商店里的这瓶酒是上等的，价钱也最高。", "target_word": "上等", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "上等：很好很好，比别的都好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '986f312e-72c3-468e-8424-eadc7ad44fc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87657, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上等", "is_correct": true, "explanation": "正确：上等表示质量很好、比别的都好，可以修饰茶叶。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：高大描写体形或物体的高度，不能用来评价茶叶的质量。"}, {"text": "悲伤", "is_correct": false, "explanation": "语义：悲伤描写情绪，不能用来说茶叶的品质。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：年轻指年龄较小，只用于人或生物，不能用来形容茶叶。"}], "explanations": {"上等": "正确：上等表示质量很好、比别的都好，可以修饰茶叶。", "高大": "体貌：高大描写体形或物体的高度，不能用来评价茶叶的质量。", "悲伤": "语义：悲伤描写情绪，不能用来说茶叶的品质。", "年轻": "语义：年轻指年龄较小，只用于人或生物，不能用来形容茶叶。"}, "sentence_index": 0, "correct_answer": "上等"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是我上等的朋友。", "explanation": "这里应该用〈最好〉。〈上等〉多用于货物、材料的质量等级，不用来形容朋友之间的关系。"}, {"text": "今天天气很上等，我们去公园吧。", "explanation": "这里应该用〈好〉。〈上等〉用于货物、材料等的质量等级，不用来形容天气。"}, {"text": "这个问题很上等，需要仔细想想。", "explanation": "这里应改用〈难〉。〈上等〉修饰物品的质量等级，不能用来评价问题的难度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be528465-bd94-493b-b734-18aa1c035366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87657, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上等", "is_correct": true, "explanation": "正确：上等表示质量好，与“客人来了”时拿出好茶招待相符。"}, {"text": "破旧", "is_correct": false, "explanation": "语义：破旧的茶不适合拿来招待客人，与句中的礼遇语境相冲突。"}, {"text": "苗条", "is_correct": false, "explanation": "体貌：苗条形容人的身形，不能用来修饰茶。"}, {"text": "幼稚", "is_correct": false, "explanation": "语义：幼稚形容人的心智或举止，不能用来描述茶的品质。"}], "explanations": {"上等": "正确：上等表示质量好，与“客人来了”时拿出好茶招待相符。", "破旧": "语义：破旧的茶不适合拿来招待客人，与句中的礼遇语境相冲突。", "苗条": "体貌：苗条形容人的身形，不能用来修饰茶。", "幼稚": "语义：幼稚形容人的心智或举止，不能用来描述茶的品质。"}, "sentence_index": 6, "correct_answer": "上等"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这瓶酒的价钱很上等，我买不起。", "explanation": "这里应该用〈高〉。〈上等〉描述质量等级，不能用来说明价钱。"}, {"text": "他的表现很上等，大家都很满意。", "explanation": "这里应该用〈出色〉。〈上等〉描述物品的质量等级，不用来形容人的表现。"}, {"text": "这瓶酒的颜色很上等。", "explanation": "搭配：〈上等〉描述质量等级，颜色应用〈鲜艳〉、〈清澈〉等词来描述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be528465-bd94-493b-b734-18aa1c035366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87657, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老板选的这批货是上等地。", "corrected_sentence": "老板选的这批货是上等的。", "error_description": "错误形式是“上等地”，正确形式是“上等的”。〈上等〉是形容词，作表语时要用〈的〉，不能加〈地〉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be528465-bd94-493b-b734-18aa1c035366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87657, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们店里的牛奶是上等了。", "corrected_sentence": "我们店里的牛奶是上等的。", "error_description": "错误形式是“上等了”，正确形式是“上等的”。〈上等〉作谓语时要用〈是……的〉结构，不能用完成标记〈了〉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be528465-bd94-493b-b734-18aa1c035366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87658, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下等", "is_correct": true, "explanation": "正确：下等与上等构成反义，指等级最低，与“上等”相对。"}, {"text": "缓慢", "is_correct": false, "explanation": "与上等无反义关系：缓慢形容速度慢。"}, {"text": "陡峭", "is_correct": false, "explanation": "与上等无反义关系：陡峭形容地势或坡度很大。"}, {"text": "欢快", "is_correct": false, "explanation": "与上等无反义关系：欢快形容情绪或节奏轻快。"}], "correct_answer": "下等", "explanations": {"下等": "正确：下等与上等构成反义，指等级最低，与“上等”相对。", "缓慢": "与上等无反义关系：缓慢形容速度慢。", "陡峭": "与上等无反义关系：陡峭形容地势或坡度很大。", "欢快": "与上等无反义关系：欢快形容情绪或节奏轻快。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be528465-bd94-493b-b734-18aa1c035366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87658, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "次等", "is_correct": true, "explanation": "正确：次等与上等构成反义，指等级低于一般。"}, {"text": "简单", "is_correct": false, "explanation": "与上等无反义关系：简单形容事情不复杂。"}, {"text": "漫长", "is_correct": false, "explanation": "与上等无反义关系：漫长形容时间或距离很长。"}, {"text": "明亮", "is_correct": false, "explanation": "与上等无反义关系：明亮形容光线充足或颜色鲜亮。"}], "correct_answer": "次等", "explanations": {"次等": "正确：次等与上等构成反义，指等级低于一般。", "简单": "与上等无反义关系：简单形容事情不复杂。", "漫长": "与上等无反义关系：漫长形容时间或距离很长。", "明亮": "与上等无反义关系：明亮形容光线充足或颜色鲜亮。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be528465-bd94-493b-b734-18aa1c035366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87658, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "等级高的；质量好的。", "primary_collocate": null, "pronunciation": "shàng děng", "ipa": "ʂɑŋ˥˩ təŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这批茶叶分三个等级，这是上等茶。", "target_word": "上等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上等的丝绸摸起来很舒服。", "target_word": "上等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家饭店只用上等的食材。", "target_word": "上等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他买不起上等货，只买中等的。", "target_word": "上等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种大米质量很好，属于上等。", "target_word": "上等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上等羊毛做的毛衣又软又暖和。", "target_word": "上等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老师傅挑了一块上等的木头。", "target_word": "上等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的海鲜都是上等的，价钱当然高。", "target_word": "上等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请给我们来一瓶上等的白酒。", "target_word": "上等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人把上等的苹果放在最前面。", "target_word": "上等", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "上等：等级高、质量好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T1: 3 words above tier T1 (max 2): 羊毛 (Zipf 3.7), 毛衣 (Zipf 3.4), 暖和 (Zipf 3.49)']::text[], '986f312e-72c3-468e-8424-eadc7ad44fc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87658, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上等", "is_correct": true, "explanation": "正确：上等表示等级高、质量好，可以修饰茶，与“分三个等级”的语境相符。"}, {"text": "瘦长", "is_correct": false, "explanation": "体貌：瘦长描写形状，不能用来说明茶的等级。"}, {"text": "吵闹", "is_correct": false, "explanation": "语义：吵闹形容声音嘈杂，与茶的等级无关。"}, {"text": "悲伤", "is_correct": false, "explanation": "语义：悲伤形容情绪，不能用来说明茶的等级。"}], "explanations": {"上等": "正确：上等表示等级高、质量好，可以修饰茶，与“分三个等级”的语境相符。", "瘦长": "体貌：瘦长描写形状，不能用来说明茶的等级。", "吵闹": "语义：吵闹形容声音嘈杂，与茶的等级无关。", "悲伤": "语义：悲伤形容情绪，不能用来说明茶的等级。"}, "sentence_index": 0, "correct_answer": "上等"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一个很上等的学生。", "explanation": "这里应该用〈优秀〉。〈优秀〉可用于人的能力和品行，〈上等〉只用于货物、材料的质量等级。"}, {"text": "他的歌声很上等，大家都爱听。", "explanation": "这里应该用〈动听〉。〈上等〉描述物品的质量等级，不用来形容歌声。"}, {"text": "这次讨论的话题很上等。", "explanation": "这里应改用〈重要〉。〈上等〉修饰物品的质量等级，不能用来评价话题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be528465-bd94-493b-b734-18aa1c035366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87658, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上等", "is_correct": true, "explanation": "正确：上等表示质量好，与“挑了”这一选择的语境相符。"}, {"text": "破旧", "is_correct": false, "explanation": "语义：挑选时不会选破旧的木头，与“挑”的语境冲突。"}, {"text": "苗条", "is_correct": false, "explanation": "体貌：苗条形容人的身形，不能用来修饰木头。"}, {"text": "幼稚", "is_correct": false, "explanation": "语义：幼稚形容人的心智或举止，不能用来说明木头的等级。"}], "explanations": {"上等": "正确：上等表示质量好，与“挑了”这一选择的语境相符。", "破旧": "语义：挑选时不会选破旧的木头，与“挑”的语境冲突。", "苗条": "体貌：苗条形容人的身形，不能用来修饰木头。", "幼稚": "语义：幼稚形容人的心智或举止，不能用来说明木头的等级。"}, "sentence_index": 6, "correct_answer": "上等"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他今天的心情很上等。", "explanation": "这里应该用〈好〉。〈上等〉用于货物、材料的质量等级，不用来形容心情。"}, {"text": "这些苹果的颜色很上等，很漂亮。", "explanation": "搭配：〈上等〉描述质量等级，颜色应用〈鲜艳〉等词来描述。"}, {"text": "这些苹果的重量很上等。", "explanation": "这里应该用〈重〉或〈轻〉。〈上等〉说明质量等级，不能用来描述重量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be528465-bd94-493b-b734-18aa1c035366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87658, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这批瓷器是上等地，很受欢迎。", "corrected_sentence": "这批瓷器是上等的，很受欢迎。", "error_description": "错误形式是“上等地”，正确形式是“上等的”。〈上等〉是形容词，作表语时要用〈的〉，不能加〈地〉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be528465-bd94-493b-b734-18aa1c035366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87658, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们店里有一批上等地茶叶。", "corrected_sentence": "我们店里有一批上等的茶叶。", "error_description": "错误形式是“上等地茶叶”，正确形式是“上等的茶叶”。〈上等〉作定语修饰〈茶叶〉，要用〈的〉，不能用〈地〉；〈地〉用于修饰动词、形容词作状语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be528465-bd94-493b-b734-18aa1c035366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
