INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87659, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "散发是把气味或热气向四周送出去。", "primary_collocate": null, "pronunciation": "sàn fā", "ipa": "san˥˩ fa˥", "syllable_count": 2, "sentences": [{"text": "花园里的花散发着淡淡的香味。", "target_word": "散发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房里散发出一股饭菜的香味。", "target_word": "散发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那堆垃圾散发着难闻的臭味。", "target_word": "散发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "炉子里的火散发着热气，屋里很暖和。", "target_word": "散发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新买的沙发散发着一股皮子的味道。", "target_word": "散发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡散发出的香气让我一下子醒了。", "target_word": "散发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的马路散发着热气，让人不想出门。", "target_word": "散发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的衣服上散发着一股汗味。", "target_word": "散发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面包刚出炉，散发着甜甜的香味。", "target_word": "散发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打开冰箱，里面散发出一股怪味。", "target_word": "散发", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "散发着", "label": "体标"}, {"form": "散发了", "label": "体标"}, {"form": "散发过", "label": "体标"}], "register": "中性", "sense_fingerprint": "气味、热气向四周发出", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63e4ab29-410c-4d06-aa49-0654232e82a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87659, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "散发", "is_correct": true, "explanation": "正确：“散发”指把气味向四周送出去，与“淡淡的香味”相符。"}, {"text": "吞", "is_correct": false, "explanation": "语义：吞是咽下去，花不会吞下香味，句意不通。"}, {"text": "咬", "is_correct": false, "explanation": "语义：咬是用牙齿咬东西，香味不能被咬，句意不通。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔”一般接具体的东西，不能与“香味”搭配。"}], "explanations": {"散发": "正确：“散发”指把气味向四周送出去，与“淡淡的香味”相符。", "吞": "语义：吞是咽下去，花不会吞下香味，句意不通。", "咬": "语义：咬是用牙齿咬东西，香味不能被咬，句意不通。", "扔": "搭配：“扔”一般接具体的东西，不能与“香味”搭配。"}, "sentence_index": 0, "correct_answer": "散发"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "电器工作时会散发很大的噪音。", "explanation": "这里应该用〈发出〉。散发指把气味、热气向外送出，声音要用“发出”。"}, {"text": "箱子里散发着很多旧衣服。", "explanation": "这里应该用〈装〉。散发指把气味或热气送出去，不能表示容器里盛放东西。"}, {"text": "会议结束后，人群很快就散发了。", "explanation": "这里应该用〈散去〉。散发指把气味或热气向外送出，不表示人群离开，人群离开要用“散去”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe2411fb-f81f-4ec6-96d9-dfb4f7804e08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87659, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "散发", "is_correct": true, "explanation": "正确：“散发”指把热气向外送出，与“马路散发着热气”相符。"}, {"text": "踢", "is_correct": false, "explanation": "语义：踢是用脚击打，热气不能被踢，句意不通。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”的对象一般是桌面、汗水等，不能说“擦着热气”。"}, {"text": "踩", "is_correct": false, "explanation": "语义：踩是用脚压在上面，热气无法被踩，句意不通。"}], "explanations": {"散发": "正确：“散发”指把热气向外送出，与“马路散发着热气”相符。", "踢": "语义：踢是用脚击打，热气不能被踢，句意不通。", "擦": "搭配：“擦”的对象一般是桌面、汗水等，不能说“擦着热气”。", "踩": "语义：踩是用脚压在上面，热气无法被踩，句意不通。"}, "sentence_index": 6, "correct_answer": "散发"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "墙上散发着一幅画，很好看。", "explanation": "这里应该用〈挂〉。散发只表示气味或热气向外送出，不能表示物体挂在某处。"}, {"text": "他散发着一只小狗走进屋。", "explanation": "这里应该用〈抱〉。散发不能带人或动物作宾语，把小狗抱在怀里要用“抱”。"}, {"text": "农民在地里散发了很多种子。", "explanation": "这里应该用〈撒〉。撒种子是把种子四处扔落，散发指气味或热气送出，不能用于种子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe2411fb-f81f-4ec6-96d9-dfb4f7804e08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87659, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "院子里的花散发着了淡淡的香味，走过的人都停下来。", "corrected_sentence": "院子里的花散发着淡淡的香味，走过的人都停下来。", "error_description": "体标错误：“着”和“了”不能同时用在“散发”后面。应去掉“了”，说“散发着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe2411fb-f81f-4ec6-96d9-dfb4f7804e08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87659, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一打开锅盖，就散发起一股饭菜的香味。", "corrected_sentence": "一打开锅盖，就散发出一股饭菜的香味。", "error_description": "补语错误：“散发”后应接趋向补语“出”，表示从里向外送出；“起”不能这样用。应说“散发出”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe2411fb-f81f-4ec6-96d9-dfb4f7804e08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
