INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87661, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "遗忘是以前的事想不起来了。", "primary_collocate": null, "pronunciation": "yí wàng", "ipa": "i˧˥ waŋ˥˩", "syllable_count": 2, "sentences": [{"text": "那些旧事，我早已遗忘，一点也想不起来。", "target_word": "遗忘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人的名字，他早已遗忘了。", "target_word": "遗忘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试前背的单词，过几天就遗忘了。", "target_word": "遗忘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年纪大了，他常常遗忘昨天的事。", "target_word": "遗忘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷的病让他遗忘了家人的样子。", "target_word": "遗忘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学过的知识不复习，很快就会遗忘。", "target_word": "遗忘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那首老歌的歌词，我已经遗忘了一大半。", "target_word": "遗忘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候的梦，我大多已经遗忘了。", "target_word": "遗忘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧照片让我想起遗忘多年的往事。", "target_word": "遗忘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说他遗忘了那天发生的一切。", "target_word": "遗忘", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "遗忘了", "label": "体标"}, {"form": "遗忘过", "label": "体标"}, {"form": "遺忘", "label": "繁体"}], "register": "书面", "sense_fingerprint": "记忆淡去，以前的事想不起来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8e11571-276b-4f80-a3d3-598e69fefa2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87661, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "遗忘", "is_correct": true, "explanation": "正确答案：“遗忘”指以前的事想不起来了。"}, {"text": "以往", "is_correct": false, "explanation": "两个音节的声调都不同（yǐ、wǎng），意思是过去的时候，与“遗忘”的意思不同。"}, {"text": "一望", "is_correct": false, "explanation": "第一个音节声调不同（yī 与 yí），意思是看一眼。"}, {"text": "一网", "is_correct": false, "explanation": "两个音节的声调都不同（yī、wǎng），意思是一张网。"}], "explanations": {"遗忘": "正确答案：“遗忘”指以前的事想不起来了。", "以往": "两个音节的声调都不同（yǐ、wǎng），意思是过去的时候，与“遗忘”的意思不同。", "一望": "第一个音节声调不同（yī 与 yí），意思是看一眼。", "一网": "两个音节的声调都不同（yī、wǎng），意思是一张网。"}, "sentence_index": null, "correct_answer": "遗忘"}, "level_3": {"options": [{"text": "遗忘", "is_correct": true, "explanation": "正确答案：“遗忘”指记忆淡去，与“一点也想不起来”呼应。"}, {"text": "记得", "is_correct": false, "explanation": "语义：“记得”与后面的“一点也想不起来”矛盾，句子说不通。"}, {"text": "收藏", "is_correct": false, "explanation": "搭配：“收藏”的对象是物品，不能与“旧事”搭配。"}, {"text": "出发", "is_correct": false, "explanation": "语义：“出发”与“想不起来”的语境无关，句子说不通。"}], "explanations": {"遗忘": "正确答案：“遗忘”指记忆淡去，与“一点也想不起来”呼应。", "记得": "语义：“记得”与后面的“一点也想不起来”矛盾，句子说不通。", "收藏": "搭配：“收藏”的对象是物品，不能与“旧事”搭配。", "出发": "语义：“出发”与“想不起来”的语境无关，句子说不通。"}, "sentence_index": 0, "correct_answer": "遗忘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她每天都遗忘远方的父母，一直很想念他们。", "explanation": "这里应该用〈思念〉。遗忘指记忆中忘掉，与“一直想念”矛盾，表达想念要用“思念”。"}, {"text": "工厂遗忘了很多汽车。", "explanation": "这里应该用〈制造〉。遗忘只用于人的记忆，不指工厂生产汽车。"}, {"text": "她遗忘这首歌，唱得很好听。", "explanation": "这里应该用〈熟记〉。遗忘指以前的事想不起来了，不表示记熟，要说“熟记”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5d38431-8fe9-4adc-a7ae-41894017f9b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87661, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遗忘", "is_correct": true, "explanation": "正确答案：“遗忘”指记忆中忘掉，与“歌词”“一大半”呼应。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的对象是场所，不能与“歌词”搭配。"}, {"text": "测量", "is_correct": false, "explanation": "搭配：“测量”的对象是长度、温度等，不能用于歌词。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”用于衣物等实物，不能用来描述歌词。"}], "explanations": {"遗忘": "正确答案：“遗忘”指记忆中忘掉，与“歌词”“一大半”呼应。", "参观": "搭配：“参观”的对象是场所，不能与“歌词”搭配。", "测量": "搭配：“测量”的对象是长度、温度等，不能用于歌词。", "洗": "语义：“洗”用于衣物等实物，不能用来描述歌词。"}, "sentence_index": 6, "correct_answer": "遗忘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她每天遗忘房间，地板总是很干净。", "explanation": "这里应该用〈打扫〉。遗忘指以前的事想不起来了，不指清理房间。"}, {"text": "妈妈遗忘菜，味道却很好。", "explanation": "这里应该用〈烧〉。遗忘指以前的事想不起来了，不用于做菜。"}, {"text": "这位老人遗忘春联，写得很整齐。", "explanation": "这里应该用〈书写〉。遗忘指以前的事想不起来了，不指写春联。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5d38431-8fe9-4adc-a7ae-41894017f9b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87661, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那段往事我早就遗忘着。", "corrected_sentence": "那段往事我早就遗忘了。", "error_description": "错误形式：“遗忘”表示记忆的结果，一般不接“着”，“遗忘着”不自然。正确形式：应用“了”，说“遗忘了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5d38431-8fe9-4adc-a7ae-41894017f9b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87661, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她已经遗忘着了那个约定。", "corrected_sentence": "她已经遗忘了那个约定。", "error_description": "错误形式：“遗忘”后不接“着”，“遗忘着了”不成立。正确形式：去掉“着”，说“已经遗忘了那个约定”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5d38431-8fe9-4adc-a7ae-41894017f9b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
