INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87663, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "不大是不太多，不太厉害。", "primary_collocate": null, "pronunciation": "bú dà", "ipa": "pu³⁵ ta⁵¹", "syllable_count": 2, "sentences": [{"text": "今天的风不大，我们去公园玩吧。", "target_word": "不大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面的雨下得不大，不用带伞。", "target_word": "不大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他受的伤不大，过几天就好了。", "target_word": "不大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小毛病不大，不用担心。", "target_word": "不大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试的难度不大，大家都考得不错。", "target_word": "不大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两家店的价格差别不大。", "target_word": "不大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场雪下得不大，路上很好走。", "target_word": "不大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的地震不大，没有人受伤。", "target_word": "不大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事对他的影响不大，他还是很开心。", "target_word": "不大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月的花费不大，还剩下不少钱。", "target_word": "不大", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "副词；表示数量不太多、程度不太厉害", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01ececac-152b-4004-ac0a-24281145fd2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87663, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不大", "is_correct": true, "explanation": "正确答案：不大（bú dà），表示数量不太多、程度不太厉害。"}, {"text": "不但", "is_correct": false, "explanation": "dàn 与 dà 韵母不同（多一个 n），意思是“不但”，是连词。"}, {"text": "不打", "is_correct": false, "explanation": "dǎ（第三声）与 dà（第四声）声调不同，意思是不击打。"}, {"text": "不带", "is_correct": false, "explanation": "dài 与 dà 韵母不同（ai 与 a），意思是不携带。"}, {"text": "不答", "is_correct": false, "explanation": "dá（第二声）与 dà（第四声）声调不同，意思是不回答。"}], "explanations": {"不大": "正确答案：不大（bú dà），表示数量不太多、程度不太厉害。", "不但": "dàn 与 dà 韵母不同（多一个 n），意思是“不但”，是连词。", "不打": "dǎ（第三声）与 dà（第四声）声调不同，意思是不击打。", "不带": "dài 与 dà 韵母不同（ai 与 a），意思是不携带。", "不答": "dá（第二声）与 dà（第四声）声调不同，意思是不回答。"}, "sentence_index": null, "correct_answer": "不大"}, "level_3": {"options": [{"text": "不大", "is_correct": true, "explanation": "不大表示风力不强，与“去公园玩”的语境相符。"}, {"text": "很大", "is_correct": false, "explanation": "语义：风很大，不适合去公园玩，与后句“我们去公园玩吧”矛盾。"}, {"text": "不多", "is_correct": false, "explanation": "搭配：“风”说大小或强弱，不说多少，不能用“不多”形容。"}, {"text": "不小", "is_correct": false, "explanation": "语义：“不小”说明风大，与“去公园玩”的语境不合。"}], "explanations": {"不大": "不大表示风力不强，与“去公园玩”的语境相符。", "很大": "语义：风很大，不适合去公园玩，与后句“我们去公园玩吧”矛盾。", "不多": "搭配：“风”说大小或强弱，不说多少，不能用“不多”形容。", "不小": "语义：“不小”说明风大，与“去公园玩”的语境不合。"}, "sentence_index": 0, "correct_answer": "不大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场雨下得非常不大，路面却全是积水。", "explanation": "这里应该用〈很大〉。“不大”表示数量不太多、程度不太厉害，不能与“非常”连用，程度深的说法是“很大”。"}, {"text": "这次的风非常不大，却把树全吹倒了。", "explanation": "这里应该用〈猛烈〉。“不大”表示程度不太厉害，不能与“非常”连用，“非常猛烈”才是正确搭配。"}, {"text": "这次地震的危害极其不大，整座城市都毁了。", "explanation": "这里应该用〈严重〉。“不大”表示程度不太厉害，不能与“极其”连用，也与“整座城市都毁了”矛盾，应说“极其严重”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f486e30-3ae2-4f13-aa8f-30c337825229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87663, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不大", "is_correct": true, "explanation": "不大表示雪下得不猛，与“路上很好走”相符。"}, {"text": "很厚", "is_correct": false, "explanation": "语义：雪下得很厚，路上会很难走，与后句“路上很好走”矛盾。"}, {"text": "很猛", "is_correct": false, "explanation": "语义：雪下得很猛，路上会很难走，与后句“路上很好走”矛盾。"}, {"text": "不高", "is_correct": false, "explanation": "搭配：“下雪”不说“高”，“下得不高”不成立。"}], "explanations": {"不大": "不大表示雪下得不猛，与“路上很好走”相符。", "很厚": "语义：雪下得很厚，路上会很难走，与后句“路上很好走”矛盾。", "很猛": "语义：雪下得很猛，路上会很难走，与后句“路上很好走”矛盾。", "不高": "搭配：“下雪”不说“高”，“下得不高”不成立。"}, "sentence_index": 6, "correct_answer": "不大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次比赛他全部不大投入。", "explanation": "这里应该用〈全力〉。“不大”表示程度不太厉害，不能与“全部”这类表示全部的词搭配，应说“全力投入”。"}, {"text": "这件事他绝对不大在乎。", "explanation": "这里应该用〈完全不〉。“不大”表示程度不太厉害，不能与“绝对”搭配，应说“完全不在乎”。"}, {"text": "这次感冒的症状十分不大，却一直咳嗽不止。", "explanation": "这里应该用〈非常严重〉。“不大”表示程度不太厉害，不能与“十分”连用，程度深的说法是“非常严重”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f486e30-3ae2-4f13-aa8f-30c337825229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87663, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨天的风不大多，没有吹坏树。", "corrected_sentence": "昨天的风不大，没有吹坏树。", "error_description": "搭配错误：“风”不能用“多”来计量，“不大多”不能形容风，应说“风不大”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f486e30-3ae2-4f13-aa8f-30c337825229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87663, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小问题影响很不大。", "corrected_sentence": "这个小问题影响不大。", "error_description": "程度错误：“不大”前不能加程度副词“很”，表示影响不太大应说“影响不大”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f486e30-3ae2-4f13-aa8f-30c337825229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
