INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87666, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示达到某个数目，强调数量足或时间长。", "primary_collocate": null, "pronunciation": "zhěng zhěng", "ipa": "ʈʂəŋ˨˩˦ ʈʂəŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我在车站等了整整三个小时。", "target_word": "整整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下了整整一个星期的雨，天还没晴。", "target_word": "整整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他整整睡了十二个小时才醒。", "target_word": "整整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事我想了整整一个晚上。", "target_word": "整整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她学了整整五年汉语，说得很好。", "target_word": "整整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "搬家用了整整两天，大家都很累。", "target_word": "整整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他整整哭了一个下午，谁也没办法。", "target_word": "整整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市整整一个月没有下雨了。", "target_word": "整整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈做了整整一桌菜，大家吃得很开心。", "target_word": "整整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书架上整整三层都是他的书。", "target_word": "整整", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "整整：强调时间长或数量足", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7d2912c-6f4e-4394-8528-f3a78e8b990c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87666, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "整整", "is_correct": true, "explanation": "整整：副词，强调时间长，这里修饰“三个小时”，表示等得久。"}, {"text": "才", "is_correct": false, "explanation": "语义：“才”表示时间短、仅此而已，与“整整”强调时间长的意思相反。"}, {"text": "只", "is_correct": false, "explanation": "语义：“只”表示时间不长、仅此而已，与“整整”强调时间长的意思相反。"}, {"text": "差点", "is_correct": false, "explanation": "语法：“差点”表示几乎，不能直接修饰数量短语，且与“等了三个小时”的事实不合。"}], "explanations": {"整整": "整整：副词，强调时间长，这里修饰“三个小时”，表示等得久。", "才": "语义：“才”表示时间短、仅此而已，与“整整”强调时间长的意思相反。", "只": "语义：“只”表示时间不长、仅此而已，与“整整”强调时间长的意思相反。", "差点": "语法：“差点”表示几乎，不能直接修饰数量短语，且与“等了三个小时”的事实不合。"}, "sentence_index": 0, "correct_answer": "整整"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一下子就想清楚了，整整用了一秒钟。", "explanation": "这里应该用〈才〉。“整整”强调时间长，而“一秒钟”极短，应说“才用了一秒钟”。"}, {"text": "他整整敲了一下门，没有人应。", "explanation": "这里应该用〈只〉。“整整”强调时间长，而“敲了一下”是很短的动作，应说“他只敲了一下门”。"}, {"text": "他整整赢了一次比赛，很高兴。", "explanation": "这里应该用〈仅〉。“整整”强调时长或数量充足，而“赢了一次”是单次事件，不能用“整整”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f555f137-7cbf-4422-bf20-421a498cfe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87666, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "整整", "is_correct": true, "explanation": "整整：副词，强调时间长，这里修饰“哭了一个下午”，与后句“谁也没办法”相合。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上，与“哭了一个下午”的长时段矛盾。"}, {"text": "很快", "is_correct": false, "explanation": "语义：“很快”表示速度快、时间短，与“哭了一个下午”的长时段矛盾。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示很快就发生，不能修饰“一个下午”这样的长时段，与句意矛盾。"}], "explanations": {"整整": "整整：副词，强调时间长，这里修饰“哭了一个下午”，与后句“谁也没办法”相合。", "立刻": "语义：“立刻”表示马上，与“哭了一个下午”的长时段矛盾。", "很快": "语义：“很快”表示速度快、时间短，与“哭了一个下午”的长时段矛盾。", "马上": "语义：“马上”表示很快就发生，不能修饰“一个下午”这样的长时段，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "整整"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他整整哭了一小会儿就停了。", "explanation": "这里应该用〈只〉。“整整”强调时间长，而“一小会儿”很短，应说“他只哭了一小会儿就停了”。"}, {"text": "他整整哭了一分钟就笑了。", "explanation": "这里应该用〈只〉。“整整”强调时间长，而“一分钟就笑了”表示时间很短，应说“他只哭了一分钟就笑了”。"}, {"text": "他整整两秒钟就把饭吃完了。", "explanation": "这里应该用〈才〉。“整整”强调时间长，而“两秒钟就把饭吃完”是极短时间，应说“他才两秒钟就把饭吃完了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f555f137-7cbf-4422-bf20-421a498cfe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87666, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们等了整整了两个小时，车还没来。", "corrected_sentence": "我们等了整整两个小时，车还没来。", "error_description": "错误：“了”放在了“整整”后面。“整整”是副词，修饰数量短语时不能带“了”；正确是“等了整整两个小时”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f555f137-7cbf-4422-bf20-421a498cfe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87666, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们很整整等了两个小时。", "corrected_sentence": "他们整整等了两个小时。", "error_description": "错误：“很”加在了副词“整整”前。“整整”是副词，不能被程度副词“很”修饰；正确是“他们整整等了两个小时”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f555f137-7cbf-4422-bf20-421a498cfe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
