INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87668, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "古代人类活动遗留下来的痕迹或建筑物。", "primary_collocate": null, "pronunciation": "yí jì", "ipa": "i˧˥ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "这里发现了一处古代人类的遗迹。", "target_word": "遗迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考古学家在山洞里找到了新的遗迹。", "target_word": "遗迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座古城遗迹已有三千年的历史。", "target_word": "遗迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客可以参观这片古老的遗迹。", "target_word": "遗迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府决定保护这处历史遗迹。", "target_word": "遗迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家正在研究沙漠中的遗迹。", "target_word": "遗迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上留着古代人生活过的遗迹。", "target_word": "遗迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些遗迹说明这里曾经有一个大城市。", "target_word": "遗迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用照片记录了遗迹的样子。", "target_word": "遗迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这处遗迹每年吸引很多游客。", "target_word": "遗迹", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "处", "label": "量词"}, {"form": "遗迹", "label": "简体"}, {"form": "遺跡", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "古代人类留下的痕迹或建筑物，考古、历史语境", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77dd5244-fd53-4152-b5ae-74a62c865356') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87668, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "移居", "is_correct": false, "explanation": "jū（第一声）与 jì（第四声）韵母不同，移居指搬到别处住。"}, {"text": "一级", "is_correct": false, "explanation": "“一级”实读 yì jí，两字声调都与 yí jì 不同，一级指一个等级。"}, {"text": "依计", "is_correct": false, "explanation": "yī（第一声）与 yí（第二声）声调不同，依计指按照计划行事。"}, {"text": "遗迹", "is_correct": true, "explanation": "正确：遗迹（yí jì），古代人类活动留下的痕迹或建筑物。"}], "explanations": {"移居": "jū（第一声）与 jì（第四声）韵母不同，移居指搬到别处住。", "一级": "“一级”实读 yì jí，两字声调都与 yí jì 不同，一级指一个等级。", "依计": "yī（第一声）与 yí（第二声）声调不同，依计指按照计划行事。", "遗迹": "正确：遗迹（yí jì），古代人类活动留下的痕迹或建筑物。"}, "sentence_index": null, "correct_answer": "遗迹"}, "level_3": {"options": [{"text": "遗迹", "is_correct": true, "explanation": "正确：“一处古代人类的遗迹”指古人留下的地点或建筑。"}, {"text": "器物", "is_correct": false, "explanation": "搭配：量词“处”指地点，器物应说“件”，不能说“一处器物”。"}, {"text": "生活", "is_correct": false, "explanation": "语义：“生活”是行为，不是可以被发现的遗存，句意不通。"}, {"text": "时代", "is_correct": false, "explanation": "语义：“时代”是时间段，不是可以被发现的地点。"}], "explanations": {"遗迹": "正确：“一处古代人类的遗迹”指古人留下的地点或建筑。", "器物": "搭配：量词“处”指地点，器物应说“件”，不能说“一处器物”。", "生活": "语义：“生活”是行为，不是可以被发现的遗存，句意不通。", "时代": "语义：“时代”是时间段，不是可以被发现的地点。"}, "sentence_index": 0, "correct_answer": "遗迹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个古代遗迹被送进了博物馆。", "explanation": "这里应该用〈文物〉。遗迹是地点或建筑，不能搬进博物馆。"}, {"text": "他留下的遗迹都放在箱子里。", "explanation": "这里应该用〈遗物〉。遗迹是地点或建筑，不能放进箱子。"}, {"text": "他把爷爷的遗迹继承了下来。", "explanation": "这里应该用〈遗产〉。遗迹是古代人活动留下的遗存，不能说继承。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f594faad-37eb-47e7-8bae-409dfee625fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87668, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "宜居", "is_correct": false, "explanation": "jū（第一声）与 jì（第四声）韵母不同，宜居指适合居住。"}, {"text": "仪器", "is_correct": false, "explanation": "qì 与 jì 只差声母（q 与 j），仪器指测量、实验用的器具。"}, {"text": "易记", "is_correct": false, "explanation": "yì（第四声）与 yí（第二声）声调不同，易记指容易记住。"}, {"text": "遗迹", "is_correct": true, "explanation": "正确：遗迹（yí jì），古代人类活动留下的痕迹或建筑物。"}], "explanations": {"宜居": "jū（第一声）与 jì（第四声）韵母不同，宜居指适合居住。", "仪器": "qì 与 jì 只差声母（q 与 j），仪器指测量、实验用的器具。", "易记": "yì（第四声）与 yí（第二声）声调不同，易记指容易记住。", "遗迹": "正确：遗迹（yí jì），古代人类活动留下的痕迹或建筑物。"}, "sentence_index": null, "correct_answer": "遗迹"}, "level_3": {"options": [{"text": "遗迹", "is_correct": true, "explanation": "正确：“山上留着古代人生活过的遗迹”指古人生活过的遗存。"}, {"text": "杂志", "is_correct": false, "explanation": "语义：杂志是现代印刷品，不可能是古人留下的遗存，句意不通。"}, {"text": "信仰", "is_correct": false, "explanation": "语义：信仰是无形的观念，不能“留着”在山上。"}, {"text": "名次", "is_correct": false, "explanation": "搭配：“留着”的对象一般是具体的遗存，“名次”不能被留着。"}], "explanations": {"遗迹": "正确：“山上留着古代人生活过的遗迹”指古人生活过的遗存。", "杂志": "语义：杂志是现代印刷品，不可能是古人留下的遗存，句意不通。", "信仰": "语义：信仰是无形的观念，不能“留着”在山上。", "名次": "搭配：“留着”的对象一般是具体的遗存，“名次”不能被留着。"}, "sentence_index": 6, "correct_answer": "遗迹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府决定在这里新建一处遗迹。", "explanation": "遗迹指古代留下的痕迹，不能新建，这里应说建造或修建新的建筑。"}, {"text": "他把这处遗迹搬到了家里。", "explanation": "这里应该用〈遗物〉。遗迹是大型古代遗存，搬不回家；能搬回家的小件旧物是遗物。"}, {"text": "这所学校的遗迹今年刚开学。", "explanation": "这里应该用〈校舍〉。遗迹是古代留下的遗存，新建的学校不算遗迹，只是新校舍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f594faad-37eb-47e7-8bae-409dfee625fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87668, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座山上有一只古代遗迹。", "corrected_sentence": "这座山上有一处古代遗迹。", "error_description": "错误：“一只古代遗迹”；正确：“一处古代遗迹”。遗迹的量词用“处”，“只”用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f594faad-37eb-47e7-8bae-409dfee625fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87668, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山顶上有一条古代遗迹。", "corrected_sentence": "山顶上有一座古代遗迹。", "error_description": "错误：“一条古代遗迹”；正确：“一座古代遗迹”。“条”用于细长的东西，遗迹是建筑，应用“座”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f594faad-37eb-47e7-8bae-409dfee625fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87669, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "错", "is_correct": true, "explanation": "正确选项。“错”与“不错”表示“对、没错”的意思相对，是反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”表示明白、不模糊，与“对、没错”的意思没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”形容声音或环境，与“对、没错”的意思没有反义关系。"}, {"text": "热闹", "is_correct": false, "explanation": "“热闹”形容场面喧闹，与“对、没错”的意思没有反义关系。"}], "correct_answer": "错", "explanations": {"错": "正确选项。“错”与“不错”表示“对、没错”的意思相对，是反义关系。", "清楚": "“清楚”表示明白、不模糊，与“对、没错”的意思没有反义关系。", "安静": "“安静”形容声音或环境，与“对、没错”的意思没有反义关系。", "热闹": "“热闹”形容场面喧闹，与“对、没错”的意思没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abe1b8c7-5769-429e-b5fd-ee02daa76644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87669, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "错", "is_correct": true, "explanation": "正确选项。“错”与“不错”表示“对、没错”的意思相对，是反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”形容光线充足或颜色鲜亮，与“对、没错”的意思没有反义关系。"}, {"text": "热情", "is_correct": false, "explanation": "“热情”形容待人的态度，与“对、没错”的意思没有反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "“干净”形容清洁，与“对、没错”的意思没有反义关系。"}], "correct_answer": "错", "explanations": {"错": "正确选项。“错”与“不错”表示“对、没错”的意思相对，是反义关系。", "明亮": "“明亮”形容光线充足或颜色鲜亮，与“对、没错”的意思没有反义关系。", "热情": "“热情”形容待人的态度，与“对、没错”的意思没有反义关系。", "干净": "“干净”形容清洁，与“对、没错”的意思没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abe1b8c7-5769-429e-b5fd-ee02daa76644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87669, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不错是对、没有错的意思，用来肯定别人的话或判断。", "primary_collocate": null, "pronunciation": "bú cuò", "ipa": "pu˧˥ tsʰuɔ˥˩", "syllable_count": 2, "sentences": [{"text": "不错，今天确实是周五，你没记错。", "target_word": "不错", "complexity_tier": "T3", "furigana": "bú cuò, jīn tiān què shí shì zhōu wǔ, nǐ méi jì cuò.", "sentence_source": "generated"}, {"text": "不错，我就是你要找的王经理。", "target_word": "不错", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "“这是你的手机吧？”“不错，是我的。”", "target_word": "不错", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不错，这正是我想说的意思。", "target_word": "不错", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "“他是不是还在路上？”“不错，他刚发信息说堵车。”", "target_word": "不错", "complexity_tier": "T3", "furigana": "tā shì bu shì hái zài lù shang? bú cuò, tā gāng fā xìn xī shuō dǔ chē.", "sentence_source": "generated"}, {"text": "“你是第一次来中国吧？”“不错，这是我第一次来。”", "target_word": "不错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“你是李老师的学生吗？”“不错，我是。”", "target_word": "不错", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不错，这本书确实是我昨天买的。", "target_word": "不错", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "“会议是三点开，对吧？”“不错，就是三点。”", "target_word": "不错", "complexity_tier": "T3", "furigana": "huì yì shì sān diǎn kāi, duì ba? bú cuò, jiù shì sān diǎn.", "sentence_source": "generated"}, {"text": "“他们是昨天到北京的吧？”“不错，昨天就到了。”", "target_word": "不错", "complexity_tier": "T3", "furigana": "tā men shì zuó tiān dào Běijīng de ba? bú cuò, zuó tiān jiù dào le.", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "不错：表示对、没有错，用来肯定别人的话或判断", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee16606a-f927-4c1a-ac0f-73f57f89b922') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87669, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不错", "is_correct": true, "explanation": "正确选项。句首“不错”表示同意对方的判断，意思是“对、没错”，与后句“你没记错”呼应。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：“漂亮”用于称赞外貌或事物，不能用来同意对方说的日期。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材或体积，无法用来回应“今天是周五”的判断。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”指人的智力，不能用来回应一个日期判断。"}], "explanations": {"不错": "正确选项。句首“不错”表示同意对方的判断，意思是“对、没错”，与后句“你没记错”呼应。", "漂亮": "搭配：“漂亮”用于称赞外貌或事物，不能用来同意对方说的日期。", "高大": "体貌：“高大”形容身材或体积，无法用来回应“今天是周五”的判断。", "聪明": "语义：“聪明”指人的智力，不能用来回应一个日期判断。"}, "sentence_index": 0, "correct_answer": "不错"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "“你是李老师的学生吗？”“不错，我不是。”", "explanation": "这里“不错”表示“对、没错”，只能用来肯定。前面问“你是…吗”，后面却说“我不是”，前后矛盾；否定应说“不对”。"}, {"text": "“会议是三点开，对吧？”“很不错，就是三点。”", "explanation": "这里加了“很”，“很不错”变成称赞，不再表示肯定；肯定对方时应单独说“不错”，不能加“很”。"}, {"text": "“这份报告写完了吗？”“不错，还没写完。”", "explanation": "这里“不错”表示“对、没错”，只能用来肯定。前面问“写完了吗”，后面却说“还没写完”，前后矛盾；否定应说“没有”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abe1b8c7-5769-429e-b5fd-ee02daa76644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87669, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不错", "is_correct": true, "explanation": "正确选项。句首“不错”表示肯定，意思是“对、没错”，用来回答“你是……吗”。"}, {"text": "温柔", "is_correct": false, "explanation": "语义：“温柔”形容性情，不能用来回答身份问题。"}, {"text": "年轻", "is_correct": false, "explanation": "搭配：“年轻”说年龄或时期，不能用来应答“是不是学生”。"}, {"text": "活泼", "is_correct": false, "explanation": "语义：“活泼”形容性格或样子，与身份判断无关。"}], "explanations": {"不错": "正确选项。句首“不错”表示肯定，意思是“对、没错”，用来回答“你是……吗”。", "温柔": "语义：“温柔”形容性情，不能用来回答身份问题。", "年轻": "搭配：“年轻”说年龄或时期，不能用来应答“是不是学生”。", "活泼": "语义：“活泼”形容性格或样子，与身份判断无关。"}, "sentence_index": 6, "correct_answer": "不错"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "“你昨天去哪儿了？”“不错，我去了图书馆。”", "explanation": "这里“不错”表示“对、没错”，只用于肯定对方的说法。问“去哪儿了”是问地点，应直接回答“我去了图书馆”，不能用“不错”。"}, {"text": "“她已经走了吗？”“不错，她还在办公室。”", "explanation": "这里“不错”表示肯定，但后面说“她还在办公室”，与“走了”相反，前后矛盾；否定应说“没有”。"}, {"text": "“请问这里是三号楼吗？”“不错，我们在一号楼。”", "explanation": "这里“不错”表示“对、没错”，用来肯定对方。后面却说“我们在一号楼”，与“三号楼”矛盾，应说“不是”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abe1b8c7-5769-429e-b5fd-ee02daa76644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87669, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "“明天的会是在图书馆开吧？”“没不错，就在图书馆。”", "corrected_sentence": "“明天的会是在图书馆开吧？”“不错，就在图书馆。”", "error_description": "错误：“没不错”；正确：“不错”。“不错”作应答表示肯定对方的判断，前面不能加否定词“没”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abe1b8c7-5769-429e-b5fd-ee02daa76644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87669, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "“你是新来的老师吗？”“不错的，我是。”", "corrected_sentence": "“你是新来的老师吗？”“不错，我是。”", "error_description": "错误：“不错的”；正确：“不错”。作应答的“不错”是独立的词，后面不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abe1b8c7-5769-429e-b5fd-ee02daa76644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87670, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "差", "is_correct": true, "explanation": "正确选项。“差”与“不错”（质量好、令人满意）是反义关系，表示质量不好。"}, {"text": "漂亮", "is_correct": false, "explanation": "“漂亮”与“不错”都是正面评价，属于近义或同类，不是反义。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”形容明白、不模糊，与“不错”的评价义没有反义关系。"}, {"text": "便宜", "is_correct": false, "explanation": "“便宜”说价格低，与“不错”的评价义没有反义关系。"}], "correct_answer": "差", "explanations": {"差": "正确选项。“差”与“不错”（质量好、令人满意）是反义关系，表示质量不好。", "漂亮": "“漂亮”与“不错”都是正面评价，属于近义或同类，不是反义。", "清楚": "“清楚”形容明白、不模糊，与“不错”的评价义没有反义关系。", "便宜": "“便宜”说价格低，与“不错”的评价义没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abe1b8c7-5769-429e-b5fd-ee02daa76644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87670, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "糟糕", "is_correct": true, "explanation": "正确选项。“糟糕”表示情况很坏、令人不满意，与“不错”（令人满意）相对。"}, {"text": "热情", "is_correct": false, "explanation": "“热情”形容待人的态度，与“不错”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”形容声音或环境平静，与“不错”没有反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "“干净”形容清洁，与“不错”的评价义没有反义关系。"}], "correct_answer": "糟糕", "explanations": {"糟糕": "正确选项。“糟糕”表示情况很坏、令人不满意，与“不错”（令人满意）相对。", "热情": "“热情”形容待人的态度，与“不错”没有反义关系。", "安静": "“安静”形容声音或环境平静，与“不错”没有反义关系。", "干净": "“干净”形容清洁，与“不错”的评价义没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abe1b8c7-5769-429e-b5fd-ee02daa76644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87670, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "好；不坏；表示称赞或认可。", "primary_collocate": null, "pronunciation": "bú cuò", "ipa": "pu˧˥ tsʰuɔ˥˩", "syllable_count": 2, "sentences": [{"text": "这家饭馆的菜很不错。", "target_word": "不错", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的成绩一直都不错。", "target_word": "不错", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今天天气不错，我们去公园走走吧。", "target_word": "不错", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个手机的拍照效果真不错。", "target_word": "不错", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的汉语说得真不错，学了几年了？", "target_word": "不错", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我觉得这个办法不错，可以试试。", "target_word": "不错", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他工作很努力，收入也不错。", "target_word": "不错", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服颜色不错，价格也不贵。", "target_word": "不错", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友推荐的那家酒店环境很不错，我们住了三天。", "target_word": "不错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试他考得不错，老师还表扬了他。", "target_word": "不错", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "不错：形容事物或人好、令人满意，表示称赞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee16606a-f927-4c1a-ac0f-73f57f89b922') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87670, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不错", "is_correct": true, "explanation": "正确选项。“很不错”表示菜品好、令人满意，符合称赞的语境。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物体的身材、体积，不能用来评价菜的味道和质量。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”指人的智力，菜没有智力，“菜很聪明”说不通。"}, {"text": "年轻", "is_correct": false, "explanation": "搭配：“年轻”说人的年龄或事物的新旧时期，一般不用来形容菜的味道。"}], "explanations": {"不错": "正确选项。“很不错”表示菜品好、令人满意，符合称赞的语境。", "高大": "体貌：“高大”形容人或物体的身材、体积，不能用来评价菜的味道和质量。", "聪明": "语义：“聪明”指人的智力，菜没有智力，“菜很聪明”说不通。", "年轻": "搭配：“年轻”说人的年龄或事物的新旧时期，一般不用来形容菜的味道。"}, "sentence_index": 0, "correct_answer": "不错"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种病毒的传播速度很不错，一个星期就感染了全城的人。", "explanation": "这里误把“不错”当成“严重”来用，描述病毒的危害，应说“严重”。“不错”只用于称赞好的事物。"}, {"text": "我们去年的销售额很不错，比前年减少了一半。", "explanation": "“不错”只用于称赞好的情况。销售额比前年减少了一半，情况不好，这里应说“很糟糕”，不能用“不错”。"}, {"text": "这次事故的损失很不错，大家都很满意。", "explanation": "“不错”只用来称赞好的事物。这里误把“不错”当成“严重”来用，描述事故损失应说“惨重”，不能用“不错”来称赞，句子意思正好相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abe1b8c7-5769-429e-b5fd-ee02daa76644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87670, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不错", "is_correct": true, "explanation": "正确选项。“收入也不错”表示收入令人满意，与前句“工作很努力”的评价一致。"}, {"text": "温柔", "is_correct": false, "explanation": "语义：“温柔”形容性情，收入没有性情，句子说不通。"}, {"text": "活泼", "is_correct": false, "explanation": "语义：“活泼”形容人的性格或样子，不能用来形容收入。"}, {"text": "懒惰", "is_correct": false, "explanation": "搭配：“懒惰”形容人的行为态度，不能说“收入懒惰”，句子说不通。"}], "explanations": {"不错": "正确选项。“收入也不错”表示收入令人满意，与前句“工作很努力”的评价一致。", "温柔": "语义：“温柔”形容性情，收入没有性情，句子说不通。", "活泼": "语义：“活泼”形容人的性格或样子，不能用来形容收入。", "懒惰": "搭配：“懒惰”形容人的行为态度，不能说“收入懒惰”，句子说不通。"}, "sentence_index": 6, "correct_answer": "不错"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的感冒越来越不错，昨晚已经烧到四十度了。", "explanation": "这里误把“不错”用来形容病情。“不错”只用于称赞好的事物；前面说“越来越”，后面烧到四十度，病情在加重，应说“严重”。"}, {"text": "这份合同的条款很不错，对我们非常不利。", "explanation": "“不错”只用于称赞好的事物。条款对我们非常不利，这里应说“很苛刻”，不能用“不错”。"}, {"text": "这次手术失败了，医生说手术效果很不错。", "explanation": "“不错”只用于称赞好的结果。前文说手术失败了，这里应说“很糟糕”，不能用“不错”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abe1b8c7-5769-429e-b5fd-ee02daa76644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87670, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的汉语学的不错。", "corrected_sentence": "他的汉语学得不错。", "error_description": "错误：“学的不错”；正确：“学得不错”。“不错”作补语，补语前要用“得”，不用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abe1b8c7-5769-429e-b5fd-ee02daa76644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87670, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店的服务很很不错。", "corrected_sentence": "这家店的服务很不错。", "error_description": "错误：“很很不错”；正确：“很不错”。“很”只用一次，重复“很”不符合汉语习惯。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abe1b8c7-5769-429e-b5fd-ee02daa76644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
