INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87671, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "新一代是后面做出来的这一批产品，比以前的更新。", "primary_collocate": null, "pronunciation": "xīn yí dài", "ipa": "ɕin˥ i˧˥ tai̯˥˩", "syllable_count": 3, "sentences": [{"text": "新一代手机明天就要上市了。", "target_word": "新一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司做出了新一代电动车。", "target_word": "新一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新一代电脑比以前快多了。", "target_word": "新一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新一代产品的价格不太高。", "target_word": "新一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们正在做新一代的机器人。", "target_word": "新一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新一代汽车更省油，也更安静。", "target_word": "新一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这款新一代相机很轻，拍照也清楚。", "target_word": "新一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说新一代飞机明年就能飞。", "target_word": "新一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新一代电视的画面特别清楚。", "target_word": "新一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想等新一代手表出来再买。", "target_word": "新一代", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "新一代+产品：比上一批更新的一批产品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1eb026d-f55f-4628-a2a2-eaf33fe1d183') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87671, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "新一代", "is_correct": true, "explanation": "新一代指比上一批更新的一批产品，与“明天就要上市”的新手机相符。"}, {"text": "上一代", "is_correct": false, "explanation": "语义：上一代指更早的一批，不会是明天才上市的新品。"}, {"text": "老一代", "is_correct": false, "explanation": "语义：老一代指较旧的一批，与“明天就要上市”矛盾。"}, {"text": "旧款", "is_correct": false, "explanation": "搭配：“上市”一般用于新品，“旧款”与“上市”不搭配。"}], "explanations": {"新一代": "新一代指比上一批更新的一批产品，与“明天就要上市”的新手机相符。", "上一代": "语义：上一代指更早的一批，不会是明天才上市的新品。", "老一代": "语义：老一代指较旧的一批，与“明天就要上市”矛盾。", "旧款": "搭配：“上市”一般用于新品，“旧款”与“上市”不搭配。"}, "sentence_index": 0, "correct_answer": "新一代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家商店刚进了一批新一代的衣服，样式很多。", "explanation": "这里应该用〈新款〉。服装的新样式要说新款，新一代指技术更新的一批产品。"}, {"text": "这辆新一代汽车是我爷爷五十年前买的。", "explanation": "这里应该用〈老式〉。五十年前买的汽车是老式的，不能用新一代来形容。"}, {"text": "新一代手机比上一代更旧、更慢。", "explanation": "这里应该用〈老一代〉。新一代产品比上一批更新，不会更旧、更慢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87671, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "新一代", "is_correct": true, "explanation": "新一代指新推出的一代产品，与“很轻，拍照也清楚”的新相机相符。"}, {"text": "钢铁", "is_correct": false, "explanation": "语义：钢铁很重，与“很轻”矛盾。"}, {"text": "大理石", "is_correct": false, "explanation": "语义：大理石很重，与“很轻”矛盾。"}, {"text": "冰块", "is_correct": false, "explanation": "搭配：“冰块”不能用来修饰“相机”，构不成这样的名词短语。"}], "explanations": {"新一代": "新一代指新推出的一代产品，与“很轻，拍照也清楚”的新相机相符。", "钢铁": "语义：钢铁很重，与“很轻”矛盾。", "大理石": "语义：大理石很重，与“很轻”矛盾。", "冰块": "搭配：“冰块”不能用来修饰“相机”，构不成这样的名词短语。"}, "sentence_index": 6, "correct_answer": "新一代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生说这种新一代病毒很危险，大家要小心。", "explanation": "这里应该用〈新型〉。新出现的病毒种类要说新型病毒，新一代指后面做出来的一批产品。"}, {"text": "这块新一代手表已经戴了二十年了。", "explanation": "这里应该用〈老款〉。戴了二十年的手表是老款，不能用新一代来形容。"}, {"text": "这台新一代收音机是我们村一九六〇年买的。", "explanation": "这里应该用〈老式〉。一九六〇年买的收音机是老式的，不能说新一代。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87671, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店下个月会卖新一代新一代冰箱。", "corrected_sentence": "这家店下个月会卖新一代冰箱。", "error_description": "错误：“新一代”重复了一次。应说“新一代冰箱”，不能说“新一代新一代冰箱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87671, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想买一台新一代新一代笔记本电脑。", "corrected_sentence": "我想买一台新一代笔记本电脑。", "error_description": "错误：“新一代”重复了一次。应说“新一代笔记本电脑”，不能说“新一代新一代笔记本电脑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87672, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "老一代", "is_correct": true, "explanation": "“老一代”与“新一代”构成反义，指年长的一辈人。"}, {"text": "农民", "is_correct": false, "explanation": "农民指从事农业的人，与“新一代”没有新旧相对的关系。"}, {"text": "歌手", "is_correct": false, "explanation": "歌手指唱歌的职业，与“新一代”没有新旧相对的关系。"}, {"text": "科学家", "is_correct": false, "explanation": "科学家指从事科学研究的人，与“新一代”没有新旧相对的关系。"}], "correct_answer": "老一代", "explanations": {"老一代": "“老一代”与“新一代”构成反义，指年长的一辈人。", "农民": "农民指从事农业的人，与“新一代”没有新旧相对的关系。", "歌手": "歌手指唱歌的职业，与“新一代”没有新旧相对的关系。", "科学家": "科学家指从事科学研究的人，与“新一代”没有新旧相对的关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
