INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87672, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "新出现的年轻一代人，与前一辈相对。", "primary_collocate": null, "pronunciation": "xīn yí dài", "ipa": "ɕin˥ i˧˥ tai̯˥˩", "syllable_count": 3, "sentences": [{"text": "新一代年轻人喜欢在网上买东西。", "target_word": "新一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们是新一代，生活和父母不一样。", "target_word": "新一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新一代的孩子从小就会用手机。", "target_word": "新一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新一代工人有文化，也会用电脑。", "target_word": "新一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，新一代要好好学习。", "target_word": "新一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是新一代的歌手，很多人喜欢他。", "target_word": "新一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新一代农民也用手机卖水果。", "target_word": "新一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家需要新一代的科学家。", "target_word": "新一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸常说，新一代比我们幸福。", "target_word": "新一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新一代大学生更喜欢自己做决定。", "target_word": "新一代", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "新一代人", "label": "复合"}], "register": "中性", "sense_fingerprint": "新一代+人：新出现的年轻一代人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1eb026d-f55f-4628-a2a2-eaf33fe1d183') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87672, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "新一代", "is_correct": true, "explanation": "新一代指新出现的年轻一代人，与“年轻人喜欢在网上买东西”相符。"}, {"text": "老一代", "is_correct": false, "explanation": "语义：老一代指年长的一辈，与“年轻人”矛盾。"}, {"text": "老年", "is_correct": false, "explanation": "语义：老年指年纪大的时期，“老年年轻人”自相矛盾。"}, {"text": "长辈", "is_correct": false, "explanation": "搭配：“长辈”一般不用来修饰“年轻人”，这样的说法不成立。"}], "explanations": {"新一代": "新一代指新出现的年轻一代人，与“年轻人喜欢在网上买东西”相符。", "老一代": "语义：老一代指年长的一辈，与“年轻人”矛盾。", "老年": "语义：老年指年纪大的时期，“老年年轻人”自相矛盾。", "长辈": "搭配：“长辈”一般不用来修饰“年轻人”，这样的说法不成立。"}, "sentence_index": 0, "correct_answer": "新一代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那位新一代老师教了我们三十年。", "explanation": "这里应该用〈老教师〉。教了三十年的老师是老教师，不能用新一代来形容。"}, {"text": "这位新一代老人已经八十岁了。", "explanation": "这里应该用〈老一辈〉。八十岁的老人属于老一辈，不能用新一代来形容。"}, {"text": "我的父亲是新一代，他出生于一九四〇年。", "explanation": "这里应该用〈上一辈〉。父亲相对于我们这一代属于上一辈，不能称为新一代。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87672, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "新一代", "is_correct": true, "explanation": "新一代指新出现的年轻一代人，与“农民也用手机卖水果”的年轻农民相符。"}, {"text": "学者", "is_correct": false, "explanation": "语义：学者指做学问的人，“学者农民”身份矛盾，与“卖水果”不符。"}, {"text": "司机", "is_correct": false, "explanation": "语义：司机与农民是两种身份，“司机农民”自相矛盾。"}, {"text": "总统", "is_correct": false, "explanation": "语义：总统与农民身份冲突，“总统农民”自相矛盾。"}], "explanations": {"新一代": "新一代指新出现的年轻一代人，与“农民也用手机卖水果”的年轻农民相符。", "学者": "语义：学者指做学问的人，“学者农民”身份矛盾，与“卖水果”不符。", "司机": "语义：司机与农民是两种身份，“司机农民”自相矛盾。", "总统": "语义：总统与农民身份冲突，“总统农民”自相矛盾。"}, "sentence_index": 6, "correct_answer": "新一代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我爷爷是新一代，他已经九十岁了。", "explanation": "这里应该用〈老一辈〉。九十岁的爷爷属于老一辈，新一代指新出现的年轻一代人。"}, {"text": "新一代的老师六十年前就退休了。", "explanation": "这里应该用〈前辈〉。六十年前就退休的老师是前辈，不能说新一代。"}, {"text": "他是个新一代司机，已经开了三十年车。", "explanation": "这里应该用〈老司机〉。开了三十年车的司机是老司机，不能用新一代来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
