INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87673, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "酷是样子很帅，让人觉得真棒。", "primary_collocate": null, "pronunciation": "kù", "ipa": "kʰu˥˩", "syllable_count": 1, "sentences": [{"text": "他戴着黑色眼镜，看起来很酷。", "target_word": "酷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件黑外套真酷！", "target_word": "酷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的新发型太酷了。", "target_word": "酷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那辆红色的车又大又酷。", "target_word": "酷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟觉得这双鞋特别酷。", "target_word": "酷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她穿上牛仔裤，样子很酷。", "target_word": "酷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个舞蹈动作好酷啊。", "target_word": "酷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他骑着摩托车，酷极了。", "target_word": "酷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得他的新手机不太酷。", "target_word": "酷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥画的画又漂亮又酷。", "target_word": "酷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "酷炫", "label": "复合"}], "register": "口语", "sense_fingerprint": "外表、样子很帅气，让人觉得棒", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c3fb48-7015-4f79-9d9c-8a4eda67e6b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87673, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "酷", "is_correct": true, "explanation": "“酷”形容外表帅气、让人觉得棒，与“戴着黑色眼镜”的形象相符。"}, {"text": "饱", "is_correct": false, "explanation": "搭配：“饱”形容吃得满足，不能用来形容人的外表。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”指味道，与眼镜、外表无关。"}, {"text": "湿", "is_correct": false, "explanation": "语义：“湿”指含有水分，不能用来形容人的外表。"}], "explanations": {"酷": "“酷”形容外表帅气、让人觉得棒，与“戴着黑色眼镜”的形象相符。", "饱": "搭配：“饱”形容吃得满足，不能用来形容人的外表。", "咸": "语义：“咸”指味道，与眼镜、外表无关。", "湿": "语义：“湿”指含有水分，不能用来形容人的外表。"}, "sentence_index": 0, "correct_answer": "酷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的数学成绩很酷。", "explanation": "这里应该用〈优秀〉。“酷”形容外表或样子，不能用来形容成绩好。"}, {"text": "这碗米饭很酷，我吃了两碗。", "explanation": "这里应该用〈好吃〉。“酷”不用于形容食物的味道。"}, {"text": "这杯水很酷，你别喝。", "explanation": "这里应该用〈凉〉。“酷”形容外表或样子很帅，不用来形容水的温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5e4362-c5fb-45e9-aafc-472479894262') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87673, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "酷", "is_correct": true, "explanation": "“酷”用于评价事物外观很棒，与“好……啊”的评价语气搭配。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”指味道，不能用来评价舞蹈动作。"}, {"text": "腥", "is_correct": false, "explanation": "语义：“腥”指气味，不能用来评价舞蹈动作。"}, {"text": "瘦", "is_correct": false, "explanation": "搭配：“瘦”形容人或物的体形，不能用来评价舞蹈动作。"}], "explanations": {"酷": "“酷”用于评价事物外观很棒，与“好……啊”的评价语气搭配。", "咸": "语义：“咸”指味道，不能用来评价舞蹈动作。", "腥": "语义：“腥”指气味，不能用来评价舞蹈动作。", "瘦": "搭配：“瘦”形容人或物的体形，不能用来评价舞蹈动作。"}, "sentence_index": 6, "correct_answer": "酷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天天气很酷，我们都穿了厚衣服。", "explanation": "这里应该用〈冷〉。“酷”形容外表或举止潇洒，不用来形容天气的冷热。"}, {"text": "我听到这个消息，心里很酷。", "explanation": "这里应该用〈高兴〉。“酷”形容外表或举止潇洒，不用来表示心情愉快。"}, {"text": "走了一下午路，我的脚很酷。", "explanation": "这里应该用〈疼〉。“酷”形容外表或举止，不用来形容身体的疼痛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5e4362-c5fb-45e9-aafc-472479894262') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87673, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他穿着白色运动鞋，看起来酷很。", "corrected_sentence": "他穿着白色运动鞋，看起来很酷。", "error_description": "语序错误：程度副词“很”应放在形容词“酷”之前，说“很酷”，不能说“酷很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5e4362-c5fb-45e9-aafc-472479894262') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87673, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件很酷地外套我也想买。", "corrected_sentence": "这件很酷的外套我也想买。", "error_description": "结构助词错误：“酷”修饰名词“外套”时应用“的”，说“很酷的外套”，不能用“地”。“地”用于修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5e4362-c5fb-45e9-aafc-472479894262') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
