INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87674, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容外表或举止潇洒、很有个性。", "primary_collocate": null, "pronunciation": "kù", "ipa": "kʰu˥˩", "syllable_count": 1, "sentences": [{"text": "她说话的样子很酷，不爱笑。", "target_word": "酷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是一个人走路，显得很酷。", "target_word": "酷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个歌手的舞台风格非常酷。", "target_word": "酷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不管别人怎么说，做事很酷。", "target_word": "酷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他表面很酷，其实很热心。", "target_word": "酷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个女孩的性格很酷。", "target_word": "酷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他冷冷地看了我一眼，真酷。", "target_word": "酷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们都说新来的老师很酷。", "target_word": "酷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢酷一点的生活方式。", "target_word": "酷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在那里，表情很酷。", "target_word": "酷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "酷炫", "label": "复合"}], "register": "口语", "sense_fingerprint": "外表或举止潇洒、有个性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c3fb48-7015-4f79-9d9c-8a4eda67e6b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87674, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "酷", "is_correct": true, "explanation": "“酷”形容说话的样子潇洒、有个性，与“不爱笑”的描写相符。"}, {"text": "饱", "is_correct": false, "explanation": "搭配：“饱”形容吃得满足，不能用来形容说话的样子。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”指味道，与说话的样子无关。"}, {"text": "湿", "is_correct": false, "explanation": "语义：“湿”指含有水分，不能用来形容说话的样子。"}], "explanations": {"酷": "“酷”形容说话的样子潇洒、有个性，与“不爱笑”的描写相符。", "饱": "搭配：“饱”形容吃得满足，不能用来形容说话的样子。", "咸": "语义：“咸”指味道，与说话的样子无关。", "湿": "语义：“湿”指含有水分，不能用来形容说话的样子。"}, "sentence_index": 0, "correct_answer": "酷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这碗汤很酷，我全喝光了。", "explanation": "这里应该用〈好喝〉。“酷”形容人的举止或外表，不用于形容食物的味道。"}, {"text": "这家店的服务很酷，我很满意。", "explanation": "这里应该用〈周到〉。“酷”不用于形容服务的周到程度。"}, {"text": "这次数学测验他考得很酷。", "explanation": "这里应该用〈优秀〉。“酷”形容举止或样子，不用于形容考试成绩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5e4362-c5fb-45e9-aafc-472479894262') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87674, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "酷", "is_correct": true, "explanation": "“酷”形容人冷冷看人时的样子潇洒、有个性，与句意相符。"}, {"text": "瘦", "is_correct": false, "explanation": "搭配：“瘦”形容体形，不能用来评价别人看人的样子。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”指味道，不能用来形容看人的样子。"}, {"text": "烫", "is_correct": false, "explanation": "语义：“烫”指温度高，与看人的样子无关。"}], "explanations": {"酷": "“酷”形容人冷冷看人时的样子潇洒、有个性，与句意相符。", "瘦": "搭配：“瘦”形容体形，不能用来评价别人看人的样子。", "甜": "语义：“甜”指味道，不能用来形容看人的样子。", "烫": "语义：“烫”指温度高，与看人的样子无关。"}, "sentence_index": 6, "correct_answer": "酷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个西瓜很酷，又甜又多汁。", "explanation": "这里应该用〈好吃〉。“酷”形容人的外表或举止潇洒，不用来形容水果的味道。"}, {"text": "听到这个好消息，我心里很酷。", "explanation": "这里应该用〈高兴〉。“酷”形容外表或举止潇洒，不用来表示心情愉快。"}, {"text": "我跑了一上午，现在腿很酷。", "explanation": "这里应该用〈疼〉。“酷”形容外表或举止，不用来形容身体的疼痛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5e4362-c5fb-45e9-aafc-472479894262') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87674, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她上台时的表情很地酷。", "corrected_sentence": "她上台时的表情很酷。", "error_description": "多出“地”：“很酷”前面不能加“地”，应说“表情很酷”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5e4362-c5fb-45e9-aafc-472479894262') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87674, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个女孩酷很，不爱说话。", "corrected_sentence": "这个女孩很酷，不爱说话。", "error_description": "语序错误：程度副词“很”应放在形容词“酷”之前，说“很酷”，不能说“酷很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5e4362-c5fb-45e9-aafc-472479894262') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
