INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87675, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "主任是一个部门里管事的人。", "primary_collocate": null, "pronunciation": "zhǔ rèn", "ipa": "ʈʂu˨˩ ʐən˥˩", "syllable_count": 2, "sentences": [{"text": "我们办公室的主任姓王。", "target_word": "主任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主任让我下午去他的办公室。", "target_word": "主任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王主任今天出差，不在公司。", "target_word": "主任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主任说明天开会，大家不要迟到。", "target_word": "主任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我们部门的主任，大家都很喜欢他。", "target_word": "主任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有问题可以先问主任。", "target_word": "主任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事我已经告诉主任了。", "target_word": "主任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的主任很年轻，工作也很认真。", "target_word": "主任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主任每天早上八点就到公司。", "target_word": "主任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这份文件交给主任。", "target_word": "主任", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位主任", "label": "量词"}, {"form": "办公室主任", "label": "复合词"}, {"form": "副主任", "label": "复合词"}], "register": "中性", "sense_fingerprint": "主任：一个部门里管事的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7286d9a-03f3-4664-99b4-2712ee008241') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87675, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主任", "is_correct": true, "explanation": "主任是办公室的负责人，可以姓王，与句子相合。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是机器，没有姓氏，“办公室的电脑姓王”说不通。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不是人，不能说“姓王”。"}, {"text": "复印机", "is_correct": false, "explanation": "搭配：“姓”只用于人，不说“复印机姓王”。"}], "explanations": {"主任": "主任是办公室的负责人，可以姓王，与句子相合。", "电脑": "语义：电脑是机器，没有姓氏，“办公室的电脑姓王”说不通。", "窗户": "语义：窗户不是人，不能说“姓王”。", "复印机": "搭配：“姓”只用于人，不说“复印机姓王”。"}, "sentence_index": 0, "correct_answer": "主任"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这朵花的主任颜色是红色。", "explanation": "这里应该用〈主要〉。主任指部门里的负责人，不表示“最重要的”，所以“主任颜色”说不通。"}, {"text": "他的主任是照顾家人。", "explanation": "这里应该用〈任务〉。主任指部门的负责人，不指要做的事。"}, {"text": "这首歌的主任是他。", "explanation": "这里应该用〈歌手〉。主任指部门的负责人，不指唱歌的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87675, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主任", "is_correct": true, "explanation": "主任是这件事的接受人，“告诉主任了”与句子相合。"}, {"text": "墙", "is_correct": false, "explanation": "配价：“告诉”的对象要能听，墙不能听，不能作接受人。"}, {"text": "花园", "is_correct": false, "explanation": "配价：花园不能接受信息，不能作“告诉”的对象。"}, {"text": "电话", "is_correct": false, "explanation": "语义：“电话”指通信工具，句子要说的是告诉某个人。"}], "explanations": {"主任": "主任是这件事的接受人，“告诉主任了”与句子相合。", "墙": "配价：“告诉”的对象要能听，墙不能听，不能作接受人。", "花园": "配价：花园不能接受信息，不能作“告诉”的对象。", "电话": "语义：“电话”指通信工具，句子要说的是告诉某个人。"}, "sentence_index": 6, "correct_answer": "主任"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这双鞋的主任太小了。", "explanation": "主任指部门里管事的人，不能指鞋的部分或大小。"}, {"text": "那只猫是这个家的主任。", "explanation": "主任只指机关、团体或部门的负责人，不指家里的成员，这里用错了词义。"}, {"text": "这台冰箱的主任很冷。", "explanation": "主任指人或机构的负责人，不能用来形容冰箱或其中的部件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87675, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只主任今天很忙。", "corrected_sentence": "这位主任今天很忙。", "error_description": "量词错误。指人的「主任」应用量词「位」，不用「只」。正确形式：「这位主任」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87675, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我已经把这件事告诉一只主任了。", "corrected_sentence": "我已经把这件事告诉一位主任了。", "error_description": "量词错误：指人的「主任」应用量词「位」，不用「只」。正确形式：「告诉一位主任了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
