INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87676, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "机关、团体或某个部门的主要负责人。", "primary_collocate": null, "pronunciation": "zhǔ rèn", "ipa": "ʈʂu˨˩ ʐən˥˩", "syllable_count": 2, "sentences": [{"text": "她是居委会的主任，每天帮邻居做事。", "target_word": "主任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "李主任在会上讲了一个好消息。", "target_word": "主任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当了三年学校办公室主任。", "target_word": "主任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院的科室主任今天来看病人。", "target_word": "主任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个委员会的主任由张老师当。", "target_word": "主任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的主任带大家修了一条路。", "target_word": "主任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家选他做社区的主任。", "target_word": "主任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "张主任对工作要求很高。", "target_word": "主任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究所的主任是一位老教授。", "target_word": "主任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作为主任，他要对整个部门负责。", "target_word": "主任", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位主任", "label": "量词"}, {"form": "居委会主任", "label": "复合词"}, {"form": "副主任", "label": "复合词"}], "register": "中性", "sense_fingerprint": "主任：机关、团体或部门的主要负责人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7286d9a-03f3-4664-99b4-2712ee008241') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87676, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主任", "is_correct": true, "explanation": "主任是居委会的负责人，“她是居委会的主任”与句子相合。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是场所，不是可以担任的职务。"}, {"text": "病人", "is_correct": false, "explanation": "搭配：“居委会的”后接职务，“病人”不是职务。"}, {"text": "钢笔", "is_correct": false, "explanation": "语义：钢笔是文具，不能担任职务。"}], "explanations": {"主任": "主任是居委会的负责人，“她是居委会的主任”与句子相合。", "厨房": "语义：厨房是场所，不是可以担任的职务。", "病人": "搭配：“居委会的”后接职务，“病人”不是职务。", "钢笔": "语义：钢笔是文具，不能担任职务。"}, "sentence_index": 0, "correct_answer": "主任"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部电影的主任是他。", "explanation": "这里应该用〈主演〉。主任指机关、团体或部门的负责人，不指电影里的演员。"}, {"text": "这本书的主任是他。", "explanation": "这里应该用〈作者〉。主任指机关、团体或部门的负责人，不指写书的人。"}, {"text": "这辆汽车的主任很大。", "explanation": "主任指机关、团体或部门的负责人，不能指汽车的部件或大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87676, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主任", "is_correct": true, "explanation": "主任是社区的负责人，“做社区的主任”与句子相合。"}, {"text": "宿舍", "is_correct": false, "explanation": "语义：宿舍指住的地方，不能作人的职务。"}, {"text": "公园", "is_correct": false, "explanation": "搭配：“做……的”要接职务或身份，“公园”不是。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是物件，不能由人选来担任职务。"}], "explanations": {"主任": "主任是社区的负责人，“做社区的主任”与句子相合。", "宿舍": "语义：宿舍指住的地方，不能作人的职务。", "公园": "搭配：“做……的”要接职务或身份，“公园”不是。", "钥匙": "语义：钥匙是物件，不能由人选来担任职务。"}, "sentence_index": 6, "correct_answer": "主任"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间房子的主任是我。", "explanation": "主任指机关、团体或部门的负责人，房子不是部门，这里用错了词义。"}, {"text": "那只狗是这个家的主任。", "explanation": "主任只指机关、团体或部门的负责人，不指家庭成员，这里用错了词义。"}, {"text": "这台电脑的主任很快。", "explanation": "主任指人或机构的负责人，不能用来形容电脑的速度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87676, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只王主任每周都来开会。", "corrected_sentence": "这位王主任每周都来开会。", "error_description": "量词错误。“主任”指人，应用量词“位”，不能用“只”（“只”多用于动物或小物件）。应说“这位王主任”，不说“这只王主任”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87676, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这头张主任每天第一个到办公室。", "corrected_sentence": "这位张主任每天第一个到办公室。", "error_description": "量词错误。“主任”指人，应用量词“位”，不能用“头”（“头”多用于大型动物）。应说“这位张主任”，不说“这头张主任”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
