INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87677, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "新任是刚刚开始做这个工作的。", "primary_collocate": null, "pronunciation": "xīn rèn", "ipa": "ɕin˥ ɻən˥˩", "syllable_count": 2, "sentences": [{"text": "新任校长今天来我们班了。", "target_word": "新任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新任经理很年轻。", "target_word": "新任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的新任老师姓王。", "target_word": "新任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新任市长昨天参观了这家医院。", "target_word": "新任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新任总经理明天要开会。", "target_word": "新任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新任队长对大家说了几句话。", "target_word": "新任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是公司的新任主任。", "target_word": "新任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新任院长说要买新电脑。", "target_word": "新任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的新任书记很有经验。", "target_word": "新任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新任大使今天到北京了。", "target_word": "新任", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "刚开始担任某个工作的（人）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d23fd0e-84cc-4b7b-8d40-c450f027c617') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87677, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "信任", "is_correct": false, "explanation": "xìn（第四声）与 xīn（第一声）声调不同，意思是相信、信赖。"}, {"text": "新任", "is_correct": true, "explanation": "xīnrèn：刚开始担任某个职务的（人）。"}, {"text": "新人", "is_correct": false, "explanation": "rén（第二声）与 rèn（第四声）声调不同，意思是刚加入的人。"}, {"text": "欣然", "is_correct": false, "explanation": "rán（第二声）与 rèn（第四声）韵母和声调都不同，意思是高兴地、愉快地。"}], "explanations": {"信任": "xìn（第四声）与 xīn（第一声）声调不同，意思是相信、信赖。", "新任": "xīnrèn：刚开始担任某个职务的（人）。", "新人": "rén（第二声）与 rèn（第四声）声调不同，意思是刚加入的人。", "欣然": "rán（第二声）与 rèn（第四声）韵母和声调都不同，意思是高兴地、愉快地。"}, "sentence_index": null, "correct_answer": "新任"}, "level_3": {"options": [{"text": "古老", "is_correct": false, "explanation": "搭配：“古老”多修饰事物和传统，不说“古老校长”。"}, {"text": "新任", "is_correct": true, "explanation": "“新任”指刚上任的，修饰“校长”，与“今天来我们班”的语境相符。"}, {"text": "幼小", "is_correct": false, "explanation": "语义：“幼小”指年纪很小，与“校长”的身份相矛盾。"}, {"text": "笨重", "is_correct": false, "explanation": "搭配：“笨重”形容物体，不能用来修饰人。"}], "explanations": {"古老": "搭配：“古老”多修饰事物和传统，不说“古老校长”。", "新任": "“新任”指刚上任的，修饰“校长”，与“今天来我们班”的语境相符。", "幼小": "语义：“幼小”指年纪很小，与“校长”的身份相矛盾。", "笨重": "搭配：“笨重”形容物体，不能用来修饰人。"}, "sentence_index": 0, "correct_answer": "新任"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一台新任电脑。", "explanation": "这里应该用〈新〉。“新任”只指刚上任、担任职务的人，不能修饰电脑这类物品。"}, {"text": "我们班来了一位新任同学。", "explanation": "这里应该用〈新来的〉。“新任”指刚担任职务的人，转来的同学并不是职务。"}, {"text": "我的新任手机很好用。", "explanation": "这里应该用〈新〉。“新任”只指刚担任职务的人，手机是物品，不能用“新任”修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b868e1-4fa8-4876-8c24-ac089d8b2a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87677, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生动", "is_correct": false, "explanation": "搭配：“生动”形容语言、形象，不说“生动主任”。"}, {"text": "新任", "is_correct": true, "explanation": "“新任”指刚上任，修饰“主任”，符合“他是公司的……主任”的语境。"}, {"text": "湿润", "is_correct": false, "explanation": "搭配：“湿润”形容空气、土地或眼睛，不用来修饰职务。"}, {"text": "幼嫩", "is_correct": false, "explanation": "语义：“幼嫩”指植物或皮肤柔嫩，与“主任”这一职务不相符。"}], "explanations": {"生动": "搭配：“生动”形容语言、形象，不说“生动主任”。", "新任": "“新任”指刚上任，修饰“主任”，符合“他是公司的……主任”的语境。", "湿润": "搭配：“湿润”形容空气、土地或眼睛，不用来修饰职务。", "幼嫩": "语义：“幼嫩”指植物或皮肤柔嫩，与“主任”这一职务不相符。"}, "sentence_index": 6, "correct_answer": "新任"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家新任的小狗很可爱。", "explanation": "这里应该用〈新〉，如“新养的小狗”。“新任”只用于刚上任的职务人员，小狗不是职务，不能用“新任”修饰。"}, {"text": "这条新任道路很平坦。", "explanation": "这里应该用〈新〉，如“新修的道路”。“新任”只用于刚上任的职务人员，道路不能用“新任”修饰。"}, {"text": "我们家新任的房子很大。", "explanation": "这里应该用〈新〉，如“新买的房子”。“新任”只用于刚上任的职务人员，房子不能用“新任”修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b868e1-4fa8-4876-8c24-ac089d8b2a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87677, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新任校长今天给我们带来了一本新任词典。", "corrected_sentence": "新任校长今天给我们带来了一本新词典。", "error_description": "错误：“新任词典”，“新任”只修饰刚担任职务的人，不能修饰词典这类物品。正确：“新词典”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b868e1-4fa8-4876-8c24-ac089d8b2a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87677, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位很新任县长很认真。", "corrected_sentence": "这位新任县长很认真。", "error_description": "错误：“很新任县长”，“新任”是只能直接修饰名词的形容词，不能受“很”修饰。正确：“新任县长”，中间不加“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b868e1-4fa8-4876-8c24-ac089d8b2a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
