INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87680, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "缝纫、注射等用的细长而尖的小工具。", "primary_collocate": null, "pronunciation": "zhēn", "ipa": "ʈʂən˥", "syllable_count": 1, "sentences": [{"text": "护士拿着针，让孩子别怕。", "target_word": "针", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根针很细，打的时候不太疼。", "target_word": "针", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用新针给病人注射。", "target_word": "针", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用过的针不能再用，要扔掉。", "target_word": "针", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子看见针就害怕，哭了起来。", "target_word": "针", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院里的针都要放进专门的盒子。", "target_word": "针", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护士把针慢慢扎进手臂。", "target_word": "针", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种针只能用一次。", "target_word": "针", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老裁缝的针又细又长，缝得很快。", "target_word": "针", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "针一定要干净，不然会让人生病。", "target_word": "针", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "根", "label": "量词"}, {"form": "枚", "label": "量词"}, {"form": "針", "label": "繁体"}], "register": "通用", "sense_fingerprint": "缝纫、注射等用的细长尖的工具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77dd5244-fd53-4152-b5ae-74a62c865356') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87680, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "针", "is_correct": true, "explanation": "针（zhēn）：注射、缝纫用的细长尖工具，是本题的目标词。"}, {"text": "诊", "is_correct": false, "explanation": "zhěn（第三声）与 zhēn（第一声）声调不同，意思是诊断。"}, {"text": "阵", "is_correct": false, "explanation": "zhèn（第四声）与 zhēn（第一声）声调不同，意思是一阵。"}, {"text": "身", "is_correct": false, "explanation": "shēn 与 zhēn 声母不同（sh 与 zh），意思是身体。"}, {"text": "争", "is_correct": false, "explanation": "zhēng 与 zhēn 韵母不同（eng 与 en），意思是争夺。"}], "explanations": {"针": "针（zhēn）：注射、缝纫用的细长尖工具，是本题的目标词。", "诊": "zhěn（第三声）与 zhēn（第一声）声调不同，意思是诊断。", "阵": "zhèn（第四声）与 zhēn（第一声）声调不同，意思是一阵。", "身": "shēn 与 zhēn 声母不同（sh 与 zh），意思是身体。", "争": "zhēng 与 zhēn 韵母不同（eng 与 en），意思是争夺。"}, "sentence_index": null, "correct_answer": "针"}, "level_3": {"options": [{"text": "针", "is_correct": true, "explanation": "针：护士用于注射的细长尖器械，符合“让孩子别怕”的医疗语境。"}, {"text": "手术刀", "is_correct": false, "explanation": "语义：手术刀是切割器械，会让孩子更害怕，与“让孩子别怕”的语境相反。"}, {"text": "扫把", "is_correct": false, "explanation": "语义：扫把不是医疗器械，护士“拿着扫把”让孩子别怕，句子读不通。"}, {"text": "木棍", "is_correct": false, "explanation": "语义：木棍会让孩子更害怕，与“让孩子别怕”的语境冲突。"}], "explanations": {"针": "针：护士用于注射的细长尖器械，符合“让孩子别怕”的医疗语境。", "手术刀": "语义：手术刀是切割器械，会让孩子更害怕，与“让孩子别怕”的语境相反。", "扫把": "语义：扫把不是医疗器械，护士“拿着扫把”让孩子别怕，句子读不通。", "木棍": "语义：木棍会让孩子更害怕，与“让孩子别怕”的语境冲突。"}, "sentence_index": 0, "correct_answer": "针"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "护士用针量了量血压的高低。", "explanation": "这里应该用〈血压计〉。针用于注射、缝合，不能用来测量血压。"}, {"text": "护士用针喝了一杯水。", "explanation": "这里应该用〈杯子〉。针用于注射、缝合，不能当容器喝水。"}, {"text": "这只针很细，护士用它注射。", "explanation": "量词错误：这里应该用〈根〉。“只”多用于动物，不用于针。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f594faad-37eb-47e7-8bae-409dfee625fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87680, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "针", "is_correct": true, "explanation": "针（zhēn）：注射、缝合用的细长尖工具，是本题的目标词。"}, {"text": "枕", "is_correct": false, "explanation": "zhěn（第三声）与 zhēn（第一声）声调不同，意思是枕头。"}, {"text": "镇", "is_correct": false, "explanation": "zhèn（第四声）与 zhēn（第一声）声调不同，意思是城镇。"}, {"text": "深", "is_correct": false, "explanation": "shēn 与 zhēn 声母不同（sh 与 zh），意思是深浅的深。"}, {"text": "征", "is_correct": false, "explanation": "zhēng 与 zhēn 韵母不同（eng 与 en），意思是征收。"}], "explanations": {"针": "针（zhēn）：注射、缝合用的细长尖工具，是本题的目标词。", "枕": "zhěn（第三声）与 zhēn（第一声）声调不同，意思是枕头。", "镇": "zhèn（第四声）与 zhēn（第一声）声调不同，意思是城镇。", "深": "shēn 与 zhēn 声母不同（sh 与 zh），意思是深浅的深。", "征": "zhēng 与 zhēn 韵母不同（eng 与 en），意思是征收。"}, "sentence_index": null, "correct_answer": "针"}, "level_3": {"options": [{"text": "针", "is_correct": true, "explanation": "针：注射用的细长尖器械，可以“扎进手臂”，符合护理语境。"}, {"text": "药", "is_correct": false, "explanation": "搭配：“扎”需要尖细的器械，药不能被“扎进手臂”。"}, {"text": "刀", "is_correct": false, "explanation": "语义：刀扎进手臂会造成伤害，不是护理操作，句子读不通。"}, {"text": "笔", "is_correct": false, "explanation": "语义：笔不能扎进手臂，“慢慢扎进手臂”的语境与笔不符。"}], "explanations": {"针": "针：注射用的细长尖器械，可以“扎进手臂”，符合护理语境。", "药": "搭配：“扎”需要尖细的器械，药不能被“扎进手臂”。", "刀": "语义：刀扎进手臂会造成伤害，不是护理操作，句子读不通。", "笔": "语义：笔不能扎进手臂，“慢慢扎进手臂”的语境与笔不符。"}, "sentence_index": 6, "correct_answer": "针"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "护士用棉签给伤口消毒，用针擦干净伤口。", "explanation": "这里应该用〈纱布〉。针用于注射、缝合，不能用来擦拭伤口。"}, {"text": "这种针很甜，孩子们都喜欢吃。", "explanation": "这里“针”被当成了〈糖果〉，实际指注射、缝纫用的细长工具，没有甜味，不能吃。"}, {"text": "这根针很重，一下子就能挂在墙上当装饰。", "explanation": "这里“针”被当成了〈挂钩〉，实际指注射、缝纫用的细长工具，不能用来挂东西当装饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f594faad-37eb-47e7-8bae-409dfee625fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87680, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "护士用针新给老人注射。", "corrected_sentence": "护士用新针给老人注射。", "error_description": "语序错误：修饰“针”的“新”要放在“针”的前面，应为“新针”，不能说“针新”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f594faad-37eb-47e7-8bae-409dfee625fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87680, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "护士把那根很细针慢慢扎进手臂。", "corrected_sentence": "护士把那根很细的针慢慢扎进手臂。", "error_description": "结构错误：作定语的“很细”后漏了“的”，应为“很细的针”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f594faad-37eb-47e7-8bae-409dfee625fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
