INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87681, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "明星是很多人都认识、喜欢的人，常常在电视或电影里出现。", "primary_collocate": null, "pronunciation": "míng xīng", "ipa": "miŋ˧˥ ɕiŋ˥", "syllable_count": 2, "sentences": [{"text": "这个明星在很多电影里演过。", "target_word": "明星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我女儿很喜欢那位明星。", "target_word": "明星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他长得很帅，像电影明星。", "target_word": "明星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明星来了，大家都想拍照。", "target_word": "明星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视上的明星看起来都很年轻。", "target_word": "明星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天在商店里看到了一个明星。", "target_word": "明星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位明星的新电影很好看。", "target_word": "明星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人在门口等明星出来。", "target_word": "明星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想长大以后当明星。", "target_word": "明星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个明星的歌我都会唱。", "target_word": "明星", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "电影明星", "label": "复合"}], "register": "中性", "sense_fingerprint": "常在电视电影里出现、大家都认识喜欢的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4e62db1-d0f4-433b-9204-45f7851b2ab7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87681, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会表演，“这个桌子在很多电影里演过”说不通。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨是自然现象，不能在电影里演戏。"}, {"text": "杯子", "is_correct": false, "explanation": "语义：杯子是东西，不会演戏，“这个杯子在很多电影里演过”说不通。"}, {"text": "明星", "is_correct": true, "explanation": "“明星”指常在电影里出现的演员，可以说“在很多电影里演过”。"}], "explanations": {"桌子": "语义：桌子不会表演，“这个桌子在很多电影里演过”说不通。", "雨": "语义：雨是自然现象，不能在电影里演戏。", "杯子": "语义：杯子是东西，不会演戏，“这个杯子在很多电影里演过”说不通。", "明星": "“明星”指常在电影里出现的演员，可以说“在很多电影里演过”。"}, "sentence_index": 0, "correct_answer": "明星"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位明星每天在地里种菜，没有人知道他的名字。", "explanation": "这里应该用〈农民〉。农民在地里种菜，没人知道名字很正常；明星指很多人都认识、喜欢的人，这样说就自相矛盾了。"}, {"text": "这个人从来没在电视、电影里出现过，也没有人认识他，他是一位明星。", "explanation": "这里应该用〈普通人〉。明星指很多人都认识、常在电视或电影里出现的人，没人认识的人不能叫明星。"}, {"text": "这位明星每天在饭店后厨炒菜，下班后没有人会注意到他。", "explanation": "这里应该用〈厨师〉。在后厨炒菜的是厨师；明星指常在电视、电影里出现、人人认识的人，“没人会注意到他”与之矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2e7a7e9-67bd-4f23-9898-ac5580120dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87681, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "病人", "is_correct": false, "explanation": "语义：病人一般不拍电影，“那位病人的新电影”说不通。"}, {"text": "护士", "is_correct": false, "explanation": "搭配：“护士”的职业与拍电影无关，“新电影”的说法不搭配。"}, {"text": "乞丐", "is_correct": false, "explanation": "语义：乞丐与拍电影的身份不符，句子语义说不通。"}, {"text": "明星", "is_correct": true, "explanation": "“明星”是有名气的演员，可以有“新电影”，与“那位”的指称相符。"}], "explanations": {"病人": "语义：病人一般不拍电影，“那位病人的新电影”说不通。", "护士": "搭配：“护士”的职业与拍电影无关，“新电影”的说法不搭配。", "乞丐": "语义：乞丐与拍电影的身份不符，句子语义说不通。", "明星": "“明星”是有名气的演员，可以有“新电影”，与“那位”的指称相符。"}, "sentence_index": 6, "correct_answer": "明星"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位明星是我们小区的保安，除了邻居，没有人认识他。", "explanation": "这里应该用〈保安〉的普通说法，比如“这位大叔”。明星是很多人都认识、喜欢的人，只有邻居认识的人不能叫明星。"}, {"text": "我的同学是明星，可是他从来没上过电视，大家也不知道他是谁。", "explanation": "这里应该用〈学生〉。明星常在电视或电影里出现，很多人都认识；没上过电视、没人知道的人不能叫明星。"}, {"text": "今天的天气是明星，阳光很好。", "explanation": "这里应该用〈晴朗〉。明星指人，不能用来形容天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2e7a7e9-67bd-4f23-9898-ac5580120dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87681, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天在机场看到了一只明星。", "corrected_sentence": "我昨天在机场看到了一位明星。", "error_description": "量词错误：指人的“明星”应用“位”或“个”，不能用“只”。应为“看到了一位明星”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2e7a7e9-67bd-4f23-9898-ac5580120dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87681, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她们是两位明星们。", "corrected_sentence": "她们是两位明星。", "error_description": "词尾错误：“明星们”不能与数量词“两位”连用，数量短语后应直接说“明星”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2e7a7e9-67bd-4f23-9898-ac5580120dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
