INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87683, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "作者是写书或写文章的人。", "primary_collocate": null, "pronunciation": "zuò zhě", "ipa": "tswo˥˩ ʈʂɤ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这本小说的作者来自上海。", "target_word": "作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道这篇报道的作者是谁吗？", "target_word": "作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作者在后记里感谢了家人。", "target_word": "作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作者写过很多儿童故事。", "target_word": "作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想见见这本书的作者。", "target_word": "作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作者把书送给了每一位读者。", "target_word": "作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇日记的作者是我的朋友。", "target_word": "作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作者没有告诉我们故事的结局。", "target_word": "作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杂志上写着作者的名字。", "target_word": "作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作者的书，我买了三本。", "target_word": "作者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "原作者", "label": "复合"}], "register": "中性", "sense_fingerprint": "写书或写文章的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5429df9e-59d2-4ea4-a29b-edbfe11afe3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87683, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "作者", "is_correct": true, "explanation": "正确。作者（zuò zhě）指写书或写文章的人。"}, {"text": "做着", "is_correct": false, "explanation": "zhe（轻声）与 zhě（第三声）声调不同，意思是“做着”，即正在做。"}, {"text": "坐直", "is_correct": false, "explanation": "zhí 与 zhě 韵母不同（i 与 e），意思是“坐直”，即身体挺直地坐。"}, {"text": "坐诊", "is_correct": false, "explanation": "zhěn 与 zhě 韵母不同（en 与 e），意思是“坐诊”，即坐在诊室里给病人看病。"}], "explanations": {"作者": "正确。作者（zuò zhě）指写书或写文章的人。", "做着": "zhe（轻声）与 zhě（第三声）声调不同，意思是“做着”，即正在做。", "坐直": "zhí 与 zhě 韵母不同（i 与 e），意思是“坐直”，即身体挺直地坐。", "坐诊": "zhěn 与 zhě 韵母不同（en 与 e），意思是“坐诊”，即坐在诊室里给病人看病。"}, "sentence_index": null, "correct_answer": "作者"}, "level_3": {"options": [{"text": "作者", "is_correct": true, "explanation": "正确。“这本小说的作者”指写这本小说的人，可以来自上海。"}, {"text": "页数", "is_correct": false, "explanation": "配价：“来自上海”需要人或事物作主语，页数不能来自某个地方。"}, {"text": "书名", "is_correct": false, "explanation": "语义：书名是书的名称，不能从上海来。"}, {"text": "字数", "is_correct": false, "explanation": "语义：字数是一个数量，不是可以来自某地的东西。"}], "explanations": {"作者": "正确。“这本小说的作者”指写这本小说的人，可以来自上海。", "页数": "配价：“来自上海”需要人或事物作主语，页数不能来自某个地方。", "书名": "语义：书名是书的名称，不能从上海来。", "字数": "语义：字数是一个数量，不是可以来自某地的东西。"}, "sentence_index": 0, "correct_answer": "作者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是这家图书馆里最认真的作者，每周都来借书。", "explanation": "这里应该用〈读者〉。写书的人叫作者，每周来借书的人是读者。"}, {"text": "体育馆里坐满了作者，大家都在等比赛开始。", "explanation": "这里应该用〈观众〉。作者是写作的人，等比赛的人要说观众。"}, {"text": "那位作者很有名，他的表演让观众很感动。", "explanation": "这里应该用〈演员〉。作者是写作的人，表演的人要说演员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d813a9-f326-4da9-8aaf-42679c863da2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87683, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "作者", "is_correct": true, "explanation": "正确。作者（zuò zhě）指写书或写文章的人。"}, {"text": "坐着", "is_correct": false, "explanation": "zhe（轻声）与 zhě（第三声）声调不同，意思是“坐着”，指保持坐的姿势。"}, {"text": "做主", "is_correct": false, "explanation": "zhǔ 与 zhě 韵母不同（u 与 e），意思是“做主”，即替别人决定。"}, {"text": "坐车", "is_correct": false, "explanation": "chē 与 zhě 声母不同（ch 与 zh），声调也不同，意思是“坐车”，即乘车。"}], "explanations": {"作者": "正确。作者（zuò zhě）指写书或写文章的人。", "坐着": "zhe（轻声）与 zhě（第三声）声调不同，意思是“坐着”，指保持坐的姿势。", "做主": "zhǔ 与 zhě 韵母不同（u 与 e），意思是“做主”，即替别人决定。", "坐车": "chē 与 zhě 声母不同（ch 与 zh），声调也不同，意思是“坐车”，即乘车。"}, "sentence_index": null, "correct_answer": "作者"}, "level_3": {"options": [{"text": "作者", "is_correct": true, "explanation": "正确。“这篇日记的作者”指写这篇日记的人，可以是我的朋友。"}, {"text": "题目", "is_correct": false, "explanation": "语义：题目是文章的标题，不是人，不能说它是我的朋友。"}, {"text": "字迹", "is_correct": false, "explanation": "语义：字迹是笔迹，不是人，不能说它是我的朋友。"}, {"text": "纸张", "is_correct": false, "explanation": "配价：“是……的朋友”需要人作主语，纸张不能是朋友。"}], "explanations": {"作者": "正确。“这篇日记的作者”指写这篇日记的人，可以是我的朋友。", "题目": "语义：题目是文章的标题，不是人，不能说它是我的朋友。", "字迹": "语义：字迹是笔迹，不是人，不能说它是我的朋友。", "纸张": "配价：“是……的朋友”需要人作主语，纸张不能是朋友。"}, "sentence_index": 6, "correct_answer": "作者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这幅油画是他最得意的作者，挂在客厅里。", "explanation": "这里应该用〈作品〉。作者指写作的人，油画是作品，不能说是作者。"}, {"text": "这位作者做的红烧肉很好吃，大家都夸他。", "explanation": "这里应该用〈厨师〉。作者是写作的人，做菜的人要说厨师。"}, {"text": "这位作者每天给很多病人看病。", "explanation": "这里应该用〈医生〉。作者是写作的人，给病人看病的人要说医生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d813a9-f326-4da9-8aaf-42679c863da2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
