INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87684, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本作者的新书很受欢迎。", "corrected_sentence": "这位作者的新书很受欢迎。", "error_description": "量词错误：“作者”指人，应用“位”，“本”用于书籍，“这本作者”应改为“这位作者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d813a9-f326-4da9-8aaf-42679c863da2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
