INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87685, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "新阶段是事情走到了新的一步。", "primary_collocate": null, "pronunciation": "xīn jiē duàn", "ipa": "ɕin˥ tɕjɛ˥ twan˥˩", "syllable_count": 3, "sentences": [{"text": "我们的工作进入了新阶段。", "target_word": "新阶段", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛已经进入新阶段。", "target_word": "新阶段", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学完拼音，我们开始了新阶段的学习。", "target_word": "新阶段", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "项目完成后，公司走到了新阶段。", "target_word": "新阶段", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们的关系到了一个新阶段。", "target_word": "新阶段", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子上小学，生活进入新阶段。", "target_word": "新阶段", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谈判有了结果，事情进入新阶段。", "target_word": "新阶段", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次会议后，合作进入了新阶段。", "target_word": "新阶段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要为新阶段做好准备。", "target_word": "新阶段", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "病情稳定了，治疗进入新阶段。", "target_word": "新阶段", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "新階段", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事情进展到新的一步", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e64b3b0f-81c3-4b52-bcde-e97b5fd7793c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87685, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "新阶段", "is_correct": true, "explanation": "新阶段：指事情走到了新的一步，与“进入了”搭配，符合语境。"}, {"text": "大海", "is_correct": false, "explanation": "语义：“工作”不能“进入大海”，与句中事情的进展语义不符。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“工作”不是可以“进入”的场所，“厨房”与语境不合。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：“工作”不能“进入雨伞”，与句意毫不相干。"}], "explanations": {"新阶段": "新阶段：指事情走到了新的一步，与“进入了”搭配，符合语境。", "大海": "语义：“工作”不能“进入大海”，与句中事情的进展语义不符。", "厨房": "语义：“工作”不是可以“进入”的场所，“厨房”与语境不合。", "雨伞": "语义：“工作”不能“进入雨伞”，与句意毫不相干。"}, "sentence_index": 0, "correct_answer": "新阶段"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次会议的新阶段是一本词典。", "explanation": "“阶段”是抽象的时期，不是具体的物品，不能等同于一本书；应说事情进入了某个时期。"}, {"text": "他一脚踩上了新阶段。", "explanation": "这里应该用〈台阶〉。“台阶”是具体的踏脚处，可以用脚踩；“阶段”是抽象的时期，不能用脚踩。"}, {"text": "我们把新阶段放进了柜子里。", "explanation": "“阶段”指事情发展的时期，是抽象概念，不能当作具体物品放进柜子里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87685, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "新阶段", "is_correct": true, "explanation": "新阶段：指事情进入了新的时期，与“事情进入”搭配，符合语境。"}, {"text": "梦境", "is_correct": false, "explanation": "语义：“事情”不能“进入梦境”，与谈判有结果的现实语境不符。"}, {"text": "抽屉", "is_correct": false, "explanation": "语义：“事情”不能“进入抽屉”，与谈判有结果的语境不符。"}, {"text": "日记", "is_correct": false, "explanation": "语义：“事情”不能“进入日记”，“日记”与句中的事情进展不相干。"}], "explanations": {"新阶段": "新阶段：指事情进入了新的时期，与“事情进入”搭配，符合语境。", "梦境": "语义：“事情”不能“进入梦境”，与谈判有结果的现实语境不符。", "抽屉": "语义：“事情”不能“进入抽屉”，与谈判有结果的语境不符。", "日记": "语义：“事情”不能“进入日记”，“日记”与句中的事情进展不相干。"}, "sentence_index": 6, "correct_answer": "新阶段"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是我们公司的新阶段。", "explanation": "“阶段”指时期，是抽象名词，不能用来指人；指人应说〈新员工〉。"}, {"text": "他一口气买了三个新阶段。", "explanation": "“阶段”是抽象概念，不是商品，不能用“买”；“买”的对象应是具体物品。"}, {"text": "他沿着新阶段一步步走上了楼。", "explanation": "这里应该用〈楼梯〉。“楼梯”是具体的建筑部件，可以沿着走；“阶段”是抽象的时期，不能用来走路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87685, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条新阶段对我们很重要。", "corrected_sentence": "这个新阶段对我们很重要。", "error_description": "错误：量词“条”用错。“阶段”是抽象名词，量词应用“个”。正确：“这个新阶段”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87685, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们的合作打开了新阶段。", "corrected_sentence": "他们的合作进入了新阶段。", "error_description": "搭配错误：“新阶段”与“进入”或“开启”搭配，不能说“打开新阶段”。正确：“合作进入了新阶段”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
