INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87686, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物发展过程中新出现的时期。", "primary_collocate": null, "pronunciation": "xīn jiē duàn", "ipa": "ɕin˥ tɕjɛ˥ twan˥˩", "syllable_count": 3, "sentences": [{"text": "经济发展进入了新阶段。", "target_word": "新阶段", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科技的新阶段已经到来。", "target_word": "新阶段", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这座城市迎来了发展的新阶段。", "target_word": "新阶段", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新阶段的特点是人们更重视健康。", "target_word": "新阶段", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司在新阶段需要更多年轻人。", "target_word": "新阶段", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家在新阶段遇到了新问题。", "target_word": "新阶段", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个新阶段会持续好几年。", "target_word": "新阶段", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面对新阶段的变化，我们要多学习。", "target_word": "新阶段", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "疫情之后，旅游业走进了新阶段。", "target_word": "新阶段", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "社会发展到新阶段，生活更方便了。", "target_word": "新阶段", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "新階段", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事物发展中新出现的时期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e64b3b0f-81c3-4b52-bcde-e97b5fd7793c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87686, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "新阶段", "is_correct": true, "explanation": "新阶段：指事物发展中新出现的时期，与“进入了”搭配，符合语境。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“经济发展”是抽象过程，不能“进入冰箱”，与句意不符。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：“经济发展”是抽象过程，不能“进入雨伞”，与句意不符。"}, {"text": "体育馆", "is_correct": false, "explanation": "语义：“经济发展”不是可以走进的场所，“体育馆”与句意不合。"}], "explanations": {"新阶段": "新阶段：指事物发展中新出现的时期，与“进入了”搭配，符合语境。", "冰箱": "语义：“经济发展”是抽象过程，不能“进入冰箱”，与句意不符。", "雨伞": "语义：“经济发展”是抽象过程，不能“进入雨伞”，与句意不符。", "体育馆": "语义：“经济发展”不是可以走进的场所，“体育馆”与句意不合。"}, "sentence_index": 0, "correct_answer": "新阶段"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条河的新阶段很宽。", "explanation": "“阶段”是抽象的时期，没有宽窄可言；说河的宽度应指河面或河道，不能用“阶段”。"}, {"text": "他住在新阶段里。", "explanation": "这里应该用〈楼层〉。“楼层”是具体的空间，可以“住在”；“阶段”是抽象的时期，不能说“住在”。"}, {"text": "他是我们班的新阶段。", "explanation": "“阶段”指时期，是抽象名词，不能用来指人；指人应说〈同学〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87686, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "新阶段", "is_correct": true, "explanation": "新阶段：指事物发展中新出现的时期，与“会持续好几年”搭配，符合语境。"}, {"text": "时刻", "is_correct": false, "explanation": "语义：“时刻”指一个时间点，不能“持续好几年”，与句意不符。"}, {"text": "假期", "is_correct": false, "explanation": "语义：“假期”通常只有几天或几周，不能持续好几年。"}, {"text": "瞬间", "is_correct": false, "explanation": "语义：“瞬间”指极短的时间，不能“持续好几年”，与句意不符。"}], "explanations": {"新阶段": "新阶段：指事物发展中新出现的时期，与“会持续好几年”搭配，符合语境。", "时刻": "语义：“时刻”指一个时间点，不能“持续好几年”，与句意不符。", "假期": "语义：“假期”通常只有几天或几周，不能持续好几年。", "瞬间": "语义：“瞬间”指极短的时间，不能“持续好几年”，与句意不符。"}, "sentence_index": 6, "correct_answer": "新阶段"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们使用了新阶段来工作。", "explanation": "这里应该用〈工具〉。“工具”是具体的东西，可以“使用”；“阶段”是抽象的时期，不能被使用。"}, {"text": "他把新阶段放进了行李箱。", "explanation": "“阶段”是抽象的时期，不是具体物品，不能“放进行李箱”。"}, {"text": "他吃掉了一个新阶段。", "explanation": "“阶段”是抽象概念，不能当作食物吃掉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87686, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条新阶段需要大家共同努力。", "corrected_sentence": "这个新阶段需要大家共同努力。", "error_description": "错误：量词“条”用错。“阶段”是抽象名词，量词应用“个”。正确：“这个新阶段”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87686, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "社会发展到了一新阶段。", "corrected_sentence": "社会发展到了一个新阶段。", "error_description": "错误：数词“一”后漏掉了量词。“阶段”用量词“个”。正确：“一个新阶段”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
