INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87688, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "法院审理案件的场所。", "primary_collocate": null, "pronunciation": "fǎ tíng", "ipa": "fa˨˩˦ tʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "法院在这个法庭审理了案件。", "target_word": "法庭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这起案件下周在法庭审理。", "target_word": "法庭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "律师在法庭上提出了新证据。", "target_word": "法庭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法庭今天开始审理这个案子。", "target_word": "法庭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "证人走进法庭，说出了真相。", "target_word": "法庭", "complexity_tier": "T3", "furigana": "zhèng rén zǒu jìn fǎ tíng, shuō chū le zhēn xiàng.", "sentence_source": "generated"}, {"text": "法庭上的人都站了起来。", "target_word": "法庭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个法庭可以坐两百人。", "target_word": "法庭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在法庭上承认了错误。", "target_word": "法庭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法庭外面有很多记者。", "target_word": "法庭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法官走进法庭，案件开始审理。", "target_word": "法庭", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个法庭", "label": "量词"}, {"form": "法庭上", "label": "复合"}], "register": "中性", "sense_fingerprint": "法院审理案件的场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '934308b8-5ea3-4b86-bc2c-3ae9d4ecc7fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87688, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "法庭", "is_correct": true, "explanation": "正确。“法院在这个……审理了案件”指审案的场所，法庭符合。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，法院不会在那里审理案件。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：“审理案件”需要法庭这类场所，不能说在花园里审理。"}, {"text": "公交车", "is_correct": false, "explanation": "语义：公交车是交通工具，不是审理案件的场所。"}], "explanations": {"法庭": "正确。“法院在这个……审理了案件”指审案的场所，法庭符合。", "厨房": "语义：厨房是做饭的地方，法院不会在那里审理案件。", "花园": "搭配：“审理案件”需要法庭这类场所，不能说在花园里审理。", "公交车": "语义：公交车是交通工具，不是审理案件的场所。"}, "sentence_index": 0, "correct_answer": "法庭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "法庭今天抓了一个小偷。", "explanation": "这里应该用〈警察局〉。抓人是警察的工作，法庭只负责审理案件。"}, {"text": "我今天去法庭做了个体检。", "explanation": "这里应该用〈医院〉。法庭是审理案件的场所，做体检要去医院。"}, {"text": "我下午去法庭取了一万块钱。", "explanation": "这里应该用〈银行〉。法庭不办理存取款，取钱要去银行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e465b488-5baf-4d5d-8d0c-f048f967da82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87688, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "法庭", "is_correct": true, "explanation": "正确。“可以坐两百人”说明这是能容纳很多人的场所，法庭符合。"}, {"text": "信封", "is_correct": false, "explanation": "语义：信封很小，装不下两百人。"}, {"text": "抽屉", "is_correct": false, "explanation": "搭配：“坐人”需要场所或座位，抽屉不能用于“可以坐两百人”。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是很小的物件，不可能坐两百人。"}], "explanations": {"法庭": "正确。“可以坐两百人”说明这是能容纳很多人的场所，法庭符合。", "信封": "语义：信封很小，装不下两百人。", "抽屉": "搭配：“坐人”需要场所或座位，抽屉不能用于“可以坐两百人”。", "钥匙": "语义：钥匙是很小的物件，不可能坐两百人。"}, "sentence_index": 6, "correct_answer": "法庭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我今天在法庭上买了一件衣服。", "explanation": "这里应该用〈商场〉。法庭是审理案件的场所，买衣服要去商场。"}, {"text": "他被关进法庭服刑。", "explanation": "这里应该用〈监狱〉。服刑要在监狱，法庭是审理案件的场所。"}, {"text": "他每天下班后去法庭健身。", "explanation": "这里应该用〈健身房〉。法庭是审理案件的场所，健身要去健身房。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e465b488-5baf-4d5d-8d0c-f048f967da82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87688, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这辆法庭今天审理了一起案件。", "corrected_sentence": "这个法庭今天审理了一起案件。", "error_description": "量词错误：法庭应该用“个”或“间”，不能用“辆”。“辆”用于车。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e465b488-5baf-4d5d-8d0c-f048f967da82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87688, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那辆法庭里坐满了记者。", "corrected_sentence": "那间法庭里坐满了记者。", "error_description": "量词错误：法庭作为房间应该用“间”，不能用“辆”。“辆”用于车辆。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e465b488-5baf-4d5d-8d0c-f048f967da82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
