INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87689, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "电压是推动电流走的力量，数大了用电要小心。", "primary_collocate": null, "pronunciation": "diàn yā", "ipa": "tjɛn˥˩ ja˥", "syllable_count": 2, "sentences": [{"text": "家里的电压太高，灯泡很容易坏。", "target_word": "电压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用电前要先看清楚电压是多少。", "target_word": "电压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小电器的电压比较低。", "target_word": "电压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电压太大的时候，不要用手去摸。", "target_word": "电压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天用电的人多，电压有时候不够。", "target_word": "电压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请检查一下插座的电压。", "target_word": "电压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电压不够，所以冰箱不工作了。", "target_word": "电压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子不能碰电压很高的设备。", "target_word": "电压", "complexity_tier": "T3", "furigana": "xiǎo háizi bù néng pèng diànyā hěn gāo de shèbèi.", "sentence_source": "generated"}, {"text": "电压变高以后，灯一下子亮多了。", "target_word": "电压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人说这条线的电压很大，要小心。", "target_word": "电压", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高电压", "label": "复合"}, {"form": "低电压", "label": "复合"}, {"form": "電壓", "label": "繁体"}], "register": "中性", "sense_fingerprint": "日常用电中推动电流的力量，大小要注意安全", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77dd5244-fd53-4152-b5ae-74a62c865356') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87689, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "声音", "is_correct": false, "explanation": "语义：声音太高不会让灯泡坏，句子意思不通。"}, {"text": "电压", "is_correct": true, "explanation": "「电压」指推动电流的力量，电压太高，灯泡就容易坏。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格的高低与灯泡坏没有关系。"}, {"text": "电能", "is_correct": false, "explanation": "搭配：「电能」一般说多少，不说「太高」，与这里的说法不搭。"}], "explanations": {"声音": "语义：声音太高不会让灯泡坏，句子意思不通。", "电压": "「电压」指推动电流的力量，电压太高，灯泡就容易坏。", "价格": "语义：价格的高低与灯泡坏没有关系。", "电能": "搭配：「电能」一般说多少，不说「太高」，与这里的说法不搭。"}, "sentence_index": 0, "correct_answer": "电压"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个电压很重，我一只手搬不动。", "explanation": "电压是抽象的电势差，没有重量，不能说“重”或用手搬动。"}, {"text": "这块手机的电压只剩百分之十了。", "explanation": "表示电池剩余的电量要用〈电量〉。「电压」指电势差，不能用来说电池还剩多少。"}, {"text": "电压会阻碍电流通过。", "explanation": "阻碍电流是〈电阻〉的作用，电压不能阻碍电流。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f594faad-37eb-47e7-8bae-409dfee625fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87689, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人气", "is_correct": false, "explanation": "语义：人气不够不会导致冰箱不工作。"}, {"text": "电压", "is_correct": true, "explanation": "「电压」不够时，电流不足，冰箱就不工作了。"}, {"text": "笑容", "is_correct": false, "explanation": "语义：笑容与冰箱能不能工作没有关系。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：「脾气」说大小，不说「不够」，与这里的说法不搭。"}], "explanations": {"人气": "语义：人气不够不会导致冰箱不工作。", "电压": "「电压」不够时，电流不足，冰箱就不工作了。", "笑容": "语义：笑容与冰箱能不能工作没有关系。", "脾气": "搭配：「脾气」说大小，不说「不够」，与这里的说法不搭。"}, "sentence_index": 6, "correct_answer": "电压"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "电压能存储电荷。", "explanation": "存储电荷是〈电容〉的功能，电压本身不能存储电荷。"}, {"text": "这条电压太高，灯泡都烧坏了。", "explanation": "「条」用于细长的东西（如线、路），电压是抽象的量，应说〈个〉。"}, {"text": "电压用来测量用电量。", "explanation": "测量用电量要用〈电表〉，电压不能用来测量用电量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f594faad-37eb-47e7-8bae-409dfee625fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87689, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "家里的电压高升了，灯泡一下子就亮了。", "corrected_sentence": "家里的电压升高了，灯泡一下子就亮了。", "error_description": "错误：“高升”；正确：“升高”。“高升”指官职或地位上升，不用于电压的变化。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f594faad-37eb-47e7-8bae-409dfee625fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87689, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个变压器可以把电压降高。", "corrected_sentence": "这个变压器可以把电压降低。", "error_description": "错误：“降高”；正确：“降低”。“降”表示减少，应与“低”搭配，“降高”与“降”的意思相反。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f594faad-37eb-47e7-8bae-409dfee625fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
