INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87690, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "推动电荷定向移动形成电流的电势差，单位是伏特。", "primary_collocate": null, "pronunciation": "diàn yā", "ipa": "tjɛn˥˩ ja˥", "syllable_count": 2, "sentences": [{"text": "这块电池的电压是一点五伏特。", "target_word": "电压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用电压表可以测出两点之间的电压。", "target_word": "电压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电压越高，电流通常就越大。", "target_word": "电压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国家庭用电的电压是二百二十伏。", "target_word": "电压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电压的单位是伏特。", "target_word": "电压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们测量电路中的电压。", "target_word": "电压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电阻不变时，电压变大，电流也变大。", "target_word": "电压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机充电器会把电压降低。", "target_word": "电压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验中，电压表显示电压为三伏。", "target_word": "电压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高压线的电压比家里的高得多。", "target_word": "电压", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高电压", "label": "复合"}, {"form": "低电压", "label": "复合"}, {"form": "電壓", "label": "繁体"}], "register": "科技", "sense_fingerprint": "物理量，电势差，单位伏特，可用电压表测量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77dd5244-fd53-4152-b5ae-74a62c865356') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87690, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电流", "is_correct": false, "explanation": "搭配：「电流」的单位是安培，不能与「伏特」搭配。"}, {"text": "电压", "is_correct": true, "explanation": "「电压」的单位是伏特，这块电池的电压是一点五伏特。"}, {"text": "电量", "is_correct": false, "explanation": "语义：「电量」表示电的多少，不以伏特计量。"}, {"text": "电阻", "is_correct": false, "explanation": "语义：「电阻」的单位是欧姆，不是伏特。"}], "explanations": {"电流": "搭配：「电流」的单位是安培，不能与「伏特」搭配。", "电压": "「电压」的单位是伏特，这块电池的电压是一点五伏特。", "电量": "语义：「电量」表示电的多少，不以伏特计量。", "电阻": "语义：「电阻」的单位是欧姆，不是伏特。"}, "sentence_index": 0, "correct_answer": "电压"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这根导线里的电压流得很快。", "explanation": "流动的是〈电流〉。电压是电势差，不会流动，这里应该用〈电流〉。"}, {"text": "这个手机的电压只剩一成了。", "explanation": "表示电池剩余的多少要用〈电量〉。「电压」不能用来表示电池还剩多少。"}, {"text": "电压能挡住电流。", "explanation": "挡住或阻碍电流是〈电阻〉的作用，电压不能挡住电流。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f594faad-37eb-47e7-8bae-409dfee625fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87690, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人数", "is_correct": false, "explanation": "语义：人数变大与电流变大没有关系。"}, {"text": "电压", "is_correct": true, "explanation": "电阻不变时，电压变大，电流也随之变大，符合欧姆定律。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业变多与电流变大无关。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：「脚步」说快慢，不说变大，与这里的说法不搭。"}], "explanations": {"人数": "语义：人数变大与电流变大没有关系。", "电压": "电阻不变时，电压变大，电流也随之变大，符合欧姆定律。", "作业": "语义：作业变多与电流变大无关。", "脚步": "搭配：「脚步」说快慢，不说变大，与这里的说法不搭。"}, "sentence_index": 6, "correct_answer": "电压"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "电压能把电荷存起来。", "explanation": "存电荷是〈电容〉的作用，电压不能存电荷。"}, {"text": "电压用来测量耗电的多少。", "explanation": "测量耗电多少要用〈电表〉，电压不能用来测量耗电。"}, {"text": "这条电压太高，灯泡很快就烧坏了。", "explanation": "「条」用于细长的东西（如线、路），电压是抽象的量，应说〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f594faad-37eb-47e7-8bae-409dfee625fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87690, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "同学们测出了这段线路的电压，是三斤。", "corrected_sentence": "同学们测出了这段线路的电压，是三伏。", "error_description": "错误：“三斤”；正确：“三伏”。电压的单位是伏特，“斤”是重量单位，不能用来表示电压。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f594faad-37eb-47e7-8bae-409dfee625fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87690, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种装置会把电压升低。", "corrected_sentence": "这种装置会把电压降低。", "error_description": "错误：“升低”；正确：“降低”。电压减小应说“降低”，“升”表示上升，不能与“低”搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f594faad-37eb-47e7-8bae-409dfee625fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
