INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87693, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87693, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "既而是说过了一会儿，后来又怎么样了。", "primary_collocate": null, "pronunciation": "jì ér", "ipa": "tɕi˥˩ ɚ˧˥", "syllable_count": 2, "sentences": [{"text": "他先是笑了笑，既而大哭起来。", "target_word": "既而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "刚才天还很晴，既而下起了大雨。", "target_word": "既而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她先是一愣，既而明白了一切。", "target_word": "既而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨声很小，既而越来越大。", "target_word": "既而", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大家先是安静，既而热烈鼓掌。", "target_word": "既而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他起初不同意，既而点了点头。", "target_word": "既而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "屋里先是一片黑，既而亮起了灯。", "target_word": "既而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子先哭了几声，既而睡着了。", "target_word": "既而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师先看了看我，既而问了一个问题。", "target_word": "既而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天空先是阴沉，既而飘起了雪花。", "target_word": "既而", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "过了一会儿，后来情况又变了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e64b3b0f-81c3-4b52-bcde-e97b5fd7793c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87693, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "既而", "is_correct": true, "explanation": "既而：表示过了一会儿，后来又怎样，接在“先是笑了笑”之后，正好表示先后变化。"}, {"text": "始终", "is_correct": false, "explanation": "语义：“始终”表示从头到尾一直如此，与“先是笑了笑”的变化相矛盾。"}, {"text": "仍然", "is_correct": false, "explanation": "语义：“仍然”表示状态延续不变，前面并没有哭，不能接在“先是笑了笑”之后。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”通常与否定或“一直”连用，不能直接修饰“大哭起来”这一变化。"}], "explanations": {"既而": "既而：表示过了一会儿，后来又怎样，接在“先是笑了笑”之后，正好表示先后变化。", "始终": "语义：“始终”表示从头到尾一直如此，与“先是笑了笑”的变化相矛盾。", "仍然": "语义：“仍然”表示状态延续不变，前面并没有哭，不能接在“先是笑了笑”之后。", "从来": "搭配：“从来”通常与否定或“一直”连用，不能直接修饰“大哭起来”这一变化。"}, "sentence_index": 0, "correct_answer": "既而"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "既而你已经答应了，就别再反悔了。", "explanation": "这里应该用〈既然〉。“既然”表示因为已经……而引出结论；“既而”表示过了不久，此处不合。"}, {"text": "他年轻时当过兵，既而三年后才做起了生意。", "explanation": "这里应该用〈直到〉。“既而”表示不久之后，与“三年后才”的长时间间隔矛盾。"}, {"text": "他既而高兴，又有些难过。", "explanation": "这里应该用〈既……又……〉。“既而”表示先后，不用于并列的两种状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87693, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "既而", "is_correct": true, "explanation": "既而：表示过了一会儿后来亮起了灯，接在“先是一片黑”之后，表示先后变化。"}, {"text": "早已", "is_correct": false, "explanation": "体貌：“早已”表示在此之前就已如此，与“先是一片黑”的已发生情况相矛盾。"}, {"text": "本来", "is_correct": false, "explanation": "语义：“本来”表示原本如此，与“先是一片黑”之后才亮灯的先后变化不符。"}, {"text": "老是", "is_correct": false, "explanation": "语域：“老是”口语色彩较重，且表示反复，与这里书面语中的一次性变化不符。"}], "explanations": {"既而": "既而：表示过了一会儿后来亮起了灯，接在“先是一片黑”之后，表示先后变化。", "早已": "体貌：“早已”表示在此之前就已如此，与“先是一片黑”的已发生情况相矛盾。", "本来": "语义：“本来”表示原本如此，与“先是一片黑”之后才亮灯的先后变化不符。", "老是": "语域：“老是”口语色彩较重，且表示反复，与这里书面语中的一次性变化不符。"}, "sentence_index": 6, "correct_answer": "既而"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "既而大家都同意了，我们就开始吧。", "explanation": "这里应该用〈既然〉。“既然”表示因为已经……而引出结论；“既而”表示过了不久，与此不符。"}, {"text": "他聪明，既而勤奋。", "explanation": "这里应该用〈而且〉。“而且”表示递进；“既而”表示过了一会儿才发生的事，不用于并列两种特征。"}, {"text": "我们既而要检查设备，再开始工作。", "explanation": "这里应该用〈首先〉。“首先”用于第一步；“既而”表示过了一会儿后发生的事，前面没有可接的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87693, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他沉默了一会儿，既而既而抬起了头。", "corrected_sentence": "他沉默了一会儿，既而抬起了头。", "error_description": "错误：“既而”重复出现，多写了一个“既而”。正确：“既而”是副词，全句只需用一次，应为「既而抬起了头」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87693, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车停在路边，很既而司机下了车。", "corrected_sentence": "车停在路边，既而司机下了车。", "error_description": "错误：“既而”是表示先后的副词，不能受程度副词“很”修饰，应删去“很”。正确为「车停在路边，既而司机下了车」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
