INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87694, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示紧接着前面的事情之后。", "primary_collocate": null, "pronunciation": "jì ér", "ipa": "tɕi˥˩ ɚ˧˥", "syllable_count": 2, "sentences": [{"text": "他先打开门，既而走了进去。", "target_word": "既而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她先喝了口水，既而开始讲故事。", "target_word": "既而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车停下来，既而门慢慢打开了。", "target_word": "既而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "主持人先介绍了嘉宾，既而宣布比赛开始。", "target_word": "既而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他先拿起笔，既而在纸上写了名字。", "target_word": "既而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "灯一闪，既而整个房间都黑了。", "target_word": "既而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人先叹了口气，既而说起往事。", "target_word": "既而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生先检查了伤口，既而给他包好。", "target_word": "既而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他先沉默了很久，既而低声说了一句话。", "target_word": "既而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们先唱了一首歌，既而跳起舞来。", "target_word": "既而", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "紧接着前一件事，随后发生另一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e64b3b0f-81c3-4b52-bcde-e97b5fd7793c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87694, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "既而", "is_correct": true, "explanation": "既而：表示紧接着前一个动作之后发生另一个动作，正好接在“先打开门”之后。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”通常与否定或“一直”连用，不能直接修饰“走了进去”这个一次性动作。"}, {"text": "始终", "is_correct": false, "explanation": "语义：“始终”表示从头到尾一直如此，与“先打开门，紧接着进去”的顺承相矛盾。"}, {"text": "曾经", "is_correct": false, "explanation": "体貌：“曾经”表示过去有过的经历，不能用来描述紧接着发生的连贯动作。"}], "explanations": {"既而": "既而：表示紧接着前一个动作之后发生另一个动作，正好接在“先打开门”之后。", "从来": "搭配：“从来”通常与否定或“一直”连用，不能直接修饰“走了进去”这个一次性动作。", "始终": "语义：“始终”表示从头到尾一直如此，与“先打开门，紧接着进去”的顺承相矛盾。", "曾经": "体貌：“曾经”表示过去有过的经历，不能用来描述紧接着发生的连贯动作。"}, "sentence_index": 0, "correct_answer": "既而"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们既而要准备材料，然后再开始实验。", "explanation": "这里应该用〈首先〉。“首先”表示第一步；“既而”表示紧接着前一件事之后发生，这里前面没有可接的动作。"}, {"text": "他既而吃饭，又看电视。", "explanation": "这里应该用〈一边……一边……〉。“既而”表示先后，不能与“又”并列，也不能表示同时进行的两件事。"}, {"text": "他大学毕业十年后，既而回到母校任教。", "explanation": "这里应该用〈才〉。“才”表示事情比预期晚；“既而”表示紧接着前一件事发生，前面隔了十年，就不合适。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87694, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "既而", "is_correct": true, "explanation": "既而：表示紧接着叹气之后又说起往事，前后顺承，符合语境。"}, {"text": "本来", "is_correct": false, "explanation": "语义：“本来”表示原本如此，与“先叹了口气”之后再说起往事的顺承不符。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不时发生，与“先叹了口气，紧接着说起”的连贯动作不符。"}, {"text": "早已", "is_correct": false, "explanation": "体貌：“早已”表示在此之前就已发生，与“先叹了口气”的先后顺序相矛盾。"}], "explanations": {"既而": "既而：表示紧接着叹气之后又说起往事，前后顺承，符合语境。", "本来": "语义：“本来”表示原本如此，与“先叹了口气”之后再说起往事的顺承不符。", "偶尔": "语义：“偶尔”表示不时发生，与“先叹了口气，紧接着说起”的连贯动作不符。", "早已": "体貌：“早已”表示在此之前就已发生，与“先叹了口气”的先后顺序相矛盾。"}, "sentence_index": 6, "correct_answer": "既而"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们既而要了解情况，再做决定。", "explanation": "这里应该用〈首先〉。“既而”表示紧接着前面的事情发生，这里是第一步，前面没有可接的动作。"}, {"text": "他们在唱歌，既而同时跳舞。", "explanation": "这里应该用〈一边……一边……〉。两件事同时进行；“既而”表示紧接着前一件事之后发生，不能表示同时。"}, {"text": "他离开家乡多年以后，既而回到了家乡。", "explanation": "这里应该用〈终于〉。“终于”表示经过较长时间后才实现；“既而”表示紧接着前面的事发生，与“多年以后”的长间隔不合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87694, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她关上门，既而既而拿起了电话。", "corrected_sentence": "她关上门，既而拿起了电话。", "error_description": "错误：“既而”重复出现，多写了一个“既而”。正确：“既而”是副词，全句只需用一次，应为「既而拿起了电话」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87694, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他放下碗，很既而擦了擦嘴。", "corrected_sentence": "他放下碗，既而擦了擦嘴。", "error_description": "错误：“既而”是表示先后的副词，不能受程度副词“很”修饰，应删去“很”。正确为「他放下碗，既而擦了擦嘴」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
