INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87695, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "饼是用面做成的圆圆的食物。", "primary_collocate": null, "pronunciation": "bǐng", "ipa": "piŋ˨˩", "syllable_count": 1, "sentences": [{"text": "奶奶早上给我烙了一张饼。", "target_word": "饼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我早饭吃了一块热饼。", "target_word": "饼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张饼又圆又薄，上面有芝麻。", "target_word": "饼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用面粉和水做了几个饼。", "target_word": "饼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把饼切成小块，递给我。", "target_word": "饼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饼在锅里烙了很久，有点儿硬了。", "target_word": "饼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们边走边吃饼，没带别的东西。", "target_word": "饼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的饼又香又软，很多人来买。", "target_word": "饼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想学做饼，请奶奶教我。", "target_word": "饼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明左手拿着一张饼，右手拿着牛奶。", "target_word": "饼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "块", "label": "量词"}, {"form": "饼干", "label": "复合"}, {"form": "月饼", "label": "复合"}, {"form": "餅", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用面做成的圆形食物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dac0efc-fc80-403b-ae86-f40de6bf3e10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87695, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "饼", "is_correct": true, "explanation": "正确。饼：用面做成的圆圆的食物。"}, {"text": "病", "is_correct": false, "explanation": "bìng（第四声）与 bǐng（第三声）声调不同，意思是生病。"}, {"text": "笔", "is_correct": false, "explanation": "bǐ 与 bǐng 韵尾不同（少了 -ng），意思是笔。"}, {"text": "领", "is_correct": false, "explanation": "lǐng 与 bǐng 声母不同（l 与 b），意思是衣领或领导。"}, {"text": "请", "is_correct": false, "explanation": "qǐng 与 bǐng 声母不同（q 与 b），意思是请求。"}], "explanations": {"饼": "正确。饼：用面做成的圆圆的食物。", "病": "bìng（第四声）与 bǐng（第三声）声调不同，意思是生病。", "笔": "bǐ 与 bǐng 韵尾不同（少了 -ng），意思是笔。", "领": "lǐng 与 bǐng 声母不同（l 与 b），意思是衣领或领导。", "请": "qǐng 与 bǐng 声母不同（q 与 b），意思是请求。"}, "sentence_index": null, "correct_answer": "饼"}, "level_3": {"options": [{"text": "饼", "is_correct": true, "explanation": "正确。烙的是面食，“烙了一张饼”符合语境。"}, {"text": "照片", "is_correct": false, "explanation": "语义：“烙”用于面食，不能烙照片。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“烙”的对象不能是桌子，桌子不能被烙。"}, {"text": "纸", "is_correct": false, "explanation": "语义：纸不能用锅烙，“烙了一张纸”不合常理。"}], "explanations": {"饼": "正确。烙的是面食，“烙了一张饼”符合语境。", "照片": "语义：“烙”用于面食，不能烙照片。", "桌子": "搭配：“烙”的对象不能是桌子，桌子不能被烙。", "纸": "语义：纸不能用锅烙，“烙了一张纸”不合常理。"}, "sentence_index": 0, "correct_answer": "饼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我用饼在本子上写字。", "explanation": "这里应该用〈笔〉。饼是食物，写字要用笔。"}, {"text": "天太热了，我们打开饼凉快一下。", "explanation": "这里应该用〈空调〉。饼是食物，不能用来降温。"}, {"text": "他口渴了，喝了一大杯饼。", "explanation": "这里应该用〈水〉。饼是固体食物，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '690cc4fd-58f2-443c-92c6-b9f3c286a0f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87695, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "饼", "is_correct": true, "explanation": "正确。饼：用面做成的圆圆的食物。"}, {"text": "冰", "is_correct": false, "explanation": "bīng（第一声）与 bǐng（第三声）声调不同，意思是冰。"}, {"text": "顶", "is_correct": false, "explanation": "dǐng 与 bǐng 声母不同（d 与 b），意思是顶部。"}, {"text": "醒", "is_correct": false, "explanation": "xǐng 与 bǐng 声母不同（x 与 b），意思是醒来。"}, {"text": "井", "is_correct": false, "explanation": "jǐng 与 bǐng 声母不同（j 与 b），意思是水井。"}], "explanations": {"饼": "正确。饼：用面做成的圆圆的食物。", "冰": "bīng（第一声）与 bǐng（第三声）声调不同，意思是冰。", "顶": "dǐng 与 bǐng 声母不同（d 与 b），意思是顶部。", "醒": "xǐng 与 bǐng 声母不同（x 与 b），意思是醒来。", "井": "jǐng 与 bǐng 声母不同（j 与 b），意思是水井。"}, "sentence_index": null, "correct_answer": "饼"}, "level_3": {"options": [{"text": "饼", "is_correct": true, "explanation": "正确。边走边吃的是食物，饼符合语境。"}, {"text": "报纸", "is_correct": false, "explanation": "语义：报纸不能吃，与“边走边吃”的语境不合。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能吃，与“没带别的东西”所指的食物语境不合。"}, {"text": "书本", "is_correct": false, "explanation": "语义：书本不能吃，与“边走边吃”的食物语境不合。"}], "explanations": {"饼": "正确。边走边吃的是食物，饼符合语境。", "报纸": "语义：报纸不能吃，与“边走边吃”的语境不合。", "石头": "语义：石头不能吃，与“没带别的东西”所指的食物语境不合。", "书本": "语义：书本不能吃，与“边走边吃”的食物语境不合。"}, "sentence_index": 6, "correct_answer": "饼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把饼拉成了长长的细条。", "explanation": "这里应该用〈面条〉。饼是扁圆的，拉不成长条，细长的面条才能这样拉。"}, {"text": "妈妈给我盛了一碗饼当早饭。", "explanation": "这里应该用〈粥〉。饼是扁圆的固体，不能用碗盛着吃，碗里盛的应是粥。"}, {"text": "他把饼倒进杯子里喝掉了。", "explanation": "这里应该用〈牛奶〉。饼是固体食品，不能倒进杯子里喝，要喝的应是牛奶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '690cc4fd-58f2-443c-92c6-b9f3c286a0f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87695, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他带了两只饼去学校。", "corrected_sentence": "他带了两块饼去学校。", "error_description": "量词用错。“饼”应用“块”或“张”来计量，“只”用于动物等，不能说“两只饼”，应说“两块饼”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '690cc4fd-58f2-443c-92c6-b9f3c286a0f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87695, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在路边买了两条饼。", "corrected_sentence": "我在路边买了两张饼。", "error_description": "量词用错。“条”用于细长的东西，如鱼、路；圆而扁的“饼”要用“张”或“块”，应说“两张饼”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '690cc4fd-58f2-443c-92c6-b9f3c286a0f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
