INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87696, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用面粉等制成的扁圆形食品；泛指扁圆形的东西。", "primary_collocate": null, "pronunciation": "bǐng", "ipa": "piŋ˨˩", "syllable_count": 1, "sentences": [{"text": "他把肉末压成圆圆的饼，放进锅里煎。", "target_word": "饼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把面团压扁，做成一个饼。", "target_word": "饼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们用湿泥巴捏了几个饼玩。", "target_word": "饼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民把豆子压成饼，用来喂牛。", "target_word": "饼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上有一张刚烙好的饼，还冒着热气。", "target_word": "饼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天中午只吃了一块饼。", "target_word": "饼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把面粉和成面团，擀成薄薄的饼。", "target_word": "饼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个饼很大，我一个人吃不完。", "target_word": "饼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了两张饼，一张自己吃，一张给弟弟。", "target_word": "饼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子把橡皮泥压成扁扁的饼。", "target_word": "饼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "块", "label": "量词"}, {"form": "饼干", "label": "复合"}, {"form": "铁饼", "label": "复合"}, {"form": "餅", "label": "繁体"}], "register": "中性", "sense_fingerprint": "扁圆形食品，泛指扁圆形的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dac0efc-fc80-403b-ae86-f40de6bf3e10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87696, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "饼", "is_correct": true, "explanation": "正确。饼：扁圆形的食品，泛指扁圆形的东西。"}, {"text": "兵", "is_correct": false, "explanation": "bīng（第一声）与 bǐng（第三声）声调不同，意思是士兵。"}, {"text": "拧", "is_correct": false, "explanation": "nǐng 与 bǐng 声母不同（n 与 b），意思是拧，如拧毛巾。"}, {"text": "景", "is_correct": false, "explanation": "jǐng 与 bǐng 声母不同（j 与 b），意思是风景。"}, {"text": "挺", "is_correct": false, "explanation": "tǐng 与 bǐng 声母不同（t 与 b），意思是挺直、挺立。"}], "explanations": {"饼": "正确。饼：扁圆形的食品，泛指扁圆形的东西。", "兵": "bīng（第一声）与 bǐng（第三声）声调不同，意思是士兵。", "拧": "nǐng 与 bǐng 声母不同（n 与 b），意思是拧，如拧毛巾。", "景": "jǐng 与 bǐng 声母不同（j 与 b），意思是风景。", "挺": "tǐng 与 bǐng 声母不同（t 与 b），意思是挺直、挺立。"}, "sentence_index": null, "correct_answer": "饼"}, "level_3": {"options": [{"text": "饼", "is_correct": true, "explanation": "正确。肉末压成圆形、放进锅里煎，符合“饼”的语境。"}, {"text": "方块", "is_correct": false, "explanation": "语义：“圆圆的”与“方块”的形状相矛盾。"}, {"text": "绳子", "is_correct": false, "explanation": "语义：绳子不能压成圆形后放进锅里煎，与语境不合。"}, {"text": "纸", "is_correct": false, "explanation": "搭配：纸不能放进锅里煎，“煎”的对象不能是纸。"}], "explanations": {"饼": "正确。肉末压成圆形、放进锅里煎，符合“饼”的语境。", "方块": "语义：“圆圆的”与“方块”的形状相矛盾。", "绳子": "语义：绳子不能压成圆形后放进锅里煎，与语境不合。", "纸": "搭配：纸不能放进锅里煎，“煎”的对象不能是纸。"}, "sentence_index": 0, "correct_answer": "饼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把饼拉成了长长的细条。", "explanation": "这里应该用〈面条〉。饼是扁圆形的，细长的是面条。"}, {"text": "她用饼把门锁上了。", "explanation": "这里应该用〈钥匙〉。锁门要用钥匙，不用饼。"}, {"text": "他口渴了，喝了一杯饼。", "explanation": "这里应该用〈水〉。饼是固体，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '690cc4fd-58f2-443c-92c6-b9f3c286a0f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87696, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "饼", "is_correct": true, "explanation": "正确。饼：扁圆形的食品，泛指扁圆形的东西。"}, {"text": "顶", "is_correct": false, "explanation": "dǐng 与 bǐng 声母不同（d 与 b），意思是顶部。"}, {"text": "请", "is_correct": false, "explanation": "qǐng 与 bǐng 声母不同（q 与 b），意思是请求。"}, {"text": "醒", "is_correct": false, "explanation": "xǐng 与 bǐng 声母不同（x 与 b），意思是醒来。"}, {"text": "病", "is_correct": false, "explanation": "bìng（第四声）与 bǐng（第三声）声调不同，意思是生病。"}], "explanations": {"饼": "正确。饼：扁圆形的食品，泛指扁圆形的东西。", "顶": "dǐng 与 bǐng 声母不同（d 与 b），意思是顶部。", "请": "qǐng 与 bǐng 声母不同（q 与 b），意思是请求。", "醒": "xǐng 与 bǐng 声母不同（x 与 b），意思是醒来。", "病": "bìng（第四声）与 bǐng（第三声）声调不同，意思是生病。"}, "sentence_index": null, "correct_answer": "饼"}, "level_3": {"options": [{"text": "饼", "is_correct": true, "explanation": "正确。面团擀成薄薄的扁圆形食品，符合“饼”的语境。"}, {"text": "木板", "is_correct": false, "explanation": "语义：擀不能用于木板，“擀成薄薄的木板”不合常理。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头擀不成薄片，与“擀”的语境不合。"}, {"text": "铁皮", "is_correct": false, "explanation": "搭配：“擀”不搭配金属，不能说擀成铁皮。"}], "explanations": {"饼": "正确。面团擀成薄薄的扁圆形食品，符合“饼”的语境。", "木板": "语义：擀不能用于木板，“擀成薄薄的木板”不合常理。", "石头": "语义：石头擀不成薄片，与“擀”的语境不合。", "铁皮": "搭配：“擀”不搭配金属，不能说擀成铁皮。"}, "sentence_index": 6, "correct_answer": "饼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子把橡皮泥搓成长长的饼。", "explanation": "这里应该用〈条〉。长长的是条，饼是扁圆的。"}, {"text": "妈妈给我盛了一碗饼喝。", "explanation": "这里应该用〈汤〉。饼不能盛在碗里喝。"}, {"text": "我用饼给朋友打电话。", "explanation": "这里应该用〈手机〉。打电话要用手机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '690cc4fd-58f2-443c-92c6-b9f3c286a0f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.va