INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87696, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她用面团擀出一只薄饼。", "corrected_sentence": "她用面团擀出一张薄饼。", "error_description": "量词用错。“饼”应用“张”或“块”来计量，“只”用于动物等，不能说“一只薄饼”，应说“一张薄饼”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '690cc4fd-58f2-443c-92c6-b9f3c286a0f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
