INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87697, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "当选是大家投票以后，你被选上了。", "primary_collocate": null, "pronunciation": "dāng xuǎn", "ipa": "taŋ˥ ɕɥɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "全班同学投票，小林当选班长。", "target_word": "当选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他得了最多的票，所以当选了。", "target_word": "当选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "投票结束后，她高兴地说：“我当选了！”", "target_word": "当选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想当选，就要多听大家的话。", "target_word": "当选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们投票选组长，老刘当选了。", "target_word": "当选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当选主席，大家都鼓掌。", "target_word": "当选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她当选过一次学生会主席。", "target_word": "当选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁的票最多，谁当选。", "target_word": "当选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王没有当选，他有点难过。", "target_word": "当选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们投了票，我当选了代表。", "target_word": "当选", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "当选了", "label": "完成体"}, {"form": "当选过", "label": "经历体"}], "register": "正式", "sense_fingerprint": "大家投票后得票最多，被选上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c82921da-4675-443e-aa98-940b45501dcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87697, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当选", "is_correct": true, "explanation": "正确：当选指经全班投票后被选上，与“投票”和“班长”相合。"}, {"text": "任命", "is_correct": false, "explanation": "语义：任命由上级指派，与前文“投票”的产生方式相矛盾。"}, {"text": "落选", "is_correct": false, "explanation": "配价：落选是不及物动词，不能直接带宾语“班长”。"}, {"text": "睡觉", "is_correct": false, "explanation": "配价：睡觉是不及物动词，不能带宾语“班长”，句子不通。"}], "explanations": {"当选": "正确：当选指经全班投票后被选上，与“投票”和“班长”相合。", "任命": "语义：任命由上级指派，与前文“投票”的产生方式相矛盾。", "落选": "配价：落选是不及物动词，不能直接带宾语“班长”。", "睡觉": "配价：睡觉是不及物动词，不能带宾语“班长”，句子不通。"}, "sentence_index": 0, "correct_answer": "当选"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他当选了最多的票。", "explanation": "这里应该用〈得〉。当选指被选上，票数要说“得”，如“得了最多的票”。"}, {"text": "这份提案当选了。", "explanation": "这里应该用〈通过〉。当选的对象是人，提案被大家同意要说通过。"}, {"text": "他在辩论赛中当选了。", "explanation": "这里应该用〈获胜〉。当选只用于投票选出，辩论比赛的胜负要说获胜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '932a57fe-9398-41db-9fdd-1b79fde921e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87697, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当选", "is_correct": true, "explanation": "正确：“当选过”表示曾经通过投票被选上，经历用“过”。"}, {"text": "哭", "is_correct": false, "explanation": "配价：哭是不及物动词，不能带宾语“学生会主席”。"}, {"text": "洗", "is_correct": false, "explanation": "语义：洗的对象是具体物品，不能作用于“学生会主席”。"}, {"text": "出生", "is_correct": false, "explanation": "配价：出生是不及物动词，不能直接带宾语“学生会主席”。"}], "explanations": {"当选": "正确：“当选过”表示曾经通过投票被选上，经历用“过”。", "哭": "配价：哭是不及物动词，不能带宾语“学生会主席”。", "洗": "语义：洗的对象是具体物品，不能作用于“学生会主席”。", "出生": "配价：出生是不及物动词，不能直接带宾语“学生会主席”。"}, "sentence_index": 6, "correct_answer": "当选"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司当选了这个工程。", "explanation": "这里应该用〈中标〉。当选的对象是人，并要经投票选出，工程通过招标获得要说中标。"}, {"text": "公司当选了三名新员工。", "explanation": "这里应该用〈录用〉。员工由公司录用，不经投票，不能说当选。"}, {"text": "他当选了这所大学。", "explanation": "这里应该用〈考上〉。当选的是职务或代表，考进学校要说考上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '932a57fe-9398-41db-9fdd-1b79fde921e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87697, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她当选了过一次班长，很有经验。", "corrected_sentence": "她当选过一次班长，很有经验。", "error_description": "体标重复：表示曾经有过的经历只用“过”，“当选了过”里“了”和“过”重复。正确说法是“当选过一次班长”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '932a57fe-9398-41db-9fdd-1b79fde921e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87697, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去年不当选班长，心里有点失望。", "corrected_sentence": "他去年没当选班长，心里有点失望。", "error_description": "否定词错误：表示过去没有被选上要用“没”，“不”多用于主观意愿或习惯。正确说法是“没当选”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '932a57fe-9398-41db-9fdd-1b79fde921e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
