INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87698, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在选举中被选中。", "primary_collocate": null, "pronunciation": "dāng xuǎn", "ipa": "taŋ˥ ɕɥɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "他在这次选举中当选了市长。", "target_word": "当选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "李老师当选为我们学校的校长。", "target_word": "当选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她当选以后，每天都很忙。", "target_word": "当选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王明去年当选了村长。", "target_word": "当选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都希望他能当选。", "target_word": "当选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他三次竞选，都没有当选。", "target_word": "当选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位女士当选过两次市长。", "target_word": "当选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁当选班长，现在还不知道。", "target_word": "当选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她当选后发表了简短的讲话。", "target_word": "当选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选举结果出来了，小张当选。", "target_word": "当选", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "当选了", "label": "完成体"}, {"form": "当选过", "label": "经历体"}], "register": "正式", "sense_fingerprint": "选举中胜出，被选为某职务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c82921da-4675-443e-aa98-940b45501dcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87698, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当选", "is_correct": true, "explanation": "正确：当选指在选举中被选上，与“选举”和“市长”搭配。"}, {"text": "任命", "is_correct": false, "explanation": "语义：任命是上级委派，不经过选举，与句中“选举中”的语境冲突。"}, {"text": "落选", "is_correct": false, "explanation": "配价：落选是不及物动词，不能带宾语“市长”。"}, {"text": "参加", "is_correct": false, "explanation": "配价：参加带的是活动或事件，不能直接以“市长”作宾语，句子不通。"}], "explanations": {"当选": "正确：当选指在选举中被选上，与“选举”和“市长”搭配。", "任命": "语义：任命是上级委派，不经过选举，与句中“选举中”的语境冲突。", "落选": "配价：落选是不及物动词，不能带宾语“市长”。", "参加": "配价：参加带的是活动或事件，不能直接以“市长”作宾语，句子不通。"}, "sentence_index": 0, "correct_answer": "当选"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去年当选了国家队。", "explanation": "这里应该用〈入选〉。当选指在选举中被选上，进入国家队这类挑选名单要说入选。"}, {"text": "他在比赛中当选了第一名。", "explanation": "这里应该用〈获得〉。当选只用于选举中被选上，比赛名次要说获得。"}, {"text": "他今年顺利当选了北京大学。", "explanation": "这里应该用〈考上〉。当选指在选举中被选上，考进学校要说考上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '932a57fe-9398-41db-9fdd-1b79fde921e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87698, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当选", "is_correct": true, "explanation": "正确：当选过表示曾经在选举中被选上，多次当选的经历用“过”。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃是吃东西的动作，不能作用于“市长”，句义完全不通。"}, {"text": "洗", "is_correct": false, "explanation": "语义：洗的对象是具体物品，不能以“市长”作宾语。"}, {"text": "辞职", "is_correct": false, "explanation": "配价：辞职是不及物动词，不能直接带宾语“市长”。"}], "explanations": {"当选": "正确：当选过表示曾经在选举中被选上，多次当选的经历用“过”。", "吃": "语义：吃是吃东西的动作，不能作用于“市长”，句义完全不通。", "洗": "语义：洗的对象是具体物品，不能以“市长”作宾语。", "辞职": "配价：辞职是不及物动词，不能直接带宾语“市长”。"}, "sentence_index": 6, "correct_answer": "当选"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司当选了三名优秀员工。", "explanation": "这里应该用〈选拔〉。当选需要选民投票选出职务或代表，公司挑选员工要说选拔。"}, {"text": "他们公司当选了这个项目。", "explanation": "这里应该用〈中标〉。当选的对象是人，并要经选举，项目通过招标获得要说中标。"}, {"text": "他当选了这次考试。", "explanation": "这里应该用〈通过〉。当选指被选上，考试不能被选上，只能说通过。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '932a57fe-9398-41db-9fdd-1b79fde921e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87698, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在选举中没有当选了村里的代表。", "corrected_sentence": "她在选举中没有当选村里的代表。", "error_description": "体标错误：“没有”否定已发生的事时不能再带“了”，应说“没有当选”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '932a57fe-9398-41db-9fdd-1b79fde921e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87698, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她当选是学生会主席。", "corrected_sentence": "她当选为学生会主席。", "error_description": "错误形式：“当选是”。“当选”后引出所当选的职务时可用介词“为”（“当选为学生会主席”），不能用“是”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '932a57fe-9398-41db-9fdd-1b79fde921e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
