INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87699, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "团体是为了一件事聚在一起的一群人。", "primary_collocate": null, "pronunciation": "tuán tǐ", "ipa": "tʰwan˧˥ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个团体一共有二十个人。", "target_word": "团体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们是来参观的团体，一起买票更便宜。", "target_word": "团体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个旅游团体走进了博物馆。", "target_word": "团体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个团体正在门口等导游。", "target_word": "团体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "团体住宿比一个人住便宜。", "target_word": "团体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个团体来自北京，要去长城。", "target_word": "团体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个团体都穿着红色的衣服。", "target_word": "团体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个外国团体坐大巴来到了学校。", "target_word": "团体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个团体要在这儿住三天。", "target_word": "团体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务员请这个团体先坐下等一等。", "target_word": "团体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "团体票", "label": "复合"}, {"form": "团体赛", "label": "复合"}], "register": "通用", "sense_fingerprint": "为同一件事临时聚在一起的一群人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcccfa74-1e16-4e92-abd1-a3b542c01668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87699, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "苹果", "is_correct": false, "explanation": "语义：苹果是水果，不能说有二十个人，这里讲不通。"}, {"text": "团体", "is_correct": true, "explanation": "「团体」指为同一件事临时聚在一起的一群人，可以说有二十个人，符合句意。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是设备，不能装有二十个人。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：「天气」不能与「有二十个人」搭配。"}], "explanations": {"苹果": "语义：苹果是水果，不能说有二十个人，这里讲不通。", "团体": "「团体」指为同一件事临时聚在一起的一群人，可以说有二十个人，符合句意。", "手机": "语义：手机是设备，不能装有二十个人。", "天气": "搭配：「天气」不能与「有二十个人」搭配。"}, "sentence_index": 0, "correct_answer": "团体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张团体正在门口等导游。", "explanation": "量词错误：团体是一群人，应用〈个〉，而〈张〉用于平面的东西。"}, {"text": "这个团体是一个小男孩，正在门口等导游。", "explanation": "这里应该用〈个人〉。团体指由多人组成的集体，不能用来指一个单独的小男孩。"}, {"text": "一块团体正在门口等导游。", "explanation": "量词错误：团体是一群人组成的集体，应用〈个〉，而〈块〉用于块状的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87699, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "课本", "is_correct": false, "explanation": "语义：课本是书，不能穿衣服。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子是建筑，不能穿衣服。"}, {"text": "团体", "is_correct": true, "explanation": "「团体」是一群人，可以说都穿着红色的衣服，符合句意。"}, {"text": "成员", "is_correct": false, "explanation": "搭配：「成员」指单个人，与表示复数的「都」搭配不当。"}], "explanations": {"课本": "语义：课本是书，不能穿衣服。", "房子": "语义：房子是建筑，不能穿衣服。", "团体": "「团体」是一群人，可以说都穿着红色的衣服，符合句意。", "成员": "搭配：「成员」指单个人，与表示复数的「都」搭配不当。"}, "sentence_index": 6, "correct_answer": "团体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "服务员请这本团体先坐下等一等。", "explanation": "量词错误：团体是一群人，应用〈个〉，而〈本〉用于书籍。"}, {"text": "服务员请这个团体的身体先坐下等一等。", "explanation": "这里应该用〈个人〉。团体是集体，没有身体，不能用来指个人的身体。"}, {"text": "服务员请那位团体先坐下等一等。", "explanation": "量词错误：「位」用于单个的人且带敬意，而团体是一群人组成的集体，应用〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87699, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只团体一共有十五个人。", "corrected_sentence": "这个团体一共有十五个人。", "error_description": "「团体」的量词应用「个」，不能用「只」。应说「这个团体」，不能说「这只团体」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87699, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位团体今天都穿着红色的衣服。", "corrected_sentence": "这个团体今天都穿着红色的衣服。", "error_description": "「团体」的量词应用「个」，不能用「位」。应说「这个团体」，不能说「这位团体」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
