INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87700, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "因共同目的、志趣而组成的集体。", "primary_collocate": null, "pronunciation": "tuán tǐ", "ipa": "tʰwan˧˥ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个团体每个周末都组织爬山活动。", "target_word": "团体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他加入了一个读书团体。", "target_word": "团体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个青年团体帮助很多孩子学习。", "target_word": "团体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校有三个音乐团体。", "target_word": "团体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个团体的成员都喜欢摄影。", "target_word": "团体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几个爱好者成立了一个环保团体。", "target_word": "团体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她参加的团体每月开一次会。", "target_word": "团体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个团体为山区小学捐了很多书。", "target_word": "团体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师鼓励我们加入学校的团体。", "target_word": "团体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个团体的目的是保护小动物。", "target_word": "团体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "团体赛", "label": "复合"}, {"form": "团体操", "label": "复合"}], "register": "通用", "sense_fingerprint": "因共同目的或兴趣组成的集体、组织", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcccfa74-1e16-4e92-abd1-a3b542c01668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87700, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "报纸", "is_correct": false, "explanation": "语义：报纸是出版物，不能组织爬山活动。"}, {"text": "团体", "is_correct": true, "explanation": "「团体」指因共同目的组成的集体，可以组织活动，符合句意。"}, {"text": "房间", "is_correct": false, "explanation": "语义：房间是空间，不能组织活动。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：「组织」需要有行动能力的主体，「天气」不能与「组织活动」搭配。"}], "explanations": {"报纸": "语义：报纸是出版物，不能组织爬山活动。", "团体": "「团体」指因共同目的组成的集体，可以组织活动，符合句意。", "房间": "语义：房间是空间，不能组织活动。", "天气": "搭配：「组织」需要有行动能力的主体，「天气」不能与「组织活动」搭配。"}, "sentence_index": 0, "correct_answer": "团体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们学校有三只团体。", "explanation": "量词错误：团体是一群人组成的集体，应用〈个〉，而〈只〉多用于动物或成对的东西。"}, {"text": "他是一个团体，住在城市里。", "explanation": "这里应该用〈个人〉。团体指由多人组成的集体，不能用来指一个人。"}, {"text": "我们楼下坐着一位团体。", "explanation": "量词错误：团体不是一个人，不能用〈位〉，〈位〉用于指人且带敬意。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87700, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手机", "is_correct": false, "explanation": "语义：手机是电子设备，不能参加活动并定期开会。"}, {"text": "团体", "is_correct": true, "explanation": "「团体」是集体，可以被参加，并能定期开会，符合句意。"}, {"text": "游戏", "is_correct": false, "explanation": "语义：游戏不能开会，「开会」的主体必须是有组织的集体。"}, {"text": "问题", "is_correct": false, "explanation": "搭配：「参加」一般不与「问题」搭配，「问题」也不能开会。"}], "explanations": {"手机": "语义：手机是电子设备，不能参加活动并定期开会。", "团体": "「团体」是集体，可以被参加，并能定期开会，符合句意。", "游戏": "语义：游戏不能开会，「开会」的主体必须是有组织的集体。", "问题": "搭配：「参加」一般不与「问题」搭配，「问题」也不能开会。"}, "sentence_index": 6, "correct_answer": "团体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本团体的目的是保护小动物。", "explanation": "量词错误：团体是一群人组成的集体，应用〈个〉，而〈本〉用于书籍。"}, {"text": "这位团体的目的是保护小动物。", "explanation": "量词错误：〈位〉用于单个的人且带敬意，团体是集体，应用〈个〉。"}, {"text": "这张团体的目的是保护小动物。", "explanation": "量词错误：〈张〉用于平面的东西，团体应用〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87700, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位团体每周都组织爬山活动。", "corrected_sentence": "这个团体每周都组织爬山活动。", "error_description": "「团体」的量词应用「个」，不能用「位」。应说「这个团体」，不能说「这位团体」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87700, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个社区有三个团体们。", "corrected_sentence": "这个社区有三个团体。", "error_description": "错误：「们」不能与「三个」这类数量短语连用，应说「这个社区有三个团体」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
