INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87703, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "首脑是一个国家或一个团体里最高的领头人。", "primary_collocate": null, "pronunciation": "shǒu nǎo", "ipa": "ʂoʊ˨˩˦ nɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "两国首脑今天在北京见面。", "target_word": "首脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各国首脑一起讨论经济问题。", "target_word": "首脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个政党的首脑是一位年轻的女士。", "target_word": "首脑", "complexity_tier": "T3", "furigana": "zhè ge zhèngdǎng de shǒunǎo shì yí wèi niánqīng de nǚshì.", "sentence_source": "generated"}, {"text": "各国首脑下个月要在一起开会。", "target_word": "首脑", "complexity_tier": "T3", "furigana": "gè guó shǒunǎo xià gè yuè yào zài yìqǐ kāihuì.", "sentence_source": "generated"}, {"text": "他是这个组织的首脑，大家都听他的。", "target_word": "首脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三位首脑握了握手，然后开始谈话。", "target_word": "首脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小团体的首脑决定明天出发。", "target_word": "首脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家首脑出国访问，需要做很多准备。", "target_word": "首脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者在门口等着首脑出来。", "target_word": "首脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议结束后，首脑们发表了声明。", "target_word": "首脑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "国家首脑", "label": "复合"}, {"form": "首腦", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "国家或团体里最高的领头人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77dd5244-fd53-4152-b5ae-74a62c865356') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87703, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "行李", "is_correct": false, "explanation": "语义：行李不能在北京见面，句子意思不通。"}, {"text": "首脑", "is_correct": true, "explanation": "「首脑」指国家的最高领导人，两国首脑在北京见面，符合句意。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会在北京见面。"}, {"text": "宴会", "is_correct": false, "explanation": "搭配：「见面」的主体要是人，宴会不能直接作主语与「见面」搭配。"}], "explanations": {"行李": "语义：行李不能在北京见面，句子意思不通。", "首脑": "「首脑」指国家的最高领导人，两国首脑在北京见面，符合句意。", "桌子": "语义：桌子不会在北京见面。", "宴会": "搭配：「见面」的主体要是人，宴会不能直接作主语与「见面」搭配。"}, "sentence_index": 0, "correct_answer": "首脑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子的首脑很结实。", "explanation": "「首脑」只指国家或团体的最高领导人，不能用于椅子等物品。"}, {"text": "会议上来了一只首脑。", "explanation": "「只」用于动物，指人要用〈位〉。"}, {"text": "他的首脑很聪明，数学总是考满分。", "explanation": "「首脑」指国家或团体的最高领导人，指脑子应说〈头脑〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f594faad-37eb-47e7-8bae-409dfee625fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87703, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "食物", "is_correct": false, "explanation": "语义：食物不能决定出发的时间。"}, {"text": "首脑", "is_correct": true, "explanation": "「首脑」是团体的最高领导人，由他决定出发，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能做决定。"}, {"text": "脚印", "is_correct": false, "explanation": "搭配：「脚印」不能作「决定」的主语，二者搭配不当。"}], "explanations": {"食物": "语义：食物不能决定出发的时间。", "首脑": "「首脑」是团体的最高领导人，由他决定出发，符合句意。", "天气": "语义：天气不能做决定。", "脚印": "搭配：「脚印」不能作「决定」的主语，二者搭配不当。"}, "sentence_index": 6, "correct_answer": "首脑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她戴着很漂亮的首脑。", "explanation": "「首脑」指国家或团体的最高领导人，戴在身上的装饰品应说〈首饰〉。"}, {"text": "这条鱼的首脑很大。", "explanation": "「首脑」指国家或团体的最高领导人，不能指鱼的头部，应说〈头〉。"}, {"text": "这篇文章的首脑写得很精彩。", "explanation": "「首脑」指国家或团体的最高领导人，文章的开头应说〈开头〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f594faad-37eb-47e7-8bae-409dfee625fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87703, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两只首脑今天在北京见面。", "corrected_sentence": "两位首脑今天在北京见面。", "error_description": "「首脑」指人，量词应用「位」，不能用「只」（只用于动物）。应说「两位首脑」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f594faad-37eb-47e7-8bae-409dfee625fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87703, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两位首脑们决定明天出发。", "corrected_sentence": "这两位首脑决定明天出发。", "error_description": "「们」不能与「数词＋量词」一起用，应说「这两位首脑」，不能说「这两位首脑们」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f594faad-37eb-47e7-8bae-409dfee625fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
