INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87704, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "国家、政府或团体的最高领导人。", "primary_collocate": null, "pronunciation": "shǒu nǎo", "ipa": "ʂoʊ˨˩˦ nɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "各国政府首脑参加了这次大会。", "target_word": "首脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是政府首脑，工作很忙。", "target_word": "首脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "联合国大楼里来了很多国家首脑。", "target_word": "首脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国首脑签署了合作协议。", "target_word": "首脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各国首脑每年都见一次面。", "target_word": "首脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者报道了各国首脑到达的消息。", "target_word": "首脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位首脑在电视上讲了话。", "target_word": "首脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两位首脑通过电话谈了一个小时。", "target_word": "首脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "欢迎仪式上，市民们向首脑挥手。", "target_word": "首脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家首脑要对人民负责。", "target_word": "首脑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "政府首脑", "label": "复合"}, {"form": "首腦", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "国家、政府或团体的最高领导人，外交与政治语境", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77dd5244-fd53-4152-b5ae-74a62c865356') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87704, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "行人", "is_correct": false, "explanation": "语义：行人不是政府的代表，不会参加大会这样的正式会议。"}, {"text": "首脑", "is_correct": true, "explanation": "「首脑」指国家或政府的最高领导人，各国政府首脑参加大会，符合句意。"}, {"text": "盆栽", "is_correct": false, "explanation": "语义：盆栽是植物，不能参加大会。"}, {"text": "大厅", "is_correct": false, "explanation": "搭配：「参加」的主语应是人，大厅不能参加会议。"}], "explanations": {"行人": "语义：行人不是政府的代表，不会参加大会这样的正式会议。", "首脑": "「首脑」指国家或政府的最高领导人，各国政府首脑参加大会，符合句意。", "盆栽": "语义：盆栽是植物，不能参加大会。", "大厅": "搭配：「参加」的主语应是人，大厅不能参加会议。"}, "sentence_index": 0, "correct_answer": "首脑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子的首脑很聪明，每次考试都得满分。", "explanation": "「首脑」指国家或政府的最高领导人，指脑子应说〈头脑〉。"}, {"text": "这座山的首脑上有很多雪。", "explanation": "「首脑」指国家、政府或团体的最高领导人，山的最高处应说〈山顶〉。"}, {"text": "这篇论文的首脑写得很清楚。", "explanation": "「首脑」指国家或政府的最高领导人，论文的开头应说〈开头〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f594faad-37eb-47e7-8bae-409dfee625fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87704, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "先人", "is_correct": false, "explanation": "语义：先人已经去世，不会在电视上讲话。"}, {"text": "首脑", "is_correct": true, "explanation": "这位首脑在电视上讲话，「首脑」是能讲话的领导人，符合句意。"}, {"text": "雕像", "is_correct": false, "explanation": "配价：「讲话」要求能说话的人作主语，雕像不能讲话。"}, {"text": "亡魂", "is_correct": false, "explanation": "语义：亡魂已不在人间，不会在电视上讲话。"}], "explanations": {"先人": "语义：先人已经去世，不会在电视上讲话。", "首脑": "这位首脑在电视上讲话，「首脑」是能讲话的领导人，符合句意。", "雕像": "配价：「讲话」要求能说话的人作主语，雕像不能讲话。", "亡魂": "语义：亡魂已不在人间，不会在电视上讲话。"}, "sentence_index": 6, "correct_answer": "首脑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她戴着一条很漂亮的首脑。", "explanation": "「首脑」指国家或政府的最高领导人，戴在身上的饰物应说〈首饰〉。"}, {"text": "这条河的首脑在山里。", "explanation": "「首脑」指国家或政府的最高领导人，河流的源头应说〈源头〉。"}, {"text": "他摔倒了，首脑碰到了桌子。", "explanation": "「首脑」指国家、政府或团体的最高领导人，不能指身体的头部，应说〈头〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f594faad-37eb-47e7-8bae-409dfee625fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87704, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两只政府首脑签署了这份协议。", "corrected_sentence": "两位政府首脑签署了这份协议。", "error_description": "「首脑」指人，量词应用「位」，不能用「只」（只用于动物）。应说「两位政府首脑」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f594faad-37eb-47e7-8bae-409dfee625fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87704, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份首脑签了这份协议。", "corrected_sentence": "这位首脑签了这份协议。", "error_description": "「首脑」指人，量词应用「位」，不能用「份」（份用于文件、协议等）。应说「这位首脑」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f594faad-37eb-47e7-8bae-409dfee625fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
