INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87705, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "发起是第一个站出来，让大家一起做一件事。", "primary_collocate": null, "pronunciation": "fā qǐ", "ipa": "fa˥ tɕʰi˨˩", "syllable_count": 2, "sentences": [{"text": "小李发起了一次爬山活动。", "target_word": "发起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁来发起这次聚会？", "target_word": "发起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他发起了一个捐书活动。", "target_word": "发起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们想发起一场比赛。", "target_word": "发起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她第一个发起讨论。", "target_word": "发起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想发起一次读书活动。", "target_word": "发起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个活动是王老师发起的。", "target_word": "发起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他发起过很多次活动。", "target_word": "发起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家让小王来发起这件事。", "target_word": "发起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居们发起了一次打扫活动。", "target_word": "发起", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发起了", "label": "体标"}, {"form": "发起过", "label": "体标"}, {"form": "发起人", "label": "复合"}], "register": "通用", "sense_fingerprint": "第一个提出并组织大家一起做某件事，如聚会、活动、讨论", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcccfa74-1e16-4e92-abd1-a3b542c01668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87705, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "发起", "is_correct": true, "explanation": "正确：fā qǐ，指第一个站出来组织大家一起做一件事，与句意相符。"}, {"text": "翻起", "is_correct": false, "explanation": "fān（第一声）与 fā（第一声）韵母不同（a 与 an），「翻起」意思是翻上来，不是发起。"}, {"text": "发青", "is_correct": false, "explanation": "qīng 与 qǐ 韵母不同（多一个 ng），「发青」意思是脸色发青，不是发起。"}, {"text": "发妻", "is_correct": false, "explanation": "qī（第一声）与 qǐ（第三声）声调不同，「发妻」指原配的妻子，不是发起。"}], "explanations": {"发起": "正确：fā qǐ，指第一个站出来组织大家一起做一件事，与句意相符。", "翻起": "fān（第一声）与 fā（第一声）韵母不同（a 与 an），「翻起」意思是翻上来，不是发起。", "发青": "qīng 与 qǐ 韵母不同（多一个 ng），「发青」意思是脸色发青，不是发起。", "发妻": "qī（第一声）与 qǐ（第三声）声调不同，「发妻」指原配的妻子，不是发起。"}, "sentence_index": null, "correct_answer": "发起"}, "level_3": {"options": [{"text": "发起", "is_correct": true, "explanation": "正确：「发起」指第一个组织大家做一件事，与「爬山活动」相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：「吃」的对象是食物，活动不能被吃，这里讲不通。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：「修理」多带机器、器具等对象，不说「修理活动」。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：「打扫」指清理场地或物品，活动不能被打扫。"}], "explanations": {"发起": "正确：「发起」指第一个组织大家做一件事，与「爬山活动」相符。", "吃": "语义：「吃」的对象是食物，活动不能被吃，这里讲不通。", "修理": "搭配：「修理」多带机器、器具等对象，不说「修理活动」。", "打扫": "语义：「打扫」指清理场地或物品，活动不能被打扫。"}, "sentence_index": 0, "correct_answer": "发起"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条河从北山发起。", "explanation": "这里应该用〈发源〉。发源指河流从某处开始流出，发起指组织大家开展活动，不能用于河流。"}, {"text": "他发起了这辆汽车。", "explanation": "这里应该用〈发动〉。发动用于车辆、机器，发起用于组织活动，不能说发起汽车。"}, {"text": "他发起了一次睡觉。", "explanation": "这里把〈发起〉当成了〈开始〉的意思。发起指有人带头组织大家共同做一件事，个人的睡眠不能被发起。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87705, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发起", "is_correct": true, "explanation": "正确：「发起的」指由王老师带头组织，与「这个活动是……的」的句式相符。"}, {"text": "洗", "is_correct": false, "explanation": "语义：「洗」的对象是物体，活动不能被洗，这里讲不通。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：「驾驶」的对象是车辆、船只等，不说「驾驶活动」。"}, {"text": "煮", "is_correct": false, "explanation": "语义：「煮」的对象是食物，活动不能被煮，这里讲不通。"}], "explanations": {"发起": "正确：「发起的」指由王老师带头组织，与「这个活动是……的」的句式相符。", "洗": "语义：「洗」的对象是物体，活动不能被洗，这里讲不通。", "驾驶": "搭配：「驾驶」的对象是车辆、船只等，不说「驾驶活动」。", "煮": "语义：「煮」的对象是食物，活动不能被煮，这里讲不通。"}, "sentence_index": 6, "correct_answer": "发起"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个地区发起了经济。", "explanation": "这里应该用〈发展〉。发展指事物壮大，发起指组织大家开展活动，不能说发起经济。"}, {"text": "昨天发起了一场事故。", "explanation": "这里应该用〈发生〉。事故是不由人组织的意外，只能说发生，不能发起。"}, {"text": "这盏灯发起了一道光。", "explanation": "这里应该用〈发出〉。发出用于光、声音等，发起指组织大家做事，不能用于光。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87705, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "王阿姨发起了了一次读书会。", "corrected_sentence": "王阿姨发起了一次读书会。", "error_description": "错误：动态助词「了」重复。「发起」后只用一个「了」，「发起了了一次读书会」有误，应说「发起了一次读书会」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87705, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "李同学发起了过一次跑步比赛。", "corrected_sentence": "李同学发起过一次跑步比赛。", "error_description": "错误：表示经历的「过」不能与「了」同时使用，「发起了过」有误，应说「发起过一次跑步比赛」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
