INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87706, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "倡议并带头开展（某种活动）。", "primary_collocate": null, "pronunciation": "fā qǐ", "ipa": "fa˥ tɕʰi˨˩", "syllable_count": 2, "sentences": [{"text": "学校发起了节约用水的活动。", "target_word": "发起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们发起了一项环保倡议。", "target_word": "发起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个运动由几位学者发起。", "target_word": "发起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司发起了一次募捐。", "target_word": "发起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市民发起了保护河流的行动。", "target_word": "发起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "青年人发起了读书活动。", "target_word": "发起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "协会发起了义务献血活动。", "target_word": "发起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次行动是由他们发起的。", "target_word": "发起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生会发起了捐款活动。", "target_word": "发起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们发起过一次植树活动。", "target_word": "发起", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发起了", "label": "体标"}, {"form": "发起过", "label": "体标"}, {"form": "发起人", "label": "复合"}], "register": "书面", "sense_fingerprint": "由组织或个人倡议并带头开展募捐、运动、行动等较正式的活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcccfa74-1e16-4e92-abd1-a3b542c01668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87706, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "发起", "is_correct": true, "explanation": "正确：fā qǐ，指由人倡议并带头开展某项活动，与句意相符。"}, {"text": "翻起", "is_correct": false, "explanation": "fān（第一声）与 fā（第一声）韵母不同（a 与 an），「翻起」意思是翻上来，不是发起。"}, {"text": "发青", "is_correct": false, "explanation": "qīng 与 qǐ 韵母不同（多一个 ng），「发青」意思是脸色发青，不是发起。"}, {"text": "发妻", "is_correct": false, "explanation": "qī（第一声）与 qǐ（第三声）声调不同，「发妻」指原配的妻子，不是发起。"}], "explanations": {"发起": "正确：fā qǐ，指由人倡议并带头开展某项活动，与句意相符。", "翻起": "fān（第一声）与 fā（第一声）韵母不同（a 与 an），「翻起」意思是翻上来，不是发起。", "发青": "qīng 与 qǐ 韵母不同（多一个 ng），「发青」意思是脸色发青，不是发起。", "发妻": "qī（第一声）与 qǐ（第三声）声调不同，「发妻」指原配的妻子，不是发起。"}, "sentence_index": null, "correct_answer": "发起"}, "level_3": {"options": [{"text": "发起", "is_correct": true, "explanation": "正确：「发起」指带头组织开展活动，与「节约用水的活动」相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：「吃」的对象是食物，活动不能被吃，这里讲不通。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：「驾驶」的对象是车辆、船只等，不说「驾驶活动」。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：「打扫」指清理场所，活动不能被打扫。"}], "explanations": {"发起": "正确：「发起」指带头组织开展活动，与「节约用水的活动」相符。", "吃": "语义：「吃」的对象是食物，活动不能被吃，这里讲不通。", "驾驶": "搭配：「驾驶」的对象是车辆、船只等，不说「驾驶活动」。", "打扫": "语义：「打扫」指清理场所，活动不能被打扫。"}, "sentence_index": 0, "correct_answer": "发起"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府发起了一条通知。", "explanation": "这里应该用〈发布〉。发布指公开颁布消息或通知，发起指组织大家开展活动，不能用于通知。"}, {"text": "这位作家发起了一篇文章。", "explanation": "这里应该用〈发表〉。发表指公开刊登，发起指组织活动，不能用于文章。"}, {"text": "我们发起了一台机器。", "explanation": "这里应该用〈发动〉。发动用于机器、车辆，发起用于组织活动，不能说发起机器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87706, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发起", "is_correct": true, "explanation": "正确：「发起」指带头组织开展活动，与「义务献血活动」相符。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：「驾驶」的对象是车辆、船只等，不说「驾驶活动」。"}, {"text": "烧", "is_correct": false, "explanation": "语义：「烧」指燃烧或加热，活动不能被烧。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：「修理」的对象多是器物，不说「修理活动」。"}], "explanations": {"发起": "正确：「发起」指带头组织开展活动，与「义务献血活动」相符。", "驾驶": "搭配：「驾驶」的对象是车辆、船只等，不说「驾驶活动」。", "烧": "语义：「烧」指燃烧或加热，活动不能被烧。", "修理": "搭配：「修理」的对象多是器物，不说「修理活动」。"}, "sentence_index": 6, "correct_answer": "发起"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个地区发起了旅游业。", "explanation": "这里应该用〈发展〉。发展指事业壮大，发起指组织开展活动，不能说发起旅游业。"}, {"text": "昨天发起了一场地震。", "explanation": "这里应该用〈发生〉。地震不是人组织的活动，只能说发生，不能发起。"}, {"text": "这台机器发起了一阵噪声。", "explanation": "这里应该用〈发出〉。发出用于声音、光等，发起指组织大家做事，不能用于噪声。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
