INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87706, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次募捐是工会发起了的。", "corrected_sentence": "这次募捐是工会发起的。", "error_description": "错误：「是……的」句式中，「发起」后面不加「了」，应说「这次募捐是工会发起的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
