INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87708, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，用在某些形容词前，表示程度很深。", "primary_collocate": null, "pronunciation": "hǎo bù", "ipa": "xau̯˨˩ pu˥˩", "syllable_count": 2, "sentences": [{"text": "新年到了，大家好不开心。", "target_word": "好不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人在外地工作，好不辛苦。", "target_word": "好不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这个好消息，全家人好不欢喜。", "target_word": "好不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后的花园里，鸟儿唱着歌，好不快活。", "target_word": "好不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明丢了新书包，好不着急。", "target_word": "好不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里的老街没有一个人，好不凄凉。", "target_word": "好不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他赢了比赛，站在台上好不神气。", "target_word": "好不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在公园里放风筝，好不快乐。", "target_word": "好不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿出新手机，同学们看着，好不惊奇。", "target_word": "好不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第一次上台讲话，他心里好不紧张。", "target_word": "好不", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "副词，置于某些形容词前，表示程度很深", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T1: 3 words above tier T1 (max 2): 花园里 (Zipf 3.19), 鸟儿 (Zipf 3.55), 快活 (Zipf 3.5)','sentence 4 above tier T1: 3 words above tier T1 (max 2): 小明 (Zipf 3.37), 书包 (Zipf 3.62), 着急 (Zipf 3.93)','sentence 5 above tier T1: 3 words above tier T1 (max 2): 夜里 (Zipf 3.96), 老街 (Zipf 3.29), 凄凉 (Zipf 3.32)']::text[], '126c10af-4fb6-480f-99ce-28dd5cb5b8f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
