) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87708, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好不", "is_correct": true, "explanation": "好不表示程度很深，与“神气”搭配，符合他赢了比赛后站在台上的样子。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”需与否定词连用，不能直接修饰肯定的“神气”。"}, {"text": "白", "is_correct": false, "explanation": "语义：“白”表示徒然，与“赢了比赛”的结果相矛盾。"}, {"text": "偏偏", "is_correct": false, "explanation": "语义：“偏偏”表示与预期相反，而赢了比赛后神气是符合预期的，句中没有相反的前提。"}], "explanations": {"好不": "好不表示程度很深，与“神气”搭配，符合他赢了比赛后站在台上的样子。", "从来": "搭配：“从来”需与否定词连用，不能直接修饰肯定的“神气”。", "白": "语义：“白”表示徒然，与“赢了比赛”的结果相矛盾。", "偏偏": "语义：“偏偏”表示与预期相反，而赢了比赛后神气是符合预期的，句中没有相反的前提。"}, "sentence_index": 6, "correct_answer": "好不"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他好不容易才找到那本书。", "explanation": "这里是固定词组“好不容易”，表示费了很大力气才（终于），不是表示程度很深的“好不”。"}, {"text": "他的病好不了，已经三天了。", "explanation": "这里是另一个词“好不了”，表示病无法痊愈，不是表示程度的“好不”。"}, {"text": "这台电脑好不了，只能换新的。", "explanation": "这里是另一个词“好不了”，表示无法修好、无法好转，不是表示程度很深的“好不”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9946c228-4e98-4a02-9217-b900dc6ca611') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87708, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他第一次一个人过节，好不的寂寞。", "corrected_sentence": "他第一次一个人过节，好不寂寞。", "error_description": "错误形式是“好不的寂寞”，正确形式是“好不寂寞”。“好不”是程度副词，直接修饰形容词，中间不能加“的”，应删去“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9946c228-4e98-4a02-9217-b900dc6ca611') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87708, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "春天的公园里，好不很热闹。", "corrected_sentence": "春天的公园里，好不热闹。", "error_description": "“好不”本身已经表示程度很深，不能再与“很”连用，应删去“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9946c228-4e98-4a02-9217-b900dc6ca611') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87710, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "淘汰", "is_correct": true, "explanation": "淘汰：在比赛中被淘汰、无法进入下一轮，与“晋级”正相反。"}, {"text": "保持", "is_correct": false, "explanation": "保持：维持原来的状态，与“晋级”不构成反义关系。"}, {"text": "训练", "is_correct": false, "explanation": "训练：指练习、培养，与“晋级”不构成反义关系。"}, {"text": "挑选", "is_correct": false, "explanation": "挑选：指选择出需要的，与“晋级”不构成反义关系。"}], "correct_answer": "淘汰", "explanations": {"淘汰": "淘汰：在比赛中被淘汰、无法进入下一轮，与“晋级”正相反。", "保持": "保持：维持原来的状态，与“晋级”不构成反义关系。", "训练": "训练：指练习、培养，与“晋级”不构成反义关系。", "挑选": "挑选：指选择出需要的，与“晋级”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd886a38-5bf1-4944-a671-17fe4416db10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87710, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "淘汰", "is_correct": true, "explanation": "淘汰：在比赛中被淘汰、无法进入下一轮，与“晋级”正相反。"}, {"text": "报名", "is_correct": false, "explanation": "报名：登记姓名以参加活动，与“晋级”不构成反义关系。"}, {"text": "观看", "is_correct": false, "explanation": "观看：看，与“晋级”不构成反义关系。"}, {"text": "出发", "is_correct": false, "explanation": "出发：动身前往某地，与“晋级”不构成反义关系。"}], "correct_answer": "淘汰", "explanations": {"淘汰": "淘汰：在比赛中被淘汰、无法进入下一轮，与“晋级”正相反。", "报名": "报名：登记姓名以参加活动，与“晋级”不构成反义关系。", "观看": "观看：看，与“晋级”不构成反义关系。", "出发": "出发：动身前往某地，与“晋级”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd886a38-5bf1-4944-a671-17fe4416db10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87710, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "升到较高的等级；在比赛中取得进入下一轮的资格。", "primary_collocate": null, "pronunciation": "jìn jí", "ipa": "tɕin⁵¹ tɕi³⁵", "syllable_count": 2, "sentences": [{"text": "他在比赛中赢了，顺利晋级。", "target_word": "晋级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明的游泳队晋级了。", "target_word": "晋级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班最后晋级决赛了。", "target_word": "晋级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她努力练习，终于晋级到了第二轮。", "target_word": "晋级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "赢了这场比赛，我们就能晋级。", "target_word": "晋级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个选手每次都能晋级。", "target_word": "晋级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的棋艺提高了，从初级晋级到中级。", "target_word": "晋级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪个队会晋级下一轮？", "target_word": "晋级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小学员晋级为正式队员。", "target_word": "晋级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国队昨天晋级了半决赛。", "target_word": "晋级", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "晋级了", "label": "体标"}, {"form": "晋级过", "label": "体标"}, {"form": "晋级赛", "label": "复合"}], "register": "中性", "sense_fingerprint": "升到更高等级，或比赛取得进入下一轮的资格", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed802cd7-e1c1-4adc-8439-d8c9d3271fb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87710, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "晋级", "is_correct": true, "explanation": "晋级（jìnjí）是正确答案：升到较高的等级；在比赛中取得进入下一轮的资格。"}, {"text": "紧急", "is_correct": false, "explanation": "紧急（jǐnjí）与晋级（jìnjí）第一音节声调不同：jǐn（第三声）与 jìn（第四声），意思是要紧、迫切。"}, {"text": "禁忌", "is_correct": false, "explanation": "禁忌（jìnjì）与晋级（jìnjí）第二音节声调不同：jì（第四声）与 jí（第二声），意思是忌讳。"}, {"text": "进击", "is_correct": false, "explanation": "进击（jìnjī）与晋级（jìnjí）第二音节声调不同：jī（第一声）与 jí（第二声），意思是向前攻击。"}, {"text": "金鸡", "is_correct": false, "explanation": "金鸡（jīnjī）与晋级（jìnjí）两个音节的声调都不同，意思是金色的公鸡。"}], "explanations": {"晋级": "晋级（jìnjí）是正确答案：升到较高的等级；在比赛中取得进入下一轮的资格。", "紧急": "紧急（jǐnjí）与晋级（jìnjí）第一音节声调不同：jǐn（第三声）与 jìn（第四声），意思是要紧、迫切。", "禁忌": "禁忌（jìnjì）与晋级（jìnjí）第二音节声调不同：jì（第四声）与 jí（第二声），意思是忌讳。", "进击": "进击（jìnjī）与晋级（jìnjí）第二音节声调不同：jī（第一声）与 jí（第二声），意思是向前攻击。", "金鸡": "金鸡（jīnjī）与晋级（jìnjí）两个音节的声调都不同，意思是金色的公鸡。"}, "sentence_index": null, "correct_answer": "晋级"}, "level_3": {"options": [{"text": "晋级", "is_correct": true, "explanation": "晋级：在比赛中赢了，取得进入下一轮的资格，与前文相符。"}, {"text": "失败", "is_correct": false, "explanation": "语义：“失败”与前文“赢了”相反，句意矛盾。"}, {"text": "退赛", "is_correct": false, "explanation": "语义：赢了之后不能说“退赛”，与前文“赢了”矛盾。"}, {"text": "下岗", "is_correct": false, "explanation": "搭配：“下岗”表示失去工作，不能用于比赛中的选手。"}], "explanations": {"晋级": "晋级：在比赛中赢了，取得进入下一轮的资格，与前文相符。", "失败": "语义：“失败”与前文“赢了”相反，句意矛盾。", "退赛": "语义：赢了之后不能说“退赛”，与前文“赢了”矛盾。", "下岗": "搭配：“下岗”表示失去工作，不能用于比赛中的选手。"}, "sentence_index": 0, "correct_answer": "晋级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的数学考试终于晋级到了满分。", "explanation": "这里应该用〈考到〉。考试分数用“考到”，“晋级”不用于分数。"}, {"text": "这次会议终于晋级了共识。", "explanation": "这里应该用〈达成〉。共识、协议这类结果用“达成”，“晋级”只用于人或队伍在等级、比赛中进入更高层次。"}, {"text": "她努力练习，终于晋级了冠军。", "explanation": "这里应该用〈获得〉。拿到冠军用“获得”，“晋级”只表示进入下一轮或升到更高等级，不能直接带“冠军”作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd886a38-5bf1-4944-a671-17fe4416db10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87710, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "晋级", "is_correct": true, "explanation": "晋级（jìnjí）是正确答案：升到较高的等级；在比赛中取得进入下一轮的资格。"}, {"text": "谨记", "is_correct": false, "explanation": "谨记（jǐnjì）与晋级（jìnjí）两个音节的声调都不同：jǐn（第三声）与 jìn（第四声），jì（第四声）与 jí（第二声），意思是牢记。"}, {"text": "禁忌", "is_correct": false, "explanation": "禁忌（jìnjì）与晋级（jìnjí）第二音节声调不同：jì（第四声）与 jí（第二声），意思是忌讳。"}, {"text": "紧记", "is_correct": false, "explanation": "紧记（jǐnjì）与晋级（jìnjí）两个音节的声调都不同，意思是牢牢记住。"}], "explanations": {"晋级": "晋级（jìnjí）是正确答案：升到较高的等级；在比赛中取得进入下一轮的资格。", "谨记": "谨记（jǐnjì）与晋级（jìnjí）两个音节的声调都不同：jǐn（第三声）与 jìn（第四声），jì（第四声）与 jí（第二声），意思是牢记。", "禁忌": "禁忌（jìnjì）与晋级（jìnjí）第二音节声调不同：jì（第四声）与 jí（第二声），意思是忌讳。", "紧记": "紧记（jǐnjì）与晋级（jìnjí）两个音节的声调都不同，意思是牢牢记住。"}, "sentence_index": null, "correct_answer": "晋级"}, "level_3": {"options": [{"text": "晋级", "is_correct": true, "explanation": "晋级：从初级进入中级，与“棋艺提高了”相符。"}, {"text": "退步", "is_correct": false, "explanation": "语义：“退步”指倒退，与前文“棋艺提高了”矛盾。"}, {"text": "失利", "is_correct": false, "explanation": "语义：“失利”指失败、败北，与“棋艺提高了”不符。"}, {"text": "降落", "is_correct": false, "explanation": "搭配：“降落”多用于飞机、伞等，不能表示棋艺的等级变化。"}], "explanations": {"晋级": "晋级：从初级进入中级，与“棋艺提高了”相符。", "退步": "语义：“退步”指倒退，与前文“棋艺提高了”矛盾。", "失利": "语义：“失利”指失败、败北，与“棋艺提高了”不符。", "降落": "搭配：“降落”多用于飞机、伞等，不能表示棋艺的等级变化。"}, "sentence_index": 6, "correct_answer": "晋级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他去年晋级了初中。", "explanation": "这里应该用〈升入〉。从小学升入初中用“升入”，“晋级”不指进入学校。"}, {"text": "这位选手的身高这学期晋级了很多。", "explanation": "这里应该用〈长〉。身高的增长用“长”，“晋级”不用于身高。"}, {"text": "他晋级了世界纪录。", "explanation": "这里应该用〈打破〉。纪录要用“打破”，“晋级”不能带“纪录”作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd886a38-5bf1-4944-a671-17fe4416db10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87710, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "三号选手今天发挥出色，成功晋级了到决赛。", "corrected_sentence": "三号选手今天发挥出色，成功晋级到了决赛。", "error_description": "错误形式：成功晋级了到决赛；正确形式：成功晋级到了决赛。“了”不能插在动词“晋级”与结果补语“到”之间，应放在“到”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd886a38-5bf1-4944-a671-17fe4416db10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87710, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "只有前两名才能晋级过下一轮。", "corrected_sentence": "只有前两名才能晋级下一轮。", "error_description": "错误形式：才能晋级过下一轮；正确形式：才能晋级下一轮。“过”表示曾经有过的经历，不能用于“只有……才能”所说的将来可能，应去掉“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd886a38-5bf1-4944-a671-17fe4416db10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
