INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87711, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "马经是介绍赛马的消息的书或报。", "primary_collocate": null, "pronunciation": "mǎ jīng", "ipa": "ma˨˩˦ tɕiŋ˥", "syllable_count": 2, "sentences": [{"text": "这份马经每周出两次，专门介绍赛马消息。", "target_word": "马经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边喝茶，一边翻马经看赛马消息。", "target_word": "马经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马经是一种报，里面都是赛马的消息。", "target_word": "马经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的马经已经卖完了。", "target_word": "马经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王在车站买了一份马经。", "target_word": "马经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的包里总是带着一本马经。", "target_word": "马经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张马经上说，周日的比赛会下雨。", "target_word": "马经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈不看马经，只看菜价和天气。", "target_word": "马经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看马经的人，多半很喜欢赛马。", "target_word": "马经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我第一次看马经，什么也看不懂。", "target_word": "马经", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "本", "label": "量词"}], "register": "口语", "sense_fingerprint": "专门刊登赛马消息的书或报", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4e08ad9-0b97-4081-94ef-5f5d51ef7e8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87711, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "马经", "is_correct": true, "explanation": "马经是专门刊登赛马消息的书或报，与“每周出两次”相合。"}, {"text": "字典", "is_correct": false, "explanation": "语义：字典不定期出版，也不专门介绍赛马消息。"}, {"text": "食谱", "is_correct": false, "explanation": "语义：食谱介绍菜肴，与赛马消息无关。"}, {"text": "花瓶", "is_correct": false, "explanation": "搭配：“出”用于出版物，不说“出花瓶”。"}], "explanations": {"马经": "马经是专门刊登赛马消息的书或报，与“每周出两次”相合。", "字典": "语义：字典不定期出版，也不专门介绍赛马消息。", "食谱": "语义：食谱介绍菜肴，与赛马消息无关。", "花瓶": "搭配：“出”用于出版物，不说“出花瓶”。"}, "sentence_index": 0, "correct_answer": "马经"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆马经很好看。", "explanation": "这里应该用〈本〉或〈份〉。“辆”用于车，书报不用“辆”。"}, {"text": "这本马经介绍了最新的时尚。", "explanation": "这里应该用〈杂志〉。马经只刊登赛马消息，不谈时尚。"}, {"text": "这份马经报道了昨天的地震新闻。", "explanation": "这里应该用〈报纸〉。马经只介绍赛马消息，不报道地震等新闻，报道新闻要用“报纸”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87711, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "马经", "is_correct": true, "explanation": "马经刊登赛马消息，能说明周日比赛的天气情况，与“上说”相合。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图不会预报比赛的天气。"}, {"text": "菜单", "is_correct": false, "explanation": "语义：菜单列出的是菜品，不会说比赛的天气。"}, {"text": "病历", "is_correct": false, "explanation": "语义：病历记录病情，不会预报比赛的天气。"}], "explanations": {"马经": "马经刊登赛马消息，能说明周日比赛的天气情况，与“上说”相合。", "地图": "语义：地图不会预报比赛的天气。", "菜单": "语义：菜单列出的是菜品，不会说比赛的天气。", "病历": "语义：病历记录病情，不会预报比赛的天气。"}, "sentence_index": 6, "correct_answer": "马经"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本马经讲了中国古代的战争。", "explanation": "这里应该用〈书〉。马经只介绍赛马消息，不讲历史，讲古代战争要用“书”。"}, {"text": "这张马经标出了城市的主要公园。", "explanation": "这里应该用〈地图〉。马经介绍赛马消息，不标注公园等地点，标出地点要用“地图”。"}, {"text": "墙上挂着今年的马经，上面有每个月的节日。", "explanation": "这里应该用〈日历〉。马经只介绍赛马消息，没有按月排列的节日，记录节日要用“日历”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87711, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天都买一根马经。", "corrected_sentence": "他每天都买一份马经。", "error_description": "“根”用于细长的东西，马经应用“份”或“本”。正确说法是“一份马经”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87711, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我每天都看这座马经。", "corrected_sentence": "我每天都看这本马经。", "error_description": "量词“座”用于山、桥等大型固定的东西，马经应用“本”或“份”。正确说法是“看这本马经”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
