INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87713, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "皇帝是古时候一个国家里最大的人，所有人都要听他的。", "primary_collocate": null, "pronunciation": "huáng dì", "ipa": "xwɑŋ˧˥ ti˥˩", "syllable_count": 2, "sentences": [{"text": "古时候，皇帝住在很大的宫殿里。", "target_word": "皇帝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇帝说的话，所有人都要听。", "target_word": "皇帝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位皇帝很年轻，才十五岁。", "target_word": "皇帝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇帝有很多大臣帮他做事。", "target_word": "皇帝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的皇帝坐在高高的椅子上。", "target_word": "皇帝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明在学校的表演里当皇帝。", "target_word": "皇帝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个国家的皇帝去世了，他的儿子当了新皇帝。", "target_word": "皇帝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇帝出门时，路上的人都要低头。", "target_word": "皇帝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在书里读过一个皇帝的故事。", "target_word": "皇帝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇帝想吃水果，大臣马上去买。", "target_word": "皇帝", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "小皇帝", "label": "复合"}], "register": "中性", "sense_fingerprint": "古时候国家里最大的人，大家都要听他的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dd449a6-9c7f-4543-8b31-149e4d1ca677') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87713, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "皇帝", "is_correct": true, "explanation": "“皇帝”是古代国家的最高统治者，住在宫殿里符合语境。"}, {"text": "农民", "is_correct": false, "explanation": "语义：农民住不进宫殿，与“宫殿”矛盾。"}, {"text": "电脑", "is_correct": false, "explanation": "配价：“住”要求有生命的主语，电脑不能住。"}, {"text": "桌子", "is_correct": false, "explanation": "配价：“住”要求有生命的主语，桌子不能住。"}], "explanations": {"皇帝": "“皇帝”是古代国家的最高统治者，住在宫殿里符合语境。", "农民": "语义：农民住不进宫殿，与“宫殿”矛盾。", "电脑": "配价：“住”要求有生命的主语，电脑不能住。", "桌子": "配价：“住”要求有生命的主语，桌子不能住。"}, "sentence_index": 0, "correct_answer": "皇帝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨天，我们班来了一只新皇帝。", "explanation": "这里应该用〈位〉。“只”多用于动物或小东西，指人要用“位”或“个”。"}, {"text": "英国的皇帝是由议会选出的。", "explanation": "这里应该用〈首相〉。皇帝是世袭的君主，英国首相由议会选出，不能称皇帝。"}, {"text": "丹麦的皇帝很受人民爱戴。", "explanation": "这里应该用〈国王〉。“皇帝”是君主的一种称号，丹麦的君主称国王，不称皇帝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56a27368-be5d-4c39-9e19-0d3e038689a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87713, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "皇帝", "is_correct": true, "explanation": "“皇帝”指国家的君主，君主去世后由儿子继位，符合语境。"}, {"text": "老虎", "is_correct": false, "explanation": "搭配：“去世”多用于人，一般不说“老虎去世”。"}, {"text": "作家", "is_correct": false, "explanation": "语义：作家不能继承君位，与“他的儿子当了新……”的继承关系矛盾。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“去世”要求有生命的主语，石头不能去世。"}], "explanations": {"皇帝": "“皇帝”指国家的君主，君主去世后由儿子继位，符合语境。", "老虎": "搭配：“去世”多用于人，一般不说“老虎去世”。", "作家": "语义：作家不能继承君位，与“他的儿子当了新……”的继承关系矛盾。", "石头": "配价：“去世”要求有生命的主语，石头不能去世。"}, "sentence_index": 6, "correct_answer": "皇帝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个共和国的皇帝由全体公民投票选出，任期四年。", "explanation": "这里应该用〈总统〉。皇帝是世袭的君主，共和国的元首由选举产生、任期有限，不称皇帝。"}, {"text": "这个国家的皇帝每年都要向议会报告工作。", "explanation": "这里应该用〈总理〉。皇帝不向议会报告；向议会报告工作的是政府首脑，称总理。"}, {"text": "这个县的皇帝由县民选举产生，任期两年。", "explanation": "这里应该用〈县长〉。皇帝是世袭的君主，不经选举产生；县的行政首长是县长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56a27368-be5d-4c39-9e19-0d3e038689a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87713, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "宫殿里住着一条皇帝。", "corrected_sentence": "宫殿里住着一位皇帝。", "error_description": "错误：“皇帝”的量词用错。“条”用于长条形的东西或鱼、狗等，指人应用“位”或“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56a27368-be5d-4c39-9e19-0d3e038689a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87713, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他小时候当过皇帝们。", "corrected_sentence": "他小时候当过皇帝。", "error_description": "错误：“皇帝”后加了“们”。指一个人当过君主时只说“皇帝”，不用“皇帝们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56a27368-be5d-4c39-9e19-0d3e038689a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
