INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87715, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "委员是一个小组里被大家选出来做事的人。", "primary_collocate": null, "pronunciation": "wěi yuán", "ipa": "wei̯˨˩ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "我们小组选他做委员，帮大家发东西。", "target_word": "委员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都想让小红当委员。", "target_word": "委员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是班里的委员，每天帮老师收作业。", "target_word": "委员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个学期，我被大家选成了委员。", "target_word": "委员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当委员要为大家做事，不能只想自己。", "target_word": "委员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小组里有两个委员，一个管书，一个管卫生。", "target_word": "委员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问：谁想当委员？", "target_word": "委员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做委员很认真，大家都喜欢他。", "target_word": "委员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们选出了三个委员，每人管一件事。", "target_word": "委员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次选委员，大家都投了小王一票。", "target_word": "委员", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位委员", "label": "量词"}, {"form": "委员会", "label": "复合"}, {"form": "委员长", "label": "复合"}], "register": "中性", "sense_fingerprint": "小组或班里被大家选出来为大家做事的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126c10af-4fb6-480f-99ce-28dd5cb5b8f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87715, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "委员", "is_correct": true, "explanation": "委员指小组里被大家选出来为大家做事的人，与“选他做”相符。"}, {"text": "老师", "is_correct": false, "explanation": "语义：小组推选的是帮忙做事的人，“老师”是职业身份，“选他做老师”句意不通。"}, {"text": "食堂", "is_correct": false, "explanation": "语义：食堂是场所，不能被选来做事，“选他做食堂”句意不通。"}, {"text": "报纸", "is_correct": false, "explanation": "语义：报纸是物品，不能被选来做事。"}], "explanations": {"委员": "委员指小组里被大家选出来为大家做事的人，与“选他做”相符。", "老师": "语义：小组推选的是帮忙做事的人，“老师”是职业身份，“选他做老师”句意不通。", "食堂": "语义：食堂是场所，不能被选来做事，“选他做食堂”句意不通。", "报纸": "语义：报纸是物品，不能被选来做事。"}, "sentence_index": 0, "correct_answer": "委员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们把旧的委员搬到了楼上。", "explanation": "“委员”指人，不能指可以搬运的物品；这里应该用〈桌子〉之类的物品名词。"}, {"text": "老师在委员里布置了作业。", "explanation": "这里应该用〈委员会〉。“委员”指人，指机构要用“委员会”，不能说“在委员里布置”。"}, {"text": "我口渴了，喝了一杯委员。", "explanation": "“委员”指人，不能指饮料；这里应该用〈水〉之类的饮品名词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9946c228-4e98-4a02-9217-b900dc6ca611') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87715, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "委员", "is_correct": true, "explanation": "委员指被大家选出来做事的人，“想当”的对象是职务，符合语境。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不是人，不能“想当”作业。"}, {"text": "铅笔", "is_correct": false, "explanation": "语义：铅笔是物品，不能“想当”它。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是物品，不能“想当”它。"}], "explanations": {"委员": "委员指被大家选出来做事的人，“想当”的对象是职务，符合语境。", "作业": "语义：作业不是人，不能“想当”作业。", "铅笔": "语义：铅笔是物品，不能“想当”它。", "雨伞": "语义：雨伞是物品，不能“想当”它。"}, "sentence_index": 6, "correct_answer": "委员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盆花是我们班的委员。", "explanation": "“委员”指有职务的人，不能用来指植物。"}, {"text": "他买了一台新委员，每天都用它打字。", "explanation": "“委员”指人，不能指机器；这里应该用〈电脑〉。"}, {"text": "我把书放在委员上面。", "explanation": "“委员”指人，不能当放置物品的处所名词；这里应该用〈桌子〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9946c228-4e98-4a02-9217-b900dc6ca611') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87715, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们小组推选一只委员，负责借书。", "corrected_sentence": "我们小组推选一位委员，负责借书。", "error_description": "错误是量词“只”，正确是“位”。“委员”指人，应该用人的量词“位”或“个”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9946c228-4e98-4a02-9217-b900dc6ca611') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87715, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "班里的三位委员们都很认真。", "corrected_sentence": "班里的三位委员都很认真。", "error_description": "错误是在“三位委员”后又加了复数后缀“们”。数量词已经表示数目，不能再加“们”，应删去“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9946c228-4e98-4a02-9217-b900dc6ca611') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
