INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87716, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "委员会的成员；被选出或任命来参加某委员会工作的人。", "primary_collocate": null, "pronunciation": "wěi yuán", "ipa": "wei̯˨˩ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "他是我们学校新选出的委员。", "target_word": "委员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位委员在会上提出了一个好办法。", "target_word": "委员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王先生被任命为这个小组的委员。", "target_word": "委员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每位委员都要在会上说说自己的看法。", "target_word": "委员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会前，委员们先看了一遍材料。", "target_word": "委员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "委员们一致同意了这个计划。", "target_word": "委员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当选为市政协的委员，工作很忙。", "target_word": "委员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个会一共有九位委员，今天来了八位。", "target_word": "委员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位老委员已经工作了二十年。", "target_word": "委员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三位委员不同意，计划没有通过。", "target_word": "委员", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位委员", "label": "量词"}, {"form": "委员会", "label": "复合"}, {"form": "委员长", "label": "复合"}], "register": "中性", "sense_fingerprint": "委员会的成员，被选出或任命参加工作的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126c10af-4fb6-480f-99ce-28dd5cb5b8f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87716, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "委员", "is_correct": true, "explanation": "委员指委员会的成员，可以被选出，与“选出”搭配，符合句意。"}, {"text": "委员会", "is_correct": false, "explanation": "搭配：“委员会”指机构，“他是……的”后要接指人的名词，不能这样搭配。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：“新选出的”与“小偷”相矛盾，没有人会被选为小偷。"}, {"text": "校车", "is_correct": false, "explanation": "语义：校车是交通工具，不是人，不能被选出做委员。"}], "explanations": {"委员": "委员指委员会的成员，可以被选出，与“选出”搭配，符合句意。", "委员会": "搭配：“委员会”指机构，“他是……的”后要接指人的名词，不能这样搭配。", "小偷": "语义：“新选出的”与“小偷”相矛盾，没有人会被选为小偷。", "校车": "语义：校车是交通工具，不是人，不能被选出做委员。"}, "sentence_index": 0, "correct_answer": "委员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班新买了一个委员，用来放书。", "explanation": "“委员”指人，不能指家具；这里应该用〈书架〉。"}, {"text": "我们在委员里讨论了这个计划。", "explanation": "这里应该用〈委员会〉。“委员”指人，指机构要用“委员会”，不能说“在委员里讨论”。"}, {"text": "下雨了，我打开委员走出门。", "explanation": "“委员”指人，不能指雨具；这里应该用〈雨伞〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9946c228-4e98-4a02-9217-b900dc6ca611') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87716, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "委员", "is_correct": true, "explanation": "委员指委员会的成员，与“当选为”搭配，符合句意。"}, {"text": "邮票", "is_correct": false, "explanation": "语义：邮票是物品，不能当选，也不能担任职务。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是物品，不能当选，也不能担任委员。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：眼镜是物品，与“当选为”的人物语境不符。"}], "explanations": {"委员": "委员指委员会的成员，与“当选为”搭配，符合句意。", "邮票": "语义：邮票是物品，不能当选，也不能担任职务。", "窗户": "语义：窗户是物品，不能当选，也不能担任委员。", "眼镜": "语义：眼镜是物品，与“当选为”的人物语境不符。"}, "sentence_index": 6, "correct_answer": "委员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的小狗是班里的委员。", "explanation": "“委员”指有职务的人，不能用来指动物。"}, {"text": "他的委员又大又软，躺着很舒服。", "explanation": "“委员”指人，不能指枕头这类物品，这里应该用〈枕头〉。"}, {"text": "我在委员下面坐着。", "explanation": "“委员”指人，不能当处所名词用；这里应该用〈桌子〉之类的处所名词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9946c228-4e98-4a02-9217-b900dc6ca611') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87716, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校委员会里有一只委员提出了建议。", "corrected_sentence": "学校委员会里有一位委员提出了建议。", "error_description": "错误是量词“只”，正确是“位”。“委员”指人，应该用人的量词“位”或“个”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9946c228-4e98-4a02-9217-b900dc6ca611') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87716, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们那个委员会有五位委员们。", "corrected_sentence": "他们那个委员会有五位委员。", "error_description": "错误是在“五位委员”后又加了复数后缀“们”。数量词已经表示数目，不能再加“们”，应删去“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9946c228-4e98-4a02-9217-b900dc6ca611') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87717, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "最多", "is_correct": true, "explanation": "“最多”与“最少”互为反义：一个表示数量最大，一个表示数量最小。"}, {"text": "很", "is_correct": false, "explanation": "“很”只表示程度高，与“最少”的数量反义关系无关。"}, {"text": "更", "is_correct": false, "explanation": "“更”表示比较程度的加深，不与“最少”构成反义词。"}, {"text": "也", "is_correct": false, "explanation": "“也”表示并列或类同，与“最少”没有反义关系。"}], "correct_answer": "最多", "explanations": {"最多": "“最多”与“最少”互为反义：一个表示数量最大，一个表示数量最小。", "很": "“很”只表示程度高，与“最少”的数量反义关系无关。", "更": "“更”表示比较程度的加深，不与“最少”构成反义词。", "也": "“也”表示并列或类同，与“最少”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd886a38-5bf1-4944-a671-17fe4416db10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87717, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "最多", "is_correct": true, "explanation": "“最多”与“最少”互为反义：一个表示数量最大，一个表示数量最小。"}, {"text": "挺", "is_correct": false, "explanation": "“挺”表示程度相当高，与“最少”的数量反义关系无关。"}, {"text": "十分", "is_correct": false, "explanation": "“十分”表示程度，不与“最少”构成反义词。"}, {"text": "太", "is_correct": false, "explanation": "“太”表示过度的程度，与“最少”没有反义关系。"}], "correct_answer": "最多", "explanations": {"最多": "“最多”与“最少”互为反义：一个表示数量最大，一个表示数量最小。", "挺": "“挺”表示程度相当高，与“最少”的数量反义关系无关。", "十分": "“十分”表示程度，不与“最少”构成反义词。", "太": "“太”表示过度的程度，与“最少”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd886a38-5bf1-4944-a671-17fe4416db10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87717, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "最少是不能再少了，是数目里最小的。", "primary_collocate": null, "pronunciation": "zuì shǎo", "ipa": "tsuei⁵¹ ʂau²¹⁴", "syllable_count": 2, "sentences": [{"text": "三个班里，我们班的人最少。", "target_word": "最少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月的雨最少。", "target_word": "最少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "四个人里，他吃得最少。", "target_word": "最少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这些学校里，这所学校的学生最少。", "target_word": "最少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年冬天的雪最少。", "target_word": "最少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买东西的人，周一最少。", "target_word": "最少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全家人里，爷爷说话最少。", "target_word": "最少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几个杯子里，红杯子里的水最少。", "target_word": "最少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪一个最多，哪一个最少？", "target_word": "最少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的作业是全班里错得最少的。", "target_word": "最少", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "数量在比较的对象中最小，不能再少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed802cd7-e1c1-4adc-8439-d8c9d3271fb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87717, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "最少", "is_correct": true, "explanation": "“最少”表示在三个班的比较中，我们班的人数最小，句意通顺。"}, {"text": "最远", "is_correct": false, "explanation": "语义：“远”说距离，与班里人数的比较无关。"}, {"text": "最有效", "is_correct": false, "explanation": "搭配：“有效”用于方法、措施，不能用来形容人。"}, {"text": "最慢", "is_correct": false, "explanation": "语义：“慢”说速度，句中没有速度的语境，与人数比较不符。"}], "explanations": {"最少": "“最少”表示在三个班的比较中，我们班的人数最小，句意通顺。", "最远": "语义：“远”说距离，与班里人数的比较无关。", "最有效": "搭配：“有效”用于方法、措施，不能用来形容人。", "最慢": "语义：“慢”说速度，句中没有速度的语境，与人数比较不符。"}, "sentence_index": 0, "correct_answer": "最少"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城市一月份的气温最少。", "explanation": "这里应该用〈最低〉。气温的高低要用“最低”，“最少”只用于可以数的数量。"}, {"text": "这个房间的面积最少。", "explanation": "这里应该用〈最小〉。面积、体积这类大小要用“最小”，“最少”只用于数量。"}, {"text": "他的体重最少。", "explanation": "这里应该用〈最轻〉。体重的多少按轻重来说，要用“最轻”，不用“最少”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd886a38-5bf1-4944-a671-17fe4416db10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87717, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "最少", "is_correct": true, "explanation": "“最少”表示全家人的比较中，爷爷说话的量最小，句意通顺。"}, {"text": "最快", "is_correct": false, "explanation": "语义：“快”说速度，与说话的多少不符。"}, {"text": "最亮", "is_correct": false, "explanation": "搭配：“亮”说光线、颜色，与说话的量无关。"}, {"text": "最苦", "is_correct": false, "explanation": "语义：“苦”说味道或滋味，句中没有这一语境，与说话的多少不符。"}], "explanations": {"最少": "“最少”表示全家人的比较中，爷爷说话的量最小，句意通顺。", "最快": "语义：“快”说速度，与说话的多少不符。", "最亮": "搭配：“亮”说光线、颜色，与说话的量无关。", "最苦": "语义：“苦”说味道或滋味，句中没有这一语境，与说话的多少不符。"}, "sentence_index": 6, "correct_answer": "最少"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座山的海拔最少。", "explanation": "这里应该用〈最低〉。海拔的高低要用“最低”，“最少”只用于可以数的数量。"}, {"text": "这条河的宽度最少。", "explanation": "这里应该用〈最小〉。宽度、长度这类大小要用“最小”，“最少”只用于数量。"}, {"text": "这个箱子的重量最少。", "explanation": "这里应该用〈最轻〉。重量的多少按轻重来说，要用“最轻”，不用“最少”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd886a38-5bf1-4944-a671-17fe4416db10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87717, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次比赛里，他比别人的失误最少。", "corrected_sentence": "这次比赛里，他的失误最少。", "error_description": "“最少”本身已表示比较中数量最小，不能再与“比别人”构成比较句。错误形式是“他比别人的失误最少”，正确形式是“他的失误最少”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd886a38-5bf1-4944-a671-17fe4416db10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87717, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这学期，她的迟到次数很最少。", "corrected_sentence": "这学期，她的迟到次数最少。", "error_description": "“最少”本身已含最高程度的意思，前面不能再加程度副词“很”。错误形式是“很最少”，正确形式是“最少”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd886a38-5bf1-4944-a671-17fe4416db10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
