INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87718, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示数量的下限；至少。", "primary_collocate": null, "pronunciation": "zuì shǎo", "ipa": "tsuei⁵¹ ʂau²¹⁴", "syllable_count": 2, "sentences": [{"text": "这件事最少要三天才能做完。", "target_word": "最少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最少要睡八个小时。", "target_word": "最少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从这儿到机场，最少要一个小时。", "target_word": "最少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书最少有三百页。", "target_word": "最少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天最少喝两杯水。", "target_word": "最少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加比赛，最少要两个人。", "target_word": "最少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学好汉语，最少需要一年。", "target_word": "最少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些菜最少够十个人吃。", "target_word": "最少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家离学校最少有五公里。", "target_word": "最少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做这个蛋糕，最少要五个鸡蛋。", "target_word": "最少", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词，表示数量的下限，相当于至少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed802cd7-e1c1-4adc-8439-d8c9d3271fb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87718, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "最少", "is_correct": true, "explanation": "“最少”表示数量的下限，即“至少”，“这件事最少要三天”句意通顺。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示已经发生，与“要三天才能做完”的将来需求矛盾。"}, {"text": "刚", "is_correct": false, "explanation": "语义：“刚”表示时间刚刚发生，与“要三天才能做完”的时长要求不符。"}, {"text": "早就", "is_correct": false, "explanation": "搭配：“早就”要与已经发生的事搭配，不能与“要……才能”的需求搭配。"}], "explanations": {"最少": "“最少”表示数量的下限，即“至少”，“这件事最少要三天”句意通顺。", "已经": "语义：“已经”表示已经发生，与“要三天才能做完”的将来需求矛盾。", "刚": "语义：“刚”表示时间刚刚发生，与“要三天才能做完”的时长要求不符。", "早就": "搭配：“早就”要与已经发生的事搭配，不能与“要……才能”的需求搭配。"}, "sentence_index": 0, "correct_answer": "最少"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个箱子最少只能装十斤东西。", "explanation": "这里应该用〈最多〉。“只能”限定上限，要说“最多只能”；“最少”表示下限，与“只能”的上限意思相矛盾。"}, {"text": "这间教室最少不能超过五十个人。", "explanation": "这里应该用〈最多〉。“不能超过”限定上限，要用“最多”；“最少”表示下限，两者矛盾。"}, {"text": "这次考试最少只能拿九十分。", "explanation": "这里应该用〈最多〉。“只能拿”限定上限，要用“最多”；“最少”表示下限，与“只能”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd886a38-5bf1-4944-a671-17fe4416db10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87718, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "最少", "is_correct": true, "explanation": "“最少”表示数量的下限，即“至少”，“学好汉语最少需要一年”句意通顺。"}, {"text": "早已", "is_correct": false, "explanation": "语义：“早已”表示早就完成，与“需要一年”的将来需求矛盾。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”表示过去的经历，与“需要一年”的需求不符。"}, {"text": "一向", "is_correct": false, "explanation": "搭配：“一向”表示长期习惯，不能与一次性的时长需求搭配。"}], "explanations": {"最少": "“最少”表示数量的下限，即“至少”，“学好汉语最少需要一年”句意通顺。", "早已": "语义：“早已”表示早就完成，与“需要一年”的将来需求矛盾。", "曾经": "语义：“曾经”表示过去的经历，与“需要一年”的需求不符。", "一向": "搭配：“一向”表示长期习惯，不能与一次性的时长需求搭配。"}, "sentence_index": 6, "correct_answer": "最少"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张桌子最少只能坐六个人。", "explanation": "这里应该用〈至多〉。“只能坐”限定上限，要用“至多”；“最少”表示下限，与“只能”矛盾。"}, {"text": "这次活动最少只能报名五十人。", "explanation": "这里应该用〈最多〉。“只能报名”限定上限，要用“最多”；“最少”表示下限，两者矛盾。"}, {"text": "这份文件最少只能保存三十天。", "explanation": "这里应该用〈至多〉。“只能保存”限定上限，要用“至多”；“最少”表示下限，与“只能”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd886a38-5bf1-4944-a671-17fe4416db10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87718, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份报告最少了要写两页。", "corrected_sentence": "这份报告最少要写两页。", "error_description": "错误形式：最少了要写两页；正确形式：最少要写两页。“最少”是副词，后面不能直接加完成标记“了”，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd886a38-5bf1-4944-a671-17fe4416db10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
