INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87719, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "鲨鱼是海里很凶的大鱼，牙齿很尖。", "primary_collocate": null, "pronunciation": "shā yú", "ipa": "ʂa⁵⁵ y³⁵", "syllable_count": 2, "sentences": [{"text": "鲨鱼是海里最凶的鱼。", "target_word": "鲨鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渔民今天网到了一条鲨鱼。", "target_word": "鲨鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的鲨鱼把船咬坏了。", "target_word": "鲨鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条鲨鱼的牙又白又尖。", "target_word": "鲨鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在书上读过鲨鱼的故事。", "target_word": "鲨鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鲨鱼住在很深的海里。", "target_word": "鲨鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友喜欢画鲨鱼。", "target_word": "鲨鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你怕不怕鲨鱼？", "target_word": "鲨鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "潜水的时候，他遇到了鲨鱼。", "target_word": "鲨鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鲨鱼要不停地游，才能呼吸。", "target_word": "鲨鱼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "中性", "sense_fingerprint": "海里很凶、牙齿很尖的大鱼", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52f58a29-0843-4b18-9594-88ac0b975df0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87719, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "鲨鱼", "is_correct": true, "explanation": "正确：听到的是“鲨鱼”（shā yú），指海里很凶的大鱼。"}, {"text": "烧鱼", "is_correct": false, "explanation": "shāo（第一声）与 shā 韵母不同（ao 与 a），意思是烹调好的鱼菜。"}, {"text": "叉鱼", "is_correct": false, "explanation": "chā（第一声）与 shā 声母不同（ch 与 sh），意思是用叉子捕鱼。"}, {"text": "啥鱼", "is_correct": false, "explanation": "第一个音节 shá（第二声）与 shā（第一声）声调不同，“啥鱼”是口语，意思是“什么鱼”。"}], "explanations": {"鲨鱼": "正确：听到的是“鲨鱼”（shā yú），指海里很凶的大鱼。", "烧鱼": "shāo（第一声）与 shā 韵母不同（ao 与 a），意思是烹调好的鱼菜。", "叉鱼": "chā（第一声）与 shā 声母不同（ch 与 sh），意思是用叉子捕鱼。", "啥鱼": "第一个音节 shá（第二声）与 shā（第一声）声调不同，“啥鱼”是口语，意思是“什么鱼”。"}, "sentence_index": null, "correct_answer": "鲨鱼"}, "level_3": {"options": [{"text": "鲨鱼", "is_correct": true, "explanation": "正确：鲨鱼是海里很凶的大鱼，与“海里最凶的鱼”相符。"}, {"text": "鲤鱼", "is_correct": false, "explanation": "语义：鲤鱼是淡水鱼，不生活在海里，“鲤鱼是海里最凶的鱼”说不通。"}, {"text": "海豚", "is_correct": false, "explanation": "语义：海豚是哺乳动物，不是鱼，也不凶，这句话不成立。"}, {"text": "小猫", "is_correct": false, "explanation": "搭配：“小猫”不是鱼，不能用“……的鱼”来说，与“最凶的鱼”搭配不当。"}], "explanations": {"鲨鱼": "正确：鲨鱼是海里很凶的大鱼，与“海里最凶的鱼”相符。", "鲤鱼": "语义：鲤鱼是淡水鱼，不生活在海里，“鲤鱼是海里最凶的鱼”说不通。", "海豚": "语义：海豚是哺乳动物，不是鱼，也不凶，这句话不成立。", "小猫": "搭配：“小猫”不是鱼，不能用“……的鱼”来说，与“最凶的鱼”搭配不当。"}, "sentence_index": 0, "correct_answer": "鲨鱼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在海边捡到了一本鲨鱼。", "explanation": "这里应该用〈条〉。“本”用于书籍，不能用来数鱼。"}, {"text": "深海里游着一座鲨鱼。", "explanation": "这里应该用〈条〉。“座”用于山、房屋等大型物体，鲨鱼要用“条”。"}, {"text": "水族馆里养着一朵鲨鱼。", "explanation": "这里应该用〈条〉。“朵”用于花，鲨鱼要用“条”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca9ddb30-e43a-4c63-956b-9f576adce309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87719, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "鲨鱼", "is_correct": true, "explanation": "正确：听到的是“鲨鱼”（shā yú），指海里很凶的大鱼。"}, {"text": "杀毒", "is_correct": false, "explanation": "第二个音节 dú（第二声）与 yú 声母不同（d 与 y），意思是消灭病毒，不是鱼。"}, {"text": "沙浴", "is_correct": false, "explanation": "第二个音节 yù（第四声）与 yú（第二声）声调不同，意思是用沙子进行的洗浴。"}, {"text": "晒鱼", "is_correct": false, "explanation": "shài（第四声）与 shā 的韵母和声调都不同，意思是把鱼晒干。"}], "explanations": {"鲨鱼": "正确：听到的是“鲨鱼”（shā yú），指海里很凶的大鱼。", "杀毒": "第二个音节 dú（第二声）与 yú 声母不同（d 与 y），意思是消灭病毒，不是鱼。", "沙浴": "第二个音节 yù（第四声）与 yú（第二声）声调不同，意思是用沙子进行的洗浴。", "晒鱼": "shài（第四声）与 shā 的韵母和声调都不同，意思是把鱼晒干。"}, "sentence_index": null, "correct_answer": "鲨鱼"}, "level_3": {"options": [{"text": "鲨鱼", "is_correct": true, "explanation": "正确：“小朋友喜欢画鲨鱼”，鲨鱼是可以画的常见动物。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气看不见，不能拿来画，“小朋友喜欢画空气”说不通。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度是抽象的数值，不能画出来，这句话不成立。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“画”与“味道”搭配不当，味道不能用画来表现。"}], "explanations": {"鲨鱼": "正确：“小朋友喜欢画鲨鱼”，鲨鱼是可以画的常见动物。", "空气": "语义：空气看不见，不能拿来画，“小朋友喜欢画空气”说不通。", "温度": "语义：温度是抽象的数值，不能画出来，这句话不成立。", "味道": "搭配：“画”与“味道”搭配不当，味道不能用画来表现。"}, "sentence_index": 6, "correct_answer": "鲨鱼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "水池里养着一把鲨鱼。", "explanation": "这里应该用〈条〉。“把”用于有柄的器具，鲨鱼不能用“把”来数。"}, {"text": "鱼缸里游着一支鲨鱼。", "explanation": "这里应该用〈条〉。“支”用于笔、枪等细长的物件，鲨鱼不能用“支”来数。"}, {"text": "展厅里摆着一间鲨鱼。", "explanation": "这里应该用〈条〉。“间”用于房屋，不能用来数鱼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca9ddb30-e43a-4c63-956b-9f576adce309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87719, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在海边看见了一个大鲨鱼。", "corrected_sentence": "我在海边看见了一条大鲨鱼。", "error_description": "量词错误：“鲨鱼”应该用量词“条”，不能用“个”。应说“一条大鲨鱼”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca9ddb30-e43a-4c63-956b-9f576adce309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87719, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "海里游过来一棵鲨鱼。", "corrected_sentence": "海里游过来一条鲨鱼。", "error_description": "量词错误：“鲨鱼”应该用量词“条”，不能用“棵”（“棵”用于植物）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca9ddb30-e43a-4c63-956b-9f576adce309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
