INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87721, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "相互是你对我好，我也对你好，两边都一样。", "primary_collocate": null, "pronunciation": "xiāng hù", "ipa": "ɕjaŋ˥ xu˥˩", "syllable_count": 2, "sentences": [{"text": "朋友要相互信任。", "target_word": "相互", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们相互喜欢。", "target_word": "相互", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好邻居总是相互照顾。", "target_word": "相互", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我帮你，你帮我，我们相互帮忙。", "target_word": "相互", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同事之间相互支持，工作更顺利。", "target_word": "相互", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们一直相互关心。", "target_word": "相互", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生和老师相互尊重。", "target_word": "相互", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个国家相互学习。", "target_word": "相互", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "感情要靠相互付出。", "target_word": "相互", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夫妻相互爱护，生活很幸福。", "target_word": "相互", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "双方彼此给予同样的态度或行为，你对我怎样，我也对你怎样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcccfa74-1e16-4e92-abd1-a3b542c01668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87721, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "偶尔", "is_correct": false, "explanation": "语义：「偶尔」表示不常发生，与「要」表示的应当义相冲突。"}, {"text": "相互", "is_correct": true, "explanation": "「相互」表示双方彼此给予同样的信任，符合「朋友」之间的对等关系。"}, {"text": "曾经", "is_correct": false, "explanation": "体貌：「曾经」指过去的事，与「要」表示的应当、将来义冲突。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：「忽然」表示突然发生，与需要长期维持的信任不相符。"}], "explanations": {"偶尔": "语义：「偶尔」表示不常发生，与「要」表示的应当义相冲突。", "相互": "「相互」表示双方彼此给予同样的信任，符合「朋友」之间的对等关系。", "曾经": "体貌：「曾经」指过去的事，与「要」表示的应当、将来义冲突。", "忽然": "语义：「忽然」表示突然发生，与需要长期维持的信任不相符。"}, "sentence_index": 0, "correct_answer": "相互"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两家人相互睡着了。", "explanation": "这里应该用〈各自〉。各自指每家单独行动，而「相互」表示双方彼此对待，睡着是每家自己的事。"}, {"text": "她相互住在山上。", "explanation": "这里应该用〈独自〉。独自指一个人单独住，而「相互」只能用于双方都参与的动作，这里只有她一个人。"}, {"text": "三位同学相互吃完了午饭。", "explanation": "这里应该用〈分别〉。分别指各吃各的，而「相互」要求双方彼此对待，吃午饭是每人自己的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87721, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "独自", "is_correct": false, "explanation": "语义：「独自」指一个人单独进行，与「学生和老师」这一双方关系不符。"}, {"text": "单独", "is_correct": false, "explanation": "搭配：「单独」多用于单独行动，不能与「尊重」这类表示态度的动词直接搭配在双方关系中。"}, {"text": "相互", "is_correct": true, "explanation": "「相互」表示双方彼此尊重，符合「学生和老师」之间的对等关系。"}, {"text": "亲手", "is_correct": false, "explanation": "搭配：「亲手」强调用手亲自做，不能修饰「尊重」这类抽象态度。"}], "explanations": {"独自": "语义：「独自」指一个人单独进行，与「学生和老师」这一双方关系不符。", "单独": "搭配：「单独」多用于单独行动，不能与「尊重」这类表示态度的动词直接搭配在双方关系中。", "相互": "「相互」表示双方彼此尊重，符合「学生和老师」之间的对等关系。", "亲手": "搭配：「亲手」强调用手亲自做，不能修饰「尊重」这类抽象态度。"}, "sentence_index": 6, "correct_answer": "相互"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我相互走回了家。", "explanation": "这里应该用〈单独〉。单独指一个人去做，而「相互」要求双方彼此对待，这里只有我一个人走。"}, {"text": "妈妈相互做了饭。", "explanation": "这里应该用〈亲手〉。亲手指用自己的手做，而「相互」表示双方彼此对待，做饭是妈妈一个人的事。"}, {"text": "他相互完成了设计。", "explanation": "这里应该用〈独立〉。独立完成指自己单独完成，而「相互」表示双方彼此，设计是他个人的工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87721, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "朋友之间要相互互相信任。", "corrected_sentence": "朋友之间要相互信任。", "error_description": "「相互」和「互相」意思相同，不能叠用。应说「相互信任」，不能说「相互互相信任」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87721, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学生和老师应该很相互尊重。", "corrected_sentence": "学生和老师应该相互尊重。", "error_description": "「相互」是副词，前面不能加程度副词「很」。应说「学生和老师应该相互尊重」，不能说「学生和老师应该很相互尊重」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
