INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87722, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示两方面彼此对待。", "primary_collocate": null, "pronunciation": "xiāng hù", "ipa": "ɕjaŋ˥ xu˥˩", "syllable_count": 2, "sentences": [{"text": "邻居之间要相互帮助。", "target_word": "相互", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该相互尊重。", "target_word": "相互", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们相互看了一眼。", "target_word": "相互", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友之间相互关心。", "target_word": "相互", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个孩子相互笑了笑。", "target_word": "相互", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家相互学习，一起进步。", "target_word": "相互", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夫妻要相互理解。", "target_word": "相互", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们相互介绍了自己。", "target_word": "相互", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们相互通信了很多年。", "target_word": "相互", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们相互留了电话号码。", "target_word": "相互", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "放在动词前，表示双方彼此做同一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcccfa74-1e16-4e92-abd1-a3b542c01668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87722, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "独自", "is_correct": false, "explanation": "语义：「独自」指一个人单独进行，与「邻居之间」的双方关系不符。"}, {"text": "相互", "is_correct": true, "explanation": "「相互」表示双方彼此对待，正对应「邻居之间」的互助关系。"}, {"text": "已经", "is_correct": false, "explanation": "体貌：「已经」表示已然发生，与情态词「要」表示的应当义冲突。"}, {"text": "曾经", "is_correct": false, "explanation": "体貌：「曾经」指过去的事，与「要」表示的应当、将来义冲突。"}], "explanations": {"独自": "语义：「独自」指一个人单独进行，与「邻居之间」的双方关系不符。", "相互": "「相互」表示双方彼此对待，正对应「邻居之间」的互助关系。", "已经": "体貌：「已经」表示已然发生，与情态词「要」表示的应当义冲突。", "曾经": "体貌：「曾经」指过去的事，与「要」表示的应当、将来义冲突。"}, "sentence_index": 0, "correct_answer": "相互"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大家相互回了家。", "explanation": "这里应该用〈各自〉。各自指每人单独行动，而「相互」表示双方彼此对待，回家是各人自己的事。"}, {"text": "三个人相互迟到了。", "explanation": "这里应该用〈各自〉。各自指每人单独行动，而「相互」表示双方彼此对待，迟到是每人自己的事。"}, {"text": "他相互去了北京。", "explanation": "这里应该用〈独自〉。独自指一个人单独去，而「相互」只能用于双方都参与的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87722, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偶尔", "is_correct": false, "explanation": "语义：「偶尔」表示不常发生，与「要」表示的应当、必须义相冲突。"}, {"text": "刚刚", "is_correct": false, "explanation": "体貌：「刚刚」指刚发生的事，与「要」表示的应当义不合。"}, {"text": "相互", "is_correct": true, "explanation": "「相互」表示双方彼此理解，符合「夫妻」之间的对等关系。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：「忽然」表示突然出现，无法表达夫妻之间应有的持续理解。"}], "explanations": {"偶尔": "语义：「偶尔」表示不常发生，与「要」表示的应当、必须义相冲突。", "刚刚": "体貌：「刚刚」指刚发生的事，与「要」表示的应当义不合。", "相互": "「相互」表示双方彼此理解，符合「夫妻」之间的对等关系。", "忽然": "语义：「忽然」表示突然出现，无法表达夫妻之间应有的持续理解。"}, "sentence_index": 6, "correct_answer": "相互"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师相互出差了。", "explanation": "这里应该用〈各自〉。各自指每人单独行动，而「相互」表示双方彼此对待，出差是每人自己的事。"}, {"text": "妈妈相互做了一桌菜。", "explanation": "这里应该用〈亲手〉。亲手强调用自己的手做，而「相互」要求双方彼此对待，做菜是妈妈一个人的事。"}, {"text": "他相互思考问题。", "explanation": "这里应该用〈独立〉。独立思考指自己思考、不依赖他人，而「相互」表示双方彼此，思考是个人的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87722, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "同学们应该相互相互帮助。", "corrected_sentence": "同学们应该相互帮助。", "error_description": "「相互」是副词，前面已有「相互」，不能重复说「相互相互」。应说「同学们应该相互帮助」，不能说「同学们应该相互相互帮助」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87722, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们很相互理解了。", "corrected_sentence": "他们相互理解了。", "error_description": "「相互」是副词，前面不能加程度副词「很」。应说「他们相互理解了」，不能说「他们很相互理解了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
