INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87724, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "勉强适应；凑合着用。", "primary_collocate": null, "pronunciation": "jiāng jiu", "ipa": "tɕjɑŋ˥ tɕjoʊ", "syllable_count": 2, "sentences": [{"text": "我们没有大桌子，只能将就着吃。", "target_word": "将就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋有点小，我将就穿了一天。", "target_word": "将就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旅馆很旧，不过睡一晚还能将就。", "target_word": "将就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "家里只有旧电脑，你将就着用吧。", "target_word": "将就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有床，客人只好在沙发上将就一晚。", "target_word": "将就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "条件不好，大家都得将就一点。", "target_word": "将就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这把伞坏了，下雨时你将就着打吧。", "target_word": "将就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不挑食，什么都能将就。", "target_word": "将就", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "新家还没收拾好，我们先将就几天。", "target_word": "将就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "屋里没有空调，夏天只好将就着过。", "target_word": "将就", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "将就着", "label": "体标"}, {"form": "将就了", "label": "体标"}, {"form": "将就将就", "label": "重叠"}], "register": "口语", "sense_fingerprint": "条件不好时勉强适应凑合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee16606a-f927-4c1a-ac0f-73f57f89b922') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87724, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "将就", "is_correct": true, "explanation": "正确：“将就”表示勉强适应条件，与“没有大桌子，只能……着吃”相符。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“只能”之后接“拒绝”，与“只能……着吃”的无奈语气矛盾。"}, {"text": "挑选", "is_correct": false, "explanation": "语义：“只能”之后接“挑选”，与没有大桌子的条件相矛盾。"}, {"text": "争夺", "is_correct": false, "explanation": "配价：“争夺”要接争夺的对象，不能接“着吃”这种进食方式。"}], "explanations": {"将就": "正确：“将就”表示勉强适应条件，与“没有大桌子，只能……着吃”相符。", "拒绝": "语义：“只能”之后接“拒绝”，与“只能……着吃”的无奈语气矛盾。", "挑选": "语义：“只能”之后接“挑选”，与没有大桌子的条件相矛盾。", "争夺": "配价：“争夺”要接争夺的对象，不能接“着吃”这种进食方式。"}, "sentence_index": 0, "correct_answer": "将就"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她将就着压力，坚持工作。", "explanation": "这里应该用〈忍耐〉。将就指凑合着用不理想的东西，不用于承受压力。"}, {"text": "大家都将就得很兴奋。", "explanation": "这里应该用〈激动〉。将就表示勉强凑合，不能用于形容兴奋的情绪。"}, {"text": "他将就了一批奖品，送给了学生们。", "explanation": "这里应该用〈凑〉。将就表示勉强凑合着用，不用于凑集奖品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abe1b8c7-5769-429e-b5fd-ee02daa76644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87724, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "将就", "is_correct": true, "explanation": "正确：“将就”表示凑合着用，与“伞坏了，下雨时”的语境相符。"}, {"text": "嫌弃", "is_correct": false, "explanation": "语义：“嫌弃”表示看不上，与“下雨时”需要伞、只能凑合用的语境不合。"}, {"text": "修理", "is_correct": false, "explanation": "配价：“修理”要接被修理的物品，不能接“着打”这种动作。"}, {"text": "收藏", "is_correct": false, "explanation": "语义：“收藏”是保存珍品，不用于下雨时拿来打。"}], "explanations": {"将就": "正确：“将就”表示凑合着用，与“伞坏了，下雨时”的语境相符。", "嫌弃": "语义：“嫌弃”表示看不上，与“下雨时”需要伞、只能凑合用的语境不合。", "修理": "配价：“修理”要接被修理的物品，不能接“着打”这种动作。", "收藏": "语义：“收藏”是保存珍品，不用于下雨时拿来打。"}, "sentence_index": 6, "correct_answer": "将就"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们都将就地夸这幅名画，很有感情。", "explanation": "这里应该用〈欣赏〉。将就表示勉强凑合，不用于真心赞赏名画。"}, {"text": "他把一件旧衬衫将就成了新衣服。", "explanation": "这里应该用〈改〉。将就表示勉强凑合着用，不能表示把东西改造成别的东西。"}, {"text": "他考了第一名，高兴得将就起来。", "explanation": "这里应该用〈跳〉。将就表示勉强凑合，不能表示高兴时的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abe1b8c7-5769-429e-b5fd-ee02daa76644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87724, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小旅馆很旧，我们只好将就了住一晚。", "corrected_sentence": "这个小旅馆很旧，我们只好将就住一晚。", "error_description": "错误：动态助词的位置。“了”不能插在连动的“将就”和“住”之间，错误形式是“将就了住”，正确形式是“将就住”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abe1b8c7-5769-429e-b5fd-ee02daa76644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87724, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些旧家具先把将就用吧。", "corrected_sentence": "这些旧家具先将就用吧。", "error_description": "错误：多余的“把”。此处“将就”直接作谓语，不应插入“把”，应说“先将就用吧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abe1b8c7-5769-429e-b5fd-ee02daa76644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
