INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87725, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "未来学是研究以后会变成什么样的学问。", "primary_collocate": null, "pronunciation": "wèi lái xué", "ipa": "wei˥˩ lai˧˥ ɕɥɛ˧˥", "syllable_count": 3, "sentences": [{"text": "他在大学里学未来学。", "target_word": "未来学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "未来学是一门很有意思的学问。", "target_word": "未来学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对未来学很感兴趣。", "target_word": "未来学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书是讲未来学的。", "target_word": "未来学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想知道未来学研究什么。", "target_word": "未来学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了未来学。", "target_word": "未来学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "未来学不是算命。", "target_word": "未来学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读了很多未来学的书。", "target_word": "未来学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学未来学，要多看新闻和数据。", "target_word": "未来学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所大学有未来学课。", "target_word": "未来学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "未來學", "label": "繁体"}], "register": "正式", "sense_fingerprint": "研究以后会怎样的学问", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c82921da-4675-443e-aa98-940b45501dcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87725, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "早餐", "is_correct": false, "explanation": "语义：早餐是一顿饭，不是学问，不能作为“学”的对象。"}, {"text": "未来学", "is_correct": true, "explanation": "正确：未来学是研究未来的学问，“在大学里学未来学”是正常说法。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：眼镜是物品，不能作为学习的对象。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食物，不是在大学里学习的学问。"}], "explanations": {"早餐": "语义：早餐是一顿饭，不是学问，不能作为“学”的对象。", "未来学": "正确：未来学是研究未来的学问，“在大学里学未来学”是正常说法。", "眼镜": "语义：眼镜是物品，不能作为学习的对象。", "蛋糕": "语义：蛋糕是食物，不是在大学里学习的学问。"}, "sentence_index": 0, "correct_answer": "未来学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一位未来学。", "explanation": "这里应该用〈未来学家〉。未来学是学科，指人要用“未来学家”。"}, {"text": "我们去未来学借书。", "explanation": "这里应该用〈图书馆〉。借书要去图书馆；未来学是学科，不是可以去的场所。"}, {"text": "这幅画是未来学的。", "explanation": "这里应该用〈未来派〉。未来派是艺术流派，说画的风格要用“未来派”，未来学是学科，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '932a57fe-9398-41db-9fdd-1b79fde921e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87725, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "预测", "is_correct": false, "explanation": "词性：预测是动词，这里需要名词作主语表示一门学问；“预测不是算命”说的是行为，不是学科。"}, {"text": "未来学", "is_correct": true, "explanation": "正确：主语应是未来学，“未来学不是算命”是在区分学问与算命。"}, {"text": "未来地", "is_correct": false, "explanation": "语法：“未来地”不是词，“地”用于状语，不能作主语。"}, {"text": "研究着", "is_correct": false, "explanation": "语法：“研究着”是带体标的动词，不能单独作主语。"}], "explanations": {"预测": "词性：预测是动词，这里需要名词作主语表示一门学问；“预测不是算命”说的是行为，不是学科。", "未来学": "正确：主语应是未来学，“未来学不是算命”是在区分学问与算命。", "未来地": "语法：“未来地”不是词，“地”用于状语，不能作主语。", "研究着": "语法：“研究着”是带体标的动词，不能单独作主语。"}, "sentence_index": 6, "correct_answer": "未来学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们应该珍惜现在和未来学。", "explanation": "这里应该用〈未来〉。“珍惜”的对象是时间，未来学是学科，不能用来指时间。"}, {"text": "他饿了，吃了一碗未来学。", "explanation": "这里应该用〈饭〉。吃的是饭、面等食物；未来学是学问，不能吃。"}, {"text": "这把椅子是用未来学做的。", "explanation": "这里应该用〈木头〉。椅子是用木头、金属等材料做的；未来学是学问，不是材料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '932a57fe-9398-41db-9fdd-1b79fde921e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87725, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在大学里学了一本未来学。", "corrected_sentence": "他在大学里学了一门未来学。", "error_description": "量词错误：学科、课程用“门”，“本”用于书籍等。应说“学了一门未来学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '932a57fe-9398-41db-9fdd-1b79fde921e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87725, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所大学有一本未来学课。", "corrected_sentence": "这所大学有一门未来学课。", "error_description": "量词错误：课程用“门”，“本”用于书籍等。应说“一门未来学课”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '932a57fe-9398-41db-9fdd-1b79fde921e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
