INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87726, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "研究未来发展趋势和各种可能性的学科。", "primary_collocate": null, "pronunciation": "wèi lái xué", "ipa": "wei˥˩ lai˧˥ ɕɥɛ˧˥", "syllable_count": 3, "sentences": [{"text": "未来学研究社会发展的趋势。", "target_word": "未来学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "未来学可以帮我们看到各种可能。", "target_word": "未来学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位教授在研究未来学。", "target_word": "未来学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "未来学的研究方法越来越多。", "target_word": "未来学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人工智能是未来学常讨论的话题。", "target_word": "未来学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她写了一篇关于未来学的文章。", "target_word": "未来学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "未来学这门学科出现得比较晚。", "target_word": "未来学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市的未来，也是未来学要问的问题。", "target_word": "未来学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学了未来学，他看问题看得更远了。", "target_word": "未来学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "未来学能让我们想到几种可能。", "target_word": "未来学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "未來學", "label": "繁体"}], "register": "正式", "sense_fingerprint": "研究未来趋势与可能性的学科", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c82921da-4675-443e-aa98-940b45501dcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87726, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "眼镜", "is_correct": false, "explanation": "语义：眼镜是物品，不是学科或机构，不能进行研究。"}, {"text": "未来学", "is_correct": true, "explanation": "正确：未来学是研究未来发展趋势的学科，可以作“研究”的主语。"}, {"text": "厨房", "is_correct": false, "explanation": "配价：“研究”需要研究主体，厨房是场所，不能作为研究的主语。"}, {"text": "手套", "is_correct": false, "explanation": "语义：手套是物品，不能研究社会发展的趋势。"}], "explanations": {"眼镜": "语义：眼镜是物品，不是学科或机构，不能进行研究。", "未来学": "正确：未来学是研究未来发展趋势的学科，可以作“研究”的主语。", "厨房": "配价：“研究”需要研究主体，厨房是场所，不能作为研究的主语。", "手套": "语义：手套是物品，不能研究社会发展的趋势。"}, "sentence_index": 0, "correct_answer": "未来学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我姐姐是一位未来学。", "explanation": "这里应该用〈未来学家〉。未来学是学科，指人要用“未来学家”。"}, {"text": "我们去未来学锻炼身体。", "explanation": "这里应该用〈体育馆〉。锻炼身体要去体育馆；未来学是学科，不是场所。"}, {"text": "这幅画是未来学的。", "explanation": "这里应该用〈未来派〉。未来派是艺术流派，说画的风格要用“未来派”，未来学是学科。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '932a57fe-9398-41db-9fdd-1b79fde921e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87726, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "篮球", "is_correct": false, "explanation": "语义：篮球是运动项目，不是学科，与“这门学科”不符。"}, {"text": "未来学", "is_correct": true, "explanation": "正确：未来学是学科，“这门学科出现得比较晚”指的正是它。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不是学科，与“这门学科”不符。"}, {"text": "手表", "is_correct": false, "explanation": "搭配：“门”是学科的量词，不能与“手表”搭配。"}], "explanations": {"篮球": "语义：篮球是运动项目，不是学科，与“这门学科”不符。", "未来学": "正确：未来学是学科，“这门学科出现得比较晚”指的正是它。", "冰箱": "语义：冰箱是家电，不是学科，与“这门学科”不符。", "手表": "搭配：“门”是学科的量词，不能与“手表”搭配。"}, "sentence_index": 6, "correct_answer": "未来学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们可以想象未来学的生活。", "explanation": "这里应该用〈未来〉。想象的对象是未来的生活，“未来学的生活”把学科当成了时间。"}, {"text": "这个未来学很重，我搬不动。", "explanation": "这里应该用〈箱子〉。箱子是有重量的东西，可以说搬不动；未来学是学问，没有重量。"}, {"text": "他每天喝一杯未来学。", "explanation": "这里应该用〈茶〉。喝的是茶、水等液体；未来学是学问，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '932a57fe-9398-41db-9fdd-1b79fde921e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87726, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她选修了一本未来学。", "corrected_sentence": "她选修了一门未来学。", "error_description": "量词错误：学科、课程用“门”，“本”用于书籍等。应说“选修了一门未来学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '932a57fe-9398-41db-9fdd-1b79fde921e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87726, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这支未来学很有意思。", "corrected_sentence": "这门未来学很有意思。", "error_description": "量词错误：学科用“门”，“支”用于队伍、笔等。应说“这门未来学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '932a57fe-9398-41db-9fdd-1b79fde921e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
