INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87727, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "党主席是一个政党里最大的领头人。", "primary_collocate": null, "pronunciation": "dǎng zhǔ xí", "ipa": "taŋ˨˩˦ ʈʂu˨˩˦ ɕi˧˥", "syllable_count": 3, "sentences": [{"text": "党主席在大会上讲了话。", "target_word": "党主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个政党的党主席是一位女士。", "target_word": "党主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新党主席下个月就要上任了。", "target_word": "党主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "党主席和记者见了面。", "target_word": "党主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当了十年党主席。", "target_word": "党主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家选他做党主席。", "target_word": "党主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "党主席明天要去国外访问。", "target_word": "党主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位党主席很受党员欢迎。", "target_word": "党主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "党主席请大家安静一下。", "target_word": "党主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在电视上看到了党主席。", "target_word": "党主席", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "黨主席", "label": "繁体"}], "register": "正式", "sense_fingerprint": "政党里最大的领头人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8e11571-276b-4f80-a3d3-598e69fefa2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87727, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "党主席", "is_correct": true, "explanation": "正确。“党主席”指政党的最高领导人，可以在大会上讲话。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫不会在大会上讲话。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能在大会上讲话。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“讲话”的主语应是能说话的人，窗户不能讲话，搭配不当。"}], "explanations": {"党主席": "正确。“党主席”指政党的最高领导人，可以在大会上讲话。", "小猫": "语义：小猫不会在大会上讲话。", "石头": "语义：石头不能在大会上讲话。", "窗户": "搭配：“讲话”的主语应是能说话的人，窗户不能讲话，搭配不当。"}, "sentence_index": 0, "correct_answer": "党主席"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场晚会的党主席是小王。", "explanation": "这里应该用“主持人”。党主席指政党的最高领导人，晚会的主持人不叫党主席。"}, {"text": "我们支部的党主席是老李。", "explanation": "这里应该用“书记”。党主席指政党的最高领导人，党支部的负责人叫书记，不叫党主席。"}, {"text": "这家公司的党主席明天要出差。", "explanation": "这里应该用“经理”。党主席指政党的最高领导人，公司的负责人应说经理，不叫党主席。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5d38431-8fe9-4adc-a7ae-41894017f9b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87727, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "党主席", "is_correct": true, "explanation": "正确。“党主席”指政党的领导人，可以去国外访问。"}, {"text": "小鸟", "is_correct": false, "explanation": "语义：小鸟不能以代表的身份去国外访问。"}, {"text": "课桌", "is_correct": false, "explanation": "语义：课桌是物品，不会去国外访问。"}, {"text": "洗衣机", "is_correct": false, "explanation": "搭配：“访问”的主语应是人或代表团，洗衣机不能去访问。"}], "explanations": {"党主席": "正确。“党主席”指政党的领导人，可以去国外访问。", "小鸟": "语义：小鸟不能以代表的身份去国外访问。", "课桌": "语义：课桌是物品，不会去国外访问。", "洗衣机": "搭配：“访问”的主语应是人或代表团，洗衣机不能去访问。"}, "sentence_index": 6, "correct_answer": "党主席"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生会的党主席是小张。", "explanation": "这里应该用“主席”。党主席专指政党的最高领导人，学生会的负责人只能叫主席。"}, {"text": "党主席在比赛中吹哨子。", "explanation": "这里应该用“裁判”。党主席不负责比赛的判罚与吹哨。"}, {"text": "我们足球队的党主席很厉害。", "explanation": "这里应该用“队长”。党主席指政党的最高领导人，球队的带队人应说队长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5d38431-8fe9-4adc-a7ae-41894017f9b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87727, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两个政党各有一只党主席。", "corrected_sentence": "这两个政党各有一位党主席。", "error_description": "量词错误：“党主席”指人，应用量词“位”，不能用“只”（“只”多用于动物或成对物件中的一个）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5d38431-8fe9-4adc-a7ae-41894017f9b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87727, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他曾经当了过党主席。", "corrected_sentence": "他曾经当过党主席。", "error_description": "体标错误：“当过”表示曾经有过的经历，“了”和“过”不能同时用在同一个动词后，应说“当过党主席”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5d38431-8fe9-4adc-a7ae-41894017f9b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
