INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87728, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "政党的最高领导人。", "primary_collocate": null, "pronunciation": "dǎng zhǔ xí", "ipa": "taŋ˨˩˦ ʈʂu˨˩˦ ɕi˧˥", "syllable_count": 3, "sentences": [{"text": "党主席是这个政党的最高领导人。", "target_word": "党主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "党主席辞职后，大家选出了新人。", "target_word": "党主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位党主席正在开会。", "target_word": "党主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个党的党主席今天见面了。", "target_word": "党主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "党主席的话，党员们都认真听着。", "target_word": "党主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就想成为党主席。", "target_word": "党主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "党主席的工作很忙，常常很晚才回家。", "target_word": "党主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上有一篇写党主席的文章。", "target_word": "党主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "党主席要带领全党走向未来。", "target_word": "党主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她第一次当上党主席，心里很激动。", "target_word": "党主席", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "黨主席", "label": "繁体"}], "register": "正式", "sense_fingerprint": "政党的最高领导人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8e11571-276b-4f80-a3d3-598e69fefa2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87728, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "党主席", "is_correct": true, "explanation": "正确。“党主席”指政党的最高领导人，与“政党的最高领导人”一致。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：小狗不是政党的最高领导人。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是地方，不能担任政党的最高领导人。"}, {"text": "学生", "is_correct": false, "explanation": "搭配：“政党的最高领导人”要求担任领导职务的人，学生与政党不搭配。"}], "explanations": {"党主席": "正确。“党主席”指政党的最高领导人，与“政党的最高领导人”一致。", "小狗": "语义：小狗不是政党的最高领导人。", "厨房": "语义：厨房是地方，不能担任政党的最高领导人。", "学生": "搭配：“政党的最高领导人”要求担任领导职务的人，学生与政党不搭配。"}, "sentence_index": 0, "correct_answer": "党主席"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两个班的党主席今天见面了。", "explanation": "这里应该用“班长”。党主席指政党的最高领导人，班级的负责人不叫党主席。"}, {"text": "两家超市的党主席今天见面了。", "explanation": "这里应该用“经理”。党主席是政党的领导，超市的负责人应说经理。"}, {"text": "学生会的党主席下周要换届。", "explanation": "这里应该用“主席”。党主席专指政党的最高领导人，学生会的负责人只能叫主席。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5d38431-8fe9-4adc-a7ae-41894017f9b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87728, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "党主席", "is_correct": true, "explanation": "正确。“党主席”指政党的领导人，有工作，会回家。"}, {"text": "小草", "is_correct": false, "explanation": "语义：小草没有工作，也不会回家。"}, {"text": "河水", "is_correct": false, "explanation": "语义：河水不会上班，也不会回家。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“常常很晚才回家”要求主语能自己回家，冰箱不能。"}], "explanations": {"党主席": "正确。“党主席”指政党的领导人，有工作，会回家。", "小草": "语义：小草没有工作，也不会回家。", "河水": "语义：河水不会上班，也不会回家。", "冰箱": "搭配：“常常很晚才回家”要求主语能自己回家，冰箱不能。"}, "sentence_index": 6, "correct_answer": "党主席"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "党主席每天带游客参观博物馆。", "explanation": "这里应该用“导游”。党主席指政党的最高领导人，不负责带团讲解。"}, {"text": "这支球队的党主席很严格。", "explanation": "这里应该用“教练”。党主席指政党的最高领导人，带队训练球员的人应说教练。"}, {"text": "这家工厂的党主席很年轻。", "explanation": "这里应该用“厂长”。党主席指政党的最高领导人，工厂的负责人应说厂长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5d38431-8fe9-4adc-a7ae-41894017f9b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
